  },
  "bar_hanging": {
    "en": ExerciseGuide(["Grip the bar overhand, hands shoulder-width apart.", "Lift your feet and let your body hang straight and relaxed.", "Keep your shoulders slightly engaged and breathe slowly for 30 seconds.", "Step down gently, rest 30 to 60 seconds, and repeat for 3 sets."], ["Swinging or kicking your legs while hanging.", "Dropping off the bar instead of stepping down."], "Start with shorter holds and add a few seconds each week."),
    "tr": ExerciseGuide(["Barı üstten kavra, ellerin omuz genişliğinde olsun.", "Ayaklarını yerden kes, vücudunu düz ve gevşek şekilde sarkıt.", "Omuzlarını hafifçe aktif tut ve 30 saniye yavaş nefes al.", "Yavaşça yere in, 30-60 saniye dinlen ve 3 set tekrarla."], ["Asılırken sallanmak ya da bacak savurmak.", "Kontrollü inmek yerine kendini bardan bırakıvermek."], "Kısa sürelerle başla, her hafta birkaç saniye ekle."),
    "de": ExerciseGuide(["Greif die Stange im Obergriff, Hände schulterbreit.", "Heb die Füße an und lass deinen Körper gerade und locker hängen.", "Halte die Schultern leicht aktiv und atme 30 Sekunden ruhig.", "Steig sanft ab, ruh dich 30 bis 60 Sekunden aus und mach 3 Sätze."], ["Beim Hängen schwingen oder mit den Beinen strampeln.", "Dich von der Stange fallen lassen, statt kontrolliert abzusteigen."], "Starte mit kürzeren Zeiten und leg jede Woche ein paar Sekunden drauf."),
    "fr": ExerciseGuide(["Attrape la barre en pronation, mains écartées à largeur d'épaules.", "Lève les pieds et laisse ton corps pendre, droit et détendu.", "Garde les épaules légèrement actives et respire calmement 30 secondes.", "Redescends doucement, repose-toi 30 à 60 secondes et fais 3 séries."], ["Te balancer ou battre des jambes pendant la suspension.", "Lâcher la barre d'un coup au lieu de redescendre en douceur."], "Commence par des durées courtes et ajoute quelques secondes chaque semaine."),
    "es": ExerciseGuide(["Agarra la barra con las palmas hacia delante, manos al ancho de los hombros.", "Levanta los pies y deja el cuerpo colgando recto y relajado.", "Mantén los hombros un poco activos y respira lento 30 segundos.", "Baja con suavidad, descansa de 30 a 60 segundos y haz 3 series."], ["Balancearte o patalear mientras cuelgas.", "Soltarte de golpe en vez de bajar con control."], "Empieza con tiempos cortos y suma unos segundos cada semana."),
    "it": ExerciseGuide(["Afferra la sbarra con presa prona, mani alla larghezza delle spalle.", "Solleva i piedi e lascia il corpo appeso, dritto e rilassato.", "Tieni le spalle leggermente attive e respira piano per 30 secondi.", "Scendi con calma, riposa 30-60 secondi e fai 3 serie."], ["Dondolare o scalciare con le gambe mentre sei appeso.", "Lasciarti cadere invece di scendere con controllo."], "Parti con tempi brevi e aggiungi qualche secondo ogni settimana."),
    "pt": ExerciseGuide(["Segure a barra com as palmas para frente, mãos na largura dos ombros.", "Tire os pés do chão e deixe o corpo pendurado, reto e relaxado.", "Mantenha os ombros levemente ativos e respire devagar por 30 segundos.", "Desça com calma, descanse de 30 a 60 segundos e faça 3 séries."], ["Balançar ou chutar as pernas enquanto está pendurado.", "Se soltar de uma vez em vez de descer com controle."], "Comece com tempos curtos e acrescente alguns segundos por semana."),
    "hi": ExerciseGuide(["बार को ऊपर से पकड़ो, हाथ कंधों जितनी चौड़ाई पर रखो।", "पैर ज़मीन से उठाओ और शरीर को सीधा और ढीला लटकने दो।", "कंधों को हल्का सक्रिय रखो और 30 सेकंड धीरे-धीरे साँस लो।", "आराम से नीचे उतरो, 30 से 60 सेकंड आराम करो और 3 सेट करो।"], ["लटकते समय झूलना या पैर चलाना।", "आराम से उतरने की बजाय बार को एकदम छोड़ देना।"], "कम समय से शुरू करो और हर हफ़्ते कुछ सेकंड बढ़ाओ।"),
    "nl": ExerciseGuide(["Pak de stang met een bovenhandse greep, handen op schouderbreedte.", "Til je voeten op en laat je lichaam recht en ontspannen hangen.", "Houd je schouders licht aangespannen en adem 30 seconden rustig door.", "Stap rustig af, rust 30 tot 60 seconden en doe in totaal 3 sets."], ["Zwaaien of schoppen met je benen tijdens het hangen.", "Je van de stang laten vallen in plaats van rustig af te stappen."], "Begin met korter hangen en tel er elke week een paar seconden bij op."),
    "pl": ExerciseGuide(["Chwyć drążek nachwytem, dłonie na szerokość barków.", "Unieś stopy i pozwól ciału zwisać prosto i swobodnie.", "Lekko napnij barki i oddychaj powoli przez 30 sekund.", "Delikatnie zejdź, odpocznij 30-60 sekund i powtórz, łącznie 3 serie."], ["Bujanie się lub machanie nogami w zwisie.", "Puszczanie drążka i spadanie zamiast spokojnego zejścia."], "Zacznij od krótszych zwisów i co tydzień dodawaj kilka sekund."),
    "sv": ExerciseGuide(["Greppa stången med överhandsgrepp, händerna axelbrett isär.", "Lyft fötterna och låt kroppen hänga rakt och avslappnat.", "Håll axlarna lätt aktiva och andas lugnt i 30 sekunder.", "Kliv ned försiktigt, vila 30–60 sekunder och upprepa i 3 set."], ["Att svinga eller sparka med benen medan du hänger.", "Att släppa stången och falla ned i stället för att kliva ned."], "Börja med kortare häng och lägg till några sekunder varje vecka."),
  },
  "cobra_stretch": {
    "en": ExerciseGuide(["Lie face down with your hands flat under your shoulders.", "Press the floor away and lift your chest slowly, hips stay down.", "Keep your elbows slightly bent and shoulders away from your ears.", "Hold 15 seconds, breathing slowly, then lower down with control."], ["Pushing up so high that your lower back pinches.", "Shrugging your shoulders up toward your ears."], "Lift only as high as feels comfortable; it deepens with practice."),
    "tr": ExerciseGuide(["Yüzüstü uzan, avuçlarını omuzlarının altına düz koy.", "Yeri iterek göğsünü yavaşça kaldır, kalçan yerde kalsın.", "Dirseklerini hafif bükük, omuzlarını kulaklarından uzak tut.", "Yavaş nefeslerle 15 saniye tut, sonra kontrollü şekilde in."], ["Belin sıkışacak kadar yükseğe itmek.", "Omuzları kulaklara doğru kaldırmak."], "Sadece rahat hissettiğin kadar kalk, pratik yaptıkça kendiliğinden derinleşir."),
    "de": ExerciseGuide(["Leg dich auf den Bauch, Hände flach unter den Schultern.", "Drück dich vom Boden weg und heb langsam die Brust, die Hüfte bleibt unten.", "Halte die Ellbogen leicht gebeugt und die Schultern weg von den Ohren.", "Halte 15 Sekunden mit ruhigem Atem und senk dich kontrolliert ab."], ["So weit hochdrücken, dass es im unteren Rücken zwickt.", "Die Schultern zu den Ohren hochziehen."], "Geh nur so hoch, wie es sich gut anfühlt; mit Übung wird es von selbst tiefer."),
    "fr": ExerciseGuide(["Allonge-toi sur le ventre, mains à plat sous les épaules.", "Pousse dans le sol et soulève lentement la poitrine, hanches au sol.", "Garde les coudes un peu pliés et les épaules loin des oreilles.", "Tiens 15 secondes en respirant lentement, puis redescends en contrôle."], ["Monter si haut que le bas du dos se pince.", "Remonter les épaules vers les oreilles."], "Monte seulement jusqu'où c'est confortable, la souplesse vient avec la pratique."),
    "es": ExerciseGuide(["Acuéstate boca abajo con las manos planas bajo los hombros.", "Empuja el suelo y eleva el pecho despacio, la cadera sigue apoyada.", "Mantén los codos algo flexionados y los hombros lejos de las orejas.", "Aguanta 15 segundos respirando lento y baja con control."], ["Subir tanto que te molesta la zona lumbar.", "Encoger los hombros hacia las orejas."], "Sube solo hasta donde estés cómodo; con la práctica irás más lejos."),
    "it": ExerciseGuide(["Sdraiati a pancia in giù con le mani piatte sotto le spalle.", "Spingi contro il pavimento e solleva piano il petto, il bacino resta giù.", "Tieni i gomiti un po' piegati e le spalle lontane dalle orecchie.", "Tieni 15 secondi respirando piano, poi scendi con controllo."], ["Salire così tanto da sentire fastidio nella zona lombare.", "Alzare le spalle verso le orecchie."], "Sali solo finché stai comodo; con la pratica andrai più in alto."),
    "pt": ExerciseGuide(["Deite de bruços com as mãos espalmadas embaixo dos ombros.", "Empurre o chão e levante o peito devagar, mantendo o quadril no chão.", "Mantenha os cotovelos levemente dobrados e os ombros longe das orelhas.", "Segure 15 segundos respirando devagar e desça com controle."], ["Subir tanto que incomoda a lombar.", "Encolher os ombros em direção às orelhas."], "Suba só até onde for confortável; com a prática você vai mais longe."),
    "hi": ExerciseGuide(["पेट के बल लेट जाओ, हथेलियाँ कंधों के नीचे ज़मीन पर रखो।", "ज़मीन को दबाओ और छाती को धीरे से उठाओ, कूल्हे नीचे ही रहें।", "कोहनियाँ हल्की मुड़ी रखो और कंधों को कानों से दूर रखो।", "धीमी साँसों के साथ 15 सेकंड रुको, फिर आराम से नीचे आओ।"], ["इतना ऊपर उठना कि कमर के निचले हिस्से में चुभन हो।", "कंधों को कानों की ओर उचकाना।"], "उतना ही उठो जितना आरामदायक लगे, अभ्यास से यह अपने आप बढ़ेगा।"),
    "nl": ExerciseGuide(["Ga op je buik liggen met je handen plat onder je schouders.", "Duw de vloer van je af en til langzaam je borst op, je heupen blijven liggen.", "Houd je ellebogen licht gebogen en je schouders weg van je oren.", "Houd 15 seconden vast terwijl je rustig ademt en zak dan gecontroleerd terug."], ["Zo hoog opdrukken dat je onderrug knelt.", "Je schouders optrekken naar je oren."], "Kom maar zo hoog als prettig voelt; met oefenen gaat het vanzelf verder."),
    "pl": ExerciseGuide(["Połóż się na brzuchu, dłonie płasko pod barkami.", "Odepchnij się od podłogi i powoli unieś klatkę piersiową, biodra zostają na ziemi.", "Łokcie lekko ugięte, barki z dala od uszu.", "Wytrzymaj 15 sekund, oddychając powoli, potem opuść się z kontrolą."], ["Unoszenie się tak wysoko, że czujesz ucisk w dolnej części pleców.", "Podciąganie barków w stronę uszu."], "Unoś się tylko tak wysoko, jak jest ci wygodnie; z praktyką ruch się pogłębi."),
    "sv": ExerciseGuide(["Ligg på mage med händerna platt under axlarna.", "Pressa ifrån golvet och lyft bröstet långsamt, höfterna ligger kvar.", "Håll armbågarna lätt böjda och axlarna borta från öronen.", "Håll i 15 sekunder och andas lugnt, sänk dig sedan kontrollerat."], ["Att pressa upp så högt att det nyper i ländryggen.", "Att dra upp axlarna mot öronen."], "Lyft bara så högt som känns bekvämt – rörligheten ökar med träning."),
  },
  "jumping": {
    "en": ExerciseGuide(["Stand with feet hip-width apart and arms relaxed at your sides.", "Bend your knees, swing your arms and jump straight up.", "Land softly on the balls of your feet with knees slightly bent.", "Do 20 jumps, rest 30 seconds, and repeat for 3 sets."], ["Landing stiff-legged on your heels.", "Letting your knees cave inward on landing."], "Quiet landings mean good control, so try to land like a cat."),
    "tr": ExerciseGuide(["Ayaklarını kalça genişliğinde aç, kolların yanlarda gevşek dursun.", "Dizlerini bük, kollarını savur ve dümdüz yukarı zıpla.", "Dizlerin hafif bükük, ayak tabanının ön kısmına yumuşakça kon.", "20 kez zıpla, 30 saniye dinlen ve 3 set tekrarla."], ["Kaskatı bacaklarla topukların üstüne inmek.", "İnişte dizlerin içe doğru kapanmasına izin vermek."], "Sessiz iniş iyi kontrol demek, bir kedi gibi konmaya çalış."),
    "de": ExerciseGuide(["Stell die Füße hüftbreit hin, die Arme hängen locker.", "Beug die Knie, schwing die Arme und spring gerade nach oben.", "Lande weich auf den Fußballen, die Knie leicht gebeugt.", "Mach 20 Sprünge, 30 Sekunden Pause und insgesamt 3 Sätze."], ["Mit steifen Beinen auf den Fersen landen.", "Bei der Landung die Knie nach innen knicken lassen."], "Leise Landungen zeigen gute Kontrolle, also lande wie eine Katze."),
    "fr": ExerciseGuide(["Place tes pieds à largeur de hanches, bras relâchés le long du corps.", "Plie les genoux, balance les bras et saute bien droit vers le haut.", "Atterris en douceur sur l'avant des pieds, genoux légèrement fléchis.", "Fais 20 sauts, repose-toi 30 secondes et enchaîne 3 séries."], ["Atterrir jambes raides sur les talons.", "Laisser les genoux rentrer vers l'intérieur à la réception."], "Un atterrissage silencieux, c'est du contrôle, alors retombe comme un chat."),
    "es": ExerciseGuide(["Separa los pies al ancho de la cadera, brazos relajados a los lados.", "Flexiona las rodillas, balancea los brazos y salta recto hacia arriba.", "Aterriza suave sobre la parte delantera del pie, rodillas algo flexionadas.", "Haz 20 saltos, descansa 30 segundos y repite 3 series."], ["Caer con las piernas rígidas sobre los talones.", "Dejar que las rodillas se vayan hacia dentro al caer."], "Caer sin hacer ruido es señal de control, así que aterriza como un gato."),
    "it": ExerciseGuide(["Metti i piedi alla larghezza del bacino, braccia rilassate lungo il corpo.", "Piega le ginocchia, slancia le braccia e salta dritto verso l'alto.", "Atterra morbido sull'avampiede, ginocchia leggermente piegate.", "Fai 20 salti, riposa 30 secondi e ripeti per 3 serie."], ["Atterrare a gambe rigide sui talloni.", "Lasciare che le ginocchia vadano verso l'interno all'atterraggio."], "Un atterraggio silenzioso vuol dire controllo, quindi atterra come un gatto."),
    "pt": ExerciseGuide(["Afaste os pés na largura do quadril, braços soltos ao lado do corpo.", "Dobre os joelhos, balance os braços e salte reto para cima.", "Aterrisse suave na parte da frente dos pés, joelhos levemente dobrados.", "Faça 20 saltos, descanse 30 segundos e repita por 3 séries."], ["Cair com as pernas duras em cima dos calcanhares.", "Deixar os joelhos irem para dentro na aterrissagem."], "Aterrissar sem barulho é sinal de controle, então caia como um gato."),
    "hi": ExerciseGuide(["पैर कूल्हों जितनी चौड़ाई पर रखो, हाथ बगल में ढीले छोड़ो।", "घुटने मोड़ो, हाथ झुलाओ और सीधे ऊपर कूदो।", "पंजों के अगले हिस्से पर नरमी से उतरो, घुटने हल्के मुड़े रहें।", "20 बार कूदो, 30 सेकंड आराम करो और 3 सेट दोहराओ।"], ["अकड़े पैरों से एड़ियों पर उतरना।", "उतरते समय घुटनों को अंदर की ओर मुड़ने देना।"], "बिना आवाज़ उतरना अच्छे कंट्रोल की निशानी है, बिल्ली की तरह उतरो।"),
    "nl": ExerciseGuide(["Sta met je voeten op heupbreedte en je armen ontspannen langs je lichaam.", "Buig je knieën, zwaai met je armen en spring recht omhoog.", "Land zacht op je voorvoeten met licht gebogen knieën.", "Doe 20 sprongen, rust 30 seconden en doe in totaal 3 sets."], ["Met gestrekte benen op je hielen landen.", "Je knieën naar binnen laten knikken bij de landing."], "Een stille landing betekent goede controle, dus probeer te landen als een kat."),
    "pl": ExerciseGuide(["Stań ze stopami na szerokość bioder, ręce luźno wzdłuż ciała.", "Ugnij kolana, zrób zamach rękami i wyskocz prosto w górę.", "Ląduj miękko na przodostopiu, z lekko ugiętymi kolanami.", "Zrób 20 skoków, odpocznij 30 sekund i powtórz, łącznie 3 serie."], ["Lądowanie na sztywnych nogach, na piętach.", "Uciekanie kolan do środka przy lądowaniu."], "Ciche lądowanie oznacza dobrą kontrolę, więc staraj się lądować jak kot."),
    "sv": ExerciseGuide(["Stå med fötterna höftbrett isär och armarna avslappnade längs sidorna.", "Böj knäna, svinga armarna och hoppa rakt upp.", "Landa mjukt på framfoten med lätt böjda knän.", "Gör 20 hopp, vila 30 sekunder och upprepa i 3 set."], ["Att landa på hälarna med raka ben.", "Att låta knäna falla inåt när du landar."], "Tysta landningar betyder bra kontroll, så försök landa som en katt."),
  },
  "swimming_basketball": {
    "en": ExerciseGuide(["Warm up for 5 minutes with easy laps or light dribbling.", "Swim or play for at least 30 minutes at a steady pace.", "Reach fully on every stroke, shot or rebound.", "Cool down with 5 minutes of easy movement and stretching."], ["Skipping the warm-up and starting at full speed.", "Forgetting to drink water while you play."], "Bring a friend; sport is easier to keep up when it is social."),
    "tr": ExerciseGuide(["5 dakika hafif kulaçlarla ya da yavaş top sürerek ısın.", "En az 30 dakika sabit bir tempoyla yüz ya da oyna.", "Her kulaçta, şutta ve ribauntta tam uzan.", "5 dakika hafif hareket ve esnemeyle soğuma yap."], ["Isınmayı atlayıp direkt tam hızla başlamak.", "Oynarken su içmeyi unutmak."], "Bir arkadaşını da çağır, spor birlikte yapılınca daha kolay devam eder."),
    "de": ExerciseGuide(["Wärm dich 5 Minuten mit lockeren Bahnen oder leichtem Dribbeln auf.", "Schwimm oder spiel mindestens 30 Minuten in gleichmäßigem Tempo.", "Streck dich bei jedem Zug, Wurf oder Rebound voll aus.", "Kühl dich 5 Minuten mit lockerer Bewegung und Dehnen ab."], ["Das Aufwärmen auslassen und sofort Vollgas geben.", "Beim Spielen das Trinken vergessen."], "Nimm einen Freund mit, zusammen bleibt man leichter dran."),
    "fr": ExerciseGuide(["Échauffe-toi 5 minutes avec des longueurs tranquilles ou du dribble léger.", "Nage ou joue au moins 30 minutes à un rythme régulier.", "Allonge-toi complètement à chaque mouvement de bras, tir ou rebond.", "Récupère avec 5 minutes de mouvements légers et d'étirements."], ["Sauter l'échauffement et partir à fond.", "Oublier de boire pendant que tu joues."], "Emmène un ami, le sport à plusieurs est plus facile à tenir."),
    "es": ExerciseGuide(["Calienta 5 minutos con largos suaves o botando el balón despacio.", "Nada o juega al menos 30 minutos a un ritmo constante.", "Estírate por completo en cada brazada, tiro o rebote.", "Vuelve a la calma con 5 minutos de movimiento suave y estiramientos."], ["Saltarte el calentamiento y empezar a tope.", "Olvidarte de beber agua mientras juegas."], "Invita a un amigo; el deporte en compañía se mantiene mejor."),
    "it": ExerciseGuide(["Scaldati 5 minuti con vasche tranquille o palleggi leggeri.", "Nuota o gioca per almeno 30 minuti a ritmo costante.", "Allungati del tutto a ogni bracciata, tiro o rimbalzo.", "Defaticati con 5 minuti di movimento leggero e stretching."], ["Saltare il riscaldamento e partire a tutta.", "Dimenticarti di bere mentre giochi."], "Porta un amico; lo sport in compagnia si mantiene più facilmente."),
    "pt": ExerciseGuide(["Aqueça por 5 minutos com voltas leves na piscina ou batendo bola devagar.", "Nade ou jogue por pelo menos 30 minutos em ritmo constante.", "Estique o corpo todo em cada braçada, arremesso ou rebote.", "Desaqueça com 5 minutos de movimento leve e alongamento."], ["Pular o aquecimento e começar com tudo.", "Esquecer de beber água durante o jogo."], "Chame um amigo; esporte em grupo é mais fácil de manter."),
    "hi": ExerciseGuide(["5 मिनट हल्की तैराकी या धीमी ड्रिबलिंग से वार्म-अप करो।", "कम से कम 30 मिनट एक जैसी रफ़्तार से तैरो या खेलो।", "हर स्ट्रोक, शॉट या रिबाउंड में शरीर को पूरा खींचो।", "5 मिनट हल्की हरकत और स्ट्रेचिंग से कूल-डाउन करो।"], ["वार्म-अप छोड़कर सीधे पूरी रफ़्तार से शुरू करना।", "खेलते समय पानी पीना भूल जाना।"], "किसी दोस्त को साथ लाओ, साथ में खेलना जारी रखना आसान होता है।"),
    "nl": ExerciseGuide(["Warm 5 minuten op met rustige baantjes of licht dribbelen.", "Zwem of speel minstens 30 minuten in een constant tempo.", "Reik volledig uit bij elke slag, elk schot en elke rebound.", "Koel af met 5 minuten rustig bewegen en stretchen."], ["De warming-up overslaan en meteen op volle snelheid beginnen.", "Vergeten water te drinken tijdens het spelen."], "Neem een vriend mee; sporten hou je makkelijker vol als je het samen doet."),
    "pl": ExerciseGuide(["Rozgrzej się przez 5 minut spokojnym pływaniem albo lekkim kozłowaniem.", "Pływaj lub graj co najmniej 30 minut w równym tempie.", "Sięgaj w pełnym zakresie przy każdym ruchu ramion, rzucie czy zbiórce.", "Na koniec wycisz się przez 5 minut spokojnym ruchem i rozciąganiem."], ["Pomijanie rozgrzewki i start od razu na pełnej prędkości.", "Zapominanie o piciu wody w trakcie gry."], "Weź ze sobą znajomego; łatwiej trzymać się sportu, gdy uprawiasz go z kimś."),
    "sv": ExerciseGuide(["Värm upp i 5 minuter med lugna längder eller lätt dribbling.", "Simma eller spela i minst 30 minuter i jämnt tempo.", "Sträck ut helt i varje simtag, skott eller retur.", "Varva ned med 5 minuter lugn rörelse och stretch."], ["Att hoppa över uppvärmningen och köra för fullt direkt.", "Att glömma att dricka vatten medan du spelar."], "Ta med en kompis – det är lättare att hålla i gång när man tränar tillsammans."),
  },
  "evening_yoga": {
    "en": ExerciseGuide(["Start on hands and knees and flow through cat-cow for 60 seconds.", "Sit back into child's pose, arms long, and breathe for 60 seconds.", "Press up into downward dog, heels reaching toward the floor.", "Stand and fold forward, letting your head hang heavy.", "Breathe in for 4 counts and out for 6 counts in every pose."], ["Rushing between poses instead of holding them.", "Forcing a pose until it hurts."], "Dim the lights while you flow to help your body wind down."),
    "tr": ExerciseGuide(["Ellerin ve dizlerin üzerinde başla, 60 saniye kedi-inek akışı yap.", "Çocuk pozuna geç, kollarını öne uzat ve 60 saniye nefes al.", "Aşağı bakan köpek pozuna geç, topuklarını yere doğru uzat.", "Ayakta öne eğil ve başını ağırlığıyla serbest bırak.", "Her pozda 4 sayıda nefes al, 6 sayıda ver."], ["Pozları tutmak yerine aceleyle geçmek.", "Bir pozu canın yanana kadar zorlamak."], "Akış sırasında ışıkları kıs, vücudun gevşemeye hazırlansın."),
    "de": ExerciseGuide(["Starte im Vierfüßlerstand und geh 60 Sekunden fließend durch Katze-Kuh.", "Setz dich in die Kindhaltung, Arme lang, und atme 60 Sekunden.", "Drück dich in den herabschauenden Hund, Fersen Richtung Boden.", "Beug dich im Stehen nach vorn und lass den Kopf schwer hängen.", "Atme in jeder Haltung 4 Zählzeiten ein und 6 aus."], ["Durch die Haltungen hetzen, statt sie zu halten.", "Eine Haltung erzwingen, bis es wehtut."], "Dimm dabei das Licht, damit dein Körper runterfahren kann."),
    "fr": ExerciseGuide(["Commence à quatre pattes et enchaîne chat-vache pendant 60 secondes.", "Assieds-toi en posture de l'enfant, bras tendus, et respire 60 secondes.", "Pousse en chien tête en bas, talons vers le sol.", "Debout, penche-toi en avant et laisse ta tête pendre lourdement.", "Inspire sur 4 temps et expire sur 6 temps dans chaque posture."], ["Enchaîner les postures trop vite sans les tenir.", "Forcer une posture jusqu'à avoir mal."], "Baisse la lumière pendant la séance pour aider ton corps à se détendre."),
    "es": ExerciseGuide(["Empieza en cuatro apoyos y fluye en gato-vaca durante 60 segundos.", "Siéntate en la postura del niño, brazos estirados, y respira 60 segundos.", "Empuja hacia el perro boca abajo, talones hacia el suelo.", "De pie, inclínate hacia delante y deja que la cabeza cuelgue pesada.", "Inhala en 4 tiempos y exhala en 6 en cada postura."], ["Pasar rápido de una postura a otra sin mantenerlas.", "Forzar una postura hasta que duela."], "Baja las luces mientras practicas para que tu cuerpo se relaje."),
    "it": ExerciseGuide(["Parti a quattro zampe e alterna gatto e mucca per 60 secondi.", "Siediti nella posizione del bambino, braccia lunghe, e respira 60 secondi.", "Spingi nel cane a testa in giù, talloni verso il pavimento.", "In piedi, piegati in avanti e lascia la testa pesante.", "Inspira in 4 tempi ed espira in 6 in ogni posizione."], ["Passare di fretta da una posizione all'altra senza tenerle.", "Forzare una posizione fino a sentire dolore."], "Abbassa le luci mentre pratichi per aiutare il corpo a rilassarsi."),
    "pt": ExerciseGuide(["Comece em quatro apoios e faça o gato-vaca por 60 segundos.", "Sente na postura da criança, braços esticados, e respire por 60 segundos.", "Empurre para o cachorro olhando para baixo, calcanhares em direção ao chão.", "Em pé, incline o tronco para frente e deixe a cabeça pender pesada.", "Inspire em 4 tempos e expire em 6 em cada postura."], ["Passar correndo pelas posturas sem segurar.", "Forçar uma postura até doer."], "Diminua as luzes durante a prática para ajudar o corpo a relaxar."),
    "hi": ExerciseGuide(["हाथों और घुटनों के बल शुरू करो और 60 सेकंड कैट-काउ करो।", "बालासन में बैठो, हाथ आगे फैलाओ और 60 सेकंड साँस लो।", "अधोमुख श्वानासन में जाओ, एड़ियाँ ज़मीन की ओर रखो।", "खड़े होकर आगे झुको और सिर को ढीला लटकने दो।", "हर आसन में 4 गिनती तक साँस लो और 6 गिनती तक छोड़ो।"], ["आसन में रुकने की बजाय जल्दी-जल्दी बदलना।", "किसी आसन को दर्द होने तक ज़बरदस्ती करना।"], "अभ्यास के दौरान रोशनी धीमी कर दो ताकि शरीर शांत हो सके।"),
    "nl": ExerciseGuide(["Begin op handen en knieën en beweeg 60 seconden rustig door kat-koe.", "Zak terug in de kindhouding, armen lang naar voren, en adem 60 seconden.", "Duw jezelf omhoog in neerwaartse hond, hielen richting de vloer.", "Kom staan en vouw voorover, laat je hoofd zwaar hangen.", "Adem in elke houding 4 tellen in en 6 tellen uit."], ["Van houding naar houding haasten in plaats van ze vast te houden.", "Een houding forceren tot het pijn doet."], "Dim het licht terwijl je beweegt, zo kan je lichaam tot rust komen."),
    "pl": ExerciseGuide(["Zacznij w klęku podpartym i przez 60 sekund płynnie wykonuj koci grzbiet.", "Usiądź na piętach w pozycji dziecka, ręce wyciągnięte, i oddychaj przez 60 sekund.", "Wypchnij się do psa z głową w dół, pięty sięgają w stronę podłogi.", "Wstań i zrób skłon w przód, pozwalając głowie swobodnie zwisać.", "W każdej pozycji rób wdech na 4 i wydech na 6."], ["Pośpieszne przechodzenie między pozycjami zamiast ich utrzymania.", "Wchodzenie w pozycję na siłę, aż zaboli."], "Przygaś światło podczas ćwiczeń, by pomóc ciału się wyciszyć."),
    "sv": ExerciseGuide(["Börja på alla fyra och gör katt-ko i 60 sekunder.", "Sätt dig bakåt i barnets position med långa armar och andas i 60 sekunder.", "Pressa upp till nedåtgående hund med hälarna mot golvet.", "Res dig och fäll framåt, låt huvudet hänga tungt.", "Andas in på 4 och ut på 6 i varje position."], ["Att stressa mellan positionerna i stället för att stanna i dem.", "Att tvinga dig in i en position tills det gör ont."], "Dämpa belysningen medan du kör, så hjälper du kroppen att varva ned."),
  },
  "sprint_intervals": {
    "en": ExerciseGuide(["Warm up with 5 minutes of easy jogging and leg swings.", "Sprint at full effort for 30 seconds, pumping your arms.", "Walk or jog slowly for 90 seconds to recover.", "Repeat for 3 sprints, then cool down with 5 minutes of walking."], ["Sprinting without warming up first.", "Leaning back and overstriding instead of driving forward."], "Pick a flat, safe surface and go all out only when you feel fresh."),
    "tr": ExerciseGuide(["5 dakika hafif koşu ve bacak sallamalarıyla ısın.", "30 saniye tüm gücünle depar at, kollarını güçlü salla.", "Toparlanmak için 90 saniye yürü ya da yavaş koş.", "3 depar tamamla, sonra 5 dakika yürüyerek soğuma yap."], ["Isınmadan depara kalkmak.", "Öne doğru itmek yerine geriye yaslanıp adımı fazla açmak."], "Düz ve güvenli bir zemin seç, tam gücü sadece dinçken ver."),
    "de": ExerciseGuide(["Wärm dich 5 Minuten mit lockerem Joggen und Beinschwüngen auf.", "Sprinte 30 Sekunden mit voller Kraft und arbeite kräftig mit den Armen.", "Geh oder jogge 90 Sekunden locker, um dich zu erholen.", "Mach 3 Sprints und geh danach 5 Minuten zum Abkühlen."], ["Ohne Aufwärmen lossprinten.", "Nach hinten lehnen und viel zu große Schritte machen."], "Such dir einen ebenen, sicheren Untergrund und gib nur Vollgas, wenn du frisch bist."),
    "fr": ExerciseGuide(["Échauffe-toi 5 minutes avec un footing léger et des balancés de jambes.", "Sprinte à fond pendant 30 secondes en poussant fort avec les bras.", "Marche ou trottine 90 secondes pour récupérer.", "Fais 3 sprints, puis marche 5 minutes pour revenir au calme."], ["Sprinter sans t'échauffer.", "Te pencher en arrière avec des foulées trop longues."], "Choisis une surface plate et sûre, et donne tout seulement quand tu es frais."),
    "es": ExerciseGuide(["Calienta 5 minutos trotando suave y con balanceos de piernas.", "Esprinta 30 segundos a máximo esfuerzo, moviendo fuerte los brazos.", "Camina o trota suave 90 segundos para recuperarte.", "Haz 3 sprints y luego camina 5 minutos para enfriar."], ["Esprintar sin calentar antes.", "Echarte hacia atrás y dar zancadas demasiado largas."], "Busca una superficie plana y segura, y da el máximo solo cuando estés fresco."),
    "it": ExerciseGuide(["Scaldati 5 minuti con corsa leggera e slanci delle gambe.", "Scatta al massimo per 30 secondi, spingendo forte con le braccia.", "Cammina o corri piano per 90 secondi per recuperare.", "Fai 3 scatti, poi cammina 5 minuti per defaticarti."], ["Scattare senza esserti scaldato.", "Inclinarti indietro e fare passi troppo lunghi."], "Scegli una superficie piana e sicura e spingi al massimo solo quando sei fresco."),
    "pt": ExerciseGuide(["Aqueça por 5 minutos com trote leve e balanços de perna.", "Corra no máximo por 30 segundos, movendo bem os braços.", "Caminhe ou trote devagar por 90 segundos para se recuperar.", "Faça 3 tiros e depois caminhe 5 minutos para desaquecer."], ["Dar tiros sem aquecer antes.", "Inclinar o corpo para trás e dar passadas longas demais."], "Escolha um piso plano e seguro e só vá no máximo quando estiver descansado."),
    "hi": ExerciseGuide(["5 मिनट हल्की जॉगिंग और पैर झुलाकर वार्म-अप करो।", "30 सेकंड पूरी ताकत से दौड़ो, हाथों को ज़ोर से चलाओ।", "रिकवरी के लिए 90 सेकंड चलो या धीरे जॉग करो।", "3 स्प्रिंट पूरे करो, फिर 5 मिनट चलकर कूल-डाउन करो।"], ["बिना वार्म-अप के स्प्रिंट करना।", "पीछे झुककर बहुत लंबे कदम रखना।"], "समतल और सुरक्षित जगह चुनो, और पूरी ताकत तभी लगाओ जब ताज़ा महसूस करो।"),
    "nl": ExerciseGuide(["Warm 5 minuten op met rustig joggen en beenzwaaien.", "Sprint 30 seconden op volle kracht en pomp mee met je armen.", "Wandel of jog 90 seconden rustig om te herstellen.", "Herhaal tot je 3 sprints hebt gedaan en koel daarna af met 5 minuten wandelen."], ["Sprinten zonder eerst op te warmen.", "Achterover leunen en te grote passen maken in plaats van naar voren te duwen."], "Kies een vlakke, veilige ondergrond en ga alleen voluit als je je fit voelt."),
    "pl": ExerciseGuide(["Rozgrzej się przez 5 minut spokojnym truchtem i wymachami nóg.", "Sprintuj z pełnym wysiłkiem przez 30 sekund, mocno pracując rękami.", "Idź lub powoli truchtaj przez 90 sekund, by odpocząć.", "Powtórz, łącznie 3 sprinty, potem wycisz się 5-minutowym marszem."], ["Sprintowanie bez wcześniejszej rozgrzewki.", "Odchylanie się do tyłu i za długie kroki zamiast mocnego napędu do przodu."], "Wybierz płaską, bezpieczną nawierzchnię i dawaj z siebie wszystko tylko wtedy, gdy masz świeże siły."),
    "sv": ExerciseGuide(["Värm upp med 5 minuters lätt jogg och bensvingar.", "Spurta för fullt i 30 sekunder och pumpa med armarna.", "Gå eller jogga lugnt i 90 sekunder för att återhämta dig.", "Gör 3 spurter och varva sedan ned med 5 minuters promenad."], ["Att spurta utan att värma upp först.", "Att luta dig bakåt och ta för långa steg i stället för att driva framåt."], "Välj ett plant och säkert underlag och kör bara för fullt när du känner dig pigg."),
  },
  "hiit_workout": {
    "en": ExerciseGuide(["Warm up for 3 minutes with marching in place and arm circles.", "Do burpees, mountain climbers and jump squats, 45 seconds each.", "Rest 15 seconds between moves and breathe deeply.", "Complete 4 rounds, then walk slowly until your breathing settles."], ["Letting your form slip to go faster.", "Holding your breath during the hard intervals."], "Go at your own pace; finishing all 4 rounds beats a fast start."),
    "tr": ExerciseGuide(["3 dakika yerinde yürüyüp kol çevirerek ısın.", "Burpee, mountain climber ve squat jump yap, her biri 45 saniye.", "Hareketler arasında 15 saniye dinlen ve derin nefes al.", "4 tur tamamla, sonra nefesin düzelene kadar yavaşça yürü."], ["Hızlanmak için formu bozmak.", "Zor aralıklarda nefesini tutmak."], "Kendi temponda git, 4 turu bitirmek hızlı başlamaktan daha değerli."),
    "de": ExerciseGuide(["Wärm dich 3 Minuten mit Marschieren auf der Stelle und Armkreisen auf.", "Mach Burpees, Mountain Climbers und Squat Jumps, je 45 Sekunden.", "Ruh dich zwischen den Übungen 15 Sekunden aus und atme tief.", "Schaff 4 Runden und geh danach locker, bis dein Atem ruhig ist."], ["Für mehr Tempo die saubere Technik aufgeben.", "In den harten Intervallen die Luft anhalten."], "Geh dein eigenes Tempo; alle 4 Runden zu schaffen schlägt einen schnellen Start."),
    "fr": ExerciseGuide(["Échauffe-toi 3 minutes en marchant sur place avec des cercles de bras.", "Fais des burpees, des mountain climbers et des squats sautés, 45 secondes chacun.", "Repose-toi 15 secondes entre les exercices en respirant profondément.", "Termine 4 tours, puis marche doucement jusqu'à retrouver ton souffle."], ["Sacrifier la technique pour aller plus vite.", "Bloquer ta respiration pendant les efforts intenses."], "Va à ton rythme, finir les 4 tours vaut mieux qu'un départ trop rapide."),
    "es": ExerciseGuide(["Calienta 3 minutos marchando en el sitio y haciendo círculos con los brazos.", "Haz burpees, escaladores y sentadillas con salto, 45 segundos cada uno.", "Descansa 15 segundos entre ejercicios y respira hondo.", "Completa 4 rondas y camina despacio hasta que se calme tu respiración."], ["Sacrificar la técnica para ir más rápido.", "Aguantar la respiración en los intervalos duros."], "Ve a tu ritmo; terminar las 4 rondas vale más que empezar rápido."),
    "it": ExerciseGuide(["Scaldati 3 minuti marciando sul posto e facendo cerchi con le braccia.", "Fai burpees, mountain climber e squat jump, 45 secondi ciascuno.", "Riposa 15 secondi tra un esercizio e l'altro e respira a fondo.", "Completa 4 giri, poi cammina piano finché il respiro si calma."], ["Sacrificare la tecnica per andare più veloce.", "Trattenere il respiro negli intervalli più duri."], "Vai al tuo ritmo; finire tutti e 4 i giri batte una partenza veloce."),
    "pt": ExerciseGuide(["Aqueça por 3 minutos marchando no lugar e girando os braços.", "Faça burpees, escalador e agachamento com salto, 45 segundos cada.", "Descanse 15 segundos entre os exercícios e respire fundo.", "Complete 4 rodadas e caminhe devagar até a respiração acalmar."], ["Sacrificar a técnica para ir mais rápido.", "Prender a respiração nos intervalos mais fortes."], "Vá no seu ritmo; terminar as 4 rodadas vale mais que começar rápido."),
    "hi": ExerciseGuide(["3 मिनट एक जगह मार्च करके और हाथ घुमाकर वार्म-अप करो।", "बर्पी, माउंटेन क्लाइंबर और जंप स्क्वैट करो, हर एक 45 सेकंड।", "हर एक्सरसाइज़ के बीच 15 सेकंड आराम करो और गहरी साँस लो।", "4 राउंड पूरे करो, फिर साँस सामान्य होने तक धीरे चलो।"], ["तेज़ी के चक्कर में सही फ़ॉर्म छोड़ देना।", "मुश्किल अंतराल में साँस रोक लेना।"], "अपनी रफ़्तार से करो, चारों राउंड पूरे करना तेज़ शुरुआत से बेहतर है।"),
    "nl": ExerciseGuide(["Warm 3 minuten op door op de plaats te marcheren en armcirkels te maken.", "Doe burpees, mountain climbers en jump squats, elk 45 seconden.", "Rust 15 seconden tussen de oefeningen en adem diep.", "Doe 4 rondes en wandel daarna rustig tot je ademhaling tot rust komt."], ["Je techniek laten verslappen om sneller te gaan.", "Je adem inhouden tijdens de zware intervallen."], "Ga in je eigen tempo; alle 4 rondes afmaken is beter dan een snelle start."),
    "pl": ExerciseGuide(["Rozgrzej się przez 3 minuty marszem w miejscu i krążeniami ramion.", "Rób burpees, wspinaczkę i wyskoki z przysiadu, po 45 sekund każde ćwiczenie.", "Odpoczywaj 15 sekund między ćwiczeniami i oddychaj głęboko.", "Zrób 4 rundy, potem spokojnie chodź, aż oddech się uspokoi."], ["Psucie techniki, żeby było szybciej.", "Wstrzymywanie oddechu w trudnych interwałach."], "Ćwicz we własnym tempie; ukończenie wszystkich 4 rund jest lepsze niż szybki start."),
    "sv": ExerciseGuide(["Värm upp i 3 minuter med marsch på stället och armcirklar.", "Gör burpees, mountain climbers och knäböjshopp, 45 sekunder vardera.", "Vila 15 sekunder mellan övningarna och andas djupt.", "Gör 4 varv och gå sedan lugnt tills andningen har lugnat sig."], ["Att slarva med tekniken för att gå snabbare.", "Att hålla andan under de tunga intervallerna."], "Kör i ditt eget tempo – att klara alla 4 varv slår en snabb start."),
  },
  "squats": {
    "en": ExerciseGuide(["Stand with feet shoulder-width apart, toes turned slightly out.", "Push your hips back and lower until your thighs are parallel to the floor.", "Keep your chest up and your knees in line with your toes.", "Press through your heels to stand, breathing out on the way up."], ["Lifting your heels off the floor.", "Rounding your back at the bottom."], "Do your first sets in front of a mirror to check your form."),
    "tr": ExerciseGuide(["Ayaklarını omuz genişliğinde aç, parmak uçların hafif dışa baksın.", "Kalçanı geriye it, uylukların yere paralel olana kadar in.", "Göğsünü dik tut, dizlerin ayak parmaklarınla aynı yöne baksın.", "Topuklarından iterek kalk, kalkarken nefes ver."], ["Topukları yerden kaldırmak.", "En altta sırtı yuvarlamak."], "İlk setleri ayna karşısında yap, formunu kolayca kontrol edersin."),
    "de": ExerciseGuide(["Stell die Füße schulterbreit hin, die Zehen zeigen leicht nach außen.", "Schieb die Hüfte nach hinten und geh runter, bis die Oberschenkel parallel zum Boden sind.", "Halte die Brust oben und die Knie in Richtung Zehen.", "Drück dich über die Fersen hoch und atme dabei aus."], ["Die Fersen vom Boden heben.", "Unten den Rücken rund machen."], "Mach die ersten Sätze vor dem Spiegel, um deine Technik zu checken."),
    "fr": ExerciseGuide(["Place tes pieds à largeur d'épaules, pointes légèrement vers l'extérieur.", "Pousse les hanches en arrière et descends jusqu'à avoir les cuisses parallèles au sol.", "Garde la poitrine haute et les genoux dans l'axe des orteils.", "Pousse sur les talons pour remonter en expirant."], ["Décoller les talons du sol.", "Arrondir le dos en bas du mouvement."], "Fais tes premières séries face à un miroir pour vérifier ta technique."),
    "es": ExerciseGuide(["Separa los pies al ancho de los hombros, puntas un poco hacia fuera.", "Lleva la cadera atrás y baja hasta que los muslos queden paralelos al suelo.", "Mantén el pecho arriba y las rodillas en línea con los pies.", "Empuja con los talones para subir y suelta el aire al subir."], ["Levantar los talones del suelo.", "Redondear la espalda abajo."], "Haz las primeras series frente a un espejo para revisar tu técnica."),
    "it": ExerciseGuide(["Metti i piedi alla larghezza delle spalle, punte un po' in fuori.", "Porta il bacino indietro e scendi finché le cosce sono parallele al pavimento.", "Tieni il petto alto e le ginocchia in linea con le punte dei piedi.", "Spingi sui talloni per risalire ed espira mentre sali."], ["Sollevare i talloni da terra.", "Arrotondare la schiena in basso."], "Fai le prime serie davanti a uno specchio per controllare la tecnica."),
    "pt": ExerciseGuide(["Afaste os pés na largura dos ombros, pontas um pouco para fora.", "Leve o quadril para trás e desça até as coxas ficarem paralelas ao chão.", "Mantenha o peito aberto e os joelhos alinhados com os pés.", "Empurre pelos calcanhares para subir, soltando o ar na subida."], ["Tirar os calcanhares do chão.", "Arredondar as costas lá embaixo."], "Faça as primeiras séries na frente do espelho para conferir a postura."),
    "hi": ExerciseGuide(["पैर कंधों जितनी चौड़ाई पर रखो, पंजे थोड़े बाहर की ओर।", "कूल्हे पीछे धकेलो और जांघें ज़मीन के समानांतर होने तक नीचे जाओ।", "छाती ऊपर रखो और घुटनों को पैरों की उंगलियों की सीध में रखो।", "एड़ियों से ज़ोर लगाकर ऊपर आओ और उठते समय साँस छोड़ो।"], ["एड़ियाँ ज़मीन से उठा देना।", "नीचे जाकर पीठ गोल कर लेना।"], "पहले कुछ सेट शीशे के सामने करो ताकि अपना फ़ॉर्म देख सको।"),
    "nl": ExerciseGuide(["Sta met je voeten op schouderbreedte, tenen licht naar buiten.", "Duw je heupen naar achteren en zak tot je bovenbenen parallel aan de vloer zijn.", "Houd je borst omhoog en je knieën in lijn met je tenen.", "Duw door je hielen omhoog en adem uit terwijl je opkomt."], ["Je hielen van de vloer tillen.", "Je rug bol maken onderin de squat."], "Doe je eerste sets voor een spiegel om je techniek te checken."),
    "pl": ExerciseGuide(["Stań ze stopami na szerokość barków, palce lekko na zewnątrz.", "Wypchnij biodra do tyłu i opuszczaj się, aż uda będą równoległe do podłogi.", "Klatka piersiowa w górze, kolana w linii z palcami stóp.", "Wstań, odpychając się piętami, i rób wydech w drodze w górę."], ["Odrywanie pięt od podłogi.", "Zaokrąglanie pleców w dolnej pozycji."], "Pierwsze serie rób przed lustrem, by sprawdzać technikę."),
    "sv": ExerciseGuide(["Stå med fötterna axelbrett isär och tårna lätt utåtvridna.", "Skjut höfterna bakåt och sänk dig tills låren är parallella med golvet.", "Håll bröstet uppe och knäna i linje med tårna.", "Pressa ifrån med hälarna för att resa dig och andas ut på vägen upp."], ["Att lyfta hälarna från golvet.", "Att runda ryggen i bottenläget."], "Gör dina första set framför en spegel så att du kan kolla tekniken."),
  },
  "deadlift_stretch": {
    "en": ExerciseGuide(["Stand with feet hip-width apart and knees softly bent.", "Hinge at your hips and slide your hands down your thighs.", "Keep your back flat and reach toward your toes until your hamstrings stretch.", "Squeeze your glutes to stand back up, 12 slow reps per set."], ["Rounding your back to reach lower.", "Locking your knees completely straight."], "Move slowly; control matters more than how far you reach."),
    "tr": ExerciseGuide(["Ayaklarını kalça genişliğinde aç, dizlerin hafif bükük olsun.", "Kalçandan menteşe gibi eğil, ellerini uylukların boyunca aşağı kaydır.", "Sırtını düz tut, bacaklarının arkasında gerilme hissedene kadar uzan.", "Kalça kaslarını sıkarak doğrul, her sette 12 yavaş tekrar yap."], ["Daha aşağı uzanmak için sırtı yuvarlamak.", "Dizleri tamamen kilitlemek."], "Yavaş hareket et, ne kadar uzandığından çok kontrol önemli."),
    "de": ExerciseGuide(["Stell die Füße hüftbreit hin, die Knie leicht gebeugt.", "Kipp aus der Hüfte nach vorn und schieb die Hände die Oberschenkel hinab.", "Halte den Rücken gerade und reich Richtung Zehen, bis die Beinrückseite zieht.", "Spann den Po an, um dich aufzurichten, 12 langsame Wiederholungen pro Satz."], ["Den Rücken rund machen, um tiefer zu kommen.", "Die Knie komplett durchdrücken."], "Beweg dich langsam; Kontrolle zählt mehr als die Reichweite."),
    "fr": ExerciseGuide(["Place tes pieds à largeur de hanches, genoux légèrement fléchis.", "Bascule depuis les hanches en faisant glisser tes mains le long des cuisses.", "Garde le dos plat et descends vers tes orteils jusqu'à sentir l'arrière des cuisses.", "Serre les fessiers pour remonter, 12 répétitions lentes par série."], ["Arrondir le dos pour descendre plus bas.", "Verrouiller complètement les genoux."], "Va lentement, le contrôle compte plus que la distance."),
    "es": ExerciseGuide(["Separa los pies al ancho de la cadera, rodillas un poco flexionadas.", "Inclínate desde la cadera y desliza las manos por los muslos.", "Mantén la espalda recta y baja hasta notar el estiramiento detrás de las piernas.", "Aprieta los glúteos para subir, 12 repeticiones lentas por serie."], ["Redondear la espalda para llegar más abajo.", "Bloquear las rodillas totalmente rectas."], "Muévete despacio; el control importa más que hasta dónde llegas."),
    "it": ExerciseGuide(["Metti i piedi alla larghezza del bacino, ginocchia leggermente piegate.", "Piegati dalle anche facendo scivolare le mani lungo le cosce.", "Tieni la schiena piatta e scendi verso i piedi finché senti tirare dietro le cosce.", "Stringi i glutei per risalire, 12 ripetizioni lente per serie."], ["Arrotondare la schiena per scendere di più.", "Bloccare le ginocchia completamente tese."], "Muoviti piano; il controllo conta più di quanto scendi."),
    "pt": ExerciseGuide(["Afaste os pés na largura do quadril, joelhos levemente dobrados.", "Incline o tronco a partir do quadril, deslizando as mãos pelas coxas.", "Mantenha as costas retas e desça até sentir alongar atrás das pernas.", "Contraia os glúteos para subir, 12 repetições lentas por série."], ["Arredondar as costas para descer mais.", "Travar os joelhos totalmente esticados."], "Vá devagar; o controle importa mais do que até onde você chega."),
    "hi": ExerciseGuide(["पैर कूल्हों जितनी चौड़ाई पर रखो, घुटने हल्के मुड़े रहें।", "कूल्हों से आगे झुको और हाथों को जांघों पर नीचे सरकाओ।", "पीठ सीधी रखो और जांघों के पीछे खिंचाव महसूस होने तक पंजों की ओर जाओ।", "ग्लूट्स कसते हुए सीधे खड़े हो जाओ, हर सेट में 12 धीमे रेप्स करो।"], ["और नीचे पहुँचने के लिए पीठ गोल करना।", "घुटनों को पूरी तरह लॉक कर देना।"], "धीरे करो, कितना नीचे पहुँचे उससे ज़्यादा कंट्रोल मायने रखता है।"),
    "nl": ExerciseGuide(["Sta met je voeten op heupbreedte en je knieën licht gebogen.", "Buig vanuit je heupen en laat je handen langs je bovenbenen naar beneden glijden.", "Houd je rug vlak en reik naar je tenen tot je je hamstrings voelt rekken.", "Span je bilspieren aan om weer rechtop te komen, 12 langzame herhalingen per set."], ["Je rug bol maken om lager te komen.", "Je knieën helemaal op slot zetten."], "Beweeg langzaam; controle is belangrijker dan hoe ver je komt."),
    "pl": ExerciseGuide(["Stań ze stopami na szerokość bioder, kolana lekko ugięte.", "Pochyl się w biodrach i przesuwaj dłonie w dół po udach.", "Plecy proste; sięgaj w stronę palców stóp, aż poczujesz rozciąganie z tyłu ud.", "Napnij pośladki, by wrócić do pionu; 12 powolnych powtórzeń na serię."], ["Zaokrąglanie pleców, by sięgnąć niżej.", "Blokowanie kolan w pełnym wyproście."], "Ruszaj się powoli; kontrola jest ważniejsza niż to, jak nisko sięgniesz."),
    "sv": ExerciseGuide(["Stå med fötterna höftbrett isär och knäna mjukt böjda.", "Fäll i höften och låt händerna glida ned längs låren.", "Håll ryggen rak och sträck dig mot tårna tills det stretchar i baksida lår.", "Spänn sätet för att resa dig igen, 12 långsamma reps per set."], ["Att runda ryggen för att nå längre ned.", "Att låsa knäna helt raka."], "Rör dig långsamt – kontroll är viktigare än hur långt ned du når."),
  },
  "overhead_press": {
    "en": ExerciseGuide(["Stand tall holding light weights or water bottles at shoulder height.", "Brace your core and press both arms straight overhead.", "Finish with arms beside your ears, then lower slowly to your shoulders.", "Breathe out as you press, in as you lower, 10 reps per set."], ["Arching your lower back as you press.", "Using weights too heavy to control."], "Start with bodyweight and add light weights once your form feels easy."),
    "tr": ExerciseGuide(["Dik dur, hafif ağırlıkları ya da su şişelerini omuz hizasında tut.", "Karnını sık ve iki kolunu dümdüz yukarı it.", "Kolların kulaklarının yanında bitsin, sonra yavaşça omuzlara indir.", "İterken nefes ver, indirirken al, her sette 10 tekrar yap."], ["İterken belini çukurlaştırmak.", "Kontrol edemeyeceğin kadar ağır ağırlık kullanmak."], "Önce vücut ağırlığınla başla, form rahatlayınca hafif ağırlık ekle."),
    "de": ExerciseGuide(["Stell dich aufrecht hin, leichte Gewichte oder Wasserflaschen auf Schulterhöhe.", "Spann den Bauch an und drück beide Arme gerade nach oben.", "Oben sind die Arme neben den Ohren, dann senk sie langsam zu den Schultern.", "Beim Drücken ausatmen, beim Senken einatmen, 10 Wiederholungen pro Satz."], ["Beim Drücken ins Hohlkreuz gehen.", "Zu schwere Gewichte nehmen, die du nicht kontrollierst."], "Starte mit deinem Körpergewicht und nimm leichte Gewichte erst dazu, wenn die Technik sitzt."),
    "fr": ExerciseGuide(["Tiens-toi droit, poids légers ou bouteilles d'eau à hauteur d'épaules.", "Gaine ton ventre et pousse les deux bras tendus au-dessus de la tête.", "Finis les bras près des oreilles, puis redescends lentement aux épaules.", "Expire en poussant, inspire en descendant, 10 répétitions par série."], ["Creuser le bas du dos en poussant.", "Prendre des poids trop lourds pour être contrôlés."], "Commence sans poids et ajoute des charges légères quand le mouvement devient facile."),
    "es": ExerciseGuide(["Ponte recto con pesas ligeras o botellas de agua a la altura de los hombros.", "Aprieta el abdomen y empuja los dos brazos rectos hacia arriba.", "Termina con los brazos junto a las orejas y baja despacio a los hombros.", "Suelta el aire al empujar y tómalo al bajar, 10 repeticiones por serie."], ["Arquear la zona lumbar al empujar.", "Usar un peso demasiado pesado para controlarlo."], "Empieza sin peso y añade algo ligero cuando la técnica te salga fácil."),
    "it": ExerciseGuide(["Stai dritto con pesi leggeri o bottiglie d'acqua all'altezza delle spalle.", "Contrai l'addome e spingi entrambe le braccia dritte sopra la testa.", "Finisci con le braccia vicino alle orecchie, poi scendi piano alle spalle.", "Espira mentre spingi, inspira mentre scendi, 10 ripetizioni per serie."], ["Inarcare la zona lombare mentre spingi.", "Usare pesi troppo pesanti da controllare."], "Inizia a corpo libero e aggiungi pesi leggeri quando la tecnica ti viene facile."),
    "pt": ExerciseGuide(["Fique reto com pesos leves ou garrafas de água na altura dos ombros.", "Contraia o abdômen e empurre os dois braços retos para cima.", "Termine com os braços ao lado das orelhas e desça devagar até os ombros.", "Solte o ar ao empurrar e puxe ao descer, 10 repetições por série."], ["Arquear a lombar ao empurrar.", "Usar peso pesado demais para controlar."], "Comece sem peso e só acrescente carga leve quando a técnica estiver fácil."),
    "hi": ExerciseGuide(["सीधे खड़े होकर हल्के वज़न या पानी की बोतलें कंधों की ऊँचाई पर पकड़ो।", "पेट कसो और दोनों हाथ सीधे सिर के ऊपर धकेलो।", "ऊपर हाथ कानों के पास हों, फिर धीरे से कंधों तक नीचे लाओ।", "धकेलते समय साँस छोड़ो, नीचे लाते समय लो, हर सेट में 10 रेप्स।"], ["धकेलते समय कमर को पीछे की ओर मोड़ना।", "इतना भारी वज़न लेना जिसे संभाल न सको।"], "बिना वज़न के शुरू करो और फ़ॉर्म आसान लगे तभी हल्का वज़न जोड़ो।"),
    "nl": ExerciseGuide(["Sta rechtop met lichte gewichten of waterflessen op schouderhoogte.", "Span je core aan en duw beide armen recht omhoog boven je hoofd.", "Eindig met je armen naast je oren en laat ze dan langzaam zakken naar je schouders.", "Adem uit als je omhoog duwt en in als je laat zakken, 10 herhalingen per set."], ["Een holle onderrug maken tijdens het duwen.", "Gewichten gebruiken die te zwaar zijn om onder controle te houden."], "Begin zonder gewicht en neem lichte gewichten zodra de beweging makkelijk voelt."),
    "pl": ExerciseGuide(["Stań prosto, trzymając lekkie ciężarki lub butelki z wodą na wysokości barków.", "Napnij brzuch i wypchnij obie ręce prosto nad głowę.", "Skończ z rękami przy uszach, potem powoli opuść je do barków.", "Rób wydech przy wypychaniu, wdech przy opuszczaniu; 10 powtórzeń na serię."], ["Wyginanie dolnej części pleców podczas wypychania.", "Za ciężkie obciążenie, nad którym nie panujesz."], "Zacznij bez obciążenia i dodaj lekkie ciężarki, gdy technika będzie łatwa."),
    "sv": ExerciseGuide(["Stå rak och håll lätta vikter eller vattenflaskor i axelhöjd.", "Spänn magen och pressa båda armarna rakt upp över huvudet.", "Avsluta med armarna bredvid öronen och sänk sedan långsamt till axlarna.", "Andas ut när du pressar och in när du sänker, 10 reps per set."], ["Att svanka i ländryggen när du pressar.", "Att använda för tunga vikter för att ha kontroll."], "Börja med kroppsvikt och lägg till lätta vikter när tekniken känns lätt."),
  },
  "skipping_rope": {
    "en": ExerciseGuide(["Hold the handles at hip height, elbows close to your sides.", "Turn the rope with your wrists, not your whole arms.", "Jump just high enough to clear the rope, landing on the balls of your feet.", "Skip for 5 minutes, rest 1 minute, and repeat for 3 sets."], ["Jumping too high and tiring out fast.", "Landing flat-footed on your heels."], "Tripping is normal; just restart and keep the rhythm going."),
    "tr": ExerciseGuide(["Sapları kalça hizasında tut, dirseklerin vücuduna yakın olsun.", "İpi tüm kolunla değil, bileklerinle çevir.", "İpin geçeceği kadar zıpla, ayak tabanının ön kısmına kon.", "5 dakika atla, 1 dakika dinlen ve 3 set tekrarla."], ["Çok yükseğe zıplayıp hemen yorulmak.", "Düz tabanla topukların üstüne inmek."], "İpe takılmak normal, hemen yeniden başla ve ritmini koru."),
    "de": ExerciseGuide(["Halte die Griffe auf Hüfthöhe, die Ellbogen nah am Körper.", "Dreh das Seil aus den Handgelenken, nicht mit den ganzen Armen.", "Spring nur so hoch wie nötig und lande auf den Fußballen.", "Spring 5 Minuten, mach 1 Minute Pause und insgesamt 3 Sätze."], ["Zu hoch springen und schnell müde werden.", "Flach auf den Fersen landen."], "Hängenbleiben ist normal, starte einfach neu und halte den Rhythmus."),
    "fr": ExerciseGuide(["Tiens les poignées à hauteur de hanches, coudes près du corps.", "Fais tourner la corde avec les poignets, pas avec tout le bras.", "Saute juste assez pour passer la corde et retombe sur l'avant des pieds.", "Saute 5 minutes, repose-toi 1 minute et fais 3 séries."], ["Sauter trop haut et t'épuiser vite.", "Retomber à plat sur les talons."], "Se prendre les pieds dans la corde, c'est normal, reprends et garde le rythme."),
    "es": ExerciseGuide(["Sujeta los mangos a la altura de la cadera, codos pegados al cuerpo.", "Gira la cuerda con las muñecas, no con todo el brazo.", "Salta lo justo para pasar la cuerda y cae en la parte delantera del pie.", "Salta 5 minutos, descansa 1 minuto y repite 3 series."], ["Saltar demasiado alto y cansarte rápido.", "Caer con el pie plano sobre los talones."], "Enredarte con la cuerda es normal; vuelve a empezar y mantén el ritmo."),
    "it": ExerciseGuide(["Tieni le maniglie all'altezza dei fianchi, gomiti vicini al corpo.", "Fai girare la corda con i polsi, non con tutto il braccio.", "Salta solo quanto basta per superare la corda, atterrando sull'avampiede.", "Salta 5 minuti, riposa 1 minuto e ripeti per 3 serie."], ["Saltare troppo in alto e stancarti subito.", "Atterrare a piedi piatti sui talloni."], "Inciampare è normale; riparti subito e tieni il ritmo."),
    "pt": ExerciseGuide(["Segure os cabos na altura do quadril, cotovelos perto do corpo.", "Gire a corda com os punhos, não com o braço inteiro.", "Pule só o necessário para passar a corda, caindo na parte da frente dos pés.", "Pule por 5 minutos, descanse 1 minuto e repita por 3 séries."], ["Pular alto demais e cansar rápido.", "Cair com o pé chapado nos calcanhares."], "Errar o pulo é normal; recomece e mantenha o ritmo."),
    "hi": ExerciseGuide(["हैंडल कूल्हों की ऊँचाई पर पकड़ो, कोहनियाँ शरीर के पास रखो।", "रस्सी पूरे हाथ से नहीं, कलाइयों से घुमाओ।", "बस उतना कूदो कि रस्सी निकल जाए, और पंजों के अगले हिस्से पर उतरो।", "5 मिनट कूदो, 1 मिनट आराम करो और 3 सेट दोहराओ।"], ["बहुत ऊँचा कूदकर जल्दी थक जाना।", "सपाट पैर से एड़ियों पर उतरना।"], "रस्सी में अटकना सामान्य है, फिर से शुरू करो और लय बनाए रखो।"),
    "nl": ExerciseGuide(["Houd de handvatten op heuphoogte, ellebogen dicht bij je lichaam.", "Draai het touw vanuit je polsen, niet met je hele armen.", "Spring net hoog genoeg om over het touw te komen en land op je voorvoeten.", "Spring 5 minuten, rust 1 minuut en doe in totaal 3 sets."], ["Te hoog springen, waardoor je snel moe wordt.", "Plat op je hielen landen."], "Struikelen is normaal; begin gewoon opnieuw en houd het ritme vast."),
    "pl": ExerciseGuide(["Trzymaj uchwyty na wysokości bioder, łokcie blisko tułowia.", "Kręć skakanką nadgarstkami, nie całymi rękami.", "Skacz tylko tak wysoko, by przeskoczyć skakankę, i ląduj na przodostopiu.", "Skacz przez 5 minut, odpocznij minutę i powtórz, łącznie 3 serie."], ["Za wysokie skoki, przez które szybko się męczysz.", "Ciężkie lądowanie na całej stopie, na piętach."], "Potknięcia są normalne; po prostu zacznij od nowa i trzymaj rytm."),
    "sv": ExerciseGuide(["Håll handtagen i höfthöjd med armbågarna nära kroppen.", "Snurra repet med handlederna, inte med hela armarna.", "Hoppa precis så högt att repet går under, och landa på framfoten.", "Hoppa i 5 minuter, vila 1 minut och upprepa i 3 set."], ["Att hoppa för högt och bli trött snabbt.", "Att landa platt på hälarna."], "Det är helt normalt att trassla in sig – börja bara om och håll rytmen."),
  },
  "pilates_core": {
    "en": ExerciseGuide(["Hold a forearm plank for 1 minute, body in one straight line.", "Lie on your back for dead bugs, lowering opposite arm and leg slowly.", "Switch to bird dog on hands and knees, reaching opposite arm and leg.", "Finish with 1 minute of glute bridges and 1 minute of leg raises.", "Breathe out every time you tighten your core."], ["Letting your hips sag during the plank.", "Arching your lower back off the floor during dead bugs."], "Slow and controlled beats fast; every clean rep builds real strength."),
    "tr": ExerciseGuide(["Dirseklerinin üzerinde 1 dakika plank yap, vücudun dümdüz olsun.", "Sırtüstü dead bug yap, karşı kol ve bacağı yavaşça indir.", "Eller ve dizler üzerinde bird dog'a geç, karşı kol ve bacağı uzat.", "1 dakika kalça köprüsü ve 1 dakika bacak kaldırmayla bitir.", "Karnını her sıktığında nefes ver."], ["Plankta kalçanın aşağı sarkması.", "Dead bug sırasında belin yerden kalkması."], "Yavaş ve kontrollü, hızlıdan iyidir; her temiz tekrar seni gerçekten güçlendirir."),
    "de": ExerciseGuide(["Halte 1 Minute einen Unterarmstütz, dein Körper bildet eine gerade Linie.", "Mach in Rückenlage Dead Bugs und senk Arm und Gegenbein langsam ab.", "Wechsle in den Vierfüßlerstand zum Bird Dog und streck Arm und Gegenbein.", "Schließ mit je 1 Minute Beckenheben und Beinheben ab.", "Atme jedes Mal aus, wenn du den Bauch anspannst."], ["Im Unterarmstütz die Hüfte durchhängen lassen.", "Beim Dead Bug den unteren Rücken vom Boden heben."], "Langsam und kontrolliert schlägt schnell; jede saubere Wiederholung macht dich stärker."),
    "fr": ExerciseGuide(["Tiens une planche sur les avant-bras 1 minute, corps bien aligné.", "Sur le dos, fais le dead bug en descendant lentement bras et jambe opposés.", "Passe à quatre pattes en bird dog et tends bras et jambe opposés.", "Termine par 1 minute de pont fessier et 1 minute de levées de jambes.", "Expire chaque fois que tu contractes tes abdos."], ["Laisser les hanches s'affaisser pendant la planche.", "Décoller le bas du dos du sol pendant le dead bug."], "Lent et contrôlé vaut mieux que rapide, chaque répétition propre te rend plus fort."),
    "es": ExerciseGuide(["Mantén una plancha sobre los antebrazos 1 minuto, cuerpo en línea recta.", "Boca arriba, haz dead bug bajando despacio brazo y pierna contrarios.", "Pasa a cuatro apoyos en bird dog, estirando brazo y pierna contrarios.", "Termina con 1 minuto de puente de glúteos y 1 minuto de elevación de piernas.", "Suelta el aire cada vez que aprietes el abdomen."], ["Dejar caer la cadera en la plancha.", "Despegar la zona lumbar del suelo en el dead bug."], "Lento y controlado gana a rápido; cada buena repetición te hace más fuerte."),
    "it": ExerciseGuide(["Tieni un plank sugli avambracci per 1 minuto, corpo in linea retta.", "Sulla schiena, fai il dead bug abbassando piano braccio e gamba opposti.", "Passa a quattro zampe nel bird dog, allungando braccio e gamba opposti.", "Chiudi con 1 minuto di ponte glutei e 1 minuto di sollevamento gambe.", "Espira ogni volta che contrai l'addome."], ["Far cedere il bacino durante il plank.", "Staccare la zona lombare da terra nel dead bug."], "Lento e controllato batte veloce; ogni ripetizione fatta bene ti rende più forte."),
    "pt": ExerciseGuide(["Segure uma prancha nos antebraços por 1 minuto, corpo em linha reta.", "Deitado de costas, faça o dead bug baixando devagar braço e perna opostos.", "Passe para quatro apoios no bird dog, esticando braço e perna opostos.", "Termine com 1 minuto de ponte de glúteos e 1 minuto de elevação de pernas.", "Solte o ar sempre que contrair o abdômen."], ["Deixar o quadril cair na prancha.", "Tirar a lombar do chão no dead bug."], "Devagar e com controle vence o rápido; cada repetição bem feita deixa você mais forte."),
    "hi": ExerciseGuide(["1 मिनट फ़ोरआर्म प्लैंक करो, शरीर एक सीधी रेखा में रखो।", "पीठ के बल डेड बग करो, उलटे हाथ और पैर को धीरे से नीचे लाओ।", "हाथों और घुटनों पर बर्ड डॉग करो, उलटा हाथ और पैर फैलाओ।", "आखिर में 1 मिनट ग्लूट ब्रिज और 1 मिनट लेग रेज़ करो।", "हर बार पेट कसते समय साँस छोड़ो।"], ["प्लैंक में कूल्हों को नीचे झुकने देना।", "डेड बग में कमर के निचले हिस्से को ज़मीन से उठाना।"], "धीमा और कंट्रोल्ड तेज़ से बेहतर है, हर सही रेप तुम्हें मज़बूत बनाता है।"),
    "nl": ExerciseGuide(["Houd 1 minuut een onderarmplank vast, je lichaam in één rechte lijn.", "Ga op je rug liggen voor dead bugs en laat langzaam je tegenovergestelde arm en been zakken.", "Ga over op bird dogs op handen en knieën en strek je tegenovergestelde arm en been uit.", "Sluit af met 1 minuut bilbruggen en 1 minuut beenheffingen.", "Adem uit elke keer dat je je core aanspant."], ["Je heupen laten doorzakken tijdens de plank.", "Je onderrug van de vloer laten komen tijdens dead bugs."], "Langzaam en gecontroleerd is beter dan snel; elke goede herhaling bouwt echte kracht op."),
    "pl": ExerciseGuide(["Utrzymaj deskę na przedramionach przez minutę, ciało w jednej linii.", "Połóż się na plecach i zrób martwego robaka, powoli opuszczając przeciwną rękę i nogę.", "Przejdź do bird dog w klęku podpartym, wyciągając przeciwną rękę i nogę.", "Na koniec minuta mostka biodrowego i minuta unoszenia nóg.", "Rób wydech za każdym razem, gdy napinasz mięśnie brzucha."], ["Opadanie bioder w desce.", "Odrywanie lędźwi od podłogi przy martwym robaku."], "Wolno i z kontrolą jest lepiej niż szybko; każde czyste powtórzenie buduje prawdziwą siłę."),
    "sv": ExerciseGuide(["Håll plankan på underarmarna i 1 minut med kroppen i en rak linje.", "Ligg på rygg och gör dead bug: sänk motsatt arm och ben långsamt.", "Byt till bird dog på alla fyra och sträck ut motsatt arm och ben.", "Avsluta med 1 minut bäckenlyft och 1 minut benlyft.", "Andas ut varje gång du spänner bålen."], ["Att låta höfterna sjunka under plankan.", "Att svanka så att ländryggen lyfter från golvet under dead bug."], "Långsamt och kontrollerat slår snabbt – varje ren rep bygger riktig styrka."),
  },
  "inversion_hang": {
    "en": ExerciseGuide(["Only invert with an adult supervising and on stable, checked equipment.", "Lock your ankles securely and start at a slight incline, not fully upside down.", "Relax your arms and breathe slowly for up to 1 minute.", "Return upright slowly and sit for a moment before standing.", "Stop right away if you feel dizzy, pressure in your head or any pain."], ["Going fully upside down in your first sessions.", "Standing up quickly right after inverting."], "Short, gentle sessions are enough; there is no need to hang longer."),
    "tr": ExerciseGuide(["Sadece bir yetişkinin gözetiminde ve sağlam, kontrol edilmiş ekipmanla ters dön.", "Ayak bileklerini sıkıca sabitle, tam ters değil hafif bir açıyla başla.", "Kollarını gevşet ve en fazla 1 dakika yavaşça nefes al.", "Yavaşça dik konuma dön, ayağa kalkmadan önce biraz otur.", "Baş dönmesi, başında basınç ya da herhangi bir ağrı hissedersen hemen dur."], ["İlk seanslarda tamamen baş aşağı dönmek.", "Ters durduktan hemen sonra hızla ayağa kalkmak."], "Kısa ve nazik seanslar yeterli, süreyi zorlamana gerek yok."),
    "de": ExerciseGuide(["Häng dich nur unter Aufsicht eines Erwachsenen und an stabilem, geprüftem Gerät kopfüber.", "Sichere deine Knöchel fest und starte leicht geneigt, nicht ganz kopfüber.", "Lass die Arme locker und atme bis zu 1 Minute ruhig.", "Komm langsam zurück in die Senkrechte und setz dich kurz, bevor du aufstehst.", "Hör sofort auf, wenn dir schwindlig wird oder du Druck im Kopf oder Schmerzen spürst."], ["In den ersten Einheiten gleich ganz kopfüber gehen.", "Direkt danach zu schnell aufstehen."], "Kurze, sanfte Einheiten reichen völlig, du musst nicht länger hängen."),
    "fr": ExerciseGuide(["Ne t'inverse qu'avec un adulte qui surveille et un matériel stable et vérifié.", "Bloque bien tes chevilles et commence légèrement incliné, pas complètement à l'envers.", "Relâche les bras et respire lentement jusqu'à 1 minute.", "Reviens lentement à la verticale et reste assis un moment avant de te lever.", "Arrête aussitôt en cas de vertige, de pression dans la tête ou de douleur."], ["Te mettre complètement à l'envers dès les premières séances.", "Te relever trop vite juste après l'inversion."], "Des séances courtes et douces suffisent, inutile de rester plus longtemps."),
    "es": ExerciseGuide(["Ponte invertido solo con un adulto supervisando y con equipo estable y revisado.", "Asegura bien los tobillos y empieza con poca inclinación, no del todo boca abajo.", "Relaja los brazos y respira despacio hasta 1 minuto.", "Vuelve despacio a la vertical y siéntate un momento antes de levantarte.", "Para enseguida si notas mareo, presión en la cabeza o cualquier dolor."], ["Ponerte totalmente boca abajo en las primeras sesiones.", "Levantarte de golpe justo después de invertirte."], "Las sesiones cortas y suaves son suficientes; no hace falta alargarlas."),
    "it": ExerciseGuide(["Fallo solo con un adulto che ti controlla e un attrezzo stabile e verificato.", "Blocca bene le caviglie e parti con una leggera inclinazione, non del tutto capovolto.", "Rilassa le braccia e respira piano fino a 1 minuto.", "Torna dritto lentamente e resta seduto un momento prima di alzarti.", "Fermati subito se senti capogiri, pressione alla testa o qualsiasi dolore."], ["Capovolgerti del tutto già nelle prime sessioni.", "Alzarti di scatto subito dopo l'inversione."], "Sessioni brevi e delicate bastano; non serve restare appeso più a lungo."),
    "pt": ExerciseGuide(["Faça só com um adulto supervisionando e com equipamento firme e revisado.", "Prenda bem os tornozelos e comece com pouca inclinação, sem inverter o corpo todo.", "Relaxe os braços e respire devagar por até 1 minuto.", "Volte devagar para a posição vertical e sente um pouco antes de levantar.", "Pare na hora se sentir tontura, pressão na cabeça ou qualquer dor."], ["Ficar totalmente de cabeça para baixo nas primeiras sessões.", "Levantar rápido logo depois da inversão."], "Sessões curtas e suaves bastam; não precisa ficar mais tempo."),
    "hi": ExerciseGuide(["उलटा सिर्फ़ किसी बड़े की निगरानी में और मज़बूत, जाँचे हुए उपकरण पर ही लटको।", "टखनों को अच्छी तरह लॉक करो और हल्के झुकाव से शुरू करो, पूरा उलटा नहीं।", "हाथ ढीले छोड़ो और 1 मिनट तक धीरे-धीरे साँस लो।", "धीरे से सीधे आओ और खड़े होने से पहले थोड़ी देर बैठो।", "चक्कर, सिर में दबाव या कोई भी दर्द हो तो तुरंत रुक जाओ।"], ["पहले ही सेशन में पूरी तरह उलटा हो जाना।", "उलटा लटकने के तुरंत बाद झट से खड़े हो जाना।"], "छोटे और हल्के सेशन काफ़ी हैं, ज़्यादा देर तक लटकने की ज़रूरत नहीं।"),
    "nl": ExerciseGuide(["Ga alleen ondersteboven hangen met een volwassene erbij en op stevige, gecontroleerde apparatuur.", "Zet je enkels goed vast en begin met een kleine hoek, niet meteen helemaal ondersteboven.", "Ontspan je armen en adem maximaal 1 minuut rustig door.", "Kom langzaam weer rechtop en blijf even zitten voordat je opstaat.", "Stop meteen als je duizelig wordt, druk in je hoofd voelt of ergens pijn hebt."], ["Al in je eerste sessies helemaal ondersteboven gaan.", "Snel opstaan meteen na het ondersteboven hangen."], "Korte, rustige sessies zijn genoeg; langer hangen is niet nodig."),
    "pl": ExerciseGuide(["Zwisaj głową w dół tylko pod okiem dorosłego i na stabilnym, sprawdzonym sprzęcie.", "Dobrze zablokuj kostki i zacznij od lekkiego nachylenia, nie od pełnego odwrócenia.", "Rozluźnij ręce i oddychaj powoli przez maksymalnie minutę.", "Powoli wróć do pionu i chwilę posiedź, zanim wstaniesz.", "Przerwij od razu, jeśli poczujesz zawroty głowy, ucisk w głowie lub jakikolwiek ból."], ["Pełne odwrócenie już na pierwszych sesjach.", "Szybkie wstawanie zaraz po zwisie głową w dół."], "Krótkie, łagodne sesje wystarczą; nie ma potrzeby wisieć dłużej."),
    "sv": ExerciseGuide(["Häng bara upp och ner med en vuxen som övervakar, och på stabil, kontrollerad utrustning.", "Lås fast fotlederna ordentligt och börja med en lätt lutning, inte helt upp och ner.", "Slappna av i armarna och andas lugnt i upp till 1 minut.", "Kom tillbaka upprätt långsamt och sitt en stund innan du reser dig.", "Avbryt direkt om du blir yr, känner tryck i huvudet eller får ont någonstans."], ["Att hänga helt upp och ner de första gångerna.", "Att resa sig snabbt direkt efter att ha hängt upp och ner."], "Korta, lugna pass räcker – du behöver inte hänga längre."),
  },
  "posture_check": {
    "en": ExerciseGuide(["Set an hourly reminder to check how you are sitting or standing.", "Stack your ears over your shoulders and your shoulders over your hips.", "Roll your shoulders back and down, chest gently open.", "Imagine a string pulling the top of your head up, then breathe."], ["Overcorrecting with a stiff, arched back.", "Looking down at your phone with your head pushed forward."], "Raise your screen to eye level and good posture becomes automatic."),
    "tr": ExerciseGuide(["Oturuşunu ve duruşunu kontrol etmek için saatlik hatırlatıcı kur.", "Kulaklarını omuzlarının, omuzlarını kalçanın üstüne hizala.", "Omuzlarını geriye ve aşağı çek, göğsün hafifçe açık olsun.", "Başının tepesini yukarı çeken bir ip hayal et ve nefes al."], ["Sırtını kaskatı ve çukur yaparak aşırı düzeltmek.", "Başın önde, telefona eğilerek bakmak."], "Ekranını göz hizasına kaldır, iyi duruş kendiliğinden gelir."),
    "de": ExerciseGuide(["Stell dir eine stündliche Erinnerung, um deine Haltung zu checken.", "Bring die Ohren über die Schultern und die Schultern über die Hüfte.", "Roll die Schultern nach hinten unten, die Brust ist leicht geöffnet.", "Stell dir einen Faden vor, der deinen Scheitel nach oben zieht, und atme."], ["Mit steifem Hohlkreuz überkorrigieren.", "Mit vorgeschobenem Kopf aufs Handy schauen."], "Bring deinen Bildschirm auf Augenhöhe, dann wird gute Haltung zur Gewohnheit."),
    "fr": ExerciseGuide(["Mets un rappel toutes les heures pour vérifier comment tu es assis ou debout.", "Aligne tes oreilles au-dessus des épaules et tes épaules au-dessus des hanches.", "Ramène les épaules en arrière et vers le bas, poitrine légèrement ouverte.", "Imagine un fil qui tire le sommet de ta tête vers le haut, et respire."], ["Trop corriger avec un dos raide et cambré.", "Regarder ton téléphone la tête en avant."], "Monte ton écran à hauteur des yeux et la bonne posture devient automatique."),
    "es": ExerciseGuide(["Pon un recordatorio cada hora para revisar cómo estás sentado o de pie.", "Coloca las orejas sobre los hombros y los hombros sobre la cadera.", "Lleva los hombros atrás y abajo, con el pecho algo abierto.", "Imagina un hilo que tira de tu coronilla hacia arriba y respira."], ["Corregir de más con la espalda rígida y arqueada.", "Mirar el teléfono con la cabeza adelantada."], "Sube la pantalla a la altura de los ojos y la buena postura saldrá sola."),
    "it": ExerciseGuide(["Imposta un promemoria ogni ora per controllare come sei seduto o in piedi.", "Allinea le orecchie sopra le spalle e le spalle sopra il bacino.", "Porta le spalle indietro e in basso, petto leggermente aperto.", "Immagina un filo che tira la cima della testa verso l'alto e respira."], ["Correggere troppo con la schiena rigida e inarcata.", "Guardare il telefono con la testa in avanti."], "Alza lo schermo all'altezza degli occhi e la buona postura diventa automatica."),
    "pt": ExerciseGuide(["Coloque um lembrete a cada hora para checar como você está sentado ou em pé.", "Alinhe as orelhas sobre os ombros e os ombros sobre o quadril.", "Leve os ombros para trás e para baixo, com o peito levemente aberto.", "Imagine um fio puxando o topo da sua cabeça para cima e respire."], ["Corrigir demais com as costas duras e arqueadas.", "Olhar o celular com a cabeça projetada para frente."], "Coloque a tela na altura dos olhos e a boa postura vira automática."),
    "hi": ExerciseGuide(["हर घंटे का रिमाइंडर लगाओ ताकि बैठने या खड़े होने का तरीका जाँच सको।", "कान कंधों के ऊपर और कंधे कूल्हों के ऊपर एक सीध में रखो।", "कंधों को पीछे और नीचे करो, छाती हल्की खुली रहे।", "सोचो कि एक धागा तुम्हारे सिर को ऊपर खींच रहा है, और साँस लो।"], ["अकड़ी और पीछे मुड़ी पीठ से ज़रूरत से ज़्यादा सुधार करना।", "सिर आगे निकालकर फ़ोन देखना।"], "स्क्रीन को आँखों की ऊँचाई पर रखो, अच्छा पोस्चर अपने आप बनेगा।"),
    "nl": ExerciseGuide(["Zet elk uur een herinnering om te checken hoe je zit of staat.", "Zorg dat je oren boven je schouders zijn en je schouders boven je heupen.", "Rol je schouders naar achteren en omlaag, je borst licht open.", "Stel je voor dat een touwtje je kruin omhoogtrekt en adem dan rustig."], ["Overcorrigeren met een stijve, holle rug.", "Naar je telefoon kijken met je hoofd naar voren."], "Zet je scherm op ooghoogte, dan gaat een goede houding vanzelf."),
    "pl": ExerciseGuide(["Ustaw przypomnienie co godzinę, by sprawdzać, jak siedzisz lub stoisz.", "Ustaw uszy nad barkami, a barki nad biodrami.", "Przesuń barki do tyłu i w dół, klatka piersiowa lekko otwarta.", "Wyobraź sobie nitkę, która ciągnie czubek głowy w górę, i oddychaj."], ["Przesadna korekta ze sztywnymi, wygiętymi plecami.", "Patrzenie w telefon z głową wysuniętą do przodu."], "Podnieś ekran na wysokość oczu, a dobra postawa przyjdzie sama."),
    "sv": ExerciseGuide(["Ställ in en påminnelse varje timme för att kolla hur du sitter eller står.", "Ha öronen över axlarna och axlarna över höfterna.", "Rulla axlarna bakåt och nedåt med bröstet lätt öppet.", "Tänk dig ett snöre som drar hjässan uppåt och andas sedan."], ["Att överkorrigera med en stel, svankande rygg.", "Att titta ned i mobilen med huvudet framskjutet."], "Höj skärmen till ögonhöjd, så blir en bra hållning automatisk."),
  },
  "wall_stand": {
    "en": ExerciseGuide(["Stand with your heels against a wall, feet hip-width apart.", "Touch your buttocks, shoulder blades and the back of your head to the wall.", "Tuck your chin slightly and keep your arms relaxed at your sides.", "Hold for 5 minutes, breathing calmly through your nose."], ["Arching your lower back far away from the wall.", "Pushing your chin up instead of keeping it level."], "Notice how this feels, then try to carry it into your day."),
    "tr": ExerciseGuide(["Topukların duvara değsin, ayakların kalça genişliğinde olsun.", "Kalçanı, kürek kemiklerini ve başının arkasını duvara değdir.", "Çeneni hafifçe içeri al, kollarını yanlarda gevşek bırak.", "5 dakika bu şekilde kal, burnundan sakin nefes al."], ["Belini duvardan fazla uzaklaştırıp çukurlaştırmak.", "Çeneni düz tutmak yerine yukarı kaldırmak."], "Bu duruşu iyice hisset, sonra gün içinde de korumaya çalış."),
    "de": ExerciseGuide(["Stell dich mit den Fersen an eine Wand, Füße hüftbreit.", "Po, Schulterblätter und Hinterkopf berühren die Wand.", "Zieh das Kinn leicht ein und lass die Arme locker hängen.", "Halte 5 Minuten und atme ruhig durch die Nase."], ["Den unteren Rücken weit von der Wand wegwölben.", "Das Kinn nach oben schieben, statt es gerade zu halten."], "Spür genau, wie sich das anfühlt, und nimm es mit in deinen Tag."),
    "fr": ExerciseGuide(["Place-toi dos au mur, talons contre le mur, pieds à largeur de hanches.", "Colle tes fesses, tes omoplates et l'arrière de ta tête au mur.", "Rentre légèrement le menton et laisse les bras relâchés le long du corps.", "Tiens 5 minutes en respirant calmement par le nez."], ["Cambrer fort le bas du dos en l'éloignant du mur.", "Lever le menton au lieu de le garder droit."], "Ressens bien cette position, puis essaie de la garder dans ta journée."),
    "es": ExerciseGuide(["Apoya la espalda en la pared con los talones pegados y los pies separados.", "Apoya glúteos, omóplatos y la parte de atrás de la cabeza en la pared.", "Mete un poco la barbilla y deja los brazos relajados a los lados.", "Mantén 5 minutos respirando tranquilo por la nariz."], ["Arquear mucho la zona lumbar separándola de la pared.", "Levantar la barbilla en vez de mantenerla recta."], "Fíjate en cómo se siente esta postura y trata de llevarla a tu día."),
    "it": ExerciseGuide(["Mettiti di spalle al muro con i talloni appoggiati, piedi alla larghezza del bacino.", "Appoggia al muro glutei, scapole e la parte posteriore della testa.", "Porta il mento leggermente indietro e lascia le braccia rilassate lungo il corpo.", "Tieni 5 minuti respirando con calma dal naso."], ["Inarcare molto la zona lombare staccandola dal muro.", "Alzare il mento invece di tenerlo dritto."], "Senti bene questa posizione e prova a portarla con te durante la giornata."),
    "pt": ExerciseGuide(["Fique de costas para a parede com os calcanhares encostados, pés na largura do quadril.", "Encoste glúteos, escápulas e a parte de trás da cabeça na parede.", "Recolha um pouco o queixo e deixe os braços relaxados ao lado do corpo.", "Segure por 5 minutos respirando calmamente pelo nariz."], ["Arquear muito a lombar, afastando-a da parede.", "Levantar o queixo em vez de mantê-lo reto."], "Perceba bem como é essa postura e tente levá-la para o seu dia."),
    "hi": ExerciseGuide(["दीवार से पीठ लगाकर खड़े हो जाओ, एड़ियाँ दीवार से सटी और पैर कूल्हों जितने खुले।", "कूल्हे, कंधे की हड्डियाँ और सिर का पिछला हिस्सा दीवार से छुआओ।", "ठुड्डी हल्की अंदर करो और हाथ बगल में ढीले छोड़ो।", "5 मिनट ऐसे ही रुको और नाक से शांति से साँस लो।"], ["कमर के निचले हिस्से को दीवार से बहुत दूर मोड़ना।", "ठुड्डी सीधी रखने की बजाय ऊपर उठाना।"], "इस मुद्रा को अच्छे से महसूस करो, फिर इसे पूरे दिन बनाए रखने की कोशिश करो।"),
    "nl": ExerciseGuide(["Sta met je hielen tegen een muur, voeten op heupbreedte.", "Raak de muur met je billen, schouderbladen en achterhoofd.", "Trek je kin een beetje in en houd je armen ontspannen langs je lichaam.", "Houd dit 5 minuten vol en adem rustig door je neus."], ["Een holle onderrug maken, ver van de muur af.", "Je kin omhoog duwen in plaats van hem recht te houden."], "Let op hoe dit voelt en probeer het mee te nemen in je dag."),
    "pl": ExerciseGuide(["Stań piętami przy ścianie, stopy na szerokość bioder.", "Dotknij ściany pośladkami, łopatkami i tyłem głowy.", "Lekko cofnij brodę, a ręce trzymaj luźno wzdłuż ciała.", "Wytrzymaj 5 minut, spokojnie oddychając przez nos."], ["Mocne wyginanie dolnej części pleców z dala od ściany.", "Zadzieranie brody zamiast trzymania jej poziomo."], "Zapamiętaj to uczucie i spróbuj przenieść je na resztę dnia."),
    "sv": ExerciseGuide(["Stå med hälarna mot en vägg och fötterna höftbrett isär.", "Låt rumpan, skulderbladen och bakhuvudet nudda väggen.", "Dra in hakan lätt och håll armarna avslappnade längs sidorna.", "Håll i 5 minuter och andas lugnt genom näsan."], ["Att svanka så att ländryggen hamnar långt från väggen.", "Att lyfta hakan i stället för att hålla den rak."], "Lägg märke till hur det känns och försök ta med det in i din dag."),
  },
  "neck_stretches": {
    "en": ExerciseGuide(["Sit or stand tall with your shoulders relaxed and down.", "Tilt your ear slowly toward one shoulder and hold 30 seconds per side.", "Lower your chin toward your chest and hold for 30 seconds.", "Lift your gaze gently for 30 seconds without dropping your head back."], ["Pulling hard on your head with your hand.", "Lifting your shoulder up to meet your ear."], "Do these after long study sessions to release tension."),
    "tr": ExerciseGuide(["Dik otur ya da dur, omuzların gevşek ve aşağıda olsun.", "Kulağını yavaşça bir omzuna doğru eğ, her tarafta 30 saniye tut.", "Çeneni göğsüne doğru indir ve 30 saniye tut.", "Başını geriye düşürmeden bakışını yavaşça yukarı kaldır, 30 saniye tut."], ["Elinle başını sertçe çekmek.", "Omzunu kulağına doğru kaldırmak."], "Uzun ders çalışmalarından sonra yap, biriken gerginliği atarsın."),
    "de": ExerciseGuide(["Sitz oder steh aufrecht, die Schultern locker und tief.", "Neig das Ohr langsam zur Schulter und halte 30 Sekunden pro Seite.", "Senk das Kinn zur Brust und halte 30 Sekunden.", "Heb den Blick sanft für 30 Sekunden, ohne den Kopf nach hinten fallen zu lassen."], ["Mit der Hand fest am Kopf ziehen.", "Die Schulter zum Ohr hochziehen."], "Mach das nach langen Lernphasen, um Verspannungen zu lösen."),
    "fr": ExerciseGuide(["Assieds-toi ou tiens-toi droit, épaules basses et détendues.", "Penche lentement l'oreille vers une épaule et tiens 30 secondes de chaque côté.", "Descends le menton vers la poitrine et tiens 30 secondes.", "Lève doucement le regard 30 secondes sans laisser tomber la tête en arrière."], ["Tirer fort sur ta tête avec la main.", "Monter l'épaule vers l'oreille."], "Fais-les après une longue séance de révisions pour relâcher les tensions."),
    "es": ExerciseGuide(["Siéntate o ponte de pie recto, con los hombros relajados y bajos.", "Inclina despacio la oreja hacia un hombro y mantén 30 segundos por lado.", "Baja la barbilla hacia el pecho y mantén 30 segundos.", "Lleva la mirada hacia arriba con suavidad 30 segundos sin echar la cabeza atrás."], ["Tirar fuerte de la cabeza con la mano.", "Subir el hombro hacia la oreja."], "Hazlos después de estudiar mucho rato para soltar tensión."),
    "it": ExerciseGuide(["Siediti o stai in piedi dritto, spalle basse e rilassate.", "Inclina piano l'orecchio verso una spalla e tieni 30 secondi per lato.", "Abbassa il mento verso il petto e tieni 30 secondi.", "Alza lo sguardo con dolcezza per 30 secondi senza buttare la testa indietro."], ["Tirare forte la testa con la mano.", "Alzare la spalla verso l'orecchio."], "Falli dopo lunghe sessioni di studio per sciogliere la tensione."),
    "pt": ExerciseGuide(["Sente ou fique em pé, bem reto, com os ombros relaxados e baixos.", "Incline devagar a orelha até um ombro e segure 30 segundos por lado.", "Leve o queixo em direção ao peito e segure 30 segundos.", "Olhe suavemente para cima por 30 segundos sem jogar a cabeça para trás."], ["Puxar a cabeça com força usando a mão.", "Subir o ombro em direção à orelha."], "Faça depois de longos períodos de estudo para soltar a tensão."),
    "hi": ExerciseGuide(["सीधे बैठो या खड़े हो जाओ, कंधे ढीले और नीचे रखो।", "कान को धीरे से एक कंधे की ओर झुकाओ, हर तरफ 30 सेकंड रुको।", "ठुड्डी को छाती की ओर नीचे लाओ और 30 सेकंड रुको।", "सिर पीछे गिराए बिना नज़र धीरे से ऊपर करो और 30 सेकंड रुको।"], ["हाथ से सिर को ज़ोर से खींचना।", "कंधे को कान की ओर उठाना।"], "लंबी पढ़ाई के बाद ये करो, जमा हुआ तनाव निकल जाएगा।"),
    "nl": ExerciseGuide(["Zit of sta rechtop met je schouders ontspannen en laag.", "Kantel je oor langzaam richting één schouder en houd 30 seconden per kant vast.", "Breng je kin naar je borst en houd 30 seconden vast.", "Kijk 30 seconden rustig omhoog zonder je hoofd naar achteren te laten vallen."], ["Hard aan je hoofd trekken met je hand.", "Je schouder optrekken naar je oor."], "Doe deze na lang studeren om spanning los te laten."),
    "pl": ExerciseGuide(["Usiądź lub stań prosto, barki rozluźnione i opuszczone.", "Powoli przechyl głowę uchem w stronę barku i wytrzymaj 30 sekund na każdą stronę.", "Opuść brodę w stronę klatki piersiowej i wytrzymaj 30 sekund.", "Delikatnie unieś wzrok na 30 sekund, nie odchylając głowy do tyłu."], ["Mocne ciągnięcie głowy ręką.", "Podnoszenie barku w stronę ucha."], "Rób te ćwiczenia po długiej nauce, by rozluźnić napięcie."),
    "sv": ExerciseGuide(["Sitt eller stå rak med axlarna avslappnade och nere.", "Luta örat långsamt mot ena axeln och håll i 30 sekunder per sida.", "Sänk hakan mot bröstet och håll i 30 sekunder.", "Lyft blicken försiktigt i 30 sekunder utan att fälla huvudet bakåt."], ["Att dra hårt i huvudet med handen.", "Att dra upp axeln mot örat."], "Gör dem efter långa pluggpass för att släppa på spänningarna."),
  },
  "shoulder_rolls": {
    "en": ExerciseGuide(["Stand tall with your arms hanging loosely at your sides.", "Roll your shoulders forward in big circles 15 times.", "Roll them backward 15 times, squeezing your shoulder blades together.", "Clasp your hands behind your back and open your chest for 20 seconds."], ["Making tiny, rushed circles.", "Shrugging while holding your breath."], "A quick set between classes or study blocks keeps your shoulders open."),
    "tr": ExerciseGuide(["Dik dur, kolların yanlarda serbestçe sarksın.", "Omuzlarını büyük daireler çizerek 15 kez öne çevir.", "15 kez geriye çevir, kürek kemiklerini arkada sık.", "Ellerini arkada kenetle ve 20 saniye göğsünü aç."], ["Küçük ve aceleci daireler çizmek.", "Nefesini tutarak omuz silkmek."], "Dersler ya da çalışma blokları arasında kısa bir set omuzlarını açık tutar."),
    "de": ExerciseGuide(["Stell dich aufrecht hin, die Arme hängen locker.", "Roll die Schultern 15 Mal in großen Kreisen nach vorn.", "Roll sie 15 Mal nach hinten und zieh dabei die Schulterblätter zusammen.", "Verschränk die Hände hinter dem Rücken und öffne die Brust 20 Sekunden."], ["Kleine, hastige Kreise machen.", "Die Schultern hochziehen und dabei die Luft anhalten."], "Ein kurzer Satz zwischen Schulstunden oder Lernblöcken hält deine Schultern offen."),
    "fr": ExerciseGuide(["Tiens-toi droit, bras relâchés le long du corps.", "Fais rouler tes épaules vers l'avant en grands cercles, 15 fois.", "Fais-les rouler 15 fois vers l'arrière en serrant les omoplates.", "Croise les mains dans le dos et ouvre la poitrine pendant 20 secondes."], ["Faire de petits cercles trop rapides.", "Hausser les épaules en bloquant ta respiration."], "Une petite série entre deux cours ou révisions garde tes épaules ouvertes."),
    "es": ExerciseGuide(["Ponte recto con los brazos sueltos a los lados.", "Gira los hombros hacia delante en círculos grandes 15 veces.", "Gíralos hacia atrás 15 veces, juntando los omóplatos.", "Entrelaza las manos detrás de la espalda y abre el pecho 20 segundos."], ["Hacer círculos pequeños y con prisa.", "Encoger los hombros aguantando la respiración."], "Una serie rápida entre clases o ratos de estudio mantiene tus hombros abiertos."),
    "it": ExerciseGuide(["Stai dritto con le braccia morbide lungo il corpo.", "Ruota le spalle in avanti con cerchi ampi per 15 volte.", "Ruotale indietro 15 volte, stringendo le scapole.", "Intreccia le mani dietro la schiena e apri il petto per 20 secondi."], ["Fare cerchi piccoli e di fretta.", "Alzare le spalle trattenendo il respiro."], "Una serie veloce tra una lezione e l'altra tiene le spalle aperte."),
    "pt": ExerciseGuide(["Fique reto com os braços soltos ao lado do corpo.", "Gire os ombros para frente em círculos grandes, 15 vezes.", "Gire para trás 15 vezes, apertando as escápulas.", "Entrelace as mãos atrás das costas e abra o peito por 20 segundos."], ["Fazer círculos pequenos e apressados.", "Encolher os ombros prendendo a respiração."], "Uma série rápida entre aulas ou estudos mantém seus ombros abertos."),
    "hi": ExerciseGuide(["सीधे खड़े हो जाओ, हाथ बगल में ढीले लटकने दो।", "कंधों को बड़े गोले में 15 बार आगे घुमाओ।", "15 बार पीछे घुमाओ और कंधे की हड्डियों को पीछे की ओर कसो।", "पीठ के पीछे हाथ फँसाओ और 20 सेकंड छाती खोलो।"], ["छोटे और जल्दबाज़ी वाले गोले बनाना।", "साँस रोककर कंधे उचकाना।"], "क्लास या पढ़ाई के बीच एक छोटा सेट तुम्हारे कंधों को खुला रखता है।"),
    "nl": ExerciseGuide(["Sta rechtop met je armen los langs je lichaam.", "Rol je schouders 15 keer in grote cirkels naar voren.", "Rol ze 15 keer naar achteren en knijp je schouderbladen samen.", "Vouw je handen achter je rug in elkaar en open je borst 20 seconden."], ["Kleine, gehaaste cirkels maken.", "Je schouders optrekken terwijl je je adem inhoudt."], "Een snelle set tussen de lessen of studieblokken door houdt je schouders open."),
    "pl": ExerciseGuide(["Stań prosto, ręce luźno zwisają wzdłuż ciała.", "Zrób 15 dużych krążeń barkami do przodu.", "Zrób 15 krążeń do tyłu, ściągając łopatki.", "Spleć dłonie za plecami i otwórz klatkę piersiową na 20 sekund."], ["Małe, pośpieszne kółka.", "Unoszenie barków przy wstrzymanym oddechu."], "Krótka seria między lekcjami albo blokami nauki pomaga utrzymać otwarte barki."),
    "sv": ExerciseGuide(["Stå rak med armarna hängande löst längs sidorna.", "Rulla axlarna framåt i stora cirklar 15 gånger.", "Rulla dem bakåt 15 gånger och dra ihop skulderbladen.", "Knäpp händerna bakom ryggen och öppna bröstet i 20 sekunder."], ["Att göra små, stressade cirklar.", "Att dra upp axlarna medan du håller andan."], "Ett snabbt set mellan lektioner eller pluggpass håller axlarna öppna."),
  },
  "pre_sleep_routine": {
    "en": ExerciseGuide(["Start 30 minutes before bed: dim the lights and put screens away.", "Read a book or listen to calm music for 15 minutes.", "Do 5 minutes of gentle stretching on your bed or the floor.", "Breathe in for 4 seconds and out for 6 seconds, 10 rounds."], ["Scrolling on your phone for just one more minute.", "Changing your bedtime a lot from night to night."], "Same time, same steps every night makes falling asleep easier."),
    "tr": ExerciseGuide(["Yatmadan 30 dakika önce başla: ışıkları kıs, ekranları bırak.", "15 dakika kitap oku ya da sakin müzik dinle.", "Yatağında ya da yerde 5 dakika hafif esneme yap.", "4 saniye nefes al, 6 saniye ver, 10 tur tekrarla."], ["Sadece bir dakika diyerek telefonda gezinmek.", "Yatma saatini geceden geceye çok değiştirmek."], "Her gece aynı saat, aynı adımlar; uykuya dalmak giderek kolaylaşır."),
    "de": ExerciseGuide(["Starte 30 Minuten vor dem Schlafen: Licht dimmen, Bildschirme weglegen.", "Lies 15 Minuten ein Buch oder hör ruhige Musik.", "Dehn dich 5 Minuten sanft auf dem Bett oder dem Boden.", "Atme 4 Sekunden ein und 6 Sekunden aus, 10 Runden lang."], ["Nur noch eine Minute am Handy scrollen.", "Die Schlafenszeit jeden Abend stark verschieben."], "Gleiche Uhrzeit, gleiche Schritte jeden Abend, dann schläfst du leichter ein."),
    "fr": ExerciseGuide(["Commence 30 minutes avant le coucher, lumière tamisée et écrans rangés.", "Lis un livre ou écoute de la musique calme pendant 15 minutes.", "Fais 5 minutes d'étirements doux sur ton lit ou au sol.", "Inspire 4 secondes et expire 6 secondes, pendant 10 cycles."], ["Scroller sur ton téléphone juste une minute de plus.", "Changer beaucoup d'heure de coucher d'un soir à l'autre."], "Même heure, mêmes étapes chaque soir, et tu t'endors plus facilement."),
    "es": ExerciseGuide(["Empieza 30 minutos antes de dormir: baja las luces y deja las pantallas.", "Lee un libro o escucha música tranquila durante 15 minutos.", "Haz 5 minutos de estiramientos suaves en la cama o en el suelo.", "Inhala 4 segundos y exhala 6 segundos, durante 10 rondas."], ["Mirar el teléfono solo un minuto más.", "Cambiar mucho la hora de acostarte cada noche."], "Misma hora y mismos pasos cada noche, así te costará menos dormirte."),
    "it": ExerciseGuide(["Inizia 30 minuti prima di dormire: abbassa le luci e metti via gli schermi.", "Leggi un libro o ascolta musica tranquilla per 15 minuti.", "Fai 5 minuti di allungamenti leggeri sul letto o sul pavimento.", "Inspira per 4 secondi ed espira per 6 secondi, per 10 cicli."], ["Scorrere il telefono solo per un altro minuto.", "Cambiare molto l'orario in cui vai a letto ogni sera."], "Stessa ora e stessi passi ogni sera, così ti addormenti più facilmente."),
    "pt": ExerciseGuide(["Comece 30 minutos antes de dormir: diminua as luzes e largue as telas.", "Leia um livro ou ouça uma música calma por 15 minutos.", "Faça 5 minutos de alongamento leve na cama ou no chão.", "Inspire por 4 segundos e expire por 6 segundos, por 10 rodadas."], ["Rolar o feed do celular só por mais um minuto.", "Mudar muito o horário de dormir de uma noite para outra."], "Mesmo horário e mesmos passos toda noite deixam o sono chegar mais fácil."),
    "hi": ExerciseGuide(["सोने से 30 मिनट पहले शुरू करो, रोशनी धीमी करो और स्क्रीन दूर रखो।", "15 मिनट कोई किताब पढ़ो या शांत संगीत सुनो।", "बिस्तर या ज़मीन पर 5 मिनट हल्की स्ट्रेचिंग करो।", "4 सेकंड साँस लो, 6 सेकंड में छोड़ो, 10 बार दोहराओ।"], ["बस एक मिनट और कहकर फ़ोन स्क्रॉल करना।", "हर रात सोने का समय बहुत बदलना।"], "हर रात एक ही समय और एक ही कदम, इससे नींद आसानी से आती है।"),
    "nl": ExerciseGuide(["Begin 30 minuten voor bedtijd: dim het licht en leg je schermen weg.", "Lees een boek of luister 15 minuten naar rustige muziek.", "Doe 5 minuten rustige stretches op je bed of op de vloer.", "Adem 4 seconden in en 6 seconden uit, 10 rondes."], ["Nog ‘heel even’ op je telefoon scrollen.", "Elke avond op een heel ander tijdstip naar bed gaan."], "Elke avond op dezelfde tijd dezelfde stappen maakt in slaap vallen makkelijker."),
    "pl": ExerciseGuide(["Zacznij 30 minut przed snem: przygaś światło i odłóż ekrany.", "Przez 15 minut czytaj książkę albo słuchaj spokojnej muzyki.", "Zrób 5 minut łagodnego rozciągania na łóżku lub na podłodze.", "Rób wdech przez 4 sekundy i wydech przez 6 sekund, 10 razy."], ["Przeglądanie telefonu „jeszcze tylko minutkę”.", "Duże zmiany pory snu z dnia na dzień."], "Ta sama pora i te same kroki co wieczór ułatwiają zasypianie."),
    "sv": ExerciseGuide(["Börja 30 minuter före läggdags: dämpa belysningen och lägg undan skärmarna.", "Läs en bok eller lyssna på lugn musik i 15 minuter.", "Stretcha lugnt i 5 minuter i sängen eller på golvet.", "Andas in i 4 sekunder och ut i 6 sekunder, 10 gånger."], ["Att scrolla på mobilen ”bara en minut till”.", "Att ändra läggtiden mycket från kväll till kväll."], "Samma tid och samma steg varje kväll gör det lättare att somna."),
  },
  "plank": {
    "en": ExerciseGuide(["Place your forearms on the floor, elbows under your shoulders.", "Step your feet back so your body forms one straight line.", "Squeeze your glutes, pull your belly button in and hold 30 seconds.", "Rest 30 seconds and repeat for 3 sets."], ["Letting your hips sag toward the floor.", "Piking your hips up too high."], "Add 5 seconds each week as it gets easier."),
    "tr": ExerciseGuide(["Ön kollarını yere koy, dirseklerin omuzlarının altında olsun.", "Ayaklarını geriye at, vücudun tek düz bir çizgi oluştursun.", "Kalçanı sık, göbeğini içeri çek ve 30 saniye tut.", "30 saniye dinlen ve 3 set tekrarla."], ["Kalçanın yere doğru sarkması.", "Kalçanın fazla yukarı kalkması."], "Kolaylaştıkça her hafta 5 saniye ekle."),
    "de": ExerciseGuide(["Leg die Unterarme auf den Boden, Ellbogen unter den Schultern.", "Stell die Füße nach hinten, sodass dein Körper eine gerade Linie bildet.", "Spann Po und Bauch an und halte 30 Sekunden.", "Mach 30 Sekunden Pause und wiederhole das für 3 Sätze."], ["Die Hüfte Richtung Boden durchhängen lassen.", "Den Po zu hoch nach oben schieben."], "Leg jede Woche 5 Sekunden drauf, wenn es leichter wird."),
    "fr": ExerciseGuide(["Pose les avant-bras au sol, coudes sous les épaules.", "Recule les pieds pour que ton corps forme une ligne droite.", "Serre les fessiers, rentre le nombril et tiens 30 secondes.", "Repose-toi 30 secondes et fais 3 séries."], ["Laisser les hanches tomber vers le sol.", "Monter les fesses trop haut."], "Ajoute 5 secondes chaque semaine quand ça devient plus facile."),
    "es": ExerciseGuide(["Apoya los antebrazos en el suelo, codos bajo los hombros.", "Lleva los pies atrás hasta que tu cuerpo forme una línea recta.", "Aprieta los glúteos, mete el ombligo y mantén 30 segundos.", "Descansa 30 segundos y repite 3 series."], ["Dejar caer la cadera hacia el suelo.", "Subir la cadera demasiado."], "Suma 5 segundos cada semana cuando te resulte más fácil."),
    "it": ExerciseGuide(["Appoggia gli avambracci a terra, gomiti sotto le spalle.", "Porta i piedi indietro finché il corpo forma una linea retta.", "Stringi i glutei, porta l'ombelico verso l'interno e tieni 30 secondi.", "Riposa 30 secondi e ripeti per 3 serie."], ["Lasciar cadere il bacino verso il pavimento.", "Alzare troppo il bacino."], "Aggiungi 5 secondi ogni settimana quando diventa più facile."),
    "pt": ExerciseGuide(["Apoie os antebraços no chão, cotovelos embaixo dos ombros.", "Leve os pés para trás até o corpo formar uma linha reta.", "Contraia os glúteos, puxe o umbigo para dentro e segure 30 segundos.", "Descanse 30 segundos e repita por 3 séries."], ["Deixar o quadril cair em direção ao chão.", "Empinar o quadril alto demais."], "Acrescente 5 segundos por semana conforme ficar mais fácil."),
    "hi": ExerciseGuide(["फ़ोरआर्म ज़मीन पर टिकाओ, कोहनियाँ कंधों के ठीक नीचे रहें।", "पैर पीछे ले जाओ ताकि शरीर एक सीधी रेखा बने।", "ग्लूट्स कसो, नाभि अंदर खींचो और 30 सेकंड रुको।", "30 सेकंड आराम करो और 3 सेट दोहराओ।"], ["कूल्हों को ज़मीन की ओर झुकने देना।", "कूल्हों को बहुत ऊपर उठा देना।"], "आसान लगने लगे तो हर हफ़्ते 5 सेकंड बढ़ाओ।"),
    "nl": ExerciseGuide(["Zet je onderarmen op de vloer, ellebogen onder je schouders.", "Stap met je voeten naar achteren zodat je lichaam één rechte lijn vormt.", "Span je bilspieren aan, trek je navel in en houd 30 seconden vast.", "Rust 30 seconden en doe in totaal 3 sets."], ["Je heupen naar de vloer laten zakken.", "Je heupen te hoog omhoog steken."], "Tel er elke week 5 seconden bij op als het makkelijker wordt."),
    "pl": ExerciseGuide(["Oprzyj przedramiona na podłodze, łokcie pod barkami.", "Odstaw stopy do tyłu, by ciało tworzyło jedną prostą linię.", "Napnij pośladki, wciągnij pępek i wytrzymaj 30 sekund.", "Odpocznij 30 sekund i powtórz, łącznie 3 serie."], ["Opadanie bioder w stronę podłogi.", "Zbyt wysokie unoszenie bioder."], "Gdy będzie łatwiej, co tydzień dodawaj 5 sekund."),
    "sv": ExerciseGuide(["Placera underarmarna på golvet med armbågarna under axlarna.", "Kliv bakåt med fötterna så att kroppen bildar en rak linje.", "Spänn sätet, dra in naveln och håll i 30 sekunder.", "Vila 30 sekunder och upprepa i 3 set."], ["Att låta höfterna sjunka mot golvet.", "Att skjuta upp höfterna för högt."], "Lägg till 5 sekunder varje vecka när det börjar kännas lättare."),
  },
  "glute_bridge": {
    "en": ExerciseGuide(["Lie on your back, knees bent, feet flat and hip-width apart.", "Press through your heels and lift your hips toward the ceiling.", "Squeeze your glutes at the top for 2 seconds.", "Lower slowly, 12 reps per set, 3 sets in total."], ["Pushing through your toes instead of your heels.", "Overarching your lower back at the top."], "If you feel it in your glutes, not your lower back, you are doing it right."),
    "tr": ExerciseGuide(["Sırtüstü uzan, dizlerin bükük, ayakların kalça genişliğinde yerde olsun.", "Topuklarından iterek kalçanı tavana doğru kaldır.", "Yukarıda kalça kaslarını 2 saniye sık.", "Yavaşça in, her sette 12 tekrar, toplam 3 set yap."], ["Topuk yerine parmak uçlarından itmek.", "Yukarıda belini fazla çukurlaştırmak."], "Belinde değil kalçanda hissediyorsan doğru yapıyorsun."),
    "de": ExerciseGuide(["Leg dich auf den Rücken, Knie gebeugt, Füße hüftbreit flach am Boden.", "Drück dich über die Fersen ab und heb die Hüfte Richtung Decke.", "Spann oben den Po 2 Sekunden lang an.", "Senk dich langsam ab, 12 Wiederholungen pro Satz, 3 Sätze."], ["Über die Zehen statt über die Fersen drücken.", "Oben ins Hohlkreuz gehen."], "Spürst du es im Po und nicht im unteren Rücken, machst du es richtig."),
    "fr": ExerciseGuide(["Allonge-toi sur le dos, genoux pliés, pieds à plat à largeur de hanches.", "Pousse sur les talons et monte le bassin vers le plafond.", "Serre les fessiers en haut pendant 2 secondes.", "Redescends lentement, 12 répétitions par série, 3 séries."], ["Pousser sur les orteils au lieu des talons.", "Trop cambrer le bas du dos en haut."], "Si tu le sens dans les fessiers et pas dans le dos, c'est que tu le fais bien."),
    "es": ExerciseGuide(["Acuéstate boca arriba, rodillas flexionadas, pies planos al ancho de la cadera.", "Empuja con los talones y sube la cadera hacia el techo.", "Aprieta los glúteos arriba durante 2 segundos.", "Baja despacio, 12 repeticiones por serie, 3 series."], ["Empujar con las puntas en vez de con los talones.", "Arquear demasiado la zona lumbar arriba."], "Si lo notas en los glúteos y no en la espalda, lo estás haciendo bien."),
    "it": ExerciseGuide(["Sdraiati sulla schiena, ginocchia piegate, piedi a terra alla larghezza del bacino.", "Spingi sui talloni e solleva il bacino verso il soffitto.", "Stringi i glutei in alto per 2 secondi.", "Scendi piano, 12 ripetizioni per serie, 3 serie."], ["Spingere sulle punte invece che sui talloni.", "Inarcare troppo la zona lombare in alto."], "Se lo senti nei glutei e non nella schiena, lo stai facendo bene."),
    "pt": ExerciseGuide(["Deite de costas, joelhos dobrados, pés no chão na largura do quadril.", "Empurre pelos calcanhares e suba o quadril em direção ao teto.", "Contraia os glúteos lá em cima por 2 segundos.", "Desça devagar, 12 repetições por série, 3 séries."], ["Empurrar pelas pontas dos pés em vez dos calcanhares.", "Arquear demais a lombar lá em cima."], "Se você sente nos glúteos e não nas costas, está fazendo certo."),
    "hi": ExerciseGuide(["पीठ के बल लेटो, घुटने मोड़ो और पैर कूल्हों जितनी चौड़ाई पर ज़मीन पर रखो।", "एड़ियों से दबाकर कूल्हों को छत की ओर उठाओ।", "ऊपर 2 सेकंड ग्लूट्स कसकर रखो।", "धीरे से नीचे आओ, हर सेट में 12 रेप्स, कुल 3 सेट।"], ["एड़ियों की बजाय पंजों से दबाना।", "ऊपर पहुँचकर कमर को ज़्यादा मोड़ना।"], "अगर कमर में नहीं, ग्लूट्स में महसूस हो रहा है, तो तुम सही कर रहे हो।"),
    "nl": ExerciseGuide(["Ga op je rug liggen, knieën gebogen, voeten plat op heupbreedte.", "Duw door je hielen en til je heupen op richting het plafond.", "Span je bilspieren bovenaan 2 seconden aan.", "Zak langzaam terug, 12 herhalingen per set, 3 sets in totaal."], ["Duwen met je tenen in plaats van met je hielen.", "Bovenaan je onderrug te hol maken."], "Voel je het in je billen en niet in je onderrug, dan doe je het goed."),
    "pl": ExerciseGuide(["Połóż się na plecach, kolana ugięte, stopy płasko na szerokość bioder.", "Odepchnij się piętami i unieś biodra w stronę sufitu.", "Na górze napnij pośladki na 2 sekundy.", "Powoli opuść biodra; 12 powtórzeń na serię, łącznie 3 serie."], ["Odpychanie się palcami zamiast piętami.", "Nadmierne wyginanie lędźwi w górnej pozycji."], "Jeśli czujesz to w pośladkach, a nie w dolnej części pleców, robisz to dobrze."),
    "sv": ExerciseGuide(["Ligg på rygg med böjda knän och fötterna platt i golvet, höftbrett isär.", "Pressa ifrån med hälarna och lyft höfterna mot taket.", "Spänn sätet i toppläget i 2 sekunder.", "Sänk långsamt, 12 reps per set, 3 set totalt."], ["Att pressa ifrån med tårna i stället för hälarna.", "Att svanka för mycket i ländryggen i toppläget."], "Känner du det i sätet och inte i ländryggen gör du rätt."),
  },
  "calf_raise": {
    "en": ExerciseGuide(["Stand tall next to a wall, fingertips touching it for balance.", "Rise slowly onto the balls of your feet as high as you can.", "Hold 1 second at the top, then lower your heels slowly.", "Do 15 reps per set, 3 sets in total."], ["Bouncing quickly instead of moving slowly.", "Letting your ankles roll outward at the top."], "Do them while brushing your teeth for an easy daily habit."),
    "tr": ExerciseGuide(["Bir duvarın yanında dik dur, denge için parmak uçlarınla dokun.", "Ayak tabanının ön kısmına doğru olabildiğince yükseğe yavaşça kalk.", "Yukarıda 1 saniye bekle, sonra topuklarını yavaşça indir.", "Her sette 15 tekrar, toplam 3 set yap."], ["Yavaş hareket etmek yerine hızlı hızlı yaylanmak.", "Yukarıda ayak bileklerini dışa doğru yatırmak."], "Dişlerini fırçalarken yap, kolay bir günlük alışkanlığa dönüşsün."),
    "de": ExerciseGuide(["Stell dich aufrecht neben eine Wand, die Fingerspitzen zur Balance daran.", "Heb dich langsam so hoch wie möglich auf die Fußballen.", "Halte oben 1 Sekunde und senk die Fersen langsam ab.", "Mach 15 Wiederholungen pro Satz, insgesamt 3 Sätze."], ["Schnell wippen, statt dich langsam zu bewegen.", "Oben mit den Knöcheln nach außen kippen."], "Mach es beim Zähneputzen, so wird es zur einfachen Gewohnheit."),
    "fr": ExerciseGuide(["Tiens-toi droit près d'un mur, le bout des doigts posé dessus.", "Monte lentement sur l'avant des pieds, le plus haut possible.", "Tiens 1 seconde en haut, puis redescends les talons lentement.", "Fais 15 répétitions par série, 3 séries au total."], ["Rebondir vite au lieu de bouger lentement.", "Laisser les chevilles partir vers l'extérieur en haut."], "Fais-les en te brossant les dents, c'est une habitude facile à prendre."),
    "es": ExerciseGuide(["Ponte recto junto a una pared, con la punta de los dedos apoyada.", "Sube despacio sobre la parte delantera del pie lo más alto que puedas.", "Mantén 1 segundo arriba y baja los talones despacio.", "Haz 15 repeticiones por serie, 3 series en total."], ["Rebotar rápido en vez de moverte despacio.", "Dejar que los tobillos se vayan hacia fuera arriba."], "Hazlo mientras te lavas los dientes y será un hábito fácil."),
    "it": ExerciseGuide(["Stai dritto vicino a un muro, con la punta delle dita appoggiata.", "Sali piano sull'avampiede, più in alto che puoi.", "Tieni 1 secondo in alto, poi abbassa piano i talloni.", "Fai 15 ripetizioni per serie, 3 serie in totale."], ["Molleggiare veloce invece di muoverti piano.", "Far piegare le caviglie verso l'esterno in alto."], "Falli mentre ti lavi i denti, così diventa un'abitudine facile."),
    "pt": ExerciseGuide(["Fique reto perto de uma parede, com a ponta dos dedos apoiada nela.", "Suba devagar na parte da frente dos pés, o mais alto que conseguir.", "Segure 1 segundo lá em cima e desça os calcanhares devagar.", "Faça 15 repetições por série, 3 séries no total."], ["Quicar rápido em vez de se mover devagar.", "Deixar os tornozelos virarem para fora lá em cima."], "Faça enquanto escova os dentes e isso vira um hábito fácil."),
    "hi": ExerciseGuide(["दीवार के पास सीधे खड़े हो जाओ, संतुलन के लिए उंगलियों से उसे छुओ।", "पंजों के अगले हिस्से पर जितना हो सके धीरे-धीरे ऊपर उठो।", "ऊपर 1 सेकंड रुको, फिर एड़ियाँ धीरे से नीचे लाओ।", "हर सेट में 15 रेप्स करो, कुल 3 सेट।"], ["धीरे करने की बजाय तेज़ी से उछलना।", "ऊपर टखनों को बाहर की ओर मुड़ने देना।"], "ब्रश करते समय करो, यह रोज़ की आसान आदत बन जाएगी।"),
    "nl": ExerciseGuide(["Sta rechtop naast een muur en raak hem met je vingertoppen aan voor je balans.", "Kom langzaam zo hoog mogelijk op je voorvoeten.", "Houd bovenaan 1 seconde vast en laat je hielen dan langzaam zakken.", "Doe 15 herhalingen per set, 3 sets in totaal."], ["Snel op en neer veren in plaats van langzaam te bewegen.", "Je enkels bovenaan naar buiten laten kantelen."], "Doe ze tijdens het tandenpoetsen, dan wordt het makkelijk een dagelijkse gewoonte."),
    "pl": ExerciseGuide(["Stań prosto przy ścianie, opierając o nią palce dla równowagi.", "Powoli wespnij się na przodostopie najwyżej, jak możesz.", "Wytrzymaj sekundę na górze, potem powoli opuść pięty.", "Zrób 15 powtórzeń na serię, łącznie 3 serie."], ["Szybkie sprężynowanie zamiast powolnego ruchu.", "Uciekanie kostek na zewnątrz w górnej pozycji."], "Rób je podczas mycia zębów, a łatwo staną się codziennym nawykiem."),
    "sv": ExerciseGuide(["Stå rak bredvid en vägg och nudda den med fingertopparna för balansen.", "Res dig långsamt upp på framfoten så högt du kan.", "Håll i 1 sekund i toppläget och sänk sedan hälarna långsamt.", "Gör 15 reps per set, 3 set totalt."], ["Att studsa snabbt i stället för att röra dig långsamt.", "Att låta fotlederna vika utåt i toppläget."], "Gör dem medan du borstar tänderna, så blir det en enkel daglig vana."),
  },
  "dead_hang_active": {
    "en": ExerciseGuide(["Grip the bar overhand, hands slightly wider than your shoulders.", "Hang with straight arms, then pull your shoulder blades down and back.", "Keep your legs together and core tight, and hold for 20 seconds.", "Step down gently and rest 40 seconds between sets."], ["Bending your elbows like a pull-up.", "Shrugging your shoulders up to your ears."], "Think of pushing the bar away from you to feel your shoulders work."),
    "tr": ExerciseGuide(["Barı üstten kavra, ellerin omuzlarından biraz geniş olsun.", "Kolların düz şekilde asıl, sonra kürek kemiklerini aşağı ve geriye çek.", "Bacaklarını birleştir, karnını sık ve 20 saniye tut.", "Yavaşça in ve setler arasında 40 saniye dinlen."], ["Barfiks çeker gibi dirsekleri bükmek.", "Omuzları kulaklara doğru kaldırmak."], "Barı kendinden uzağa ittiğini düşün, omuzlarının çalıştığını hissedeceksin."),
    "de": ExerciseGuide(["Greif die Stange im Obergriff, Hände etwas breiter als schulterbreit.", "Häng mit gestreckten Armen und zieh die Schulterblätter nach hinten unten.", "Halte die Beine zusammen und den Bauch fest, 20 Sekunden lang.", "Steig sanft ab und mach 40 Sekunden Pause zwischen den Sätzen."], ["Die Ellbogen beugen wie bei einem Klimmzug.", "Die Schultern zu den Ohren hochziehen."], "Stell dir vor, du drückst die Stange von dir weg, dann spürst du deine Schultern arbeiten."),
    "fr": ExerciseGuide(["Attrape la barre en pronation, mains un peu plus écartées que les épaules.", "Suspends-toi bras tendus, puis tire les omoplates vers le bas et l'arrière.", "Jambes serrées et ventre gainé, tiens 20 secondes.", "Redescends doucement et repose-toi 40 secondes entre les séries."], ["Plier les coudes comme pour une traction.", "Monter les épaules vers les oreilles."], "Imagine que tu repousses la barre loin de toi pour sentir tes épaules travailler."),
    "es": ExerciseGuide(["Agarra la barra con las palmas hacia delante, manos algo más abiertas que los hombros.", "Cuelga con los brazos rectos y lleva los omóplatos hacia abajo y atrás.", "Junta las piernas, mantén el abdomen firme y aguanta 20 segundos.", "Baja con suavidad y descansa 40 segundos entre series."], ["Doblar los codos como en una dominada.", "Subir los hombros hacia las orejas."], "Piensa en empujar la barra lejos de ti para sentir cómo trabajan tus hombros."),
    "it": ExerciseGuide(["Afferra la sbarra con presa prona, mani un po' più larghe delle spalle.", "Resta appeso a braccia tese, poi porta le scapole in basso e indietro.", "Tieni le gambe unite e l'addome contratto per 20 secondi.", "Scendi con calma e riposa 40 secondi tra le serie."], ["Piegare i gomiti come in una trazione.", "Alzare le spalle verso le orecchie."], "Immagina di spingere la sbarra lontano da te per sentire lavorare le spalle."),
    "pt": ExerciseGuide(["Segure a barra com as palmas para frente, mãos além da largura dos ombros.", "Fique pendurado com os braços esticados e puxe as escápulas para baixo e para trás.", "Mantenha as pernas juntas e o abdômen firme por 20 segundos.", "Desça com calma e descanse 40 segundos entre as séries."], ["Dobrar os cotovelos como numa barra fixa.", "Subir os ombros em direção às orelhas."], "Pense em empurrar a barra para longe de você para sentir os ombros trabalharem."),
    "hi": ExerciseGuide(["बार को ऊपर से पकड़ो, हाथ कंधों से थोड़े ज़्यादा चौड़े रखो।", "सीधे हाथों से लटको, फिर कंधे की हड्डियों को नीचे और पीछे खींचो।", "पैर साथ रखो, पेट कसो और 20 सेकंड रुको।", "आराम से उतरो और सेट के बीच 40 सेकंड आराम करो।"], ["पुल-अप की तरह कोहनियाँ मोड़ना।", "कंधों को कानों की ओर उचकाना।"], "सोचो कि तुम बार को खुद से दूर धकेल रहे हो, कंधों का काम महसूस होगा।"),
    "nl": ExerciseGuide(["Pak de stang met een bovenhandse greep, handen iets breder dan je schouders.", "Hang met gestrekte armen en trek dan je schouderbladen omlaag en naar achteren.", "Houd je benen bij elkaar en je core aangespannen, en houd 20 seconden vast.", "Stap rustig af en rust 40 seconden tussen de sets."], ["Je ellebogen buigen alsof je je optrekt.", "Je schouders optrekken naar je oren."], "Denk eraan dat je de stang van je af duwt, dan voel je je schouders werken."),
    "pl": ExerciseGuide(["Chwyć drążek nachwytem, dłonie trochę szerzej niż barki.", "Zawiśnij na prostych rękach, potem ściągnij łopatki w dół i do tyłu.", "Nogi razem, brzuch napięty; wytrzymaj 20 sekund.", "Delikatnie zejdź i odpoczywaj 40 sekund między seriami."], ["Uginanie łokci jak przy podciąganiu.", "Podciąganie barków do uszu."], "Wyobraź sobie, że odpychasz drążek od siebie, a poczujesz pracę barków."),
    "sv": ExerciseGuide(["Greppa stången med överhandsgrepp, händerna lite bredare än axlarna.", "Häng med raka armar och dra sedan skulderbladen nedåt och bakåt.", "Håll ihop benen och spänn bålen, och håll i 20 sekunder.", "Kliv ned försiktigt och vila 40 sekunder mellan seten."], ["Att böja armbågarna som i en chins.", "Att dra upp axlarna mot öronen."], "Tänk att du trycker stången bort från dig, så känner du hur axlarna jobbar."),
  },
  "cat_cow": {
    "en": ExerciseGuide(["Start on hands and knees, wrists under shoulders, knees under hips.", "Breathe in, drop your belly and lift your chest and gaze (cow).", "Breathe out, round your back and tuck your chin (cat).", "Move slowly with your breath for 10 rounds, 2 sets."], ["Moving faster than your breathing.", "Moving only your neck instead of your whole spine."], "Great as your first move in the morning or a reset after sitting."),
    "tr": ExerciseGuide(["Eller ve dizler üzerinde başla, bilekler omuzların, dizler kalçanın altında.", "Nefes al, karnını aşağı bırak, göğsünü ve bakışını kaldır (inek).", "Nefes ver, sırtını yuvarla ve çeneni içeri al (kedi).", "Nefesinle uyumlu şekilde yavaşça 10 tur yap, toplam 2 set."], ["Nefesinden daha hızlı hareket etmek.", "Tüm omurga yerine sadece boynunu oynatmak."], "Sabahın ilk hareketi ya da uzun oturmanın ardından mola için harika."),
    "de": ExerciseGuide(["Starte im Vierfüßlerstand, Handgelenke unter den Schultern, Knie unter der Hüfte.", "Atme ein, lass den Bauch sinken und heb Brust und Blick (Kuh).", "Atme aus, mach den Rücken rund und zieh das Kinn ein (Katze).", "Beweg dich langsam im Atemrhythmus, 10 Runden, 2 Sätze."], ["Dich schneller bewegen, als du atmest.", "Nur den Nacken statt der ganzen Wirbelsäule bewegen."], "Perfekt als erste Übung am Morgen oder als Pause nach langem Sitzen."),
    "fr": ExerciseGuide(["Commence à quatre pattes, poignets sous les épaules, genoux sous les hanches.", "Inspire, laisse descendre le ventre, lève la poitrine et le regard (vache).", "Expire, arrondis le dos et rentre le menton (chat).", "Bouge lentement au rythme de ta respiration, 10 cycles, 2 séries."], ["Bouger plus vite que ta respiration.", "Bouger seulement la nuque au lieu de toute la colonne."], "Parfait comme premier mouvement le matin ou pour te relancer après être resté assis."),
    "es": ExerciseGuide(["Empieza en cuatro apoyos, muñecas bajo los hombros y rodillas bajo la cadera.", "Inhala, deja caer el abdomen y levanta el pecho y la mirada (vaca).", "Exhala, redondea la espalda y mete la barbilla (gato).", "Muévete despacio al ritmo de tu respiración, 10 rondas, 2 series."], ["Moverte más rápido que tu respiración.", "Mover solo el cuello en vez de toda la columna."], "Ideal como primer movimiento de la mañana o para despejarte tras estar sentado."),
    "it": ExerciseGuide(["Parti a quattro zampe, polsi sotto le spalle, ginocchia sotto le anche.", "Inspira, lascia scendere la pancia e alza petto e sguardo (mucca).", "Espira, arrotonda la schiena e porta il mento verso il petto (gatto).", "Muoviti piano seguendo il respiro, 10 cicli, 2 serie."], ["Muoverti più veloce del tuo respiro.", "Muovere solo il collo invece di tutta la colonna."], "Perfetto come primo movimento del mattino o come pausa dopo tanto tempo seduto."),
    "pt": ExerciseGuide(["Comece em quatro apoios, punhos sob os ombros e joelhos sob o quadril.", "Inspire, solte a barriga e levante o peito e o olhar (vaca).", "Expire, arredonde as costas e recolha o queixo (gato).", "Mova-se devagar no ritmo da respiração, 10 ciclos, 2 séries."], ["Se mover mais rápido que a respiração.", "Mexer só o pescoço em vez da coluna inteira."], "Ótimo como primeiro movimento da manhã ou como pausa depois de ficar sentado."),
    "hi": ExerciseGuide(["हाथों और घुटनों के बल शुरू करो, कलाइयाँ कंधों के नीचे, घुटने कूल्हों के नीचे।", "साँस लो, पेट नीचे जाने दो, छाती और नज़र ऊपर करो (काउ)।", "साँस छोड़ो, पीठ गोल करो और ठुड्डी अंदर करो (कैट)।", "साँस के साथ धीरे-धीरे 10 राउंड करो, कुल 2 सेट।"], ["साँस से तेज़ हरकत करना।", "पूरी रीढ़ की बजाय सिर्फ़ गर्दन हिलाना।"], "सुबह की पहली हरकत या लंबे समय बैठने के बाद ब्रेक के लिए बढ़िया।"),
    "nl": ExerciseGuide(["Begin op handen en knieën, polsen onder je schouders, knieën onder je heupen.", "Adem in, laat je buik zakken en til je borst en blik op (koe).", "Adem uit, maak je rug bol en trek je kin in (kat).", "Beweeg langzaam mee met je adem, 10 rondes, 2 sets."], ["Sneller bewegen dan je ademt.", "Alleen je nek bewegen in plaats van je hele wervelkolom."], "Top als eerste oefening in de ochtend of als reset na lang zitten."),
    "pl": ExerciseGuide(["Zacznij w klęku podpartym: nadgarstki pod barkami, kolana pod biodrami.", "Wdech: opuść brzuch, unieś klatkę piersiową i wzrok (krowa).", "Wydech: zaokrąglij plecy i przyciągnij brodę (kot).", "Poruszaj się powoli w rytmie oddechu, 10 cykli, 2 serie."], ["Ruch szybszy niż oddech.", "Poruszanie tylko szyją zamiast całym kręgosłupem."], "Świetne jako pierwszy ruch rano albo reset po siedzeniu."),
    "sv": ExerciseGuide(["Börja på alla fyra med handlederna under axlarna och knäna under höfterna.", "Andas in, sänk magen och lyft bröstet och blicken (ko).", "Andas ut, runda ryggen och dra in hakan (katt).", "Rör dig långsamt i takt med andningen i 10 varv, 2 set."], ["Att röra dig snabbare än du andas.", "Att bara röra nacken i stället för hela ryggraden."], "Perfekt som första rörelse på morgonen eller som omstart efter mycket sittande."),
  },
  "hip_flexor_stretch": {
    "en": ExerciseGuide(["Kneel on one knee with the other foot flat in front of you.", "Tuck your hips under slightly and squeeze the glute of your back leg.", "Shift forward gently until you feel a stretch at the front of your hip.", "Hold 30 seconds, breathing slowly, then switch sides."], ["Arching your lower back instead of tucking your hips.", "Letting your front knee drift past your toes."], "Put a folded towel under your knee to make it more comfortable."),
    "tr": ExerciseGuide(["Bir dizinin üzerine çök, diğer ayağın önde yere düz bassın.", "Kalçanı hafifçe içeri al ve arkadaki bacağının kalça kasını sık.", "Kalçanın önünde gerilme hissedene kadar nazikçe öne kay.", "Yavaş nefeslerle 30 saniye tut, sonra taraf değiştir."], ["Kalçayı içeri almak yerine beli çukurlaştırmak.", "Öndeki dizin ayak parmaklarını geçmesine izin vermek."], "Daha rahat olması için dizinin altına katlanmış bir havlu koy."),
    "de": ExerciseGuide(["Knie dich auf ein Knie, der andere Fuß steht flach vor dir.", "Kipp das Becken leicht nach hinten und spann den Po des hinteren Beins an.", "Schieb dich sanft nach vorn, bis es vorne an der Hüfte zieht.", "Halte 30 Sekunden mit ruhigem Atem und wechsle dann die Seite."], ["Ins Hohlkreuz gehen, statt das Becken zu kippen.", "Das vordere Knie über die Zehen hinausschieben."], "Leg ein gefaltetes Handtuch unters Knie, dann ist es bequemer."),
    "fr": ExerciseGuide(["Pose un genou au sol, l'autre pied à plat devant toi.", "Bascule légèrement le bassin et serre le fessier de la jambe arrière.", "Avance doucement jusqu'à sentir l'étirement à l'avant de la hanche.", "Tiens 30 secondes en respirant lentement, puis change de côté."], ["Cambrer le bas du dos au lieu de basculer le bassin.", "Laisser le genou avant dépasser les orteils."], "Mets une serviette pliée sous ton genou pour plus de confort."),
    "es": ExerciseGuide(["Apoya una rodilla en el suelo con el otro pie plano delante.", "Mete un poco la pelvis y aprieta el glúteo de la pierna de atrás.", "Avanza con suavidad hasta notar el estiramiento delante de la cadera.", "Mantén 30 segundos respirando lento y cambia de lado."], ["Arquear la zona lumbar en vez de meter la pelvis.", "Dejar que la rodilla de delante pase de la punta del pie."], "Pon una toalla doblada bajo la rodilla para estar más cómodo."),
    "it": ExerciseGuide(["Metti un ginocchio a terra e l'altro piede piatto davanti a te.", "Porta il bacino leggermente in dentro e stringi il gluteo della gamba dietro.", "Spostati piano in avanti finché senti tirare davanti all'anca.", "Tieni 30 secondi respirando piano, poi cambia lato."], ["Inarcare la zona lombare invece di portare il bacino in dentro.", "Lasciare che il ginocchio davanti superi le punte dei piedi."], "Metti un asciugamano piegato sotto il ginocchio per stare più comodo."),
    "pt": ExerciseGuide(["Apoie um joelho no chão com o outro pé plano à sua frente.", "Encaixe levemente o quadril e contraia o glúteo da perna de trás.", "Leve o corpo suavemente para frente até sentir alongar na frente do quadril.", "Segure 30 segundos respirando devagar e troque de lado."], ["Arquear a lombar em vez de encaixar o quadril.", "Deixar o joelho da frente passar da ponta do pé."], "Coloque uma toalha dobrada sob o joelho para ficar mais confortável."),
    "hi": ExerciseGuide(["एक घुटना ज़मीन पर रखो, दूसरा पैर सामने ज़मीन पर सपाट रखो।", "कूल्हों को हल्का अंदर की ओर दबाओ और पीछे वाले पैर का ग्लूट कसो।", "कूल्हे के आगे खिंचाव महसूस होने तक धीरे से आगे खिसको।", "धीमी साँसों के साथ 30 सेकंड रुको, फिर तरफ़ बदलो।"], ["कूल्हे अंदर करने की बजाय कमर मोड़ना।", "आगे वाले घुटने को पंजों से आगे जाने देना।"], "आराम के लिए घुटने के नीचे मोड़ा हुआ तौलिया रखो।"),
    "nl": ExerciseGuide(["Kniel op één knie met je andere voet plat voor je.", "Kantel je bekken iets naar achteren en span de bilspier van je achterste been aan.", "Schuif rustig naar voren tot je een stretch voelt aan de voorkant van je heup.", "Houd 30 seconden vast, adem rustig en wissel dan van kant."], ["Een holle onderrug maken in plaats van je bekken te kantelen.", "Je voorste knie voorbij je tenen laten schuiven."], "Leg een opgevouwen handdoek onder je knie, dat zit een stuk fijner."),
    "pl": ExerciseGuide(["Uklęknij na jedno kolano, drugą stopę postaw płasko przed sobą.", "Lekko podwiń miednicę i napnij pośladek tylnej nogi.", "Delikatnie przesuń się do przodu, aż poczujesz rozciąganie z przodu biodra.", "Wytrzymaj 30 sekund, oddychając powoli, potem zmień stronę."], ["Wyginanie lędźwi zamiast podwijania miednicy.", "Wysuwanie przedniego kolana poza palce stóp."], "Podłóż pod kolano złożony ręcznik, będzie wygodniej."),
    "sv": ExerciseGuide(["Stå på ena knät med den andra foten platt i golvet framför dig.", "Tippa bäckenet lätt bakåt och spänn sätet på det bakre benet.", "För kroppen försiktigt framåt tills du känner en stretch på framsidan av höften.", "Håll i 30 sekunder och andas lugnt, byt sedan sida."], ["Att svanka i ländryggen i stället för att tippa bäckenet.", "Att låta det främre knät glida förbi tårna."], "Lägg en vikt handduk under knät så blir det skönare."),
  },
  "masai_jumps": {
    "en": ExerciseGuide(["Stand tall with your arms by your sides or reaching up.", "Make small, springy jumps and keep your body upright the whole time.", "Land softly on the balls of your feet, knees slightly bent.", "Keep going for 20 seconds, 3 sets in total."], ["Landing hard on your heels.", "Slumping forward as you get tired."], "Stop if your knees or shins hurt, and rest before you try again."),
    "tr": ExerciseGuide(["Dik dur, kolların yanda ya da yukarıda olsun.", "Küçük, yaylı zıplamalar yap ve vücudunu baştan sona dik tut.", "Ayak tabanının ön kısmına yumuşakça in, dizlerin hafif bükük olsun.", "20 saniye boyunca devam et, toplam 3 set yap."], ["Topuklarının üstüne sert inmek.", "Yoruldukça öne doğru çökmek."], "Dizlerin ya da kaval kemiklerin ağrırsa dur ve tekrar denemeden önce dinlen."),
    "de": ExerciseGuide(["Stell dich aufrecht hin, die Arme seitlich am Körper oder nach oben gestreckt.", "Mach kleine, federnde Sprünge und bleib die ganze Zeit aufrecht.", "Lande weich auf den Fußballen, die Knie leicht gebeugt.", "Mach 20 Sekunden lang weiter, insgesamt 3 Sätze."], ["Hart auf den Fersen landen.", "Bei Müdigkeit nach vorn zusammensacken."], "Hör auf, wenn dir Knie oder Schienbeine wehtun, und ruh dich aus, bevor du es wieder versuchst."),
    "fr": ExerciseGuide(["Tiens-toi droit, les bras le long du corps ou levés.", "Fais de petits sauts souples en gardant le corps droit du début à la fin.", "Reçois-toi en douceur sur l'avant des pieds, genoux légèrement fléchis.", "Continue pendant 20 secondes, 3 séries au total."], ["Retomber lourdement sur les talons.", "T'affaisser vers l'avant quand la fatigue arrive."], "Arrête si tes genoux ou tes tibias te font mal, et repose-toi avant de recommencer."),
    "es": ExerciseGuide(["Ponte recto, con los brazos a los lados o hacia arriba.", "Da saltos pequeños y elásticos y mantén el cuerpo recto todo el tiempo.", "Cae con suavidad sobre la parte delantera del pie, con las rodillas algo flexionadas.", "Sigue durante 20 segundos, 3 series en total."], ["Caer con fuerza sobre los talones.", "Encorvarte hacia delante cuando te cansas."], "Para si te duelen las rodillas o las espinillas, y descansa antes de volver a intentarlo."),
    "it": ExerciseGuide(["Stai dritto, con le braccia lungo i fianchi o verso l'alto.", "Fai piccoli salti elastici e tieni il corpo dritto per tutto il tempo.", "Atterra morbido sull'avampiede, con le ginocchia leggermente piegate.", "Continua per 20 secondi, 3 serie in totale."], ["Atterrare pesantemente sui talloni.", "Incurvarti in avanti quando ti stanchi."], "Fermati se ti fanno male le ginocchia o gli stinchi, e riposa prima di riprovare."),
    "pt": ExerciseGuide(["Fique reto, com os braços ao lado do corpo ou para cima.", "Dê saltos pequenos e elásticos e mantenha o corpo reto o tempo todo.", "Aterrisse suavemente na parte da frente dos pés, com os joelhos levemente dobrados.", "Continue por 20 segundos, 3 séries no total."], ["Cair com força sobre os calcanhares.", "Curvar o corpo para frente quando cansar."], "Pare se os joelhos ou as canelas doerem, e descanse antes de tentar de novo."),
    "hi": ExerciseGuide(["सीधे खड़े हो जाओ, हाथ बगल में या ऊपर रखो।", "छोटी, लचीली छलाँगें लगाओ और पूरे समय शरीर सीधा रखो।", "पंजों के अगले हिस्से पर नरमी से उतरो, घुटने हल्के मुड़े रहें।", "20 सेकंड तक करते रहो, कुल 3 सेट।"], ["एड़ियों पर ज़ोर से उतरना।", "थकने पर आगे की ओर झुक जाना।"], "घुटनों या पिंडली की हड्डी में दर्द हो तो रुक जाओ और दोबारा करने से पहले आराम करो।"),
    "nl": ExerciseGuide(["Sta rechtop met je armen langs je lichaam of omhoog.", "Maak kleine, verende sprongen en blijf de hele tijd rechtop.", "Land zacht op je voorvoeten, met je knieën licht gebogen.", "Ga 20 seconden door, 3 sets in totaal."], ["Hard op je hielen landen.", "Voorover zakken als je moe wordt."], "Stop als je knieën of schenen pijn doen, en rust uit voordat je het opnieuw probeert."),
    "pl": ExerciseGuide(["Stań prosto, ręce wzdłuż ciała lub uniesione w górę.", "Wykonuj małe, sprężyste skoki i cały czas trzymaj ciało prosto.", "Ląduj miękko na przodostopiu, z lekko ugiętymi kolanami.", "Kontynuuj przez 20 sekund, łącznie 3 serie."], ["Twarde lądowanie na piętach.", "Garbienie się do przodu, gdy przychodzi zmęczenie."], "Przerwij, jeśli bolą cię kolana lub piszczele, i odpocznij przed kolejną próbą."),
    "sv": ExerciseGuide(["Stå rak med armarna längs sidorna eller uppåt.", "Gör små, fjädrande hopp och håll kroppen upprätt hela tiden.", "Landa mjukt på framfoten med lätt böjda knän.", "Fortsätt i 20 sekunder, 3 set totalt."], ["Att landa hårt på hälarna.", "Att sjunka ihop framåt när du blir trött."], "Sluta om det gör ont i knäna eller smalbenen, och vila innan du försöker igen."),
  },
  "calf_pulses": {
    "en": ExerciseGuide(["Stand tall and rise onto your tiptoes, fingertips on a wall if you need balance.", "Bounce up and down in small pulses, just a few centimetres.", "Keep your heels off the floor for the whole set.", "Keep going for 20 seconds, 3 sets in total."], ["Letting your heels touch the floor between pulses.", "Making the movement so big that it stops being a pulse."], "A burn in your calves is normal. Sharp pain means stop."),
    "tr": ExerciseGuide(["Dik dur ve parmak uçlarına kalk, dengen için gerekirse parmaklarınla duvara dokun.", "Birkaç santimetrelik küçük hareketlerle aşağı yukarı yaylan.", "Set boyunca topuklarını yerden kesik tut.", "20 saniye boyunca devam et, toplam 3 set yap."], ["Yaylanmaların arasında topukları yere değdirmek.", "Hareketi fazla büyütüp yaylanmayı bozmak."], "Baldırlarda yanma normaldir. Keskin bir ağrı olursa dur."),
    "de": ExerciseGuide(["Stell dich aufrecht auf die Zehenspitzen, bei Bedarf mit den Fingerspitzen an der Wand.", "Federe in kleinen Pulsen auf und ab, nur ein paar Zentimeter.", "Lass die Fersen den ganzen Satz über in der Luft.", "Mach 20 Sekunden lang weiter, insgesamt 3 Sätze."], ["Die Fersen zwischen den Pulsen auf den Boden setzen.", "Die Bewegung so groß machen, dass es kein Puls mehr ist."], "Brennen in den Waden ist normal. Bei stechendem Schmerz hörst du auf."),
    "fr": ExerciseGuide(["Tiens-toi droit et monte sur la pointe des pieds, le bout des doigts au mur si besoin.", "Rebondis par petites impulsions, juste quelques centimètres.", "Garde les talons décollés pendant toute la série.", "Continue pendant 20 secondes, 3 séries au total."], ["Reposer les talons au sol entre les rebonds.", "Faire un mouvement trop ample au lieu de petites impulsions."], "Une brûlure dans les mollets est normale. Une douleur vive, c'est stop."),
    "es": ExerciseGuide(["Ponte recto y sube de puntillas, con los dedos en la pared si necesitas equilibrio.", "Rebota arriba y abajo con pulsos pequeños, solo unos centímetros.", "Mantén los talones sin tocar el suelo toda la serie.", "Sigue durante 20 segundos, 3 series en total."], ["Apoyar los talones en el suelo entre pulsos.", "Hacer el movimiento tan grande que deja de ser un pulso."], "Sentir ardor en las pantorrillas es normal. Si hay dolor agudo, para."),
    "it": ExerciseGuide(["Stai dritto e sali sulle punte, con le dita sul muro se ti serve equilibrio.", "Molleggia su e giù con piccole pulsazioni, solo pochi centimetri.", "Tieni i talloni sollevati per tutta la serie.", "Continua per 20 secondi, 3 serie in totale."], ["Appoggiare i talloni a terra tra una pulsazione e l'altra.", "Fare un movimento così ampio da non essere più una pulsazione."], "Un bruciore ai polpacci è normale. Se senti un dolore acuto, fermati."),
    "pt": ExerciseGuide(["Fique reto e suba na ponta dos pés, com os dedos na parede se precisar de equilíbrio.", "Quique para cima e para baixo em pulsos pequenos, só alguns centímetros.", "Mantenha os calcanhares sem tocar o chão durante toda a série.", "Continue por 20 segundos, 3 séries no total."], ["Encostar os calcanhares no chão entre os pulsos.", "Fazer um movimento tão grande que deixa de ser um pulso."], "Sentir ardor nas panturrilhas é normal. Se for uma dor aguda, pare."),
    "hi": ExerciseGuide(["सीधे खड़े होकर पंजों पर उठो, संतुलन चाहिए तो उंगलियों से दीवार छुओ।", "बस कुछ सेंटीमीटर की छोटी पल्स में ऊपर-नीचे उछलो।", "पूरे सेट में एड़ियाँ ज़मीन से ऊपर रखो।", "20 सेकंड तक करते रहो, कुल 3 सेट।"], ["पल्स के बीच एड़ियों को ज़मीन पर टिका देना।", "हरकत इतनी बड़ी कर देना कि वह पल्स न रहे।"], "पिंडलियों में जलन होना सामान्य है। तेज़ दर्द हो तो रुक जाओ।"),
    "nl": ExerciseGuide(["Sta rechtop en kom op je tenen, met je vingertoppen tegen de muur als je balans nodig hebt.", "Veer op en neer in kleine pulsen, maar een paar centimeter.", "Houd je hielen de hele set van de vloer.", "Ga 20 seconden door, 3 sets in totaal."], ["Je hielen tussen de pulsen op de vloer zetten.", "De beweging zo groot maken dat het geen puls meer is."], "Een branderig gevoel in je kuiten is normaal. Bij scherpe pijn stop je."),
    "pl": ExerciseGuide(["Stań prosto i wspnij się na palce, w razie potrzeby oprzyj palce dłoni o ścianę.", "Sprężynuj w górę i w dół małymi ruchami, tylko o kilka centymetrów.", "Przez całą serię trzymaj pięty nad podłogą.", "Kontynuuj przez 20 sekund, łącznie 3 serie."], ["Dotykanie piętami podłogi między pulsacjami.", "Zbyt duży ruch, który przestaje być pulsacją."], "Pieczenie w łydkach jest normalne. Przy ostrym bólu przerwij."),
    "sv": ExerciseGuide(["Stå rak och res dig upp på tå, med fingertopparna mot en vägg om du behöver balans.", "Fjädra upp och ned i små pulser, bara några centimeter.", "Håll hälarna ovanför golvet hela setet.", "Fortsätt i 20 sekunder, 3 set totalt."], ["Att sätta ned hälarna i golvet mellan pulserna.", "Att göra rörelsen så stor att det inte längre är en puls."], "Det är normalt att det bränner i vaderna. Sluta vid skarp smärta."),
  },
  "toe_touch": {
    "en": ExerciseGuide(["Stand with your feet hip-width apart and your knees soft.", "Fold forward from your hips and let your hands reach toward your toes.", "Hold still for 20 seconds and breathe slowly.", "Roll up slowly, rest, and repeat once more."], ["Bouncing to reach further.", "Locking your knees straight."], "If you cannot reach your toes, stop at your shins. It still works."),
    "tr": ExerciseGuide(["Ayakların kalça genişliğinde dur, dizlerin hafif gevşek olsun.", "Kalçandan öne eğil, ellerini ayak parmaklarına doğru uzat.", "20 saniye sabit kal ve yavaşça nefes al.", "Yavaşça doğrul, dinlen ve bir kez daha tekrarla."], ["Daha aşağı inmek için yaylanmak.", "Dizlerini kilitleyip tamamen germek."], "Parmaklarına yetişemiyorsan kaval kemiklerinde dur, yine işe yarar."),
    "de": ExerciseGuide(["Stell die Füße hüftbreit hin und lass die Knie locker.", "Beug dich aus der Hüfte nach vorn, die Hände Richtung Zehen.", "Bleib 20 Sekunden ruhig und atme langsam.", "Roll dich langsam hoch, mach eine Pause und wiederhole es einmal."], ["Wippen, um weiter nach unten zu kommen.", "Die Knie durchdrücken."], "Kommst du nicht bis zu den Zehen, bleib bei den Schienbeinen. Das wirkt genauso."),
    "fr": ExerciseGuide(["Place les pieds à largeur de hanches, genoux souples.", "Penche-toi depuis les hanches et descends les mains vers les orteils.", "Reste immobile 20 secondes et respire lentement.", "Remonte lentement, repose-toi et recommence une fois."], ["Faire des rebonds pour descendre plus bas.", "Verrouiller les genoux."], "Si tu n'atteins pas tes orteils, arrête-toi aux tibias. Ça marche aussi."),
    "es": ExerciseGuide(["Separa los pies al ancho de la cadera, con las rodillas sin bloquear.", "Inclínate desde la cadera y lleva las manos hacia los pies.", "Quédate quieto 20 segundos y respira lento.", "Sube despacio, descansa y repite una vez más."], ["Rebotar para llegar más lejos.", "Bloquear las rodillas."], "Si no llegas a los pies, quédate en las espinillas. También funciona."),
    "it": ExerciseGuide(["Tieni i piedi alla larghezza del bacino e le ginocchia morbide.", "Piegati in avanti dalle anche e porta le mani verso le punte dei piedi.", "Resta fermo 20 secondi e respira piano.", "Risali piano, riposa e ripeti ancora una volta."], ["Molleggiare per arrivare più giù.", "Bloccare le ginocchia."], "Se non arrivi alle punte, fermati agli stinchi. Funziona lo stesso."),
    "pt": ExerciseGuide(["Fique com os pés na largura do quadril e os joelhos soltos.", "Incline o tronco a partir do quadril e leve as mãos em direção aos pés.", "Fique parado por 20 segundos e respire devagar.", "Suba devagar, descanse e repita mais uma vez."], ["Dar trancos para ir mais longe.", "Travar os joelhos."], "Se não alcançar os pés, pare nas canelas. Funciona do mesmo jeito."),
    "hi": ExerciseGuide(["पैर कूल्हों जितनी चौड़ाई पर रखो, घुटने ढीले रखो।", "कूल्हों से आगे झुको और हाथ पैरों की उंगलियों की ओर ले जाओ।", "20 सेकंड स्थिर रहो और धीरे-धीरे साँस लो।", "धीरे से ऊपर आओ, आराम करो और एक बार फिर दोहराओ।"], ["और नीचे जाने के लिए झटके देना।", "घुटनों को लॉक कर देना।"], "उंगलियों तक न पहुँचो तो पिंडलियों पर रुक जाओ। तब भी फ़ायदा होता है।"),
    "nl": ExerciseGuide(["Zet je voeten op heupbreedte en houd je knieën zacht.", "Buig voorover vanuit je heupen en breng je handen richting je tenen.", "Blijf 20 seconden stil en adem rustig.", "Rol langzaam omhoog, rust even en herhaal nog één keer."], ["Veren om verder te komen.", "Je knieën op slot zetten."], "Kom je niet bij je tenen, stop dan bij je schenen. Dat werkt ook."),
    "pl": ExerciseGuide(["Stań ze stopami na szerokość bioder i z miękkimi kolanami.", "Pochyl się z bioder i sięgnij dłońmi w stronę palców stóp.", "Zostań nieruchomo przez 20 sekund i oddychaj powoli.", "Powoli się wyprostuj, odpocznij i powtórz jeszcze raz."], ["Sprężynowanie, by sięgnąć dalej.", "Blokowanie kolan."], "Jeśli nie sięgasz palców, zatrzymaj się na piszczelach. To też działa."),
    "sv": ExerciseGuide(["Stå med fötterna höftbrett isär och mjuka knän.", "Fäll framåt i höften och för händerna mot tårna.", "Håll still i 20 sekunder och andas lugnt.", "Rulla långsamt upp, vila och upprepa en gång till."], ["Att gunga för att nå längre.", "Att låsa knäna."], "Når du inte tårna stannar du vid smalbenen. Det fungerar också."),
  },
  "downward_dog": {
    "en": ExerciseGuide(["Start on hands and knees, hands under your shoulders.", "Lift your hips high so your body makes an upside-down V.", "Keep your spine long and let your heels sink toward the floor.", "Hold 20 seconds and rest, 2 sets in total."], ["Rounding your back to force your heels down.", "Shrugging your shoulders up to your ears."], "Bend your knees a little if your back rounds. Your heels do not need to touch the floor."),
    "tr": ExerciseGuide(["Eller ve dizler üzerinde başla, ellerin omuzlarının altında olsun.", "Kalçanı yukarı kaldır, vücudun ters bir V oluştursun.", "Omurganı uzun tut, topuklarını yere doğru bırak.", "20 saniye tut ve dinlen, toplam 2 set yap."], ["Topukları yere indirmek için sırtı yuvarlamak.", "Omuzları kulaklara doğru kaldırmak."], "Sırtın yuvarlanıyorsa dizlerini biraz bük. Topukların yere değmek zorunda değil."),
    "de": ExerciseGuide(["Starte im Vierfüßlerstand, die Hände unter den Schultern.", "Schieb die Hüfte hoch, sodass dein Körper ein umgekehrtes V bildet.", "Halte die Wirbelsäule lang und lass die Fersen Richtung Boden sinken.", "Halte 20 Sekunden und mach Pause, insgesamt 2 Sätze."], ["Den Rücken rund machen, um die Fersen nach unten zu zwingen.", "Die Schultern zu den Ohren hochziehen."], "Beug die Knie leicht, wenn dein Rücken rund wird. Die Fersen müssen den Boden nicht berühren."),
    "fr": ExerciseGuide(["Commence à quatre pattes, mains sous les épaules.", "Monte les hanches pour que ton corps forme un V inversé.", "Garde la colonne longue et laisse les talons descendre vers le sol.", "Tiens 20 secondes et repose-toi, 2 séries au total."], ["Arrondir le dos pour forcer les talons au sol.", "Monter les épaules vers les oreilles."], "Plie un peu les genoux si ton dos s'arrondit. Tes talons n'ont pas besoin de toucher le sol."),
    "es": ExerciseGuide(["Empieza en cuatro apoyos, con las manos bajo los hombros.", "Sube la cadera hasta que tu cuerpo forme una V invertida.", "Mantén la columna larga y deja que los talones bajen hacia el suelo.", "Mantén 20 segundos y descansa, 2 series en total."], ["Redondear la espalda para forzar los talones hacia abajo.", "Subir los hombros hacia las orejas."], "Dobla un poco las rodillas si se te redondea la espalda. Los talones no tienen que tocar el suelo."),
    "it": ExerciseGuide(["Parti a quattro zampe, con le mani sotto le spalle.", "Solleva il bacino in alto finché il corpo forma una V rovesciata.", "Tieni la colonna lunga e lascia scendere i talloni verso il pavimento.", "Tieni 20 secondi e riposa, 2 serie in totale."], ["Arrotondare la schiena per forzare i talloni a terra.", "Alzare le spalle verso le orecchie."], "Piega un po' le ginocchia se la schiena si arrotonda. I talloni non devono per forza toccare terra."),
    "pt": ExerciseGuide(["Comece em quatro apoios, com as mãos embaixo dos ombros.", "Suba o quadril até o corpo formar um V invertido.", "Mantenha a coluna longa e deixe os calcanhares descerem em direção ao chão.", "Segure 20 segundos e descanse, 2 séries no total."], ["Arredondar as costas para forçar os calcanhares para baixo.", "Subir os ombros em direção às orelhas."], "Dobre um pouco os joelhos se as costas arredondarem. Os calcanhares não precisam tocar o chão."),
    "hi": ExerciseGuide(["हाथों और घुटनों के बल शुरू करो, हाथ कंधों के नीचे रखो।", "कूल्हे ऊपर उठाओ ताकि शरीर उल्टा V बने।", "रीढ़ लंबी रखो और एड़ियों को ज़मीन की ओर जाने दो।", "20 सेकंड रुको और आराम करो, कुल 2 सेट।"], ["एड़ियाँ नीचे लाने के लिए पीठ गोल कर लेना।", "कंधों को कानों की ओर उचकाना।"], "पीठ गोल हो रही हो तो घुटने थोड़े मोड़ लो। एड़ियों का ज़मीन छूना ज़रूरी नहीं है।"),
    "nl": ExerciseGuide(["Begin op handen en knieën, handen onder je schouders.", "Til je heupen hoog op zodat je lichaam een omgekeerde V vormt.", "Houd je wervelkolom lang en laat je hielen richting de vloer zakken.", "Houd 20 seconden vast en rust, 2 sets in totaal."], ["Je rug bol maken om je hielen omlaag te dwingen.", "Je schouders optrekken naar je oren."], "Buig je knieën een beetje als je rug bol wordt. Je hielen hoeven de vloer niet te raken."),
    "pl": ExerciseGuide(["Zacznij w klęku podpartym, dłonie pod barkami.", "Unieś biodra wysoko, by ciało utworzyło odwrócone V.", "Trzymaj długi kręgosłup i pozwól piętom opadać w stronę podłogi.", "Wytrzymaj 20 sekund i odpocznij, łącznie 2 serie."], ["Zaokrąglanie pleców, by na siłę opuścić pięty.", "Podciąganie barków do uszu."], "Jeśli plecy się zaokrąglają, lekko ugnij kolana. Pięty nie muszą dotykać podłogi."),
    "sv": ExerciseGuide(["Börja på alla fyra med händerna under axlarna.", "Lyft höfterna högt så att kroppen bildar ett upp- och nedvänt V.", "Håll ryggraden lång och låt hälarna sjunka mot golvet.", "Håll i 20 sekunder och vila, 2 set totalt."], ["Att runda ryggen för att tvinga ned hälarna.", "Att dra upp axlarna mot öronen."], "Böj knäna lite om ryggen rundas. Hälarna behöver inte nå golvet."),
  },
  "wall_angels": {
    "en": ExerciseGuide(["Stand with your back against a wall, feet a little in front of you.", "Put your arms on the wall with your elbows bent, like a goalpost.", "Keep your ribs down and slowly slide your arms up, then back down.", "Do 8 slow reps per set, 2 sets in total."], ["Letting your ribs flare and your lower back arch.", "Letting your arms come off the wall."], "Only go as high as your arms can stay on the wall. It gets easier with practice."),
    "tr": ExerciseGuide(["Sırtını duvara yasla, ayakların biraz önde olsun.", "Kollarını duvara koy, dirseklerin kale direği gibi bükülü olsun.", "Kaburgalarını aşağıda tut, kollarını yavaşça yukarı kaydır, sonra indir.", "Her sette 8 yavaş tekrar, toplam 2 set yap."], ["Kaburgaların öne çıkması ve belin çukurlaşması.", "Kolların duvardan ayrılması."], "Kolların duvarda kaldığı yere kadar çık. Yaptıkça kolaylaşır."),
    "de": ExerciseGuide(["Stell dich mit dem Rücken an die Wand, die Füße etwas davor.", "Leg die Arme an die Wand, die Ellbogen gebeugt wie ein Torpfosten.", "Halte die Rippen unten und schieb die Arme langsam hoch und wieder runter.", "Mach 8 langsame Wiederholungen pro Satz, insgesamt 2 Sätze."], ["Die Rippen nach vorn schieben und ins Hohlkreuz gehen.", "Die Arme von der Wand lösen."], "Geh nur so hoch, wie deine Arme an der Wand bleiben. Mit der Zeit wird es leichter."),
    "fr": ExerciseGuide(["Dos contre un mur, pieds légèrement devant toi.", "Pose les bras sur le mur, coudes pliés comme un poteau de but.", "Garde les côtes basses et fais glisser lentement les bras vers le haut, puis vers le bas.", "Fais 8 répétitions lentes par série, 2 séries au total."], ["Laisser les côtes s'ouvrir et le bas du dos se cambrer.", "Décoller les bras du mur."], "Monte seulement tant que tes bras restent sur le mur. Ça devient plus facile avec la pratique."),
    "es": ExerciseGuide(["Apoya la espalda en la pared, con los pies un poco adelantados.", "Pon los brazos en la pared con los codos doblados, como un poste de portería.", "Mantén las costillas abajo y desliza los brazos despacio hacia arriba y hacia abajo.", "Haz 8 repeticiones lentas por serie, 2 series en total."], ["Abrir las costillas y arquear la zona lumbar.", "Separar los brazos de la pared."], "Sube solo hasta donde tus brazos sigan en la pared. Con la práctica será más fácil."),
    "it": ExerciseGuide(["Appoggia la schiena al muro, con i piedi un po' in avanti.", "Metti le braccia sul muro con i gomiti piegati, come un palo della porta.", "Tieni le costole basse e fai scorrere piano le braccia in alto, poi di nuovo in basso.", "Fai 8 ripetizioni lente per serie, 2 serie in totale."], ["Lasciare aprire le costole e inarcare la zona lombare.", "Staccare le braccia dal muro."], "Sali solo finché le braccia restano sul muro. Con la pratica diventa più facile."),
    "pt": ExerciseGuide(["Encoste as costas na parede, com os pés um pouco à frente.", "Coloque os braços na parede com os cotovelos dobrados, como uma trave.", "Mantenha as costelas para baixo e deslize os braços devagar para cima e para baixo.", "Faça 8 repetições lentas por série, 2 séries no total."], ["Abrir as costelas e arquear a lombar.", "Tirar os braços da parede."], "Suba só até onde os braços continuam na parede. Com a prática fica mais fácil."),
    "hi": ExerciseGuide(["पीठ दीवार से लगाकर खड़े हो जाओ, पैर थोड़े आगे रखो।", "हाथ दीवार पर रखो, कोहनियाँ गोलपोस्ट की तरह मुड़ी रहें।", "पसलियाँ नीचे रखो और हाथ धीरे-धीरे ऊपर सरकाओ, फिर नीचे लाओ।", "हर सेट में 8 धीमे रेप्स करो, कुल 2 सेट।"], ["पसलियाँ बाहर निकालना और कमर मोड़ना।", "हाथों को दीवार से हटा लेना।"], "उतना ही ऊपर जाओ जितना हाथ दीवार पर टिके रहें। अभ्यास से आसान हो जाएगा।"),
    "nl": ExerciseGuide(["Sta met je rug tegen een muur, je voeten iets naar voren.", "Leg je armen tegen de muur met gebogen ellebogen, als een doelpaal.", "Houd je ribben laag en schuif je armen langzaam omhoog en weer omlaag.", "Doe 8 langzame herhalingen per set, 2 sets in totaal."], ["Je ribben naar voren duwen en je onderrug hol maken.", "Je armen van de muur laten komen."], "Ga alleen zo hoog als je armen op de muur kunnen blijven. Met oefening gaat het makkelijker."),
    "pl": ExerciseGuide(["Stań plecami do ściany, stopy trochę przed sobą.", "Oprzyj ręce o ścianę, łokcie zgięte jak słupek bramki.", "Trzymaj żebra nisko i powoli przesuwaj ręce w górę, potem w dół.", "Zrób 8 powolnych powtórzeń na serię, łącznie 2 serie."], ["Wypychanie żeber i wyginanie lędźwi.", "Odrywanie rąk od ściany."], "Podnoś ręce tylko tak wysoko, jak mogą zostać na ścianie. Z czasem będzie łatwiej."),
    "sv": ExerciseGuide(["Stå med ryggen mot en vägg och fötterna en bit framför dig.", "Lägg armarna mot väggen med böjda armbågar, som en målstolpe.", "Håll revbenen nere och för armarna långsamt uppåt och sedan nedåt.", "Gör 8 långsamma reps per set, 2 set totalt."], ["Att låta revbenen sticka ut och svanka i ländryggen.", "Att låta armarna lämna väggen."], "Gå bara så högt som armarna kan ligga kvar mot väggen. Det blir lättare med tiden."),
  },
  "superman": {
    "en": ExerciseGuide(["Lie face down with your arms reaching forward.", "Lift your arms and legs slightly off the floor.", "Keep your neck long, look at the floor and hold 2 seconds.", "Lower slowly, 8 reps per set, 2 sets in total."], ["Forcing your chest and legs up as high as you can.", "Tilting your head up and squeezing your neck."], "A small lift is enough. If your lower back pinches, lift less."),
    "tr": ExerciseGuide(["Yüzüstü uzan, kolların önde uzansın.", "Kollarını ve bacaklarını yerden hafifçe kaldır.", "Boynunu uzun tut, yere bak ve 2 saniye bekle.", "Yavaşça in, her sette 8 tekrar, toplam 2 set yap."], ["Göğsü ve bacakları zorlayarak olabildiğince yükseğe kaldırmak.", "Başı kaldırıp boynu sıkıştırmak."], "Küçük bir kaldırış yeterli. Belin sıkışıyorsa daha az kaldır."),
    "de": ExerciseGuide(["Leg dich auf den Bauch und streck die Arme nach vorn.", "Heb Arme und Beine leicht vom Boden ab.", "Halte den Nacken lang, schau zum Boden und halte 2 Sekunden.", "Senk dich langsam ab, 8 Wiederholungen pro Satz, 2 Sätze."], ["Brust und Beine mit Gewalt so hoch wie möglich heben.", "Den Kopf heben und den Nacken stauchen."], "Ein kleines Anheben reicht. Zwickt es im unteren Rücken, heb weniger an."),
    "fr": ExerciseGuide(["Allonge-toi sur le ventre, bras tendus vers l'avant.", "Décolle légèrement les bras et les jambes du sol.", "Garde la nuque longue, regarde le sol et tiens 2 secondes.", "Redescends lentement, 8 répétitions par série, 2 séries."], ["Forcer pour monter la poitrine et les jambes le plus haut possible.", "Relever la tête et écraser la nuque."], "Une petite élévation suffit. Si le bas du dos pince, monte moins."),
    "es": ExerciseGuide(["Túmbate boca abajo con los brazos estirados al frente.", "Levanta un poco los brazos y las piernas del suelo.", "Mantén el cuello largo, mira al suelo y aguanta 2 segundos.", "Baja despacio, 8 repeticiones por serie, 2 series."], ["Forzar el pecho y las piernas lo más alto posible.", "Levantar la cabeza y apretar el cuello."], "Con elevarlos un poco basta. Si te molesta la zona lumbar, sube menos."),
    "it": ExerciseGuide(["Sdraiati a pancia in giù con le braccia tese in avanti.", "Solleva leggermente braccia e gambe da terra.", "Tieni il collo lungo, guarda il pavimento e tieni 2 secondi.", "Scendi piano, 8 ripetizioni per serie, 2 serie."], ["Forzare petto e gambe il più in alto possibile.", "Alzare la testa e schiacciare il collo."], "Basta sollevarsi poco. Se senti pizzicare la zona lombare, sali di meno."),
    "pt": ExerciseGuide(["Deite de bruços com os braços esticados à frente.", "Levante um pouco os braços e as pernas do chão.", "Mantenha o pescoço longo, olhe para o chão e segure 2 segundos.", "Desça devagar, 8 repetições por série, 2 séries."], ["Forçar o peito e as pernas o mais alto que der.", "Levantar a cabeça e apertar o pescoço."], "Levantar um pouco já basta. Se a lombar incomodar, suba menos."),
    "hi": ExerciseGuide(["पेट के बल लेटो, हाथ आगे की ओर फैलाओ।", "हाथ और पैर ज़मीन से थोड़ा ऊपर उठाओ।", "गर्दन लंबी रखो, नज़र ज़मीन पर रखो और 2 सेकंड रुको।", "धीरे से नीचे आओ, हर सेट में 8 रेप्स, कुल 2 सेट।"], ["छाती और पैरों को ज़ोर लगाकर जितना हो सके ऊपर उठाना।", "सिर ऊपर करके गर्दन को दबाना।"], "थोड़ा उठाना ही काफ़ी है। कमर में चुभन हो तो और कम उठाओ।"),
    "nl": ExerciseGuide(["Ga op je buik liggen met je armen naar voren.", "Til je armen en benen iets van de vloer.", "Houd je nek lang, kijk naar de vloer en houd 2 seconden vast.", "Zak langzaam terug, 8 herhalingen per set, 2 sets in totaal."], ["Je borst en benen zo hoog mogelijk omhoog forceren.", "Je hoofd optillen en je nek samendrukken."], "Een klein stukje optillen is genoeg. Knelt je onderrug, til dan minder hoog."),
    "pl": ExerciseGuide(["Połóż się na brzuchu, ręce wyciągnięte do przodu.", "Unieś lekko ręce i nogi nad podłogę.", "Trzymaj długą szyję, patrz w podłogę i wytrzymaj 2 sekundy.", "Powoli opuść, 8 powtórzeń na serię, łącznie 2 serie."], ["Unoszenie klatki i nóg na siłę jak najwyżej.", "Zadzieranie głowy i ściskanie karku."], "Wystarczy niewielkie uniesienie. Jeśli coś ciśnie w lędźwiach, unoś mniej."),
    "sv": ExerciseGuide(["Ligg på mage med armarna sträckta framåt.", "Lyft armar och ben en liten bit från golvet.", "Håll nacken lång, titta ned i golvet och håll i 2 sekunder.", "Sänk långsamt, 8 reps per set, 2 set totalt."], ["Att tvinga upp bröst och ben så högt det går.", "Att lyfta huvudet och klämma ihop nacken."], "Ett litet lyft räcker. Om det nyper i ländryggen lyfter du mindre."),
  },
  "knee_circles": {
    "en": ExerciseGuide(["Stand with your feet together and bend your knees slightly.", "Put your hands on your knees.", "Make small, slow circles with your knees for 15 seconds one way.", "Switch direction and go 15 seconds the other way."], ["Making big circles that twist your knees.", "Doing all your circles in one direction."], "Use it as a warm-up before jumps or running."),
    "tr": ExerciseGuide(["Ayaklarını birleştir ve dizlerini hafifçe bük.", "Ellerini dizlerinin üstüne koy.", "Dizlerinle küçük ve yavaş daireler çiz, 15 saniye bir yöne.", "Yön değiştir, 15 saniye de diğer yöne yap."], ["Dizleri zorlayan büyük daireler çizmek.", "Bütün turları tek yöne yapmak."], "Zıplama ya da koşudan önce ısınma olarak yap."),
    "de": ExerciseGuide(["Stell die Füße zusammen und beug die Knie leicht.", "Leg die Hände auf die Knie.", "Mach 15 Sekunden lang kleine, langsame Kreise mit den Knien in eine Richtung.", "Wechsle die Richtung und mach 15 Sekunden in die andere."], ["Große Kreise machen, die die Knie verdrehen.", "Alle Kreise nur in eine Richtung machen."], "Nutz es zum Aufwärmen vor Sprüngen oder dem Laufen."),
    "fr": ExerciseGuide(["Pieds joints, plie légèrement les genoux.", "Pose les mains sur les genoux.", "Fais de petits cercles lents avec les genoux pendant 15 secondes dans un sens.", "Change de sens et continue 15 secondes dans l'autre."], ["Faire de grands cercles qui tordent les genoux.", "Faire tous les cercles dans le même sens."], "Fais-les en échauffement avant de sauter ou de courir."),
    "es": ExerciseGuide(["Junta los pies y flexiona un poco las rodillas.", "Pon las manos sobre las rodillas.", "Haz círculos pequeños y lentos con las rodillas durante 15 segundos hacia un lado.", "Cambia de dirección y sigue 15 segundos hacia el otro."], ["Hacer círculos grandes que retuercen las rodillas.", "Hacer todos los círculos en una sola dirección."], "Úsalo como calentamiento antes de saltar o correr."),
    "it": ExerciseGuide(["Unisci i piedi e piega leggermente le ginocchia.", "Appoggia le mani sulle ginocchia.", "Fai piccoli cerchi lenti con le ginocchia per 15 secondi in un senso.", "Cambia direzione e continua per 15 secondi nell'altro."], ["Fare cerchi grandi che torcono le ginocchia.", "Fare tutti i cerchi nella stessa direzione."], "Usalo come riscaldamento prima di saltare o correre."),
    "pt": ExerciseGuide(["Junte os pés e dobre levemente os joelhos.", "Coloque as mãos sobre os joelhos.", "Faça círculos pequenos e lentos com os joelhos por 15 segundos para um lado.", "Troque de direção e continue por 15 segundos para o outro."], ["Fazer círculos grandes que torcem os joelhos.", "Fazer todos os círculos na mesma direção."], "Use como aquecimento antes de pular ou correr."),
    "hi": ExerciseGuide(["पैर साथ रखो और घुटने हल्के मोड़ो।", "हाथ घुटनों पर रखो।", "घुटनों से छोटे, धीमे घेरे बनाओ, एक दिशा में 15 सेकंड।", "दिशा बदलो और दूसरी ओर 15 सेकंड करो।"], ["बड़े घेरे बनाना जिनसे घुटने मुड़ें।", "सारे घेरे एक ही दिशा में करना।"], "छलाँग या दौड़ से पहले वॉर्म-अप के तौर पर करो।"),
    "nl": ExerciseGuide(["Zet je voeten tegen elkaar en buig je knieën licht.", "Leg je handen op je knieën.", "Maak 15 seconden lang kleine, langzame rondjes met je knieën de ene kant op.", "Wissel van richting en ga 15 seconden de andere kant op."], ["Grote rondjes maken die je knieën verdraaien.", "Alle rondjes dezelfde kant op doen."], "Gebruik het als warming-up voor springen of rennen."),
    "pl": ExerciseGuide(["Złącz stopy i lekko ugnij kolana.", "Połóż dłonie na kolanach.", "Rób kolanami małe, powolne kółka przez 15 sekund w jedną stronę.", "Zmień kierunek i rób kółka przez 15 sekund w drugą stronę."], ["Duże kółka, które skręcają kolana.", "Robienie wszystkich kółek w jedną stronę."], "Rób je jako rozgrzewkę przed skakaniem lub bieganiem."),
    "sv": ExerciseGuide(["Ställ fötterna ihop och böj knäna lätt.", "Lägg händerna på knäna.", "Gör små, långsamma cirklar med knäna i 15 sekunder åt ena hållet.", "Byt riktning och fortsätt i 15 sekunder åt andra hållet."], ["Att göra stora cirklar som vrider knäna.", "Att göra alla cirklar åt samma håll."], "Använd den som uppvärmning före hopp eller löpning."),
  },
  "upward_salute": {
    "en": ExerciseGuide(["Stand with your feet together and your arms by your sides.", "Breathe in and reach both arms up over your head.", "Keep your ribs down and your shoulders away from your ears.", "Hold 15 seconds, breathing slowly, then lower your arms. 2 sets in total."], ["Leaning back and arching your lower back.", "Letting your ribs push forward."], "Reach up, not back. Keep your body stacked over your feet."),
    "tr": ExerciseGuide(["Ayaklarını birleştir, kolların yanda olsun.", "Nefes al ve iki kolunu başının üstüne uzat.", "Kaburgalarını aşağıda, omuzlarını kulaklarından uzakta tut.", "Yavaş nefeslerle 15 saniye tut, sonra kollarını indir. Toplam 2 set yap."], ["Geriye yaslanıp beli çukurlaştırmak.", "Kaburgaların öne çıkmasına izin vermek."], "Geriye değil yukarı uzan. Vücudun ayaklarının tam üstünde kalsın."),
    "de": ExerciseGuide(["Stell die Füße zusammen, die Arme seitlich am Körper.", "Atme ein und streck beide Arme über den Kopf.", "Halte die Rippen unten und die Schultern weg von den Ohren.", "Halte 15 Sekunden mit ruhigem Atem und senk dann die Arme. Insgesamt 2 Sätze."], ["Nach hinten lehnen und ins Hohlkreuz gehen.", "Die Rippen nach vorn schieben."], "Streck dich nach oben, nicht nach hinten. Dein Körper bleibt genau über den Füßen."),
    "fr": ExerciseGuide(["Pieds joints, bras le long du corps.", "Inspire et monte les deux bras au-dessus de la tête.", "Garde les côtes basses et les épaules loin des oreilles.", "Tiens 15 secondes en respirant lentement, puis redescends les bras. 2 séries au total."], ["Te pencher en arrière en cambrant le bas du dos.", "Laisser les côtes pousser vers l'avant."], "Monte vers le haut, pas vers l'arrière. Ton corps reste bien aligné au-dessus des pieds."),
    "es": ExerciseGuide(["Junta los pies y deja los brazos a los lados.", "Inhala y sube los dos brazos por encima de la cabeza.", "Mantén las costillas abajo y los hombros lejos de las orejas.", "Mantén 15 segundos respirando lento y baja los brazos. 2 series en total."], ["Echarte hacia atrás y arquear la zona lumbar.", "Dejar que las costillas se vayan hacia delante."], "Sube hacia arriba, no hacia atrás. Mantén el cuerpo alineado sobre los pies."),
    "it": ExerciseGuide(["Unisci i piedi e tieni le braccia lungo i fianchi.", "Inspira e porta entrambe le braccia sopra la testa.", "Tieni le costole basse e le spalle lontane dalle orecchie.", "Tieni 15 secondi respirando piano, poi abbassa le braccia. 2 serie in totale."], ["Inclinarti indietro inarcando la zona lombare.", "Lasciare che le costole spingano in avanti."], "Vai verso l'alto, non indietro. Tieni il corpo allineato sopra i piedi."),
    "pt": ExerciseGuide(["Junte os pés e deixe os braços ao lado do corpo.", "Inspire e leve os dois braços acima da cabeça.", "Mantenha as costelas baixas e os ombros longe das orelhas.", "Segure 15 segundos respirando devagar e abaixe os braços. 2 séries no total."], ["Inclinar para trás e arquear a lombar.", "Deixar as costelas irem para frente."], "Vá para cima, não para trás. Mantenha o corpo alinhado sobre os pés."),
    "hi": ExerciseGuide(["पैर साथ रखो, हाथ बगल में रखो।", "साँस लो और दोनों हाथ सिर के ऊपर ले जाओ।", "पसलियाँ नीचे और कंधे कानों से दूर रखो।", "धीमी साँसों के साथ 15 सेकंड रुको, फिर हाथ नीचे लाओ। कुल 2 सेट।"], ["पीछे झुकना और कमर मोड़ना।", "पसलियों को आगे निकलने देना।"], "ऊपर की ओर जाओ, पीछे की ओर नहीं। शरीर पैरों के ठीक ऊपर रखो।"),
    "nl": ExerciseGuide(["Zet je voeten tegen elkaar, armen langs je lichaam.", "Adem in en breng beide armen boven je hoofd.", "Houd je ribben laag en je schouders weg van je oren.", "Houd 15 seconden vast, adem rustig en laat dan je armen zakken. 2 sets in totaal."], ["Achterover leunen en je onderrug hol maken.", "Je ribben naar voren laten duwen."], "Reik omhoog, niet naar achteren. Houd je lichaam recht boven je voeten."),
    "pl": ExerciseGuide(["Złącz stopy, ręce wzdłuż ciała.", "Zrób wdech i unieś obie ręce nad głowę.", "Trzymaj żebra nisko, a barki z dala od uszu.", "Wytrzymaj 15 sekund, oddychając powoli, potem opuść ręce. Łącznie 2 serie."], ["Odchylanie się do tyłu i wyginanie lędźwi.", "Wypychanie żeber do przodu."], "Sięgaj w górę, nie do tyłu. Trzymaj ciało w linii nad stopami."),
    "sv": ExerciseGuide(["Ställ fötterna ihop med armarna längs sidorna.", "Andas in och för båda armarna över huvudet.", "Håll revbenen nere och axlarna bort från öronen.", "Håll i 15 sekunder och andas lugnt, sänk sedan armarna. 2 set totalt."], ["Att luta dig bakåt och svanka i ländryggen.", "Att låta revbenen trycka framåt."], "Sträck dig uppåt, inte bakåt. Håll kroppen rakt ovanför fötterna."),
  },
  "wall_dog": {
    "en": ExerciseGuide(["Stand facing a wall, about one leg length away.", "Put your hands on the wall at hip height.", "Hinge back from your hips until your arms are straight and your spine is long.", "Hold 20 seconds, breathing slowly, 2 sets in total."], ["Rounding your upper back.", "Bending your elbows and leaning on the wall."], "A great break at your desk when you cannot get on the floor."),
    "tr": ExerciseGuide(["Duvara dön, yaklaşık bir bacak boyu uzakta dur.", "Ellerini kalça hizasında duvara koy.", "Kolların düz, omurgan uzun olana kadar kalçanı geriye it.", "Yavaş nefeslerle 20 saniye tut, toplam 2 set yap."], ["Sırtın üst kısmını yuvarlamak.", "Dirsekleri büküp duvara yaslanmak."], "Yere inemediğin zamanlarda masa başında harika bir mola."),
    "de": ExerciseGuide(["Stell dich etwa eine Beinlänge vor eine Wand.", "Leg die Hände auf Hüfthöhe an die Wand.", "Schieb die Hüfte nach hinten, bis die Arme gestreckt sind und die Wirbelsäule lang ist.", "Halte 20 Sekunden mit ruhigem Atem, 2 Sätze."], ["Den oberen Rücken rund machen.", "Die Ellbogen beugen und dich an die Wand lehnen."], "Ideal als Pause am Schreibtisch, wenn du nicht auf den Boden kannst."),
    "fr": ExerciseGuide(["Place-toi face à un mur, à environ une longueur de jambe.", "Pose les mains sur le mur à hauteur de hanches.", "Recule les hanches jusqu'à avoir les bras tendus et la colonne longue.", "Tiens 20 secondes en respirant lentement, 2 séries au total."], ["Arrondir le haut du dos.", "Plier les coudes et t'appuyer sur le mur."], "Parfait comme pause au bureau quand tu ne peux pas te mettre au sol."),
    "es": ExerciseGuide(["Ponte frente a una pared, a una pierna de distancia más o menos.", "Apoya las manos en la pared a la altura de la cadera.", "Lleva la cadera atrás hasta tener los brazos rectos y la columna larga.", "Mantén 20 segundos respirando lento, 2 series en total."], ["Redondear la parte alta de la espalda.", "Doblar los codos y apoyarte en la pared."], "Ideal como pausa en el escritorio cuando no puedes tumbarte en el suelo."),
    "it": ExerciseGuide(["Mettiti di fronte a un muro, a circa una gamba di distanza.", "Appoggia le mani al muro all'altezza delle anche.", "Porta il bacino indietro finché le braccia sono tese e la colonna è lunga.", "Tieni 20 secondi respirando piano, 2 serie in totale."], ["Arrotondare la parte alta della schiena.", "Piegare i gomiti e appoggiarti al muro."], "Perfetto come pausa alla scrivania quando non puoi metterti a terra."),
    "pt": ExerciseGuide(["Fique de frente para uma parede, a mais ou menos uma perna de distância.", "Apoie as mãos na parede na altura do quadril.", "Leve o quadril para trás até os braços ficarem retos e a coluna longa.", "Segure 20 segundos respirando devagar, 2 séries no total."], ["Arredondar a parte de cima das costas.", "Dobrar os cotovelos e se apoiar na parede."], "Ótimo como pausa na mesa de trabalho quando não dá para ir ao chão."),
    "hi": ExerciseGuide(["दीवार की ओर मुँह करके लगभग एक पैर की दूरी पर खड़े हो जाओ।", "हाथ कूल्हों की ऊँचाई पर दीवार पर रखो।", "कूल्हों को पीछे ले जाओ जब तक हाथ सीधे और रीढ़ लंबी न हो जाए।", "धीमी साँसों के साथ 20 सेकंड रुको, कुल 2 सेट।"], ["पीठ का ऊपरी हिस्सा गोल करना।", "कोहनियाँ मोड़कर दीवार पर टिक जाना।"], "जब ज़मीन पर न जा सको, तब डेस्क पर बढ़िया ब्रेक है।"),
    "nl": ExerciseGuide(["Ga met je gezicht naar een muur staan, ongeveer een beenlengte ervandaan.", "Zet je handen op heuphoogte tegen de muur.", "Duw je heupen naar achteren tot je armen gestrekt zijn en je wervelkolom lang is.", "Houd 20 seconden vast en adem rustig, 2 sets in totaal."], ["Je bovenrug bol maken.", "Je ellebogen buigen en tegen de muur leunen."], "Een fijne pauze aan je bureau als je niet op de vloer kunt."),
    "pl": ExerciseGuide(["Stań twarzą do ściany, mniej więcej na długość nogi od niej.", "Oprzyj dłonie o ścianę na wysokości bioder.", "Cofnij biodra, aż ręce będą proste, a kręgosłup długi.", "Wytrzymaj 20 sekund, oddychając powoli, łącznie 2 serie."], ["Zaokrąglanie górnej części pleców.", "Uginanie łokci i opieranie się o ścianę."], "Świetna przerwa przy biurku, gdy nie możesz położyć się na podłodze."),
    "sv": ExerciseGuide(["Stå vänd mot en vägg, ungefär en benlängd ifrån.", "Sätt händerna mot väggen i höfthöjd.", "Fäll höfterna bakåt tills armarna är raka och ryggraden är lång.", "Håll i 20 sekunder och andas lugnt, 2 set totalt."], ["Att runda övre delen av ryggen.", "Att böja armbågarna och luta dig mot väggen."], "En perfekt paus vid skrivbordet när du inte kan gå ned på golvet."),
  },
  "chin_tucks": {
    "en": ExerciseGuide(["Sit or stand tall and look straight ahead.", "Slide your chin straight back, as if making a double chin.", "Hold 3 seconds, then relax.", "Do 8 reps per set, 2 sets in total."], ["Nodding your head down instead of sliding it back.", "Pushing so hard that your neck hurts."], "Do a few every time you put your phone down."),
    "tr": ExerciseGuide(["Dik otur ya da dur, tam karşıya bak.", "Çeneni düz bir şekilde geriye kaydır, gıdı yapar gibi.", "3 saniye bekle, sonra gevşe.", "Her sette 8 tekrar, toplam 2 set yap."], ["Geriye kaydırmak yerine başı aşağı sallamak.", "Boynun ağrıyacak kadar zorlamak."], "Telefonu her bıraktığında birkaç tane yap."),
    "de": ExerciseGuide(["Sitz oder steh aufrecht und schau geradeaus.", "Schieb das Kinn gerade nach hinten, als würdest du ein Doppelkinn machen.", "Halte 3 Sekunden und lass dann locker.", "Mach 8 Wiederholungen pro Satz, insgesamt 2 Sätze."], ["Mit dem Kopf nicken, statt ihn nach hinten zu schieben.", "So stark drücken, dass der Nacken wehtut."], "Mach ein paar, jedes Mal wenn du dein Handy weglegst."),
    "fr": ExerciseGuide(["Assis ou debout bien droit, regarde devant toi.", "Fais glisser le menton droit vers l'arrière, comme pour faire un double menton.", "Tiens 3 secondes, puis relâche.", "Fais 8 répétitions par série, 2 séries au total."], ["Hocher la tête vers le bas au lieu de la reculer.", "Pousser si fort que le cou fait mal."], "Fais-en quelques-uns chaque fois que tu poses ton téléphone."),
    "es": ExerciseGuide(["Siéntate o ponte recto y mira al frente.", "Desliza la barbilla recta hacia atrás, como si hicieras papada.", "Mantén 3 segundos y relaja.", "Haz 8 repeticiones por serie, 2 series en total."], ["Asentir con la cabeza en vez de llevarla hacia atrás.", "Empujar tanto que te duela el cuello."], "Haz unas cuantas cada vez que dejes el teléfono."),
    "it": ExerciseGuide(["Stai seduto o in piedi ben dritto e guarda davanti a te.", "Fai scorrere il mento dritto indietro, come per fare il doppio mento.", "Tieni 3 secondi, poi rilassa.", "Fai 8 ripetizioni per serie, 2 serie in totale."], ["Fare sì con la testa invece di portarla indietro.", "Spingere così forte da farti male al collo."], "Fanne qualcuna ogni volta che posi il telefono."),
    "pt": ExerciseGuide(["Sente ou fique em pé bem reto e olhe para frente.", "Deslize o queixo reto para trás, como se fizesse papada.", "Segure 3 segundos e relaxe.", "Faça 8 repetições por série, 2 séries no total."], ["Abaixar a cabeça em vez de levá-la para trás.", "Empurrar tanto que o pescoço dói."], "Faça algumas toda vez que largar o celular."),
    "hi": ExerciseGuide(["सीधे बैठो या खड़े रहो और सामने देखो।", "ठुड्डी को सीधा पीछे सरकाओ, जैसे डबल चिन बना रहे हो।", "3 सेकंड रुको, फिर ढीला छोड़ो।", "हर सेट में 8 रेप्स करो, कुल 2 सेट।"], ["पीछे सरकाने की बजाय सिर को नीचे हिलाना।", "इतना ज़ोर लगाना कि गर्दन में दर्द हो।"], "जब भी फ़ोन नीचे रखो, कुछ बार कर लो।"),
    "nl": ExerciseGuide(["Zit of sta rechtop en kijk recht vooruit.", "Schuif je kin recht naar achteren, alsof je een dubbele kin maakt.", "Houd 3 seconden vast en ontspan dan.", "Doe 8 herhalingen per set, 2 sets in totaal."], ["Met je hoofd knikken in plaats van het naar achteren te schuiven.", "Zo hard duwen dat je nek pijn doet."], "Doe er een paar telkens als je je telefoon weglegt."),
    "pl": ExerciseGuide(["Usiądź lub stań prosto i patrz przed siebie.", "Przesuń brodę prosto do tyłu, jakbyś robił podwójny podbródek.", "Wytrzymaj 3 sekundy, potem rozluźnij.", "Zrób 8 powtórzeń na serię, łącznie 2 serie."], ["Kiwanie głową w dół zamiast cofania jej.", "Pchanie tak mocno, że boli szyja."], "Zrób kilka za każdym razem, gdy odkładasz telefon."),
    "sv": ExerciseGuide(["Sitt eller stå rak och titta rakt fram.", "För hakan rakt bakåt, som om du gör en dubbelhaka.", "Håll i 3 sekunder och slappna sedan av.", "Gör 8 reps per set, 2 set totalt."], ["Att nicka med huvudet i stället för att föra det bakåt.", "Att trycka så hårt att det gör ont i nacken."], "Gör några varje gång du lägger ifrån dig mobilen."),
  },
  // ── v5 moves (generated by tool/moves_v2_gen.py) ──
  "pogo_jumps": {
    "en": ExerciseGuide(["Stand tall with your feet hip-width apart and your hands on your hips.", "Bounce on the balls of your feet with your knees almost straight.", "Keep each ground contact short and quick, like a pogo stick.", "Keep going for 20 seconds, 3 sets in total."], ["Bending your knees deeply on every bounce.", "Letting your heels slam into the floor."], "Jump on a firm, flat surface and stop if your shins or ankles hurt."),
    "tr": ExerciseGuide(["Dik dur, ayaklarını kalça genişliğinde aç, ellerini beline koy.", "Dizlerin neredeyse düzken ayak tabanının ön kısmında zıpla.", "Yere her değişin kısa ve hızlı olsun, zıplama çubuğu gibi.", "20 saniye boyunca devam et, toplam 3 set yap."], ["Her zıplamada dizleri fazla bükmek.", "Topukları yere sertçe vurmak."], "Sert ve düz bir zeminde zıpla, kaval kemiğin ya da bileğin ağrırsa dur."),
    "de": ExerciseGuide(["Stell dich aufrecht hin, die Füße hüftbreit, die Hände an den Hüften.", "Federe auf den Fußballen, die Knie fast gestreckt.", "Halte jeden Bodenkontakt kurz und schnell, wie ein Pogostock.", "Mach 20 Sekunden lang weiter, insgesamt 3 Sätze."], ["Bei jedem Sprung die Knie tief beugen.", "Die Fersen auf den Boden knallen lassen."], "Spring auf festem, ebenem Untergrund und hör auf, wenn Schienbeine oder Knöchel wehtun."),
    "fr": ExerciseGuide(["Tiens-toi droit, les pieds écartés largeur de hanches et les mains sur les hanches.", "Rebondis sur l'avant des pieds, les genoux presque tendus.", "Garde chaque contact avec le sol court et rapide, comme sur un bâton sauteur.", "Continue pendant 20 secondes, 3 séries au total."], ["Plier profondément les genoux à chaque rebond.", "Laisser les talons claquer au sol."], "Saute sur une surface ferme et plane, et arrête si tes tibias ou tes chevilles te font mal."),
    "es": ExerciseGuide(["Ponte recto con los pies a la anchura de las caderas y las manos en la cintura.", "Rebota sobre la parte delantera de los pies con las rodillas casi estiradas.", "Haz cada contacto con el suelo corto y rápido, como un palo de pogo.", "Sigue durante 20 segundos, 3 series en total."], ["Flexionar mucho las rodillas en cada rebote.", "Dejar que los talones golpeen el suelo."], "Salta sobre una superficie firme y plana, y para si te duelen las espinillas o los tobillos."),
    "it": ExerciseGuide(["Stai dritto con i piedi alla larghezza delle anche e le mani sui fianchi.", "Rimbalza sull'avampiede con le ginocchia quasi tese.", "Tieni ogni contatto con il suolo breve e veloce, come su un pogo stick.", "Continua per 20 secondi, 3 serie in totale."], ["Piegare molto le ginocchia a ogni rimbalzo.", "Far sbattere i talloni sul pavimento."], "Salta su una superficie dura e piana e fermati se ti fanno male gli stinchi o le caviglie."),
    "pt": ExerciseGuide(["Fique em pé com os pés na largura do quadril e as mãos na cintura.", "Quique na ponta dos pés com os joelhos quase esticados.", "Deixe cada contato com o chão curto e rápido, como um pula-pula.", "Continue por 20 segundos, 3 séries no total."], ["Dobrar muito os joelhos a cada quique.", "Bater os calcanhares no chão."], "Salte em uma superfície firme e plana e pare se as canelas ou os tornozelos doerem."),
    "hi": ExerciseGuide(["पैरों को कूल्हों की चौड़ाई में रखकर सीधे खड़े हो जाओ, हाथ कमर पर रखो।", "घुटनों को लगभग सीधा रखकर पंजों के अगले हिस्से पर उछलो।", "हर बार ज़मीन से संपर्क छोटा और तेज़ रखो, जैसे पोगो स्टिक पर।", "20 सेकंड तक करते रहो, कुल 3 सेट।"], ["हर उछाल पर घुटनों को बहुत ज़्यादा मोड़ना।", "एड़ियों को ज़मीन पर पटकना।"], "सख़्त और समतल जगह पर कूदो और पिंडली या टखनों में दर्द हो तो रुक जाओ।"),
    "nl": ExerciseGuide(["Sta rechtop met je voeten op heupbreedte en je handen op je heupen.", "Veer op de ballen van je voeten met je knieën bijna gestrekt.", "Houd elk grondcontact kort en snel, als op een pogostick.", "Ga 20 seconden door, 3 sets in totaal."], ["Bij elke sprong je knieën diep buigen.", "Je hielen op de vloer laten knallen."], "Spring op een stevige, vlakke ondergrond en stop als je schenen of enkels pijn doen."),
    "pl": ExerciseGuide(["Stań prosto, stopy na szerokość bioder, dłonie na biodrach.", "Odbijaj się na przodostopiu, z kolanami prawie wyprostowanymi.", "Kontakt z podłożem niech będzie krótki i szybki, jak na kiju pogo.", "Kontynuuj przez 20 sekund, łącznie 3 serie."], ["Głębokie uginanie kolan przy każdym odbiciu.", "Uderzanie piętami o podłogę."], "Skacz na twardym, płaskim podłożu i przerwij, jeśli bolą cię piszczele lub kostki."),
    "sv": ExerciseGuide(["Stå rak med fötterna höftbrett isär och händerna på höfterna.", "Studsa på framfötterna med nästan raka knän.", "Håll varje markkontakt kort och snabb, som på en hoppstylta.", "Fortsätt i 20 sekunder, 3 set totalt."], ["Att böja knäna djupt vid varje studs.", "Att låta hälarna smälla i golvet."], "Hoppa på ett fast, plant underlag och sluta om det gör ont i smalbenen eller fotlederna."),
  },
  "jump_squats": {
    "en": ExerciseGuide(["Stand with your feet shoulder-width apart and your chest up.", "Sit back into a squat until your thighs are about level with the floor.", "Push hard through your feet, jump straight up and land softly back in the squat.", "Do 8 jumps, rest, and repeat for 3 sets in total."], ["Letting your knees cave inward on the landing.", "Landing with stiff, straight legs."], "Land as quietly as you can, and stop the set when your landings get loud."),
    "tr": ExerciseGuide(["Ayaklarını omuz genişliğinde aç, göğsünü dik tut.", "Uylukların yere yaklaşık paralel olana kadar geriye doğru çök.", "Yeri güçlüce it, dümdüz yukarı sıçra ve yumuşakça tekrar squat pozisyonuna in.", "8 sıçrayış yap, dinlen ve toplam 3 set tamamla."], ["İnişte dizlerin içe doğru kaçması.", "Bacaklar dümdüz ve kaskatı halde yere inmek."], "Olabildiğince sessiz inmeye çalış, inişlerin gürültülü olmaya başlayınca seti bitir."),
    "de": ExerciseGuide(["Stell dich schulterbreit hin, die Brust offen.", "Setz dich nach hinten in die Kniebeuge, bis die Oberschenkel etwa waagerecht sind.", "Drück dich kräftig über die Füße ab, spring senkrecht hoch und lande weich wieder in der Kniebeuge.", "Mach 8 Sprünge, ruh dich aus und wiederhole das Ganze, insgesamt 3 Sätze."], ["Die Knie bei der Landung nach innen kippen lassen.", "Mit steifen, durchgestreckten Beinen landen."], "Lande so leise wie möglich und beende den Satz, sobald die Landungen laut werden."),
    "fr": ExerciseGuide(["Tiens-toi les pieds écartés largeur d'épaules, la poitrine ouverte.", "Descends en squat en reculant les fesses, jusqu'à ce que les cuisses soient à peu près à l'horizontale.", "Pousse fort dans tes pieds, saute bien droit vers le haut et réceptionne-toi en douceur en squat.", "Fais 8 sauts, repose-toi et recommence, 3 séries au total."], ["Laisser les genoux rentrer vers l'intérieur à la réception.", "Retomber les jambes raides et tendues."], "Réceptionne-toi le plus silencieusement possible, et arrête la série quand les réceptions deviennent bruyantes."),
    "es": ExerciseGuide(["Ponte con los pies a la anchura de los hombros y el pecho abierto.", "Siéntate hacia atrás en una sentadilla hasta que los muslos queden casi paralelos al suelo.", "Empuja fuerte con los pies, salta recto hacia arriba y cae con suavidad otra vez en sentadilla.", "Haz 8 saltos, descansa y repite, 3 series en total."], ["Dejar que las rodillas se metan hacia dentro al caer.", "Caer con las piernas rígidas y estiradas."], "Cae lo más silencioso que puedas y termina la serie cuando las caídas empiecen a sonar fuerte."),
    "it": ExerciseGuide(["Stai con i piedi alla larghezza delle spalle e il petto alto.", "Siediti all'indietro in squat finché le cosce sono più o meno parallele al pavimento.", "Spingi forte sui piedi, salta in verticale e atterra morbido di nuovo in squat.", "Fai 8 salti, riposa e ripeti per 3 serie in totale."], ["Far cadere le ginocchia verso l'interno all'atterraggio.", "Atterrare con le gambe rigide e tese."], "Atterra più piano che puoi e chiudi la serie quando gli atterraggi diventano rumorosi."),
    "pt": ExerciseGuide(["Fique com os pés na largura dos ombros e o peito aberto.", "Sente para trás em um agachamento até as coxas ficarem mais ou menos paralelas ao chão.", "Empurre forte o chão, salte para cima e aterrisse suave de volta no agachamento.", "Faça 8 saltos, descanse e repita até completar 3 séries."], ["Deixar os joelhos caírem para dentro na aterrissagem.", "Aterrissar com as pernas duras e esticadas."], "Aterrisse o mais silenciosamente que puder e encerre a série quando as aterrissagens ficarem barulhentas."),
    "hi": ExerciseGuide(["पैरों को कंधों की चौड़ाई में रखकर खड़े हो जाओ, सीना ऊपर रखो।", "पीछे की ओर बैठकर स्क्वाट करो, जब तक जांघें लगभग ज़मीन के बराबर न आ जाएँ।", "पैरों से ज़ोर लगाओ, सीधे ऊपर कूदो और नरमी से वापस स्क्वाट में उतरो।", "8 जंप करो, आराम करो और दोहराओ, कुल 3 सेट।"], ["उतरते समय घुटनों को अंदर की ओर गिरने देना।", "सीधे और अकड़े पैरों से उतरना।"], "जितना हो सके धीरे उतरो और जब उतरने की आवाज़ तेज़ होने लगे तो सेट रोक दो।"),
    "nl": ExerciseGuide(["Sta met je voeten op schouderbreedte en je borst omhoog.", "Zak door je knieën tot je bovenbenen ongeveer horizontaal zijn.", "Duw hard af door je voeten, spring recht omhoog en land zacht terug in de squat.", "Doe 8 sprongen, rust en herhaal, 3 sets in totaal."], ["Je knieën naar binnen laten zakken bij het landen.", "Met stijve, gestrekte benen landen."], "Land zo stil mogelijk en stop de set zodra je landingen luid worden."),
    "pl": ExerciseGuide(["Stań w rozkroku na szerokość barków, klatka piersiowa uniesiona.", "Usiądź w przysiadzie, aż uda będą mniej więcej równolegle do podłogi.", "Mocno odepchnij się stopami, wyskocz prosto w górę i wyląduj miękko z powrotem w przysiadzie.", "Zrób 8 skoków, odpocznij i powtórz, łącznie 3 serie."], ["Zapadanie się kolan do środka przy lądowaniu.", "Lądowanie na sztywnych, prostych nogach."], "Lądując, staraj się robić jak najmniej hałasu i przerwij serię, gdy lądowania robią się głośne."),
    "sv": ExerciseGuide(["Stå med fötterna axelbrett isär och bröstet uppe.", "Sjunk ner i en knäböj tills låren är ungefär i höjd med golvet.", "Tryck hårt genom fötterna, hoppa rakt upp och landa mjukt tillbaka i knäböjen.", "Gör 8 hopp, vila och upprepa, 3 set totalt."], ["Att låta knäna falla inåt vid landningen.", "Att landa med stela, raka ben."], "Landa så tyst du kan och avbryt setet när landningarna börjar bli högljudda."),
  },
  "tuck_jumps": {
    "en": ExerciseGuide(["Stand tall with your feet hip-width apart.", "Dip into a quick quarter squat and jump as high as you can.", "Pull both knees toward your chest at the top, then land softly on bent knees.", "Do 6 jumps, rest, and repeat for 3 sets in total."], ["Bending your chest down to your knees instead of lifting the knees.", "Landing hard with straight legs."], "Reset your balance between jumps, and make sure you have clear space and a floor that does not slip."),
    "tr": ExerciseGuide(["Dik dur, ayaklarını kalça genişliğinde aç.", "Hızlıca hafif çök ve zıplayabildiğin kadar yükseğe zıpla.", "En tepede iki dizini göğsüne doğru çek, sonra dizlerin bükük halde yumuşakça in.", "6 zıplayış yap, dinlen ve toplam 3 set tamamla."], ["Dizleri kaldırmak yerine göğsü dizlere doğru eğmek.", "Bacaklar düzken sertçe yere inmek."], "Her zıplayıştan önce dengeni topla, etrafının boş ve zeminin kaymaz olduğundan emin ol."),
    "de": ExerciseGuide(["Stell dich aufrecht hin, die Füße hüftbreit.", "Geh kurz in eine kleine Kniebeuge und spring so hoch du kannst.", "Zieh oben beide Knie zur Brust und lande weich mit gebeugten Knien.", "Mach 6 Sprünge, ruh dich aus und wiederhole das Ganze, insgesamt 3 Sätze."], ["Den Oberkörper zu den Knien beugen, statt die Knie anzuheben.", "Mit durchgestreckten Beinen hart landen."], "Finde zwischen den Sprüngen dein Gleichgewicht wieder und sorg für freien Platz und einen rutschfesten Boden."),
    "fr": ExerciseGuide(["Tiens-toi droit, les pieds écartés largeur de hanches.", "Fléchis vite les genoux en quart de squat et saute le plus haut possible.", "En haut, ramène les deux genoux vers la poitrine, puis réceptionne-toi en douceur, genoux fléchis.", "Fais 6 sauts, repose-toi et recommence, 3 séries au total."], ["Pencher la poitrine vers les genoux au lieu de monter les genoux.", "Retomber lourdement, jambes tendues."], "Retrouve ton équilibre entre les sauts, et vérifie que tu as de la place et un sol qui ne glisse pas."),
    "es": ExerciseGuide(["Ponte recto con los pies a la anchura de las caderas.", "Baja rápido en un cuarto de sentadilla y salta lo más alto que puedas.", "Arriba, lleva las dos rodillas hacia el pecho y cae con suavidad con las rodillas flexionadas.", "Haz 6 saltos, descansa y repite, 3 series en total."], ["Inclinar el pecho hacia las rodillas en vez de subir las rodillas.", "Caer fuerte con las piernas estiradas."], "Recupera el equilibrio entre saltos, y asegúrate de tener espacio libre y un suelo que no resbale."),
    "it": ExerciseGuide(["Stai dritto con i piedi alla larghezza delle anche.", "Fai un rapido quarto di squat e salta più in alto che puoi.", "In alto porta entrambe le ginocchia verso il petto, poi atterra morbido a ginocchia piegate.", "Fai 6 salti, riposa e ripeti per 3 serie in totale."], ["Piegare il busto verso le ginocchia invece di alzare le ginocchia.", "Atterrare forte con le gambe tese."], "Ritrova l'equilibrio tra un salto e l'altro e assicurati di avere spazio libero e un pavimento che non scivola."),
    "pt": ExerciseGuide(["Fique em pé com os pés na largura do quadril.", "Desça em um quarto de agachamento rápido e salte o mais alto que puder.", "No alto, puxe os dois joelhos em direção ao peito e aterrisse suave com os joelhos dobrados.", "Faça 6 saltos, descanse e repita até completar 3 séries."], ["Curvar o peito para os joelhos em vez de subir os joelhos.", "Aterrissar forte com as pernas esticadas."], "Recupere o equilíbrio entre um salto e outro e garanta espaço livre e um piso que não escorregue."),
    "hi": ExerciseGuide(["पैरों को कूल्हों की चौड़ाई में रखकर सीधे खड़े हो जाओ।", "जल्दी से चौथाई स्क्वाट में झुको और जितना ऊँचा हो सके कूदो।", "ऊपर पहुँचकर दोनों घुटनों को सीने की ओर खींचो, फिर मुड़े घुटनों पर नरमी से उतरो।", "6 जंप करो, आराम करो और दोहराओ, कुल 3 सेट।"], ["घुटने उठाने की जगह सीने को घुटनों की ओर झुकाना।", "सीधे पैरों से ज़ोर से उतरना।"], "हर जंप के बीच संतुलन वापस पाओ और ध्यान रखो कि जगह खुली हो और फ़र्श फिसलने वाला न हो।"),
    "nl": ExerciseGuide(["Sta rechtop met je voeten op heupbreedte.", "Zak snel een kwart door je knieën en spring zo hoog als je kunt.", "Trek bovenaan beide knieën naar je borst en land dan zacht op gebogen knieën.", "Doe 6 sprongen, rust en herhaal, 3 sets in totaal."], ["Je borst naar je knieën buigen in plaats van je knieën op te trekken.", "Hard met gestrekte benen landen."], "Herstel je balans tussen de sprongen en zorg voor genoeg ruimte en een vloer die niet glad is."),
    "pl": ExerciseGuide(["Stań prosto, stopy na szerokość bioder.", "Szybko ugnij kolana w ćwierć przysiadu i wyskocz tak wysoko, jak potrafisz.", "W górze podciągnij oba kolana do klatki piersiowej, potem wyląduj miękko na ugiętych kolanach.", "Zrób 6 skoków, odpocznij i powtórz, łącznie 3 serie."], ["Zginanie klatki do kolan zamiast unoszenia kolan.", "Twarde lądowanie na prostych nogach."], "Odzyskuj równowagę między skokami i zadbaj o wolne miejsce oraz podłogę, która się nie ślizga."),
    "sv": ExerciseGuide(["Stå rak med fötterna höftbrett isär.", "Sjunk snabbt ner i en kvarts knäböj och hoppa så högt du kan.", "Dra båda knäna mot bröstet högst upp och landa sedan mjukt på böjda knän.", "Gör 6 hopp, vila och upprepa, 3 set totalt."], ["Att böja bröstet ner mot knäna i stället för att lyfta knäna.", "Att landa hårt med raka ben."], "Hitta balansen igen mellan hoppen och se till att du har fritt utrymme och ett golv som inte slirar."),
  },
  "broad_jumps": {
    "en": ExerciseGuide(["Stand with your feet hip-width apart and your toes behind a line.", "Swing your arms back, bend your knees and push your hips back.", "Swing your arms forward, jump as far as you can and land on both feet.", "Hold the landing for a second, walk back and do 5 jumps, 3 sets in total."], ["Falling forward or backward on the landing.", "Landing with your knees locked straight."], "Jump on a surface that does not slip, and jump shorter until you can hold every landing still."),
    "tr": ExerciseGuide(["Ayaklarını kalça genişliğinde aç, parmak uçların bir çizginin gerisinde olsun.", "Kollarını geriye sal, dizlerini bük ve kalçanı geriye it.", "Kollarını öne savur, atlayabildiğin kadar uzağa atla ve iki ayağının üstüne in.", "İnişte bir saniye sabit kal, geri yürü ve 5 atlayış yap, toplam 3 set."], ["İnişte öne ya da arkaya düşmek.", "Dizler kilitli ve dümdüz halde yere inmek."], "Kaymayan bir zeminde atla, her inişte sabit kalabilene kadar mesafeyi kısa tut."),
    "de": ExerciseGuide(["Stell dich hüftbreit hin, die Zehen hinter einer Linie.", "Schwing die Arme nach hinten, beuge die Knie und schieb die Hüfte zurück.", "Schwing die Arme nach vorn, spring so weit du kannst und lande auf beiden Füßen.", "Halte die Landung eine Sekunde, geh zurück und mach 5 Sprünge, insgesamt 3 Sätze."], ["Bei der Landung nach vorn oder hinten kippen.", "Mit durchgedrückten Knien landen."], "Spring auf rutschfestem Untergrund und spring kürzer, bis du jede Landung ruhig halten kannst."),
    "fr": ExerciseGuide(["Tiens-toi les pieds écartés largeur de hanches, les orteils derrière une ligne.", "Balance les bras vers l'arrière, fléchis les genoux et pousse les fesses en arrière.", "Balance les bras vers l'avant, saute aussi loin que possible et réceptionne-toi sur les deux pieds.", "Tiens la réception une seconde, reviens en marchant et fais 5 sauts, 3 séries au total."], ["Basculer vers l'avant ou vers l'arrière à la réception.", "Retomber les genoux bloqués, jambes tendues."], "Saute sur une surface qui ne glisse pas, et fais des sauts plus courts jusqu'à tenir chaque réception sans bouger."),
    "es": ExerciseGuide(["Ponte con los pies a la anchura de las caderas y las puntas detrás de una línea.", "Lleva los brazos hacia atrás, flexiona las rodillas y echa las caderas atrás.", "Lanza los brazos hacia delante, salta lo más lejos que puedas y cae con los dos pies.", "Aguanta la caída un segundo, vuelve andando y haz 5 saltos, 3 series en total."], ["Caerte hacia delante o hacia atrás al aterrizar.", "Caer con las rodillas bloqueadas y estiradas."], "Salta sobre una superficie que no resbale, y haz saltos más cortos hasta que puedas aguantar cada caída sin moverte."),
    "it": ExerciseGuide(["Stai con i piedi alla larghezza delle anche e le punte dietro una linea.", "Porta le braccia indietro, piega le ginocchia e spingi i fianchi all'indietro.", "Porta le braccia avanti, salta più lontano che puoi e atterra su entrambi i piedi.", "Resta fermo un secondo nell'atterraggio, torna indietro a piedi e fai 5 salti, 3 serie in totale."], ["Cadere in avanti o all'indietro all'atterraggio.", "Atterrare con le ginocchia bloccate e tese."], "Salta su una superficie che non scivola e fai salti più corti finché non riesci a fermare ogni atterraggio."),
    "pt": ExerciseGuide(["Fique com os pés na largura do quadril e os dedos atrás de uma linha.", "Balance os braços para trás, dobre os joelhos e leve o quadril para trás.", "Balance os braços para a frente, salte o mais longe que puder e aterrisse com os dois pés.", "Segure a aterrissagem por um segundo, volte andando e faça 5 saltos, 3 séries no total."], ["Cair para a frente ou para trás na aterrissagem.", "Aterrissar com os joelhos travados e esticados."], "Salte em uma superfície que não escorregue e faça saltos mais curtos até conseguir segurar cada aterrissagem parado."),
    "hi": ExerciseGuide(["पैरों को कूल्हों की चौड़ाई में रखकर खड़े हो जाओ, पंजे एक लाइन के पीछे हों।", "बाँहों को पीछे झुलाओ, घुटने मोड़ो और कूल्हों को पीछे ले जाओ।", "बाँहों को आगे झुलाओ, जितना दूर हो सके कूदो और दोनों पैरों पर उतरो।", "लैंडिंग पर एक सेकंड रुको, चलकर वापस आओ और 5 जंप करो, कुल 3 सेट।"], ["लैंडिंग पर आगे या पीछे की ओर गिर जाना।", "घुटनों को सीधा लॉक करके उतरना।"], "फिसलन रहित सतह पर कूदो और छोटी जंप लगाओ, जब तक हर लैंडिंग पर स्थिर न रुक सको।"),
    "nl": ExerciseGuide(["Sta met je voeten op heupbreedte en je tenen achter een lijn.", "Zwaai je armen naar achteren, buig je knieën en duw je heupen naar achteren.", "Zwaai je armen naar voren, spring zo ver als je kunt en land op beide voeten.", "Houd de landing een seconde vast, loop terug en doe 5 sprongen, 3 sets in totaal."], ["Naar voren of achteren vallen bij de landing.", "Landen met je knieën op slot."], "Spring op een ondergrond die niet glijdt en spring korter totdat je elke landing stil kunt houden."),
    "pl": ExerciseGuide(["Stań w rozkroku na szerokość bioder, palce stóp za linią.", "Zamachnij ramiona do tyłu, ugnij kolana i odsuń biodra w tył.", "Zamachnij ramiona do przodu, skocz jak najdalej i wyląduj na obu stopach.", "Utrzymaj lądowanie przez sekundę, wróć na start i zrób 5 skoków, łącznie 3 serie."], ["Przewracanie się do przodu lub do tyłu przy lądowaniu.", "Lądowanie ze sztywno wyprostowanymi kolanami."], "Skacz na nieśliskiej powierzchni i skacz krócej, aż każde lądowanie utrzymasz w bezruchu."),
    "sv": ExerciseGuide(["Stå med fötterna höftbrett isär och tårna bakom en linje.", "Svinga armarna bakåt, böj knäna och skjut höfterna bakåt.", "Svinga armarna framåt, hoppa så långt du kan och landa på båda fötterna.", "Håll landningen i en sekund, gå tillbaka och gör 5 hopp, 3 set totalt."], ["Att falla framåt eller bakåt vid landningen.", "Att landa med knäna spärrade."], "Hoppa på ett underlag som inte slirar och hoppa kortare tills du kan hålla varje landning stilla."),
  },
  "single_leg_hops": {
    "en": ExerciseGuide(["Stand on one leg with the other foot lifted behind you.", "Make small hops on the spot, landing on the ball of your foot.", "Keep your hips level and your standing knee slightly bent.", "Do 8 hops, switch legs, and do 2 sets on each side."], ["Letting the knee of the hopping leg cave inward.", "Hopping so high that you lose your balance."], "Stay close to a wall you can touch, and keep the hops low until your balance feels steady."),
    "tr": ExerciseGuide(["Tek ayağının üstünde dur, diğer ayağını arkada yerden kaldır.", "Olduğun yerde küçük küçük sek, ayak tabanının ön kısmına in.", "Kalçanı düz, yerdeki dizini hafif bükük tut.", "8 kez sek, bacak değiştir ve her tarafta 2 set yap."], ["Sektiğin bacağın dizinin içe kaçması.", "Dengeni kaybedecek kadar yükseğe sekmek."], "Dokunabileceğin bir duvarın yanında dur, dengen oturana kadar alçak sek."),
    "de": ExerciseGuide(["Stell dich auf ein Bein, den anderen Fuß hinten angehoben.", "Hüpfe in kleinen Sprüngen auf der Stelle und lande auf dem Fußballen.", "Halte die Hüfte gerade und das Standbein leicht gebeugt.", "Mach 8 Hüpfer, wechsle das Bein und mach 2 Sätze pro Seite."], ["Das Knie des Sprungbeins nach innen kippen lassen.", "So hoch hüpfen, dass du das Gleichgewicht verlierst."], "Bleib nah an einer Wand, die du berühren kannst, und hüpf flach, bis dein Gleichgewicht stabil ist."),
    "fr": ExerciseGuide(["Tiens-toi sur une jambe, l'autre pied levé derrière toi.", "Fais de petits sauts sur place en te réceptionnant sur l'avant du pied.", "Garde les hanches à niveau et le genou d'appui légèrement fléchi.", "Fais 8 sauts, change de jambe et fais 2 séries de chaque côté."], ["Laisser le genou de la jambe qui saute rentrer vers l'intérieur.", "Sauter si haut que tu perds l'équilibre."], "Reste près d'un mur que tu peux toucher, et saute bas jusqu'à ce que ton équilibre soit stable."),
    "es": ExerciseGuide(["Ponte sobre una pierna con el otro pie levantado hacia atrás.", "Haz saltitos pequeños en el sitio, cayendo sobre la parte delantera del pie.", "Mantén las caderas niveladas y la rodilla de apoyo un poco flexionada.", "Haz 8 saltitos, cambia de pierna y haz 2 series de cada lado."], ["Dejar que la rodilla de la pierna que salta se meta hacia dentro.", "Saltar tan alto que pierdes el equilibrio."], "Quédate cerca de una pared que puedas tocar, y salta bajo hasta que tu equilibrio sea firme."),
    "it": ExerciseGuide(["Stai su una gamba con l'altro piede sollevato dietro di te.", "Fai piccoli saltelli sul posto, atterrando sull'avampiede.", "Tieni le anche livellate e il ginocchio d'appoggio leggermente piegato.", "Fai 8 saltelli, cambia gamba e fai 2 serie per lato."], ["Far cadere verso l'interno il ginocchio della gamba che salta.", "Saltare così in alto da perdere l'equilibrio."], "Resta vicino a un muro che puoi toccare e tieni i saltelli bassi finché l'equilibrio non è stabile."),
    "pt": ExerciseGuide(["Fique em uma perna só, com o outro pé levantado atrás de você.", "Dê pequenos saltinhos no lugar, aterrissando na ponta do pé.", "Mantenha o quadril nivelado e o joelho de apoio levemente dobrado.", "Faça 8 saltinhos, troque de perna e faça 2 séries de cada lado."], ["Deixar o joelho da perna que salta cair para dentro.", "Saltar tão alto que perde o equilíbrio."], "Fique perto de uma parede em que possa se apoiar e mantenha os saltinhos baixos até o equilíbrio ficar firme."),
    "hi": ExerciseGuide(["एक पैर पर खड़े हो जाओ, दूसरा पैर पीछे उठाकर रखो।", "अपनी जगह पर छोटी हॉप्स लगाओ और पंजे के अगले हिस्से पर उतरो।", "कूल्हों को बराबर रखो और सहारे वाला घुटना हल्का मुड़ा रहे।", "8 हॉप्स करो, पैर बदलो और हर तरफ़ 2 सेट करो।"], ["कूदने वाले पैर के घुटने को अंदर की ओर गिरने देना।", "इतना ऊँचा उछलना कि संतुलन बिगड़ जाए।"], "दीवार के पास रहो जिसे तुम छू सको और हॉप्स नीची रखो, जब तक संतुलन स्थिर न हो।"),
    "nl": ExerciseGuide(["Sta op één been met de andere voet achter je opgetild.", "Maak kleine hopjes op de plek en land op de bal van je voet.", "Houd je heupen recht en je standbeen licht gebogen.", "Doe 8 hopjes, wissel van been en doe 2 sets per kant."], ["De knie van je hopbeen naar binnen laten zakken.", "Zo hoog hoppen dat je je evenwicht verliest."], "Blijf dicht bij een muur die je kunt aanraken en hop laag totdat je balans stabiel voelt."),
    "pl": ExerciseGuide(["Stań na jednej nodze, drugą stopę unieś za sobą.", "Wykonuj małe podskoki w miejscu, lądując na przodostopiu.", "Utrzymuj biodra w jednej linii, a kolano nogi podporowej lekko ugięte.", "Zrób 8 podskoków, zmień nogę i wykonaj 2 serie na każdą stronę."], ["Zapadanie się kolana nogi skaczącej do środka.", "Skakanie tak wysoko, że tracisz równowagę."], "Stój blisko ściany, której możesz dotknąć, i skacz nisko, aż równowaga będzie stabilna."),
    "sv": ExerciseGuide(["Stå på ett ben med den andra foten lyft bakom dig.", "Gör små hopp på stället och landa på framfoten.", "Håll höfterna i våg och det stående knät lätt böjt.", "Gör 8 hopp, byt ben och gör 2 set på varje sida."], ["Att låta knät på hoppbenet falla inåt.", "Att hoppa så högt att du tappar balansen."], "Stå nära en vägg du kan nudda och håll hoppen låga tills balansen känns stabil."),
  },
  "high_knees": {
    "en": ExerciseGuide(["Stand tall with your feet hip-width apart.", "Run on the spot and lift each knee to hip height.", "Pump your arms and stay light on the balls of your feet.", "Keep going for 20 seconds, 3 sets in total."], ["Leaning back as your knees come up.", "Stomping the floor with flat feet."], "Slow it down to a march with high knees if you get out of breath."),
    "tr": ExerciseGuide(["Dik dur, ayaklarını kalça genişliğinde aç.", "Yerinde koş ve her dizini kalça hizasına kadar kaldır.", "Kollarını salla, ayak tabanının ön kısmında hafif kal.", "20 saniye boyunca devam et, toplam 3 set yap."], ["Dizler yukarı gelirken geriye yaslanmak.", "Düz tabanla yere sertçe basmak."], "Nefesin kesilirse hareketi yavaşlat, dizlerini yüksek kaldırarak yürüyüş temposuna geç."),
    "de": ExerciseGuide(["Stell dich aufrecht hin, die Füße hüftbreit.", "Lauf auf der Stelle und heb jedes Knie auf Hüfthöhe.", "Schwing die Arme mit und bleib leicht auf den Fußballen.", "Mach 20 Sekunden lang weiter, insgesamt 3 Sätze."], ["Sich nach hinten lehnen, wenn die Knie hochkommen.", "Mit flachen Füßen auf den Boden stampfen."], "Geh in ein Marschieren mit hohen Knien über, wenn dir die Luft ausgeht."),
    "fr": ExerciseGuide(["Tiens-toi droit, les pieds écartés largeur de hanches.", "Cours sur place en montant chaque genou à hauteur de hanches.", "Balance les bras et reste léger sur l'avant des pieds.", "Continue pendant 20 secondes, 3 séries au total."], ["Se pencher en arrière quand les genoux montent.", "Taper le sol avec les pieds à plat."], "Ralentis en marchant genoux hauts si tu es essoufflé."),
    "es": ExerciseGuide(["Ponte recto con los pies a la anchura de las caderas.", "Corre en el sitio y sube cada rodilla a la altura de la cadera.", "Mueve los brazos y mantente ligero sobre la parte delantera de los pies.", "Sigue durante 20 segundos, 3 series en total."], ["Inclinarte hacia atrás al subir las rodillas.", "Pisar el suelo con los pies planos."], "Baja el ritmo a una marcha con rodillas altas si te quedas sin aire."),
    "it": ExerciseGuide(["Stai dritto con i piedi alla larghezza delle anche.", "Corri sul posto e porta ogni ginocchio all'altezza dell'anca.", "Muovi le braccia con energia e resta leggero sull'avampiede.", "Continua per 20 secondi, 3 serie in totale."], ["Inclinarti all'indietro mentre alzi le ginocchia.", "Battere sul pavimento con i piedi piatti."], "Rallenta e fai una marcia a ginocchia alte se rimani senza fiato."),
    "pt": ExerciseGuide(["Fique em pé com os pés na largura do quadril.", "Corra no lugar e leve cada joelho até a altura do quadril.", "Balance os braços com energia e fique leve na ponta dos pés.", "Continue por 20 segundos, 3 séries no total."], ["Inclinar o corpo para trás quando os joelhos sobem.", "Bater no chão com o pé inteiro."], "Diminua o ritmo e faça uma marcha com joelhos altos se ficar sem fôlego."),
    "hi": ExerciseGuide(["पैरों को कूल्हों की चौड़ाई में रखकर सीधे खड़े हो जाओ।", "अपनी जगह पर दौड़ो और हर घुटने को कूल्हे की ऊँचाई तक उठाओ।", "बाँहों को तेज़ी से चलाओ और पंजों के अगले हिस्से पर हल्के रहो।", "20 सेकंड तक करते रहो, कुल 3 सेट।"], ["घुटने उठाते समय पीछे की ओर झुक जाना।", "पूरे तलवे से ज़मीन पर पटकना।"], "साँस फूल जाए तो रफ़्तार घटाकर घुटने ऊँचे रखते हुए मार्च करो।"),
    "nl": ExerciseGuide(["Sta rechtop met je voeten op heupbreedte.", "Ren op de plek en til elke knie op tot heuphoogte.", "Zwaai met je armen en blijf licht op de ballen van je voeten.", "Ga 20 seconden door, 3 sets in totaal."], ["Achterover leunen als je knieën omhoog komen.", "Met platte voeten op de vloer stampen."], "Maak er een marcheren met hoge knieën van als je buiten adem raakt."),
    "pl": ExerciseGuide(["Stań prosto, stopy na szerokość bioder.", "Biegnij w miejscu i unoś każde kolano na wysokość bioder.", "Pracuj ramionami i pozostań lekko na przodostopiu.", "Kontynuuj przez 20 sekund, łącznie 3 serie."], ["Odchylanie się do tyłu przy unoszeniu kolan.", "Tupanie płaskimi stopami o podłogę."], "Zwolnij do marszu z wysokimi kolanami, jeśli brakuje ci tchu."),
    "sv": ExerciseGuide(["Stå rak med fötterna höftbrett isär.", "Spring på stället och lyft varje knä till höftnivå.", "Pumpa med armarna och var lätt på framfötterna.", "Fortsätt i 20 sekunder, 3 set totalt."], ["Att luta sig bakåt när knäna kommer upp.", "Att stampa i golvet med platta fötter."], "Sänk tempot till en marsch med höga knän om du blir andfådd."),
  },
  "mountain_pose": {
    "en": ExerciseGuide(["Stand with your feet together and your weight even on both feet.", "Reach both arms straight overhead with your palms facing each other.", "Rise onto your toes and stretch up through your fingertips.", "Hold 20 seconds and lower slowly, 2 sets in total."], ["Flaring your ribs and arching your lower back.", "Shrugging your shoulders up to your ears."], "Fix your eyes on one point in front of you, or keep your heels down if you wobble."),
    "tr": ExerciseGuide(["Ayaklarını birleştir, ağırlığını iki ayağına eşit ver.", "İki kolunu başının üstüne dümdüz uzat, avuçların birbirine baksın.", "Parmak uçlarına kalk ve parmak uçlarından yukarı doğru esne.", "20 saniye tut ve yavaşça in, toplam 2 set yap."], ["Kaburgaları öne açıp beli çukurlaştırmak.", "Omuzları kulaklara doğru kaldırmak."], "Karşında tek bir noktaya bak, sallanıyorsan topuklarını yerde tut."),
    "de": ExerciseGuide(["Stell dich mit geschlossenen Füßen hin, das Gewicht gleichmäßig verteilt.", "Streck beide Arme senkrecht über den Kopf, die Handflächen zeigen zueinander.", "Komm auf die Zehenspitzen und streck dich bis in die Fingerspitzen.", "Halte 20 Sekunden und senk dich langsam ab, insgesamt 2 Sätze."], ["Den Rippenbogen abspreizen und ins Hohlkreuz gehen.", "Die Schultern bis zu den Ohren hochziehen."], "Fixiere einen Punkt vor dir oder lass die Fersen unten, wenn du wackelst."),
    "fr": ExerciseGuide(["Tiens-toi les pieds joints, le poids réparti également sur les deux pieds.", "Lève les deux bras tendus au-dessus de la tête, paumes face à face.", "Monte sur la pointe des pieds et étire-toi jusqu'au bout des doigts.", "Tiens 20 secondes et redescends lentement, 2 séries au total."], ["Ouvrir les côtes et creuser le bas du dos.", "Monter les épaules jusqu'aux oreilles."], "Fixe un point devant toi, ou garde les talons au sol si tu vacilles."),
    "es": ExerciseGuide(["Ponte con los pies juntos y el peso repartido por igual en los dos pies.", "Estira los dos brazos por encima de la cabeza con las palmas enfrentadas.", "Sube de puntillas y estírate hasta la punta de los dedos.", "Aguanta 20 segundos y baja despacio, 2 series en total."], ["Abrir las costillas y arquear la zona lumbar.", "Subir los hombros hasta las orejas."], "Fija la vista en un punto frente a ti, o deja los talones en el suelo si te tambaleas."),
    "it": ExerciseGuide(["Stai con i piedi uniti e il peso distribuito in modo uniforme.", "Porta entrambe le braccia tese sopra la testa, con i palmi uno di fronte all'altro.", "Sali sulle punte e allungati fino alla punta delle dita.", "Tieni 20 secondi e scendi lentamente, 2 serie in totale."], ["Aprire le costole e inarcare la zona lombare.", "Alzare le spalle fino alle orecchie."], "Fissa lo sguardo su un punto davanti a te, oppure tieni i talloni a terra se ondeggi."),
    "pt": ExerciseGuide(["Fique com os pés juntos e o peso igual nos dois pés.", "Estique os dois braços acima da cabeça, com as palmas de frente uma para a outra.", "Suba na ponta dos pés e estique-se até a ponta dos dedos.", "Segure 20 segundos e desça devagar, 2 séries no total."], ["Abrir as costelas e arquear a lombar.", "Subir os ombros até as orelhas."], "Fixe o olhar em um ponto à sua frente ou mantenha os calcanhares no chão se balançar."),
    "hi": ExerciseGuide(["पैरों को साथ रखकर खड़े हो जाओ, वज़न दोनों पैरों पर बराबर रखो।", "दोनों बाँहों को सिर के ऊपर सीधा करो, हथेलियाँ एक-दूसरे के सामने रहें।", "पंजों पर उठो और उँगलियों के सिरों तक ऊपर खिंचो।", "20 सेकंड रुको और धीरे नीचे आओ, कुल 2 सेट।"], ["पसलियों को बाहर निकालकर पीठ के निचले हिस्से को मोड़ देना।", "कंधों को कानों तक उचका लेना।"], "सामने किसी एक बिंदु पर नज़र टिकाओ, या डगमगाओ तो एड़ियाँ नीचे रखो।"),
    "nl": ExerciseGuide(["Sta met je voeten tegen elkaar en je gewicht gelijk verdeeld.", "Strek beide armen recht boven je hoofd met je handpalmen naar elkaar toe.", "Kom op je tenen en rek je uit tot in je vingertoppen.", "Houd 20 seconden vast en zak langzaam terug, 2 sets in totaal."], ["Je ribben naar voren duwen en een holle onderrug maken.", "Je schouders tot aan je oren optrekken."], "Kijk naar één punt voor je of houd je hielen op de grond als je wiebelt."),
    "pl": ExerciseGuide(["Stań ze stopami razem i ciężarem równo rozłożonym na obie stopy.", "Wyciągnij oba ramiona prosto nad głowę, dłońmi do siebie.", "Unieś się na palce i wyciągaj się przez czubki palców.", "Wytrzymaj 20 sekund i opuść się powoli, łącznie 2 serie."], ["Wypychanie żeber i wyginanie lędźwi.", "Unoszenie barków do uszu."], "Utkwij wzrok w jednym punkcie przed sobą albo trzymaj pięty na podłodze, jeśli się chwiejesz."),
    "sv": ExerciseGuide(["Stå med fötterna ihop och vikten jämnt fördelad på båda fötterna.", "Sträck båda armarna rakt upp med handflatorna mot varandra.", "Res dig på tå och sträck dig upp genom fingertopparna.", "Håll i 20 sekunder och sänk dig långsamt, 2 set totalt."], ["Att spreta ut revbenen och svanka.", "Att dra upp axlarna mot öronen."], "Fäst blicken på en punkt framför dig, eller ha hälarna i golvet om du vinglar."),
  },
  "pelvic_shift": {
    "en": ExerciseGuide(["Lie on your back with your knees bent and your feet flat on the floor.", "Tuck your tailbone and peel your spine off the floor from the bottom up.", "Pause at the top, then lower slowly, one vertebra at a time.", "Do 10 slow reps and rest, 2 sets in total."], ["Pushing the hips up fast in one piece.", "Arching the lower back at the top."], "Move slowly enough to feel each part of your back touch the floor."),
    "tr": ExerciseGuide(["Sırtüstü uzan, dizlerini bük, ayak tabanlarını yere bas.", "Kuyruk sokumunu içeri al ve omurganı alttan başlayarak yerden kaldır.", "Tepede kısa bir an dur, sonra omur omur yavaşça in.", "10 yavaş tekrar yap ve dinlen, toplam 2 set."], ["Kalçayı tek parça halinde hızla yukarı itmek.", "Tepede beli çukurlaştırmak."], "Sırtının her bölümünün yere değdiğini hissedecek kadar yavaş hareket et."),
    "de": ExerciseGuide(["Leg dich auf den Rücken, die Knie gebeugt und die Füße flach auf dem Boden.", "Kipp das Becken ein und roll die Wirbelsäule von unten nach oben vom Boden ab.", "Halte oben kurz inne und roll dann langsam zurück, Wirbel für Wirbel.", "Mach 10 langsame Wiederholungen und ruh dich aus, insgesamt 2 Sätze."], ["Die Hüfte schnell und in einem Stück hochdrücken.", "Oben ins Hohlkreuz gehen."], "Beweg dich so langsam, dass du spürst, wie jeder Teil deines Rückens den Boden berührt."),
    "fr": ExerciseGuide(["Allonge-toi sur le dos, les genoux fléchis et les pieds à plat au sol.", "Rentre le coccyx et décolle la colonne du sol de bas en haut.", "Marque une pause en haut, puis redescends lentement, vertèbre par vertèbre.", "Fais 10 répétitions lentes et repose-toi, 2 séries au total."], ["Pousser les hanches vers le haut d'un seul bloc et trop vite.", "Creuser le bas du dos en haut du mouvement."], "Bouge assez lentement pour sentir chaque partie de ton dos toucher le sol."),
    "es": ExerciseGuide(["Túmbate boca arriba con las rodillas flexionadas y los pies planos en el suelo.", "Mete el coxis y despega la columna del suelo de abajo hacia arriba.", "Haz una pausa arriba y baja despacio, vértebra a vértebra.", "Haz 10 repeticiones lentas y descansa, 2 series en total."], ["Subir las caderas rápido y de una sola pieza.", "Arquear la zona lumbar arriba."], "Muévete tan despacio que notes cómo cada parte de la espalda toca el suelo."),
    "it": ExerciseGuide(["Sdraiati sulla schiena con le ginocchia piegate e i piedi appoggiati a terra.", "Porta il coccige in dentro e stacca la schiena dal pavimento dal basso verso l'alto.", "Fermati in alto, poi scendi lentamente, una vertebra alla volta.", "Fai 10 ripetizioni lente e riposa, 2 serie in totale."], ["Spingere il bacino in alto di scatto, tutto in un blocco.", "Inarcare la zona lombare in alto."], "Muoviti abbastanza piano da sentire ogni tratto della schiena che tocca il pavimento."),
    "pt": ExerciseGuide(["Deite de costas com os joelhos dobrados e os pés apoiados no chão.", "Encaixe o cóccix e descole a coluna do chão de baixo para cima.", "Pare no alto e depois desça devagar, uma vértebra de cada vez.", "Faça 10 repetições lentas e descanse, 2 séries no total."], ["Empurrar o quadril para cima rápido, de uma vez só.", "Arquear a lombar lá em cima."], "Mova-se devagar o bastante para sentir cada parte das costas tocando o chão."),
    "hi": ExerciseGuide(["पीठ के बल लेट जाओ, घुटने मुड़े हों और पैर ज़मीन पर सपाट हों।", "टेलबोन को अंदर की ओर मोड़ो और रीढ़ को नीचे से ऊपर की ओर ज़मीन से उठाओ।", "ऊपर रुको, फिर धीरे नीचे आओ, एक-एक कशेरुका करके।", "10 धीमी रेप्स करो और आराम करो, कुल 2 सेट।"], ["कूल्हों को एक झटके में पूरे एक टुकड़े की तरह ऊपर धकेलना।", "ऊपर पहुँचकर पीठ के निचले हिस्से को मोड़ देना।"], "इतना धीरे चलो कि पीठ का हर हिस्सा ज़मीन को छूता हुआ महसूस हो।"),
    "nl": ExerciseGuide(["Lig op je rug met gebogen knieën en je voeten plat op de vloer.", "Kantel je staartbeen in en rol je ruggengraat van onderaf van de vloer.", "Pauzeer bovenaan en zak dan langzaam terug, wervel voor wervel.", "Doe 10 rustige herhalingen en rust, 2 sets in totaal."], ["Je heupen snel en in één keer omhoog duwen.", "Bovenaan een holle onderrug maken."], "Beweeg zo langzaam dat je elk stukje van je rug de vloer voelt raken."),
    "pl": ExerciseGuide(["Połóż się na plecach, kolana ugięte, stopy płasko na podłodze.", "Podwiń kość ogonową i odklejaj kręgosłup od podłogi od dołu do góry.", "Zatrzymaj się na górze, potem opuszczaj się powoli, kręg po kręgu.", "Zrób 10 wolnych powtórzeń i odpocznij, łącznie 2 serie."], ["Szybkie wypychanie bioder w górę jednym ruchem.", "Wyginanie lędźwi na górze."], "Poruszaj się tak wolno, by każdy fragment pleców po kolei dotykał podłogi."),
    "sv": ExerciseGuide(["Ligg på rygg med böjda knän och fötterna platta i golvet.", "Tippa svanskotan inåt och rulla upp ryggraden från golvet nerifrån och upp.", "Pausa högst upp och sänk sedan långsamt, en kota i taget.", "Gör 10 långsamma upprepningar och vila, 2 set totalt."], ["Att skjuta upp höfterna snabbt i ett stycke.", "Att svanka högst upp."], "Rör dig så långsamt att du känner varje del av ryggen nudda golvet."),
  },
  "table_top": {
    "en": ExerciseGuide(["Sit with your knees bent, feet flat and hands on the floor behind your hips.", "Point your fingers toward your feet and press into your hands and feet.", "Lift your hips until your body is flat from knees to shoulders.", "Hold 15 seconds and lower, 2 sets in total."], ["Letting the hips sag in the middle.", "Dropping the head back so the neck strains."], "Turn your fingers out to the sides if your wrists feel sore."),
    "tr": ExerciseGuide(["Dizlerin bükük otur, ayak tabanların yerde, ellerin kalçanın arkasında olsun.", "Parmaklarını ayaklarına doğru çevir, ellerinle ve ayaklarınla yeri it.", "Dizlerinden omuzlarına kadar dümdüz olana dek kalçanı kaldır.", "15 saniye tut ve in, toplam 2 set yap."], ["Kalçanın ortada aşağı sarkması.", "Başı arkaya düşürüp boynu zorlamak."], "Bileklerin ağrırsa parmaklarını yanlara doğru çevir."),
    "de": ExerciseGuide(["Setz dich mit gebeugten Knien, flachen Füßen und den Händen hinter der Hüfte auf den Boden.", "Dreh die Finger zu den Füßen und drück in Hände und Füße.", "Heb die Hüfte, bis dein Körper von den Knien bis zu den Schultern flach ist.", "Halte 15 Sekunden und senk dich ab, insgesamt 2 Sätze."], ["Die Hüfte in der Mitte durchhängen lassen.", "Den Kopf in den Nacken fallen lassen, sodass sich der Nacken verspannt."], "Dreh die Finger zur Seite, wenn deine Handgelenke schmerzen."),
    "fr": ExerciseGuide(["Assieds-toi, genoux fléchis, pieds à plat et mains au sol derrière les hanches.", "Oriente les doigts vers les pieds et appuie dans tes mains et tes pieds.", "Monte les hanches jusqu'à ce que ton corps soit plat des genoux aux épaules.", "Tiens 15 secondes et redescends, 2 séries au total."], ["Laisser les hanches s'affaisser au milieu.", "Laisser tomber la tête en arrière au point de forcer sur la nuque."], "Tourne les doigts vers l'extérieur si tes poignets sont douloureux."),
    "es": ExerciseGuide(["Siéntate con las rodillas flexionadas, los pies planos y las manos en el suelo detrás de las caderas.", "Apunta los dedos hacia los pies y presiona con las manos y los pies.", "Sube las caderas hasta que el cuerpo quede plano de las rodillas a los hombros.", "Aguanta 15 segundos y baja, 2 series en total."], ["Dejar que las caderas se hundan en el medio.", "Dejar caer la cabeza hacia atrás y forzar el cuello."], "Gira los dedos hacia fuera si te duelen las muñecas."),
    "it": ExerciseGuide(["Siediti con le ginocchia piegate, i piedi a terra e le mani sul pavimento dietro i fianchi.", "Punta le dita verso i piedi e spingi su mani e piedi.", "Solleva il bacino finché il corpo è piatto dalle ginocchia alle spalle.", "Tieni 15 secondi e scendi, 2 serie in totale."], ["Lasciar cedere il bacino al centro.", "Lasciar cadere indietro la testa e stirare il collo."], "Ruota le dita verso l'esterno se senti dolore ai polsi."),
    "pt": ExerciseGuide(["Sente com os joelhos dobrados, os pés no chão e as mãos no chão atrás do quadril.", "Aponte os dedos para os pés e pressione as mãos e os pés no chão.", "Levante o quadril até o corpo ficar reto dos joelhos aos ombros.", "Segure 15 segundos e desça, 2 séries no total."], ["Deixar o quadril cair no meio.", "Jogar a cabeça para trás e forçar o pescoço."], "Gire os dedos para fora se os punhos doerem."),
    "hi": ExerciseGuide(["घुटने मोड़कर बैठो, पैर ज़मीन पर सपाट हों और हाथ कूल्हों के पीछे ज़मीन पर रखो।", "उँगलियाँ पैरों की ओर रखो और हाथों और पैरों से ज़मीन को दबाओ।", "कूल्हों को तब तक उठाओ जब तक शरीर घुटनों से कंधों तक सपाट न हो जाए।", "15 सेकंड रुको और नीचे आओ, कुल 2 सेट।"], ["कूल्हों को बीच में झुकने देना।", "सिर को पीछे गिराकर गर्दन पर ज़ोर डालना।"], "कलाइयों में दर्द हो तो उँगलियों को बाहर की ओर घुमा लो।"),
    "nl": ExerciseGuide(["Zit met gebogen knieën, voeten plat en je handen achter je heupen op de vloer.", "Wijs met je vingers naar je voeten en duw in je handen en voeten.", "Til je heupen tot je lichaam vlak is van knieën tot schouders.", "Houd 15 seconden vast en zak terug, 2 sets in totaal."], ["Je heupen in het midden laten doorzakken.", "Je hoofd naar achteren laten hangen, waardoor je nek wordt belast."], "Draai je vingers naar buiten als je polsen pijn doen."),
    "pl": ExerciseGuide(["Usiądź z ugiętymi kolanami, stopami płasko i dłońmi na podłodze za biodrami.", "Skieruj palce dłoni w stronę stóp i dociśnij dłonie i stopy do podłogi.", "Unieś biodra, aż ciało będzie płaskie od kolan do barków.", "Wytrzymaj 15 sekund i opuść się, łącznie 2 serie."], ["Zapadanie się bioder w środku.", "Opuszczanie głowy do tyłu, co przeciąża kark."], "Skieruj palce dłoni na boki, jeśli bolą cię nadgarstki."),
    "sv": ExerciseGuide(["Sitt med böjda knän, fötterna platta och händerna i golvet bakom höfterna.", "Peka med fingrarna mot fötterna och tryck ner i händer och fötter.", "Lyft höfterna tills kroppen är platt från knän till axlar.", "Håll i 15 sekunder och sänk, 2 set totalt."], ["Att låta höfterna hänga ner i mitten.", "Att tappa huvudet bakåt så att nacken belastas."], "Vrid fingrarna utåt åt sidorna om handlederna känns ömma."),
  },
  "childs_pose": {
    "en": ExerciseGuide(["Kneel on the floor with your big toes together and your knees apart.", "Sit your hips back onto your heels.", "Walk your hands forward and rest your forehead on the floor.", "Breathe slowly for 30 seconds and come up, 2 sets in total."], ["Lifting the hips far off the heels to reach further.", "Holding the breath and tensing the shoulders."], "Put a cushion between your hips and heels if your knees feel tight."),
    "tr": ExerciseGuide(["Yere diz çök, ayak başparmakların birleşsin, dizlerin açık olsun.", "Kalçanı geriye, topuklarının üstüne indir.", "Ellerini öne doğru yürüt ve alnını yere bırak.", "30 saniye yavaş nefes al ve doğrul, toplam 2 set yap."], ["Daha ileri uzanmak için kalçayı topuklardan fazla kaldırmak.", "Nefesi tutup omuzları kasmak."], "Dizlerin geriliyorsa kalçanla topukların arasına bir yastık koy."),
    "de": ExerciseGuide(["Knie dich auf den Boden, die großen Zehen berühren sich, die Knie sind geöffnet.", "Setz die Hüfte nach hinten auf die Fersen.", "Lauf mit den Händen nach vorn und leg die Stirn auf dem Boden ab.", "Atme 30 Sekunden lang ruhig und komm wieder hoch, insgesamt 2 Sätze."], ["Die Hüfte weit von den Fersen abheben, um weiter zu kommen.", "Den Atem anhalten und die Schultern anspannen."], "Leg ein Kissen zwischen Hüfte und Fersen, wenn sich deine Knie eng anfühlen."),
    "fr": ExerciseGuide(["Mets-toi à genoux au sol, gros orteils réunis et genoux écartés.", "Recule les fesses sur les talons.", "Avance les mains et pose le front au sol.", "Respire lentement pendant 30 secondes et remonte, 2 séries au total."], ["Décoller les fesses des talons pour aller plus loin.", "Retenir sa respiration et crisper les épaules."], "Glisse un coussin entre les fesses et les talons si tes genoux sont tendus."),
    "es": ExerciseGuide(["Arrodíllate en el suelo con los dedos gordos de los pies juntos y las rodillas separadas.", "Lleva las caderas hacia atrás, sobre los talones.", "Camina con las manos hacia delante y apoya la frente en el suelo.", "Respira despacio durante 30 segundos y sube, 2 series en total."], ["Levantar las caderas de los talones para llegar más lejos.", "Aguantar la respiración y tensar los hombros."], "Pon un cojín entre las caderas y los talones si notas las rodillas tensas."),
    "it": ExerciseGuide(["Inginocchiati a terra con gli alluci uniti e le ginocchia aperte.", "Porta i fianchi indietro sui talloni.", "Cammina con le mani in avanti e appoggia la fronte a terra.", "Respira lentamente per 30 secondi e risali, 2 serie in totale."], ["Alzare molto il bacino dai talloni per andare più avanti.", "Trattenere il respiro e irrigidire le spalle."], "Metti un cuscino tra i fianchi e i talloni se senti le ginocchia tese."),
    "pt": ExerciseGuide(["Ajoelhe no chão com os dedões dos pés juntos e os joelhos afastados.", "Leve o quadril para trás até sentar sobre os calcanhares.", "Caminhe com as mãos para a frente e apoie a testa no chão.", "Respire devagar por 30 segundos e suba, 2 séries no total."], ["Levantar muito o quadril dos calcanhares para ir mais longe.", "Prender a respiração e tensionar os ombros."], "Coloque uma almofada entre o quadril e os calcanhares se os joelhos ficarem tensos."),
    "hi": ExerciseGuide(["ज़मीन पर घुटनों के बल बैठो, पैर के अंगूठे साथ हों और घुटने अलग हों।", "कूल्हों को पीछे लाकर एड़ियों पर बैठ जाओ।", "हाथों को आगे चलाओ और माथा ज़मीन पर टिकाओ।", "30 सेकंड धीरे साँस लो और ऊपर आओ, कुल 2 सेट।"], ["और आगे जाने के लिए कूल्हों को एड़ियों से बहुत ऊपर उठा देना।", "साँस रोकना और कंधों को तानना।"], "घुटने जकड़े लगें तो कूल्हों और एड़ियों के बीच तकिया रख लो।"),
    "nl": ExerciseGuide(["Kniel op de vloer met je grote tenen tegen elkaar en je knieën uit elkaar.", "Zit met je heupen terug op je hielen.", "Loop met je handen naar voren en leg je voorhoofd op de vloer.", "Adem 30 seconden rustig en kom omhoog, 2 sets in totaal."], ["Je heupen ver van je hielen tillen om verder te reiken.", "Je adem inhouden en je schouders aanspannen."], "Leg een kussen tussen je heupen en hielen als je knieën strak aanvoelen."),
    "pl": ExerciseGuide(["Uklęknij na podłodze z dużymi palcami stóp razem i kolanami rozstawionymi.", "Opuść biodra na pięty.", "Przesuń dłonie do przodu i oprzyj czoło o podłogę.", "Oddychaj powoli przez 30 sekund i wstań, łącznie 2 serie."], ["Odrywanie bioder daleko od pięt, by sięgnąć dalej.", "Wstrzymywanie oddechu i napinanie barków."], "Połóż poduszkę między biodrami a piętami, jeśli kolana są spięte."),
    "sv": ExerciseGuide(["Knäböj på golvet med stortårna ihop och knäna isär.", "Sänk höfterna bakåt ner på hälarna.", "Gå med händerna framåt och vila pannan i golvet.", "Andas långsamt i 30 sekunder och kom upp, 2 set totalt."], ["Att lyfta höfterna långt från hälarna för att nå längre.", "Att hålla andan och spänna axlarna."], "Lägg en kudde mellan höfterna och hälarna om knäna känns stela."),
  },
  "puppy_pose": {
    "en": ExerciseGuide(["Start on all fours with your hips right above your knees.", "Walk your hands forward and keep your hips where they are.", "Let your chest and forehead sink toward the floor.", "Hold 20 seconds and come back up, 2 sets in total."], ["Letting the hips slide back toward the heels.", "Bending the elbows and resting them on the floor."], "Rest your forehead on a cushion if the stretch in your shoulders feels too strong."),
    "tr": ExerciseGuide(["Eller ve dizler üzerinde başla, kalçan tam dizlerinin üstünde olsun.", "Kalçanı yerinde tutarak ellerini öne doğru yürüt.", "Göğsünü ve alnını yere doğru bırak.", "20 saniye tut ve geri gel, toplam 2 set yap."], ["Kalçanın topuklara doğru geriye kayması.", "Dirsekleri büküp yere koymak."], "Omuzlarındaki esneme fazla gelirse alnını bir yastığa yasla."),
    "de": ExerciseGuide(["Starte im Vierfüßlerstand, die Hüfte genau über den Knien.", "Lauf mit den Händen nach vorn, die Hüfte bleibt, wo sie ist.", "Lass Brust und Stirn Richtung Boden sinken.", "Halte 20 Sekunden und komm wieder hoch, insgesamt 2 Sätze."], ["Die Hüfte nach hinten zu den Fersen rutschen lassen.", "Die Ellbogen beugen und auf dem Boden ablegen."], "Leg die Stirn auf ein Kissen, wenn die Dehnung in den Schultern zu stark ist."),
    "fr": ExerciseGuide(["Mets-toi à quatre pattes, les hanches juste au-dessus des genoux.", "Avance les mains sans bouger les hanches.", "Laisse la poitrine et le front descendre vers le sol.", "Tiens 20 secondes et remonte, 2 séries au total."], ["Laisser les hanches reculer vers les talons.", "Plier les coudes et les poser au sol."], "Pose le front sur un coussin si l'étirement des épaules est trop fort."),
    "es": ExerciseGuide(["Empieza a cuatro patas con las caderas justo encima de las rodillas.", "Camina con las manos hacia delante y deja las caderas donde están.", "Deja que el pecho y la frente se hundan hacia el suelo.", "Aguanta 20 segundos y vuelve a subir, 2 series en total."], ["Dejar que las caderas se deslicen hacia los talones.", "Doblar los codos y apoyarlos en el suelo."], "Apoya la frente en un cojín si el estiramiento de los hombros es demasiado fuerte."),
    "it": ExerciseGuide(["Parti a quattro zampe con i fianchi esattamente sopra le ginocchia.", "Cammina con le mani in avanti e tieni i fianchi dove sono.", "Lascia che petto e fronte scendano verso il pavimento.", "Tieni 20 secondi e risali, 2 serie in totale."], ["Lasciar scivolare i fianchi indietro verso i talloni.", "Piegare i gomiti e appoggiarli a terra."], "Appoggia la fronte su un cuscino se l'allungamento delle spalle è troppo intenso."),
    "pt": ExerciseGuide(["Comece de quatro apoios, com o quadril bem acima dos joelhos.", "Caminhe com as mãos para a frente e mantenha o quadril onde está.", "Deixe o peito e a testa afundarem em direção ao chão.", "Segure 20 segundos e volte, 2 séries no total."], ["Deixar o quadril escorregar para trás em direção aos calcanhares.", "Dobrar os cotovelos e apoiá-los no chão."], "Apoie a testa em uma almofada se o alongamento dos ombros ficar forte demais."),
    "hi": ExerciseGuide(["चारों हाथ-पैरों पर आ जाओ, कूल्हे ठीक घुटनों के ऊपर हों।", "हाथों को आगे चलाओ और कूल्हों को अपनी जगह पर रखो।", "सीने और माथे को ज़मीन की ओर धँसने दो।", "20 सेकंड रुको और वापस ऊपर आओ, कुल 2 सेट।"], ["कूल्हों को एड़ियों की ओर पीछे फिसलने देना।", "कोहनियाँ मोड़कर उन्हें ज़मीन पर टिका देना।"], "कंधों में खिंचाव ज़्यादा लगे तो माथा तकिये पर रख लो।"),
    "nl": ExerciseGuide(["Begin op handen en knieën met je heupen recht boven je knieën.", "Loop met je handen naar voren en houd je heupen op hun plek.", "Laat je borst en voorhoofd naar de vloer zakken.", "Houd 20 seconden vast en kom terug omhoog, 2 sets in totaal."], ["Je heupen naar je hielen laten glijden.", "Je ellebogen buigen en op de vloer laten rusten."], "Leg je voorhoofd op een kussen als de stretch in je schouders te sterk voelt."),
    "pl": ExerciseGuide(["Zacznij w podporze klęcznym, biodra dokładnie nad kolanami.", "Przesuń dłonie do przodu, a biodra zostaw tam, gdzie są.", "Pozwól klatce piersiowej i czołu opaść w stronę podłogi.", "Wytrzymaj 20 sekund i wróć, łącznie 2 serie."], ["Cofanie bioder w stronę pięt.", "Uginanie łokci i opieranie ich o podłogę."], "Oprzyj czoło na poduszce, jeśli rozciąganie barków jest zbyt mocne."),
    "sv": ExerciseGuide(["Börja på alla fyra med höfterna rakt ovanför knäna.", "Gå med händerna framåt och låt höfterna stå kvar.", "Låt bröstet och pannan sjunka mot golvet.", "Håll i 20 sekunder och kom tillbaka upp, 2 set totalt."], ["Att låta höfterna glida bakåt mot hälarna.", "Att böja armbågarna och vila dem i golvet."], "Vila pannan på en kudde om sträckningen i axlarna känns för stark."),
  },
  "seated_forward_fold": {
    "en": ExerciseGuide(["Sit on the floor with your legs straight and your toes pointing up.", "Sit up tall and reach both arms overhead.", "Hinge forward from your hips and reach for your shins or feet.", "Hold 20 seconds and sit back up, 2 sets in total."], ["Rounding the upper back to reach the toes.", "Bouncing to get deeper into the stretch."], "Bend your knees a little or sit on a folded towel if your lower back rounds."),
    "tr": ExerciseGuide(["Yere otur, bacaklarını düz uzat, ayak parmakların yukarı baksın.", "Dik otur ve iki kolunu başının üstüne uzat.", "Kalçandan öne eğil, kaval kemiklerine ya da ayaklarına uzan.", "20 saniye tut ve doğrul, toplam 2 set yap."], ["Parmaklara yetişmek için sırtın üst kısmını yuvarlamak.", "Daha derine inmek için yaylanmak."], "Belin yuvarlanıyorsa dizlerini biraz bük ya da katlanmış bir havlunun üstüne otur."),
    "de": ExerciseGuide(["Setz dich mit gestreckten Beinen auf den Boden, die Zehen zeigen nach oben.", "Sitz aufrecht und streck beide Arme über den Kopf.", "Beug dich aus der Hüfte nach vorn und greif zu den Schienbeinen oder Füßen.", "Halte 20 Sekunden und richte dich wieder auf, insgesamt 2 Sätze."], ["Den oberen Rücken rund machen, um die Zehen zu erreichen.", "Wippen, um tiefer in die Dehnung zu kommen."], "Beug die Knie leicht oder setz dich auf ein gefaltetes Handtuch, wenn sich dein unterer Rücken rundet."),
    "fr": ExerciseGuide(["Assieds-toi au sol, jambes tendues et orteils vers le haut.", "Redresse-toi et lève les deux bras au-dessus de la tête.", "Penche-toi depuis les hanches et attrape tes tibias ou tes pieds.", "Tiens 20 secondes et redresse-toi, 2 séries au total."], ["Arrondir le haut du dos pour atteindre les orteils.", "Faire des rebonds pour aller plus loin dans l'étirement."], "Fléchis un peu les genoux ou assieds-toi sur une serviette pliée si ton bas du dos s'arrondit."),
    "es": ExerciseGuide(["Siéntate en el suelo con las piernas estiradas y las puntas de los pies hacia arriba.", "Siéntate bien recto y estira los dos brazos por encima de la cabeza.", "Inclínate desde las caderas y alcanza las espinillas o los pies.", "Aguanta 20 segundos y siéntate otra vez recto, 2 series en total."], ["Redondear la parte alta de la espalda para llegar a los pies.", "Rebotar para profundizar en el estiramiento."], "Flexiona un poco las rodillas o siéntate sobre una toalla doblada si se te redondea la zona lumbar."),
    "it": ExerciseGuide(["Siediti a terra con le gambe tese e le punte dei piedi verso l'alto.", "Allungati verso l'alto e porta entrambe le braccia sopra la testa.", "Piegati in avanti dalle anche e cerca di arrivare a stinchi o piedi.", "Tieni 20 secondi e torna su, 2 serie in totale."], ["Arrotondare la parte alta della schiena per toccare le punte.", "Molleggiare per andare più a fondo."], "Piega un po' le ginocchia o siediti su un asciugamano ripiegato se la zona lombare si arrotonda."),
    "pt": ExerciseGuide(["Sente no chão com as pernas esticadas e os dedos dos pés apontando para cima.", "Sente-se alto e estique os dois braços acima da cabeça.", "Incline-se para a frente a partir do quadril e alcance as canelas ou os pés.", "Segure 20 segundos e volte a sentar reto, 2 séries no total."], ["Arredondar a parte de cima das costas para alcançar os dedos.", "Quicar para descer mais no alongamento."], "Dobre um pouco os joelhos ou sente em uma toalha dobrada se a lombar arredondar."),
    "hi": ExerciseGuide(["ज़मीन पर पैर सीधे करके बैठो, पंजे ऊपर की ओर हों।", "सीधे बैठो और दोनों बाँहें सिर के ऊपर ले जाओ।", "कूल्हों से आगे झुको और पिंडलियों या पैरों तक पहुँचो।", "20 सेकंड रुको और वापस सीधे बैठो, कुल 2 सेट।"], ["पंजों तक पहुँचने के लिए पीठ के ऊपरी हिस्से को गोल करना।", "और गहरा जाने के लिए झटके देना।"], "पीठ का निचला हिस्सा गोल हो तो घुटने थोड़े मोड़ लो या मुड़े तौलिये पर बैठो।"),
    "nl": ExerciseGuide(["Zit op de vloer met gestrekte benen en je tenen omhoog.", "Zit rechtop en strek beide armen boven je hoofd.", "Buig vanuit je heupen naar voren en reik naar je schenen of voeten.", "Houd 20 seconden vast en kom weer rechtop, 2 sets in totaal."], ["Je bovenrug ronden om je tenen te bereiken.", "Veren om dieper in de stretch te komen."], "Buig je knieën een beetje of zit op een opgevouwen handdoek als je onderrug rond wordt."),
    "pl": ExerciseGuide(["Usiądź na podłodze z wyprostowanymi nogami i palcami stóp skierowanymi w górę.", "Wyprostuj się i wyciągnij oba ramiona nad głowę.", "Pochyl się do przodu w biodrach i sięgnij do goleni lub stóp.", "Wytrzymaj 20 sekund i wróć do siadu, łącznie 2 serie."], ["Zaokrąglanie górnej części pleców, by dosięgnąć palców.", "Podrywanie się, by wejść głębiej w rozciąganie."], "Lekko ugnij kolana albo usiądź na złożonym ręczniku, jeśli dolne plecy się zaokrąglają."),
    "sv": ExerciseGuide(["Sitt på golvet med raka ben och tårna pekande uppåt.", "Sitt rak och sträck båda armarna över huvudet.", "Böj dig framåt från höfterna och sträck dig mot smalbenen eller fötterna.", "Håll i 20 sekunder och sätt dig upp igen, 2 set totalt."], ["Att runda överryggen för att nå tårna.", "Att fjädra för att komma djupare i sträckningen."], "Böj knäna lite eller sitt på en vikt handduk om ländryggen rundar sig."),
  },
  "standing_side_stretch": {
    "en": ExerciseGuide(["Stand tall with your feet hip-width apart.", "Reach both arms overhead and hold one wrist with the other hand.", "Lean slowly to one side and keep both feet pressed into the floor.", "Hold 15 seconds, switch sides, and do 2 sets on each side."], ["Leaning forward or twisting instead of bending straight to the side.", "Pushing the hips far out to the side."], "Imagine you are standing between two walls, so you can only move sideways."),
    "tr": ExerciseGuide(["Dik dur, ayaklarını kalça genişliğinde aç.", "İki kolunu başının üstüne uzat, bir elinle diğer bileğini tut.", "Yavaşça bir yana eğil, iki ayağını da yere basılı tut.", "15 saniye tut, taraf değiştir ve her tarafta 2 set yap."], ["Düz yana eğilmek yerine öne eğilmek ya da dönmek.", "Kalçayı fazla yana itmek."], "İki duvarın arasında durduğunu düşün, yalnızca yana hareket edebilirsin."),
    "de": ExerciseGuide(["Stell dich aufrecht hin, die Füße hüftbreit.", "Streck beide Arme über den Kopf und halte ein Handgelenk mit der anderen Hand.", "Neig dich langsam zur Seite und drück beide Füße in den Boden.", "Halte 15 Sekunden, wechsle die Seite und mach 2 Sätze pro Seite."], ["Sich nach vorn lehnen oder verdrehen, statt gerade zur Seite zu neigen.", "Die Hüfte weit zur Seite schieben."], "Stell dir vor, du stehst zwischen zwei Wänden und kannst dich nur seitlich bewegen."),
    "fr": ExerciseGuide(["Tiens-toi droit, les pieds écartés largeur de hanches.", "Lève les deux bras et attrape un poignet avec l'autre main.", "Penche-toi lentement sur le côté en appuyant les deux pieds dans le sol.", "Tiens 15 secondes, change de côté et fais 2 séries de chaque côté."], ["Se pencher vers l'avant ou se tordre au lieu de s'incliner droit sur le côté.", "Pousser les hanches loin sur le côté."], "Imagine que tu es coincé entre deux murs et que tu ne peux bouger que sur le côté."),
    "es": ExerciseGuide(["Ponte recto con los pies a la anchura de las caderas.", "Estira los dos brazos hacia arriba y agárrate una muñeca con la otra mano.", "Inclínate despacio hacia un lado y mantén los dos pies bien apoyados en el suelo.", "Aguanta 15 segundos, cambia de lado y haz 2 series de cada lado."], ["Inclinarte hacia delante o girarte en vez de doblarte recto hacia el lado.", "Sacar mucho las caderas hacia un lado."], "Imagina que estás entre dos paredes y solo puedes moverte hacia los lados."),
    "it": ExerciseGuide(["Stai dritto con i piedi alla larghezza delle anche.", "Porta entrambe le braccia sopra la testa e tieni un polso con l'altra mano.", "Inclinati lentamente da un lato e tieni entrambi i piedi premuti a terra.", "Tieni 15 secondi, cambia lato e fai 2 serie per lato."], ["Inclinarti in avanti o ruotare invece di piegarti dritto di lato.", "Spingere i fianchi molto di lato."], "Immagina di stare tra due pareti, così puoi muoverti solo di lato."),
    "pt": ExerciseGuide(["Fique em pé com os pés na largura do quadril.", "Estique os dois braços acima da cabeça e segure um pulso com a outra mão.", "Incline-se devagar para um lado e mantenha os dois pés pressionados no chão.", "Segure 15 segundos, troque de lado e faça 2 séries de cada lado."], ["Inclinar para a frente ou girar em vez de dobrar direto para o lado.", "Empurrar o quadril muito para o lado."], "Imagine que você está entre duas paredes e só consegue se mover para o lado."),
    "hi": ExerciseGuide(["पैरों को कूल्हों की चौड़ाई में रखकर सीधे खड़े हो जाओ।", "दोनों बाँहें सिर के ऊपर ले जाओ और एक हाथ से दूसरी कलाई पकड़ो।", "धीरे एक तरफ़ झुको और दोनों पैरों को ज़मीन में दबाए रखो।", "15 सेकंड रुको, तरफ़ बदलो और हर तरफ़ 2 सेट करो।"], ["सीधे बगल में झुकने की जगह आगे झुकना या घूम जाना।", "कूल्हों को बगल में बहुत दूर धकेलना।"], "सोचो कि तुम दो दीवारों के बीच खड़े हो, इसलिए सिर्फ़ बगल में हिल सकते हो।"),
    "nl": ExerciseGuide(["Sta rechtop met je voeten op heupbreedte.", "Strek beide armen boven je hoofd en pak met één hand de andere pols vast.", "Leun langzaam naar één kant en houd beide voeten stevig op de vloer.", "Houd 15 seconden vast, wissel van kant en doe 2 sets per kant."], ["Naar voren leunen of draaien in plaats van recht opzij buigen.", "Je heupen ver naar de zijkant duwen."], "Stel je voor dat je tussen twee muren staat, zodat je alleen opzij kunt bewegen."),
    "pl": ExerciseGuide(["Stań prosto, stopy na szerokość bioder.", "Wyciągnij oba ramiona nad głowę i chwyć jedną ręką drugi nadgarstek.", "Pochyl się powoli na jedną stronę, mocno dociskając obie stopy do podłogi.", "Wytrzymaj 15 sekund, zmień stronę i wykonaj 2 serie na każdą stronę."], ["Pochylanie się do przodu lub skręcanie zamiast zgięcia prosto w bok.", "Mocne wypychanie bioder w bok."], "Wyobraź sobie, że stoisz między dwiema ścianami i możesz poruszać się tylko na boki."),
    "sv": ExerciseGuide(["Stå rak med fötterna höftbrett isär.", "Sträck båda armarna över huvudet och håll ena handleden med andra handen.", "Luta dig långsamt åt ena sidan och tryck båda fötterna mot golvet.", "Håll i 15 sekunder, byt sida och gör 2 set på varje sida."], ["Att luta sig framåt eller vrida sig i stället för att böja sig rakt åt sidan.", "Att skjuta ut höfterna långt åt sidan."], "Föreställ dig att du står mellan två väggar så att du bara kan röra dig åt sidan."),
  },
  "low_lunge_arch": {
    "en": ExerciseGuide(["Step one foot forward and lower your back knee to the floor.", "Slide your hips forward until you feel a stretch at the front of the back hip.", "Reach both arms up and lift your chest into a gentle arch.", "Hold 20 seconds, switch legs, and do 2 sets on each side."], ["Letting the front knee travel far past the toes.", "Bending only from the lower back."], "Put a folded towel under your back knee, and keep the arch small."),
    "tr": ExerciseGuide(["Bir ayağını öne at, arka dizini yere indir.", "Arkadaki kalçanın önünde esneme hissedene kadar kalçanı öne kaydır.", "İki kolunu yukarı uzat, göğsünü kaldırarak hafifçe geriye yaylan.", "20 saniye tut, bacak değiştir ve her tarafta 2 set yap."], ["Öndeki dizin ayak parmaklarını fazla geçmesi.", "Yalnızca belden bükülmek."], "Arka dizinin altına katlanmış bir havlu koy, geriye yaylanmayı küçük tut."),
    "de": ExerciseGuide(["Mach einen Schritt nach vorn und senk das hintere Knie auf den Boden.", "Schieb die Hüfte nach vorn, bis du vorn an der hinteren Hüfte eine Dehnung spürst.", "Streck beide Arme nach oben und heb die Brust in ein sanftes Hohlkreuz.", "Halte 20 Sekunden, wechsle das Bein und mach 2 Sätze pro Seite."], ["Das vordere Knie weit über die Zehen schieben.", "Nur aus dem unteren Rücken nach hinten beugen."], "Leg ein gefaltetes Handtuch unter das hintere Knie und halte den Bogen klein."),
    "fr": ExerciseGuide(["Fais un pas en avant et pose le genou arrière au sol.", "Avance les hanches jusqu'à sentir un étirement à l'avant de la hanche arrière.", "Lève les deux bras et ouvre la poitrine en une légère cambrure.", "Tiens 20 secondes, change de jambe et fais 2 séries de chaque côté."], ["Laisser le genou avant dépasser largement les orteils.", "Se cambrer uniquement avec le bas du dos."], "Glisse une serviette pliée sous le genou arrière, et garde la cambrure petite."),
    "es": ExerciseGuide(["Da un paso hacia delante y apoya la rodilla de atrás en el suelo.", "Desliza las caderas hacia delante hasta notar un estiramiento en la parte delantera de la cadera de atrás.", "Sube los dos brazos y eleva el pecho en un arco suave.", "Aguanta 20 segundos, cambia de pierna y haz 2 series de cada lado."], ["Dejar que la rodilla de delante pase mucho de la punta del pie.", "Arquearte solo desde la zona lumbar."], "Pon una toalla doblada bajo la rodilla de atrás y mantén el arco pequeño."),
    "it": ExerciseGuide(["Fai un passo avanti con un piede e abbassa a terra il ginocchio dietro.", "Fai scivolare i fianchi in avanti finché senti l'allungamento davanti all'anca dietro.", "Porta entrambe le braccia in alto e solleva il petto in un leggero inarcamento.", "Tieni 20 secondi, cambia gamba e fai 2 serie per lato."], ["Lasciare che il ginocchio davanti superi molto la punta del piede.", "Piegarti solo con la zona lombare."], "Metti un asciugamano ripiegato sotto il ginocchio dietro e tieni l'inarcamento piccolo."),
    "pt": ExerciseGuide(["Dê um passo à frente com um pé e abaixe o joelho de trás até o chão.", "Deslize o quadril para a frente até sentir o alongamento na frente do quadril de trás.", "Estique os dois braços para cima e levante o peito em um arco leve.", "Segure 20 segundos, troque de perna e faça 2 séries de cada lado."], ["Deixar o joelho da frente passar muito dos dedos do pé.", "Arquear só a lombar."], "Coloque uma toalha dobrada sob o joelho de trás e mantenha o arco pequeno."),
    "hi": ExerciseGuide(["एक पैर आगे रखो और पीछे वाला घुटना ज़मीन पर टिका दो।", "कूल्हों को आगे सरकाओ, जब तक पीछे वाले कूल्हे के आगे खिंचाव न लगे।", "दोनों बाँहें ऊपर करो और सीने को हल्के आर्च में उठाओ।", "20 सेकंड रुको, पैर बदलो और हर तरफ़ 2 सेट करो।"], ["आगे वाले घुटने को पंजों से बहुत आगे जाने देना।", "सिर्फ़ पीठ के निचले हिस्से से मुड़ना।"], "पीछे वाले घुटने के नीचे मुड़ा तौलिया रखो और आर्च छोटा रखो।"),
    "nl": ExerciseGuide(["Zet één voet naar voren en zak met je achterste knie naar de vloer.", "Schuif je heupen naar voren tot je een stretch voelt aan de voorkant van je achterste heup.", "Strek beide armen omhoog en til je borst in een lichte holling.", "Houd 20 seconden vast, wissel van been en doe 2 sets per kant."], ["Je voorste knie ver voorbij je tenen laten gaan.", "Alleen vanuit je onderrug buigen."], "Leg een opgevouwen handdoek onder je achterste knie en houd de holling klein."),
    "pl": ExerciseGuide(["Zrób krok jedną nogą do przodu i opuść tylne kolano na podłogę.", "Przesuń biodra do przodu, aż poczujesz rozciąganie z przodu tylnego biodra.", "Wyciągnij oba ramiona w górę i unieś klatkę piersiową w delikatnym wygięciu.", "Wytrzymaj 20 sekund, zmień nogę i wykonaj 2 serie na każdą stronę."], ["Wysuwanie przedniego kolana daleko poza palce.", "Wyginanie się tylko w lędźwiach."], "Podłóż złożony ręcznik pod tylne kolano i utrzymuj wygięcie niewielkie."),
    "sv": ExerciseGuide(["Kliv fram med ena foten och sänk det bakre knät mot golvet.", "Skjut höfterna framåt tills du känner en stretch på framsidan av den bakre höften.", "Sträck båda armarna uppåt och lyft bröstet i en mjuk båge.", "Håll i 20 sekunder, byt ben och gör 2 set på varje sida."], ["Att låta det främre knät glida långt förbi tårna.", "Att bara böja sig i ländryggen."], "Lägg en vikt handduk under det bakre knät och håll bågen liten."),
  },
  "bow_pose": {
    "en": ExerciseGuide(["Lie face down and bend your knees so your heels come toward your hips.", "Reach back and hold both ankles.", "Kick your feet into your hands to lift your chest and thighs.", "Hold 10 seconds and lower slowly, 2 sets in total."], ["Letting the knees spread wider than the hips.", "Throwing the head back and straining the neck."], "Lift only as high as feels comfortable, and skip this one if your lower back hurts."),
    "tr": ExerciseGuide(["Yüzüstü uzan, dizlerini bük, topukların kalçana yaklaşsın.", "Geriye uzan ve iki ayak bileğini tut.", "Ayaklarını ellerine doğru iterek göğsünü ve uyluklarını kaldır.", "10 saniye tut ve yavaşça in, toplam 2 set yap."], ["Dizlerin kalçadan daha geniş açılması.", "Başı geriye atıp boynu zorlamak."], "Yalnızca rahat ettiğin kadar yüksel, belin ağrıyorsa bu hareketi atla."),
    "de": ExerciseGuide(["Leg dich auf den Bauch und beug die Knie, sodass die Fersen zur Hüfte kommen.", "Greif nach hinten und halte beide Knöchel.", "Tritt mit den Füßen in die Hände und heb Brust und Oberschenkel an.", "Halte 10 Sekunden und senk dich langsam ab, insgesamt 2 Sätze."], ["Die Knie weiter als hüftbreit auseinandergehen lassen.", "Den Kopf in den Nacken werfen und den Nacken überlasten."], "Heb nur so hoch, wie es sich angenehm anfühlt, und lass die Übung aus, wenn dein unterer Rücken wehtut."),
    "fr": ExerciseGuide(["Allonge-toi sur le ventre et fléchis les genoux pour amener les talons vers les fesses.", "Passe les mains derrière toi et attrape les deux chevilles.", "Pousse les pieds dans les mains pour monter la poitrine et les cuisses.", "Tiens 10 secondes et redescends lentement, 2 séries au total."], ["Laisser les genoux s'écarter plus que les hanches.", "Jeter la tête en arrière et forcer sur la nuque."], "Monte seulement aussi haut que c'est confortable, et saute cet exercice si ton bas du dos te fait mal."),
    "es": ExerciseGuide(["Túmbate boca abajo y flexiona las rodillas para acercar los talones a las caderas.", "Lleva las manos hacia atrás y agarra los dos tobillos.", "Empuja los pies contra las manos para levantar el pecho y los muslos.", "Aguanta 10 segundos y baja despacio, 2 series en total."], ["Dejar que las rodillas se separen más que las caderas.", "Echar la cabeza hacia atrás y forzar el cuello."], "Sube solo hasta donde te resulte cómodo, y sáltate este ejercicio si te duele la zona lumbar."),
    "it": ExerciseGuide(["Sdraiati a pancia in giù e piega le ginocchia portando i talloni verso i fianchi.", "Porta le mani indietro e afferra entrambe le caviglie.", "Spingi i piedi contro le mani per sollevare petto e cosce.", "Tieni 10 secondi e scendi lentamente, 2 serie in totale."], ["Aprire le ginocchia più della larghezza delle anche.", "Gettare la testa indietro e stirare il collo."], "Sali solo fin dove ti senti a tuo agio e salta questo esercizio se ti fa male la zona lombare."),
    "pt": ExerciseGuide(["Deite de barriga para baixo e dobre os joelhos levando os calcanhares em direção ao quadril.", "Estique os braços para trás e segure os dois tornozelos.", "Empurre os pés contra as mãos para levantar o peito e as coxas.", "Segure 10 segundos e desça devagar, 2 séries no total."], ["Deixar os joelhos mais abertos que o quadril.", "Jogar a cabeça para trás e forçar o pescoço."], "Suba só até onde for confortável e pule este exercício se a lombar doer."),
    "hi": ExerciseGuide(["पेट के बल लेट जाओ और घुटने मोड़ो ताकि एड़ियाँ कूल्हों की ओर आएँ।", "पीछे हाथ ले जाकर दोनों टखने पकड़ लो।", "पैरों को हाथों में धकेलो ताकि सीना और जांघें ऊपर उठें।", "10 सेकंड रुको और धीरे नीचे आओ, कुल 2 सेट।"], ["घुटनों को कूल्हों से ज़्यादा फैलने देना।", "सिर को पीछे फेंककर गर्दन पर ज़ोर डालना।"], "सिर्फ़ उतना ऊपर उठो जितना आरामदायक लगे, और पीठ के निचले हिस्से में दर्द हो तो इसे छोड़ दो।"),
    "nl": ExerciseGuide(["Lig op je buik en buig je knieën zodat je hielen naar je heupen komen.", "Reik naar achteren en pak beide enkels vast.", "Duw je voeten in je handen om je borst en bovenbenen op te tillen.", "Houd 10 seconden vast en zak langzaam terug, 2 sets in totaal."], ["Je knieën breder dan je heupen laten uitwaaieren.", "Je hoofd achterover gooien, waardoor je nek wordt belast."], "Til alleen zo hoog als prettig voelt en sla deze over als je onderrug pijn doet."),
    "pl": ExerciseGuide(["Połóż się na brzuchu i ugnij kolana, aby pięty zbliżyły się do bioder.", "Sięgnij do tyłu i chwyć obie kostki.", "Wypchnij stopy w dłonie, by unieść klatkę piersiową i uda.", "Wytrzymaj 10 sekund i opuść się powoli, łącznie 2 serie."], ["Rozstawianie kolan szerzej niż biodra.", "Odrzucanie głowy do tyłu, co przeciąża kark."], "Unoś się tylko tak wysoko, jak jest wygodnie, i pomiń to ćwiczenie, jeśli bolą cię dolne plecy."),
    "sv": ExerciseGuide(["Ligg på mage och böj knäna så att hälarna närmar sig höfterna.", "Sträck dig bakåt och ta tag i båda vristerna.", "Sparka fötterna in i händerna för att lyfta bröst och lår.", "Håll i 10 sekunder och sänk långsamt, 2 set totalt."], ["Att låta knäna glida isär bredare än höfterna.", "Att kasta huvudet bakåt så att nacken belastas."], "Lyft bara så högt som känns bekvämt och hoppa över den här om du har ont i ländryggen."),
  },
  "pilates_roll_over": {
    "en": ExerciseGuide(["Lie on your back with your arms by your sides and your legs straight up.", "Press your arms into the floor and lift your hips to roll your legs overhead.", "Stop when your legs are level with the floor behind your head.", "Roll back down slowly, do 5 reps and rest, 2 sets in total."], ["Swinging the legs over with momentum.", "Rolling onto the neck instead of the shoulders."], "Keep your weight on your shoulders and never on your neck, and bend your knees to make it easier."),
    "tr": ExerciseGuide(["Sırtüstü uzan, kolların yanında, bacakların dümdüz yukarıda olsun.", "Kollarınla yeri it ve kalçanı kaldırarak bacaklarını başının üstüne doğru götür.", "Bacakların başının arkasında yere paralel olunca dur.", "Yavaşça geri in, 5 tekrar yap ve dinlen, toplam 2 set."], ["Bacakları hız alarak savurmak.", "Omuzların yerine boynun üstüne yuvarlanmak."], "Ağırlığın hep omuzlarında olsun, asla boynunda olmasın, kolaylaştırmak için dizlerini bük."),
    "de": ExerciseGuide(["Leg dich auf den Rücken, die Arme neben dem Körper und die Beine senkrecht nach oben.", "Drück die Arme in den Boden und heb die Hüfte an, sodass die Beine über den Kopf rollen.", "Stopp, wenn die Beine hinter dem Kopf auf Bodenhöhe sind.", "Roll langsam zurück, mach 5 Wiederholungen und ruh dich aus, insgesamt 2 Sätze."], ["Die Beine mit Schwung nach hinten werfen.", "Auf den Nacken statt auf die Schultern rollen."], "Halte das Gewicht auf den Schultern und nie auf dem Nacken, und beug die Knie, um es leichter zu machen."),
    "fr": ExerciseGuide(["Allonge-toi sur le dos, les bras le long du corps et les jambes tendues vers le plafond.", "Appuie les bras dans le sol et monte les hanches pour faire passer les jambes au-dessus de la tête.", "Arrête-toi quand tes jambes sont à l'horizontale derrière ta tête.", "Redescends lentement, fais 5 répétitions et repose-toi, 2 séries au total."], ["Envoyer les jambes par-dessus avec de l'élan.", "Rouler sur la nuque au lieu des épaules."], "Garde le poids sur les épaules et jamais sur la nuque, et fléchis les genoux pour faciliter l'exercice."),
    "es": ExerciseGuide(["Túmbate boca arriba con los brazos a los lados y las piernas estiradas hacia el techo.", "Presiona los brazos contra el suelo y levanta las caderas para llevar las piernas por encima de la cabeza.", "Para cuando las piernas queden a la altura del suelo detrás de la cabeza.", "Vuelve rodando despacio, haz 5 repeticiones y descansa, 2 series en total."], ["Lanzar las piernas hacia atrás con impulso.", "Rodar sobre el cuello en vez de sobre los hombros."], "Mantén el peso sobre los hombros y nunca sobre el cuello, y flexiona las rodillas para hacerlo más fácil."),
    "it": ExerciseGuide(["Sdraiati sulla schiena con le braccia lungo i fianchi e le gambe tese verso l'alto.", "Premi le braccia a terra e solleva il bacino per portare le gambe sopra la testa.", "Fermati quando le gambe sono all'altezza del pavimento dietro la testa.", "Torna giù lentamente, fai 5 ripetizioni e riposa, 2 serie in totale."], ["Lanciare le gambe oltre con lo slancio.", "Rotolare sul collo invece che sulle spalle."], "Tieni il peso sulle spalle e mai sul collo, e piega le ginocchia per renderlo più facile."),
    "pt": ExerciseGuide(["Deite de costas com os braços ao lado do corpo e as pernas esticadas para cima.", "Pressione os braços no chão e levante o quadril para levar as pernas por cima da cabeça.", "Pare quando as pernas estiverem na altura do chão atrás da cabeça.", "Desça devagar, faça 5 repetições e descanse, 2 séries no total."], ["Jogar as pernas por cima com impulso.", "Rolar sobre o pescoço em vez dos ombros."], "Mantenha o peso nos ombros e nunca no pescoço, e dobre os joelhos para facilitar."),
    "hi": ExerciseGuide(["पीठ के बल लेट जाओ, बाँहें बगल में हों और पैर सीधे ऊपर हों।", "बाँहों को ज़मीन में दबाओ और कूल्हे उठाकर पैरों को सिर के ऊपर ले जाओ।", "तब रुको जब पैर सिर के पीछे ज़मीन के बराबर आ जाएँ।", "धीरे वापस लुढ़को, 5 रेप्स करो और आराम करो, कुल 2 सेट।"], ["पैरों को झोंक से ऊपर फेंकना।", "कंधों की जगह गर्दन पर लुढ़कना।"], "वज़न कंधों पर रखो, गर्दन पर कभी नहीं, और आसान बनाने के लिए घुटने मोड़ लो।"),
    "nl": ExerciseGuide(["Lig op je rug met je armen langs je lichaam en je benen recht omhoog.", "Duw je armen in de vloer en til je heupen op om je benen over je hoofd te rollen.", "Stop als je benen achter je hoofd horizontaal zijn.", "Rol langzaam terug, doe 5 herhalingen en rust, 2 sets in totaal."], ["Je benen met vaart over je hoofd zwaaien.", "Op je nek rollen in plaats van op je schouders."], "Houd je gewicht op je schouders en nooit op je nek, en buig je knieën om het makkelijker te maken."),
    "pl": ExerciseGuide(["Połóż się na plecach, ramiona wzdłuż ciała, nogi proste w górę.", "Dociśnij ramiona do podłogi i unieś biodra, by przetoczyć nogi nad głowę.", "Zatrzymaj się, gdy nogi będą równolegle do podłogi za głową.", "Przetocz się powoli z powrotem, zrób 5 powtórzeń i odpocznij, łącznie 2 serie."], ["Przerzucanie nóg rozpędem.", "Przetaczanie się na kark zamiast na barki."], "Utrzymuj ciężar na barkach, nigdy na karku, i ugnij kolana, by było łatwiej."),
    "sv": ExerciseGuide(["Ligg på rygg med armarna längs sidorna och benen rakt upp.", "Tryck armarna mot golvet och lyft höfterna för att rulla benen över huvudet.", "Stanna när benen är i höjd med golvet bakom huvudet.", "Rulla tillbaka långsamt, gör 5 upprepningar och vila, 2 set totalt."], ["Att svinga benen över med fart.", "Att rulla upp på nacken i stället för på axlarna."], "Håll vikten på axlarna och aldrig på nacken, och böj knäna för att göra det lättare."),
  },
  "legs_up_wall": {
    "en": ExerciseGuide(["Sit sideways next to a wall with one hip touching it.", "Swing your legs up the wall as you lie back on the floor.", "Let your arms rest by your sides and relax your legs against the wall.", "Stay for 3 minutes, breathing slowly."], ["Lifting the lower back off the floor.", "Locking the knees hard and tensing the legs."], "Move your hips a little away from the wall if the back of your legs feels tight."),
    "tr": ExerciseGuide(["Duvarın yanına yan otur, bir kalçan duvara değsin.", "Sırtüstü yere uzanırken bacaklarını duvara doğru kaldır.", "Kollarını yanlarına bırak, bacaklarını duvara yaslayıp gevşet.", "Yavaş nefes alarak 3 dakika kal."], ["Beli yerden kaldırmak.", "Dizleri sertçe kilitleyip bacakları kasmak."], "Bacaklarının arkası geriliyorsa kalçanı duvardan biraz uzaklaştır."),
    "de": ExerciseGuide(["Setz dich seitlich an eine Wand, eine Hüfte berührt sie.", "Schwing die Beine an der Wand hoch, während du dich auf den Boden legst.", "Lass die Arme neben dem Körper ruhen und entspann die Beine an der Wand.", "Bleib 3 Minuten und atme ruhig."], ["Den unteren Rücken vom Boden abheben.", "Die Knie hart durchdrücken und die Beine anspannen."], "Rück mit der Hüfte etwas von der Wand weg, wenn sich die Beinrückseite eng anfühlt."),
    "fr": ExerciseGuide(["Assieds-toi de côté contre un mur, une hanche touchant le mur.", "Fais monter les jambes le long du mur en t'allongeant sur le dos.", "Laisse les bras le long du corps et relâche les jambes contre le mur.", "Reste 3 minutes en respirant lentement."], ["Décoller le bas du dos du sol.", "Bloquer fort les genoux et crisper les jambes."], "Éloigne un peu les hanches du mur si l'arrière de tes jambes est tendu."),
    "es": ExerciseGuide(["Siéntate de lado junto a una pared con una cadera tocándola.", "Sube las piernas por la pared mientras te tumbas en el suelo.", "Deja los brazos a los lados y relaja las piernas contra la pared.", "Quédate 3 minutos respirando despacio."], ["Levantar la zona lumbar del suelo.", "Bloquear las rodillas con fuerza y tensar las piernas."], "Aleja un poco las caderas de la pared si notas tensa la parte de atrás de las piernas."),
    "it": ExerciseGuide(["Siediti di lato accanto a un muro, con un fianco che lo tocca.", "Fai salire le gambe lungo il muro mentre ti sdrai all'indietro.", "Lascia le braccia lungo i fianchi e rilassa le gambe contro il muro.", "Resta così per 3 minuti, respirando lentamente."], ["Staccare la zona lombare dal pavimento.", "Bloccare forte le ginocchia e irrigidire le gambe."], "Allontana un po' i fianchi dal muro se senti tese le gambe dietro."),
    "pt": ExerciseGuide(["Sente de lado ao lado de uma parede, com um quadril encostado nela.", "Levante as pernas pela parede enquanto deita de costas no chão.", "Deixe os braços ao lado do corpo e relaxe as pernas contra a parede.", "Fique 3 minutos, respirando devagar."], ["Descolar a lombar do chão.", "Travar os joelhos com força e tensionar as pernas."], "Afaste um pouco o quadril da parede se a parte de trás das pernas ficar tensa."),
    "hi": ExerciseGuide(["दीवार के बगल में साइड से बैठो, एक कूल्हा दीवार को छूता हो।", "पीठ के बल लेटते हुए पैरों को दीवार पर ऊपर चढ़ा दो।", "बाँहें बगल में रखो और पैरों को दीवार पर ढीला छोड़ दो।", "3 मिनट इसी तरह रहो और धीरे साँस लेते रहो।"], ["पीठ के निचले हिस्से को ज़मीन से उठा देना।", "घुटनों को ज़ोर से लॉक करके पैरों को तानना।"], "पैरों के पिछले हिस्से में खिंचाव ज़्यादा लगे तो कूल्हों को दीवार से थोड़ा दूर कर लो।"),
    "nl": ExerciseGuide(["Ga zijdelings naast een muur zitten met één heup ertegen.", "Zwaai je benen omhoog langs de muur terwijl je achterover op de vloer gaat liggen.", "Laat je armen langs je lichaam rusten en ontspan je benen tegen de muur.", "Blijf 3 minuten liggen en adem rustig."], ["Je onderrug van de vloer tillen.", "Je knieën hard op slot zetten en je benen aanspannen."], "Schuif je heupen iets van de muur af als de achterkant van je benen strak voelt."),
    "pl": ExerciseGuide(["Usiądź bokiem przy ścianie, jednym biodrem dotykając jej.", "Unieś nogi po ścianie, kładąc się jednocześnie na plecach na podłodze.", "Ramiona połóż wzdłuż ciała i rozluźnij nogi na ścianie.", "Zostań w tej pozycji 3 minuty, oddychając powoli."], ["Odrywanie dolnych pleców od podłogi.", "Mocne blokowanie kolan i napinanie nóg."], "Odsuń biodra trochę od ściany, jeśli tył nóg jest napięty."),
    "sv": ExerciseGuide(["Sitt på sidan intill en vägg med ena höften mot den.", "Sväng upp benen uppför väggen medan du lägger dig ner på golvet.", "Låt armarna vila längs sidorna och slappna av i benen mot väggen.", "Stanna i 3 minuter och andas långsamt."], ["Att lyfta ländryggen från golvet.", "Att spärra knäna hårt och spänna benen."], "Flytta höfterna lite bort från väggen om baksidan av benen känns stram."),
  },
  "spinal_twist": {
    "en": ExerciseGuide(["Lie on your back with your arms out to the sides.", "Bend one knee and bring it across your body toward the floor.", "Keep both shoulders on the floor and look to the opposite side.", "Hold 20 seconds, switch sides, and do 2 sets on each side."], ["Letting the opposite shoulder lift off the floor.", "Forcing the knee down with the hand."], "Rest your knee on a cushion if it does not reach the floor."),
    "tr": ExerciseGuide(["Sırtüstü uzan, kollarını iki yana aç.", "Bir dizini bük ve vücudunun karşı tarafına, yere doğru götür.", "İki omzunu da yerde tut, başını ters yöne çevir.", "20 saniye tut, taraf değiştir ve her tarafta 2 set yap."], ["Karşı omzun yerden kalkması.", "Dizi elle zorlayarak aşağı bastırmak."], "Dizin yere değmiyorsa altına bir yastık koy."),
    "de": ExerciseGuide(["Leg dich auf den Rücken, die Arme seitlich ausgestreckt.", "Beug ein Knie und führ es quer über den Körper Richtung Boden.", "Lass beide Schultern am Boden und schau zur anderen Seite.", "Halte 20 Sekunden, wechsle die Seite und mach 2 Sätze pro Seite."], ["Die gegenüberliegende Schulter vom Boden abheben.", "Das Knie mit der Hand nach unten zwingen."], "Leg das Knie auf ein Kissen, wenn es den Boden nicht erreicht."),
    "fr": ExerciseGuide(["Allonge-toi sur le dos, les bras écartés sur les côtés.", "Fléchis un genou et amène-le de l'autre côté du corps vers le sol.", "Garde les deux épaules au sol et regarde du côté opposé.", "Tiens 20 secondes, change de côté et fais 2 séries de chaque côté."], ["Laisser l'épaule opposée se décoller du sol.", "Forcer le genou vers le bas avec la main."], "Pose le genou sur un coussin s'il n'atteint pas le sol."),
    "es": ExerciseGuide(["Túmbate boca arriba con los brazos abiertos a los lados.", "Flexiona una rodilla y llévala cruzando el cuerpo hacia el suelo.", "Mantén los dos hombros en el suelo y mira hacia el lado contrario.", "Aguanta 20 segundos, cambia de lado y haz 2 series de cada lado."], ["Dejar que el hombro contrario se levante del suelo.", "Forzar la rodilla hacia abajo con la mano."], "Apoya la rodilla en un cojín si no llega al suelo."),
    "it": ExerciseGuide(["Sdraiati sulla schiena con le braccia aperte ai lati.", "Piega un ginocchio e portalo oltre il corpo verso il pavimento.", "Tieni entrambe le spalle a terra e guarda dal lato opposto.", "Tieni 20 secondi, cambia lato e fai 2 serie per lato."], ["Far sollevare da terra la spalla opposta.", "Forzare il ginocchio verso il basso con la mano."], "Appoggia il ginocchio su un cuscino se non arriva a terra."),
    "pt": ExerciseGuide(["Deite de costas com os braços abertos para os lados.", "Dobre um joelho e leve-o para o outro lado do corpo em direção ao chão.", "Mantenha os dois ombros no chão e olhe para o lado oposto.", "Segure 20 segundos, troque de lado e faça 2 séries de cada lado."], ["Deixar o ombro oposto levantar do chão.", "Forçar o joelho para baixo com a mão."], "Apoie o joelho em uma almofada se ele não alcançar o chão."),
    "hi": ExerciseGuide(["पीठ के बल लेट जाओ, बाँहें दोनों तरफ़ फैली हों।", "एक घुटना मोड़ो और उसे शरीर के आर-पार ज़मीन की ओर ले जाओ।", "दोनों कंधे ज़मीन पर रखो और दूसरी तरफ़ देखो।", "20 सेकंड रुको, तरफ़ बदलो और हर तरफ़ 2 सेट करो।"], ["दूसरी तरफ़ के कंधे को ज़मीन से उठने देना।", "हाथ से घुटने को ज़बरदस्ती नीचे दबाना।"], "घुटना ज़मीन तक न पहुँचे तो उसके नीचे तकिया रख लो।"),
    "nl": ExerciseGuide(["Lig op je rug met je armen opzij.", "Buig één knie en breng hem over je lichaam naar de vloer.", "Houd beide schouders op de vloer en kijk naar de andere kant.", "Houd 20 seconden vast, wissel van kant en doe 2 sets per kant."], ["De schouder aan de andere kant van de vloer laten komen.", "De knie met je hand naar beneden forceren."], "Laat je knie op een kussen rusten als hij de vloer niet haalt."),
    "pl": ExerciseGuide(["Połóż się na plecach, ramiona wyciągnij na boki.", "Ugnij jedno kolano i przenieś je w poprzek ciała w stronę podłogi.", "Oba barki trzymaj na podłodze i spójrz w przeciwną stronę.", "Wytrzymaj 20 sekund, zmień stronę i wykonaj 2 serie na każdą stronę."], ["Odrywanie przeciwnego barku od podłogi.", "Dociskanie kolana do podłogi ręką na siłę."], "Oprzyj kolano na poduszce, jeśli nie sięga podłogi."),
    "sv": ExerciseGuide(["Ligg på rygg med armarna utsträckta åt sidorna.", "Böj ena knät och för det över kroppen mot golvet.", "Håll båda axlarna i golvet och titta åt motsatt håll.", "Håll i 20 sekunder, byt sida och gör 2 set på varje sida."], ["Att låta motsatt axel lyfta från golvet.", "Att tvinga ner knät med handen."], "Vila knät på en kudde om det inte når golvet."),
  },
  "chest_stretch": {
    "en": ExerciseGuide(["Stand in a doorway and place one forearm on the frame, elbow at shoulder height.", "Step the same-side foot forward through the doorway.", "Lean your chest forward until you feel a stretch across the front of your shoulder.", "Hold 20 seconds, switch sides, and do 2 sets on each side."], ["Arching the lower back to lean further.", "Shrugging the shoulder up toward the ear."], "Keep the stretch gentle, and back off if you feel a pinch in your shoulder."),
    "tr": ExerciseGuide(["Kapı aralığında dur, bir ön kolunu kasaya yasla, dirseğin omuz hizasında olsun.", "Aynı taraftaki ayağınla kapıdan öne adım at.", "Omzunun önünde esneme hissedene kadar göğsünü öne ver.", "20 saniye tut, taraf değiştir ve her tarafta 2 set yap."], ["Daha çok uzanmak için beli çukurlaştırmak.", "Omzu kulağa doğru kaldırmak."], "Esnemeyi hafif tut, omzunda sıkışma hissedersen biraz geri çekil."),
    "de": ExerciseGuide(["Stell dich in einen Türrahmen und leg einen Unterarm an den Rahmen, der Ellbogen auf Schulterhöhe.", "Setz den Fuß derselben Seite durch den Türrahmen nach vorn.", "Lehn die Brust nach vorn, bis du eine Dehnung vorn an der Schulter spürst.", "Halte 20 Sekunden, wechsle die Seite und mach 2 Sätze pro Seite."], ["Ins Hohlkreuz gehen, um weiter zu kommen.", "Die Schulter zum Ohr hochziehen."], "Dehn sanft und geh zurück, wenn du ein Zwicken in der Schulter spürst."),
    "fr": ExerciseGuide(["Place-toi dans l'encadrement d'une porte et pose un avant-bras contre le montant, le coude à hauteur d'épaule.", "Avance le pied du même côté à travers la porte.", "Penche la poitrine vers l'avant jusqu'à sentir un étirement à l'avant de l'épaule.", "Tiens 20 secondes, change de côté et fais 2 séries de chaque côté."], ["Se cambrer pour aller plus loin.", "Monter l'épaule vers l'oreille."], "Reste en douceur et relâche si tu sens un pincement dans l'épaule."),
    "es": ExerciseGuide(["Ponte en el marco de una puerta y apoya un antebrazo en él, con el codo a la altura del hombro.", "Da un paso adelante con el pie del mismo lado, atravesando la puerta.", "Inclina el pecho hacia delante hasta notar un estiramiento en la parte delantera del hombro.", "Aguanta 20 segundos, cambia de lado y haz 2 series de cada lado."], ["Arquear la zona lumbar para inclinarte más.", "Subir el hombro hacia la oreja."], "Estira con suavidad y afloja si notas un pellizco en el hombro."),
    "it": ExerciseGuide(["Mettiti in uno stipite e appoggia un avambraccio sul telaio, con il gomito all'altezza della spalla.", "Fai un passo avanti, attraverso lo stipite, con il piede dello stesso lato.", "Inclina il petto in avanti finché senti l'allungamento davanti alla spalla.", "Tieni 20 secondi, cambia lato e fai 2 serie per lato."], ["Inarcare la zona lombare per andare più avanti.", "Alzare la spalla verso l'orecchio."], "Tieni l'allungamento leggero e fermati se senti un pizzico alla spalla."),
    "pt": ExerciseGuide(["Fique em uma porta e apoie um antebraço no batente, com o cotovelo na altura do ombro.", "Dê um passo à frente, atravessando a porta, com o pé do mesmo lado.", "Incline o peito para a frente até sentir o alongamento na frente do ombro.", "Segure 20 segundos, troque de lado e faça 2 séries de cada lado."], ["Arquear a lombar para ir mais longe.", "Subir o ombro em direção à orelha."], "Mantenha o alongamento leve e recue se sentir uma pontada no ombro."),
    "hi": ExerciseGuide(["दरवाज़े में खड़े हो जाओ और एक अग्रबाहु चौखट पर रखो, कोहनी कंधे की ऊँचाई पर हो।", "उसी तरफ़ का पैर दरवाज़े के पार आगे रखो।", "सीने को आगे झुकाओ, जब तक कंधे के आगे खिंचाव न लगे।", "20 सेकंड रुको, तरफ़ बदलो और हर तरफ़ 2 सेट करो।"], ["और आगे झुकने के लिए पीठ के निचले हिस्से को मोड़ना।", "कंधे को कान की ओर उचका लेना।"], "स्ट्रेच हल्का रखो और कंधे में चुभन लगे तो पीछे हट जाओ।"),
    "nl": ExerciseGuide(["Sta in een deuropening en leg één onderarm op het kozijn met je elleboog op schouderhoogte.", "Zet de voet aan dezelfde kant naar voren door de deuropening.", "Leun met je borst naar voren tot je een stretch voelt aan de voorkant van je schouder.", "Houd 20 seconden vast, wissel van kant en doe 2 sets per kant."], ["Een holle onderrug maken om verder te leunen.", "Je schouder naar je oor optrekken."], "Houd de stretch rustig en ga terug als je een scherpe steek in je schouder voelt."),
    "pl": ExerciseGuide(["Stań w drzwiach i oprzyj jedno przedramię o framugę, łokieć na wysokości barku.", "Zrób krok przez drzwi stopą po tej samej stronie.", "Pochyl klatkę piersiową do przodu, aż poczujesz rozciąganie z przodu barku.", "Wytrzymaj 20 sekund, zmień stronę i wykonaj 2 serie na każdą stronę."], ["Wyginanie lędźwi, by pochylić się dalej.", "Unoszenie barku w stronę ucha."], "Rozciągaj delikatnie i wycofaj się, jeśli poczujesz kłucie w barku."),
    "sv": ExerciseGuide(["Stå i en dörröppning och lägg ena underarmen mot karmen med armbågen i axelhöjd.", "Kliv fram med foten på samma sida genom dörröppningen.", "Luta bröstet framåt tills du känner en stretch över framsidan av axeln.", "Håll i 20 sekunder, byt sida och gör 2 set på varje sida."], ["Att svanka för att luta sig längre.", "Att dra upp axeln mot örat."], "Håll stretchen mjuk och backa om du känner ett nyp i axeln."),
  },
  "scapular_retraction": {
    "en": ExerciseGuide(["Sit or stand tall with your arms relaxed at your sides.", "Pull your shoulder blades back and down, as if tucking them into your back pockets.", "Hold the squeeze for one slow breath, then release.", "Do 10 reps and rest, 2 sets in total."], ["Shrugging the shoulders up while squeezing.", "Pushing the ribs forward and arching the back."], "Keep your chin level and your neck relaxed the whole time."),
    "tr": ExerciseGuide(["Dik otur ya da ayakta dur, kolların yanlarda gevşek olsun.", "Kürek kemiklerini arka ceplerine sokar gibi geriye ve aşağı çek.", "Bir yavaş nefes boyunca sıkılı tut, sonra bırak.", "10 tekrar yap ve dinlen, toplam 2 set."], ["Sıkarken omuzları yukarı kaldırmak.", "Kaburgaları öne itip beli çukurlaştırmak."], "Hareket boyunca çeneni düz, boynunu gevşek tut."),
    "de": ExerciseGuide(["Sitz oder steh aufrecht, die Arme locker an den Seiten.", "Zieh die Schulterblätter nach hinten und unten, als würdest du sie in die Hosentaschen stecken.", "Halte die Spannung einen langsamen Atemzug lang und lass dann los.", "Mach 10 Wiederholungen und ruh dich aus, insgesamt 2 Sätze."], ["Die Schultern beim Zusammenziehen hochziehen.", "Die Rippen nach vorn schieben und ins Hohlkreuz gehen."], "Halte das Kinn waagerecht und den Nacken die ganze Zeit entspannt."),
    "fr": ExerciseGuide(["Assieds-toi ou tiens-toi droit, les bras relâchés le long du corps.", "Ramène les omoplates vers l'arrière et vers le bas, comme pour les glisser dans tes poches arrière.", "Garde le serrage le temps d'une respiration lente, puis relâche.", "Fais 10 répétitions et repose-toi, 2 séries au total."], ["Monter les épaules en serrant.", "Pousser les côtes vers l'avant en se cambrant."], "Garde le menton à l'horizontale et la nuque détendue tout le temps."),
    "es": ExerciseGuide(["Siéntate o ponte de pie, recto, con los brazos relajados a los lados.", "Lleva los omóplatos hacia atrás y abajo, como si los metieras en los bolsillos de atrás.", "Aguanta el apretón durante una respiración lenta y suelta.", "Haz 10 repeticiones y descansa, 2 series en total."], ["Subir los hombros mientras aprietas.", "Sacar las costillas hacia delante y arquear la espalda."], "Mantén la barbilla a nivel y el cuello relajado todo el tiempo."),
    "it": ExerciseGuide(["Stai seduto o in piedi con le braccia rilassate lungo i fianchi.", "Porta le scapole indietro e in basso, come se le infilassi nelle tasche posteriori dei pantaloni.", "Mantieni la stretta per un respiro lento, poi rilascia.", "Fai 10 ripetizioni e riposa, 2 serie in totale."], ["Alzare le spalle mentre stringi.", "Spingere le costole in avanti e inarcare la schiena."], "Tieni il mento in piano e il collo rilassato per tutto il tempo."),
    "pt": ExerciseGuide(["Sente ou fique em pé com os braços relaxados ao lado do corpo.", "Puxe as escápulas para trás e para baixo, como se as guardasse nos bolsos de trás da calça.", "Segure o aperto por uma respiração lenta e depois solte.", "Faça 10 repetições e descanse, 2 séries no total."], ["Subir os ombros enquanto aperta.", "Empurrar as costelas para a frente e arquear as costas."], "Mantenha o queixo reto e o pescoço relaxado o tempo todo."),
    "hi": ExerciseGuide(["सीधे बैठो या खड़े हो जाओ, बाँहें बगल में ढीली रहें।", "ब्लेड्स को पीछे और नीचे खींचो, जैसे उन्हें पीछे की जेबों में डाल रहे हो।", "एक धीमी साँस तक भींचे रखो, फिर छोड़ दो।", "10 रेप्स करो और आराम करो, कुल 2 सेट।"], ["भींचते समय कंधों को ऊपर उचका लेना।", "पसलियों को आगे धकेलकर पीठ को मोड़ देना।"], "पूरे समय ठोड़ी सीधी और गर्दन ढीली रखो।"),
    "nl": ExerciseGuide(["Zit of sta rechtop met je armen ontspannen langs je zij.", "Trek je schouderbladen naar achteren en omlaag, alsof je ze in je achterzakken stopt.", "Houd de knijp vast tijdens één rustige ademhaling en laat dan los.", "Doe 10 herhalingen en rust, 2 sets in totaal."], ["Je schouders optrekken terwijl je knijpt.", "Je ribben naar voren duwen en een holle rug maken."], "Houd je kin recht en je nek de hele tijd ontspannen."),
    "pl": ExerciseGuide(["Usiądź lub stań prosto z rozluźnionymi ramionami wzdłuż ciała.", "Ściągnij łopatki do tyłu i w dół, jakbyś chował je do tylnych kieszeni.", "Utrzymaj napięcie przez jeden powolny oddech, potem puść.", "Zrób 10 powtórzeń i odpocznij, łącznie 2 serie."], ["Unoszenie barków podczas ściągania.", "Wypychanie żeber do przodu i wyginanie pleców."], "Trzymaj brodę prosto, a kark rozluźniony przez cały czas."),
    "sv": ExerciseGuide(["Sitt eller stå rakt med armarna avslappnade längs sidorna.", "Dra skulderbladen bakåt och nedåt, som om du stoppade ner dem i bakfickorna.", "Håll kvar knipet under ett långsamt andetag och släpp sedan.", "Gör 10 upprepningar och vila, 2 set totalt."], ["Att dra upp axlarna medan du knipar.", "Att skjuta fram revbenen och svanka."], "Håll hakan i våg och nacken avslappnad hela tiden."),
  },
  "thoracic_extension": {
    "en": ExerciseGuide(["Sit on a sturdy chair with the top of its back just below your shoulder blades.", "Put your hands behind your head and keep your elbows wide.", "Lean your upper back slowly over the chair back and look up.", "Come back up, do 8 reps and rest, 2 sets in total."], ["Bending from the lower back instead of the upper back.", "Pulling the head forward with the hands."], "Use a chair that cannot roll or tip, and keep your feet flat on the floor."),
    "tr": ExerciseGuide(["Sağlam bir sandalyeye otur, arkalığın üst kenarı kürek kemiklerinin hemen altına gelsin.", "Ellerini başının arkasına koy, dirseklerini açık tut.", "Sırtının üst kısmını yavaşça arkalığın üstünden geriye bırak ve yukarı bak.", "Geri doğrul, 8 tekrar yap ve dinlen, toplam 2 set."], ["Sırtın üst kısmı yerine belden bükülmek.", "Ellerle başı öne doğru çekmek."], "Tekerleksiz ve devrilmeyecek bir sandalye kullan, ayak tabanların yerde kalsın."),
    "de": ExerciseGuide(["Setz dich auf einen stabilen Stuhl, die Oberkante der Lehne knapp unter deinen Schulterblättern.", "Leg die Hände hinter den Kopf und halte die Ellbogen weit.", "Lehn den oberen Rücken langsam über die Lehne und schau nach oben.", "Komm zurück, mach 8 Wiederholungen und ruh dich aus, insgesamt 2 Sätze."], ["Aus dem unteren statt aus dem oberen Rücken beugen.", "Den Kopf mit den Händen nach vorn ziehen."], "Nimm einen Stuhl, der nicht rollen oder kippen kann, und halte die Füße flach auf dem Boden."),
    "fr": ExerciseGuide(["Assieds-toi sur une chaise solide, le haut du dossier juste sous tes omoplates.", "Mets les mains derrière la tête en gardant les coudes bien ouverts.", "Penche lentement le haut du dos par-dessus le dossier et regarde vers le haut.", "Reviens, fais 8 répétitions et repose-toi, 2 séries au total."], ["Se cambrer avec le bas du dos au lieu du haut du dos.", "Tirer la tête vers l'avant avec les mains."], "Prends une chaise qui ne peut ni rouler ni basculer, et garde les pieds à plat au sol."),
    "es": ExerciseGuide(["Siéntate en una silla resistente con el borde superior del respaldo justo debajo de los omóplatos.", "Pon las manos detrás de la cabeza y mantén los codos abiertos.", "Inclina despacio la parte alta de la espalda sobre el respaldo y mira hacia arriba.", "Vuelve a subir, haz 8 repeticiones y descansa, 2 series en total."], ["Doblarte desde la zona lumbar en vez de la parte alta de la espalda.", "Tirar de la cabeza hacia delante con las manos."], "Usa una silla que no ruede ni se incline, y mantén los pies planos en el suelo."),
    "it": ExerciseGuide(["Siediti su una sedia stabile con il bordo dello schienale appena sotto le scapole.", "Metti le mani dietro la testa e tieni i gomiti larghi.", "Piegati lentamente all'indietro con la parte alta della schiena sullo schienale e guarda in alto.", "Torna su, fai 8 ripetizioni e riposa, 2 serie in totale."], ["Piegarti con la zona lombare invece che con la parte alta della schiena.", "Tirare la testa in avanti con le mani."], "Usa una sedia che non scivola né si ribalta e tieni i piedi piatti a terra."),
    "pt": ExerciseGuide(["Sente em uma cadeira firme, com o topo do encosto logo abaixo das escápulas.", "Coloque as mãos atrás da cabeça e mantenha os cotovelos abertos.", "Incline devagar a parte de cima das costas sobre o encosto e olhe para cima.", "Volte, faça 8 repetições e descanse, 2 séries no total."], ["Dobrar pela lombar em vez da parte de cima das costas.", "Puxar a cabeça para a frente com as mãos."], "Use uma cadeira que não role nem tombe e mantenha os pés apoiados no chão."),
    "hi": ExerciseGuide(["मज़बूत कुर्सी पर बैठो, उसकी पीठ का ऊपरी किनारा कंधे के ब्लेड्स के ठीक नीचे हो।", "हाथ सिर के पीछे रखो और कोहनियाँ चौड़ी रखो।", "पीठ के ऊपरी हिस्से को धीरे कुर्सी की पीठ पर पीछे झुकाओ और ऊपर देखो।", "वापस ऊपर आओ, 8 रेप्स करो और आराम करो, कुल 2 सेट।"], ["पीठ के ऊपरी हिस्से की जगह निचले हिस्से से मुड़ना।", "हाथों से सिर को आगे खींचना।"], "ऐसी कुर्सी लो जो लुढ़के या पलटे नहीं, और पैर ज़मीन पर सपाट रखो।"),
    "nl": ExerciseGuide(["Zit op een stevige stoel met de bovenkant van de rugleuning net onder je schouderbladen.", "Leg je handen achter je hoofd en houd je ellebogen wijd.", "Leun met je bovenrug langzaam over de rugleuning en kijk omhoog.", "Kom weer omhoog, doe 8 herhalingen en rust, 2 sets in totaal."], ["Buigen vanuit je onderrug in plaats van je bovenrug.", "Je hoofd met je handen naar voren trekken."], "Gebruik een stoel die niet kan rollen of kantelen en houd je voeten plat op de vloer."),
    "pl": ExerciseGuide(["Usiądź na stabilnym krześle tak, by górna krawędź oparcia była tuż pod łopatkami.", "Złóż dłonie za głową i trzymaj łokcie szeroko.", "Powoli odchylaj górną część pleców przez oparcie i patrz w górę.", "Wróć do pionu, zrób 8 powtórzeń i odpocznij, łącznie 2 serie."], ["Zginanie się w lędźwiach zamiast w górnej części pleców.", "Ciągnięcie głowy do przodu rękami."], "Użyj krzesła, które nie jeździ ani nie przechyla się, i trzymaj stopy płasko na podłodze."),
    "sv": ExerciseGuide(["Sitt på en stadig stol med ryggstödets överkant strax under skulderbladen.", "Lägg händerna bakom huvudet och håll armbågarna brett.", "Luta överryggen långsamt bakåt över stolsryggen och titta uppåt.", "Kom upp igen, gör 8 upprepningar och vila, 2 set totalt."], ["Att böja sig i ländryggen i stället för i överryggen.", "Att dra huvudet framåt med händerna."], "Använd en stol som inte kan rulla eller tippa och ha fötterna platta i golvet."),
  },
  "hanging_knee_raise": {
    "en": ExerciseGuide(["Grip the bar overhand and hang with straight arms.", "Pull your shoulders down away from your ears.", "Lift both knees to hip height without swinging, then lower them slowly.", "Do 5 reps, step down and rest, 3 sets in total."], ["Swinging the body to throw the knees up.", "Hanging with the shoulders up by the ears."], "Check that the bar is solid before you hang, and step down instead of dropping off."),
    "tr": ExerciseGuide(["Barı üstten kavra, kolların düz şekilde asıl.", "Omuzlarını kulaklarından uzağa, aşağı çek.", "Sallanmadan iki dizini kalça hizasına kaldır, sonra yavaşça indir.", "5 tekrar yap, in ve dinlen, toplam 3 set."], ["Dizleri yukarı atmak için vücudu sallamak.", "Omuzlar kulak hizasındayken asılmak."], "Asılmadan önce barın sağlam olduğunu kontrol et, bırakıp düşmek yerine basarak in."),
    "de": ExerciseGuide(["Greif die Stange im Obergriff und häng mit gestreckten Armen.", "Zieh die Schultern von den Ohren weg nach unten.", "Heb beide Knie auf Hüfthöhe, ohne zu schwingen, und senk sie langsam wieder ab.", "Mach 5 Wiederholungen, steig ab und ruh dich aus, insgesamt 3 Sätze."], ["Mit dem Körper schwingen, um die Knie hochzuwerfen.", "Mit den Schultern bis zu den Ohren hängen."], "Prüf vor dem Hängen, ob die Stange stabil ist, und steig ab, statt abzuspringen."),
    "fr": ExerciseGuide(["Attrape la barre en pronation et suspends-toi, bras tendus.", "Abaisse les épaules en les éloignant des oreilles.", "Monte les deux genoux à hauteur de hanches sans te balancer, puis redescends-les lentement.", "Fais 5 répétitions, descends de la barre et repose-toi, 3 séries au total."], ["Se balancer pour projeter les genoux vers le haut.", "Rester suspendu avec les épaules collées aux oreilles."], "Vérifie que la barre est solide avant de t'y suspendre, et descends en douceur au lieu de sauter."),
    "es": ExerciseGuide(["Agarra la barra con las palmas hacia delante y cuélgate con los brazos estirados.", "Baja los hombros alejándolos de las orejas.", "Sube las dos rodillas a la altura de la cadera sin balancearte y bájalas despacio.", "Haz 5 repeticiones, bájate de la barra y descansa, 3 series en total."], ["Balancear el cuerpo para lanzar las rodillas hacia arriba.", "Colgarte con los hombros pegados a las orejas."], "Comprueba que la barra es firme antes de colgarte, y bájate con cuidado en vez de dejarte caer."),
    "it": ExerciseGuide(["Afferra la sbarra a presa prona e resta appeso con le braccia tese.", "Abbassa le spalle lontano dalle orecchie.", "Porta entrambe le ginocchia all'altezza delle anche senza dondolare, poi abbassale lentamente.", "Fai 5 ripetizioni, scendi e riposa, 3 serie in totale."], ["Dondolare con il corpo per lanciare su le ginocchia.", "Restare appeso con le spalle vicino alle orecchie."], "Controlla che la sbarra sia solida prima di appenderti e scendi con i piedi invece di lasciarti cadere."),
    "pt": ExerciseGuide(["Segure a barra com as palmas para a frente e fique pendurado com os braços esticados.", "Puxe os ombros para baixo, longe das orelhas.", "Leve os dois joelhos até a altura do quadril sem balançar e depois desça devagar.", "Faça 5 repetições, desça e descanse, 3 séries no total."], ["Balançar o corpo para jogar os joelhos para cima.", "Ficar pendurado com os ombros junto às orelhas."], "Confira se a barra é firme antes de pendurar e desça com os pés em vez de se soltar."),
    "hi": ExerciseGuide(["बार को ऊपर से पकड़ो और सीधी बाँहों के साथ लटक जाओ।", "कंधों को कानों से दूर नीचे खींचो।", "बिना झूले दोनों घुटनों को कूल्हों की ऊँचाई तक उठाओ, फिर धीरे नीचे लाओ।", "5 रेप्स करो, नीचे उतरो और आराम करो, कुल 3 सेट।"], ["घुटनों को ऊपर फेंकने के लिए शरीर को झुलाना।", "कंधों को कानों के पास चढ़ाकर लटकना।"], "लटकने से पहले जाँच लो कि बार मज़बूत है, और कूदकर गिरने की जगह कदम रखकर उतरो।"),
    "nl": ExerciseGuide(["Pak de stang vast met je handpalmen van je af en hang met gestrekte armen.", "Trek je schouders omlaag, weg van je oren.", "Til beide knieën tot heuphoogte zonder te zwaaien en laat ze langzaam zakken.", "Doe 5 herhalingen, stap naar beneden en rust, 3 sets in totaal."], ["Met je lichaam zwaaien om je knieën omhoog te gooien.", "Hangen met je schouders bij je oren."], "Controleer of de stang stevig is voordat je gaat hangen en stap naar beneden in plaats van te vallen."),
    "pl": ExerciseGuide(["Chwyć drążek nachwytem i zwisaj z wyprostowanymi ramionami.", "Ściągnij barki w dół, z dala od uszu.", "Unieś oba kolana na wysokość bioder bez bujania, potem opuść je powoli.", "Zrób 5 powtórzeń, zejdź i odpocznij, łącznie 3 serie."], ["Bujanie ciałem, by wyrzucić kolana w górę.", "Zwis z barkami przy uszach."], "Sprawdź, czy drążek jest solidny, zanim zawiśniesz, i zejdź zamiast spadać."),
    "sv": ExerciseGuide(["Ta tag i stången med överhandsgrepp och häng med raka armar.", "Dra ner axlarna bort från öronen.", "Lyft båda knäna till höftnivå utan att svinga och sänk dem sedan långsamt.", "Gör 5 upprepningar, kliv ner och vila, 3 set totalt."], ["Att svinga kroppen för att kasta upp knäna.", "Att hänga med axlarna uppe vid öronen."], "Kontrollera att stången är stabil innan du hänger dig och kliv ner i stället för att släppa dig."),
  },
  "scapular_pull": {
    "en": ExerciseGuide(["Grip the bar overhand, hands slightly wider than your shoulders.", "Hang with straight arms and let your shoulders rise toward your ears.", "Pull your shoulder blades down so your body lifts a little, elbows straight.", "Hold a second and release, do 5 reps, 3 sets in total."], ["Bending the elbows to pull higher.", "Swinging the legs to help."], "Check that the bar is solid, and keep your feet on a box if a full hang is too hard."),
    "tr": ExerciseGuide(["Barı üstten kavra, ellerin omuzlarından biraz geniş olsun.", "Kolların düz şekilde asıl, omuzlarının kulaklarına doğru çıkmasına izin ver.", "Dirseklerini bükmeden kürek kemiklerini aşağı çek, vücudun biraz yükselsin.", "Bir saniye tut ve bırak, 5 tekrar yap, toplam 3 set."], ["Daha yükseğe çıkmak için dirsekleri bükmek.", "Yardım almak için bacakları sallamak."], "Barın sağlam olduğunu kontrol et, tam asılmak zor geliyorsa ayaklarını bir kasaya bas."),
    "de": ExerciseGuide(["Greif die Stange im Obergriff, die Hände etwas weiter als schulterbreit.", "Häng mit gestreckten Armen und lass die Schultern Richtung Ohren steigen.", "Zieh die Schulterblätter nach unten, sodass sich dein Körper ein Stück hebt, die Ellbogen bleiben gestreckt.", "Halte eine Sekunde und lass los, mach 5 Wiederholungen, insgesamt 3 Sätze."], ["Die Ellbogen beugen, um höher zu kommen.", "Mit den Beinen schwingen, um nachzuhelfen."], "Prüf, ob die Stange stabil ist, und lass die Füße auf einer Box, wenn der volle Hang zu schwer ist."),
    "fr": ExerciseGuide(["Attrape la barre en pronation, les mains un peu plus larges que les épaules.", "Suspends-toi bras tendus et laisse les épaules monter vers les oreilles.", "Tire les omoplates vers le bas pour que ton corps monte un peu, les coudes restent tendus.", "Tiens une seconde et relâche, fais 5 répétitions, 3 séries au total."], ["Plier les coudes pour monter plus haut.", "Balancer les jambes pour s'aider."], "Vérifie que la barre est solide, et garde les pieds sur un banc si la suspension complète est trop difficile."),
    "es": ExerciseGuide(["Agarra la barra con las palmas hacia delante, con las manos un poco más abiertas que los hombros.", "Cuélgate con los brazos estirados y deja que los hombros suban hacia las orejas.", "Tira de los omóplatos hacia abajo para que el cuerpo suba un poco, con los codos estirados.", "Aguanta un segundo y suelta, haz 5 repeticiones, 3 series en total."], ["Doblar los codos para subir más.", "Balancear las piernas para ayudarte."], "Comprueba que la barra es firme, y deja los pies sobre un cajón si el cuelgue completo es demasiado difícil."),
    "it": ExerciseGuide(["Afferra la sbarra a presa prona, con le mani un po' più larghe delle spalle.", "Resta appeso con le braccia tese e lascia salire le spalle verso le orecchie.", "Abbassa le scapole in modo che il corpo si sollevi un po', con i gomiti tesi.", "Tieni un secondo e rilascia, fai 5 ripetizioni, 3 serie in totale."], ["Piegare i gomiti per salire di più.", "Dondolare le gambe per aiutarti."], "Controlla che la sbarra sia solida e tieni i piedi su un rialzo se restare appeso del tutto è troppo difficile."),
    "pt": ExerciseGuide(["Segure a barra com as palmas para a frente, com as mãos um pouco mais abertas que os ombros.", "Fique pendurado com os braços esticados e deixe os ombros subirem em direção às orelhas.", "Puxe as escápulas para baixo para o corpo subir um pouco, com os cotovelos esticados.", "Segure um segundo e solte, faça 5 repetições, 3 séries no total."], ["Dobrar os cotovelos para subir mais.", "Balançar as pernas para ajudar."], "Confira se a barra é firme e apoie os pés em uma caixa se ficar totalmente pendurado for difícil demais."),
    "hi": ExerciseGuide(["बार को ऊपर से पकड़ो, हाथ कंधों से थोड़े चौड़े हों।", "सीधी बाँहों के साथ लटको और कंधों को कानों की ओर उठने दो।", "ब्लेड्स को नीचे खींचो ताकि शरीर थोड़ा ऊपर उठे, कोहनियाँ सीधी रहें।", "एक सेकंड रुको और छोड़ो, 5 रेप्स करो, कुल 3 सेट।"], ["और ऊपर जाने के लिए कोहनियाँ मोड़ना।", "मदद के लिए पैर झुलाना।"], "जाँच लो कि बार मज़बूत है, और पूरी तरह लटकना मुश्किल हो तो पैर बॉक्स पर रख लो।"),
    "nl": ExerciseGuide(["Pak de stang vast met je handpalmen van je af, iets breder dan je schouders.", "Hang met gestrekte armen en laat je schouders naar je oren komen.", "Trek je schouderbladen omlaag zodat je lichaam een stukje omhoog komt, met gestrekte ellebogen.", "Houd het een seconde vast en laat los, doe 5 herhalingen, 3 sets in totaal."], ["Je ellebogen buigen om hoger te trekken.", "Met je benen zwaaien om te helpen."], "Controleer of de stang stevig is en houd je voeten op een kist als een volledige hang te zwaar is."),
    "pl": ExerciseGuide(["Chwyć drążek nachwytem, ręce nieco szerzej niż barki.", "Zwisaj na prostych ramionach i pozwól barkom unieść się w stronę uszu.", "Ściągnij łopatki w dół, aby ciało lekko się uniosło, z wyprostowanymi łokciami.", "Przytrzymaj sekundę i puść, zrób 5 powtórzeń, łącznie 3 serie."], ["Uginanie łokci, by podciągnąć się wyżej.", "Bujanie nogami dla pomocy."], "Sprawdź, czy drążek jest solidny, i postaw stopy na skrzyni, jeśli pełny zwis jest za trudny."),
    "sv": ExerciseGuide(["Ta tag i stången med överhandsgrepp, händerna något bredare än axlarna.", "Häng med raka armar och låt axlarna glida upp mot öronen.", "Dra skulderbladen nedåt så att kroppen lyfts lite, med raka armbågar.", "Håll en sekund och släpp, gör 5 upprepningar, 3 set totalt."], ["Att böja armbågarna för att dra högre.", "Att svinga benen för att hjälpa till."], "Kontrollera att stången är stabil och ha fötterna på en låda om ett helt häng är för tungt."),
  },
  "pull_ups": {
    "en": ExerciseGuide(["Grip the bar overhand, hands slightly wider than your shoulders.", "Start from a straight-arm hang and pull your shoulder blades down.", "Pull until your chin clears the bar, then lower yourself slowly.", "Do 2 reps, step down and rest, 3 sets in total."], ["Kicking and swinging to get over the bar.", "Dropping down fast instead of lowering with control."], "Loop a band under your feet or jump to the top and lower slowly, and check that the bar is solid."),
    "tr": ExerciseGuide(["Barı üstten kavra, ellerin omuzlarından biraz geniş olsun.", "Kolların düz şekilde asılı başla ve kürek kemiklerini aşağı çek.", "Çenen barı geçene kadar kendini çek, sonra yavaşça in.", "2 tekrar yap, in ve dinlen, toplam 3 set."], ["Barı geçmek için tekme atıp sallanmak.", "Kontrollü inmek yerine kendini hızla bırakmak."], "Ayaklarının altına bir lastik geçir ya da zıplayıp tepeden yavaşça in, barın sağlam olduğunu kontrol et."),
    "de": ExerciseGuide(["Greif die Stange im Obergriff, die Hände etwas weiter als schulterbreit.", "Starte im Hang mit gestreckten Armen und zieh die Schulterblätter nach unten.", "Zieh dich hoch, bis das Kinn über der Stange ist, und lass dich langsam wieder ab.", "Mach 2 Wiederholungen, steig ab und ruh dich aus, insgesamt 3 Sätze."], ["Strampeln und schwingen, um über die Stange zu kommen.", "Schnell nach unten fallen, statt kontrolliert abzulassen."], "Schling ein Band unter die Füße oder spring nach oben und lass dich langsam ab, und prüf, ob die Stange stabil ist."),
    "fr": ExerciseGuide(["Attrape la barre en pronation, les mains un peu plus larges que les épaules.", "Pars d'une suspension bras tendus et tire les omoplates vers le bas.", "Tire jusqu'à ce que le menton passe au-dessus de la barre, puis redescends lentement.", "Fais 2 répétitions, descends de la barre et repose-toi, 3 séries au total."], ["Donner des coups de pied et se balancer pour passer la barre.", "Se laisser tomber vite au lieu de descendre avec contrôle."], "Passe un élastique sous tes pieds, ou saute en haut et descends lentement, et vérifie que la barre est solide."),
    "es": ExerciseGuide(["Agarra la barra con las palmas hacia delante, con las manos un poco más abiertas que los hombros.", "Empieza desde un cuelgue con los brazos estirados y baja los omóplatos.", "Sube hasta que la barbilla pase la barra y baja despacio.", "Haz 2 repeticiones, bájate de la barra y descansa, 3 series en total."], ["Patalear y balancearte para pasar la barra.", "Dejarte caer rápido en vez de bajar con control."], "Pasa una banda elástica bajo los pies, o salta hasta arriba y baja despacio, y comprueba que la barra es firme."),
    "it": ExerciseGuide(["Afferra la sbarra a presa prona, con le mani un po' più larghe delle spalle.", "Parti appeso con le braccia tese e abbassa le scapole.", "Tira finché il mento supera la sbarra, poi scendi lentamente.", "Fai 2 ripetizioni, scendi e riposa, 3 serie in totale."], ["Scalciare e dondolare per superare la sbarra.", "Lasciarsi cadere in fretta invece di scendere con controllo."], "Fai passare un elastico sotto i piedi, oppure salta in alto e scendi lentamente, e controlla che la sbarra sia solida."),
    "pt": ExerciseGuide(["Segure a barra com as palmas para a frente, com as mãos um pouco mais abertas que os ombros.", "Comece pendurado com os braços esticados e puxe as escápulas para baixo.", "Puxe até o queixo passar da barra e depois desça devagar.", "Faça 2 repetições, desça e descanse, 3 séries no total."], ["Chutar e balançar para passar da barra.", "Despencar rápido em vez de descer com controle."], "Passe uma faixa elástica sob os pés ou salte até o topo e desça devagar, e confira se a barra é firme."),
    "hi": ExerciseGuide(["बार को ऊपर से पकड़ो, हाथ कंधों से थोड़े चौड़े हों।", "सीधी बाँहों के साथ लटककर शुरू करो और ब्लेड्स को नीचे खींचो।", "तब तक खींचो जब तक ठोड़ी बार के ऊपर न निकल जाए, फिर धीरे नीचे आओ।", "2 रेप्स करो, नीचे उतरो और आराम करो, कुल 3 सेट।"], ["बार के ऊपर जाने के लिए पैर चलाना और झूलना।", "काबू से उतरने की जगह तेज़ी से नीचे गिर जाना।"], "पैरों के नीचे बैंड लगाओ या कूदकर ऊपर पहुँचो और धीरे नीचे आओ, और जाँच लो कि बार मज़बूत है।"),
    "nl": ExerciseGuide(["Pak de stang vast met je handpalmen van je af, iets breder dan je schouders.", "Begin vanuit een hang met gestrekte armen en trek je schouderbladen omlaag.", "Trek tot je kin boven de stang komt en laat je dan langzaam zakken.", "Doe 2 herhalingen, stap naar beneden en rust, 3 sets in totaal."], ["Schoppen en zwaaien om over de stang te komen.", "Snel naar beneden vallen in plaats van gecontroleerd zakken."], "Doe een band onder je voeten of spring naar boven en zak langzaam, en controleer of de stang stevig is."),
    "pl": ExerciseGuide(["Chwyć drążek nachwytem, ręce nieco szerzej niż barki.", "Zacznij od zwisu na prostych ramionach i ściągnij łopatki w dół.", "Podciągaj się, aż broda znajdzie się nad drążkiem, potem opuszczaj się powoli.", "Zrób 2 powtórzenia, zejdź i odpocznij, łącznie 3 serie."], ["Kopanie i bujanie się, by przejść nad drążek.", "Szybkie opadanie zamiast kontrolowanego opuszczania."], "Zapętl gumę pod stopami albo wskocz do góry i opuszczaj się powoli, oraz sprawdź, czy drążek jest solidny."),
    "sv": ExerciseGuide(["Ta tag i stången med överhandsgrepp, händerna något bredare än axlarna.", "Börja i ett häng med raka armar och dra skulderbladen nedåt.", "Dra tills hakan går över stången och sänk dig sedan långsamt.", "Gör 2 upprepningar, kliv ner och vila, 3 set totalt."], ["Att sparka och svinga för att komma över stången.", "Att släppa sig ner snabbt i stället för att sänka sig under kontroll."], "Lägg ett gummiband under fötterna eller hoppa upp och sänk dig långsamt, och kontrollera att stången är stabil."),
  },
  "bird_dog": {
    "en": ExerciseGuide(["Start on all fours, hands under your shoulders and knees under your hips.", "Reach one arm forward and the opposite leg straight back.", "Hold for two seconds with your hips level, then return.", "Do 8 reps, switch sides, and do 2 sets on each side."], ["Letting the lower back sag as the leg lifts.", "Rotating the hips open to raise the leg higher."], "Imagine a glass of water resting on your lower back that must not spill."),
    "tr": ExerciseGuide(["Eller ve dizler üzerinde başla, ellerin omuzlarının, dizlerin kalçanın altında olsun.", "Bir kolunu öne, çapraz bacağını dümdüz geriye uzat.", "Kalçan düz dururken iki saniye tut, sonra geri gel.", "8 tekrar yap, taraf değiştir ve her tarafta 2 set yap."], ["Bacak kalkarken belin aşağı çökmesi.", "Bacağı daha yükseğe kaldırmak için kalçayı yana açmak."], "Belinin üstünde dökülmemesi gereken bir bardak su durduğunu düşün."),
    "de": ExerciseGuide(["Starte im Vierfüßlerstand, die Hände unter den Schultern und die Knie unter der Hüfte.", "Streck einen Arm nach vorn und das gegenüberliegende Bein gerade nach hinten.", "Halte zwei Sekunden mit waagerechter Hüfte und komm zurück.", "Mach 8 Wiederholungen, wechsle die Seite und mach 2 Sätze pro Seite."], ["Den unteren Rücken beim Heben des Beins durchhängen lassen.", "Die Hüfte aufdrehen, um das Bein höher zu bekommen."], "Stell dir ein Glas Wasser auf deinem unteren Rücken vor, das nicht überschwappen darf."),
    "fr": ExerciseGuide(["Mets-toi à quatre pattes, les mains sous les épaules et les genoux sous les hanches.", "Tends un bras vers l'avant et la jambe opposée droite vers l'arrière.", "Tiens deux secondes, les hanches bien à niveau, puis reviens.", "Fais 8 répétitions, change de côté et fais 2 séries de chaque côté."], ["Laisser le bas du dos s'affaisser quand la jambe monte.", "Ouvrir les hanches pour monter la jambe plus haut."], "Imagine un verre d'eau posé sur ton bas du dos qui ne doit pas se renverser."),
    "es": ExerciseGuide(["Empieza a cuatro patas con las manos bajo los hombros y las rodillas bajo las caderas.", "Estira un brazo hacia delante y la pierna contraria recta hacia atrás.", "Aguanta dos segundos con las caderas niveladas y vuelve.", "Haz 8 repeticiones, cambia de lado y haz 2 series de cada lado."], ["Dejar que la zona lumbar se hunda al subir la pierna.", "Abrir la cadera hacia un lado para subir más la pierna."], "Imagina un vaso de agua apoyado en la zona lumbar que no se debe derramar."),
    "it": ExerciseGuide(["Parti a quattro zampe, con le mani sotto le spalle e le ginocchia sotto le anche.", "Allunga un braccio in avanti e la gamba opposta dritta all'indietro.", "Resta fermo per due secondi con le anche livellate, poi torna.", "Fai 8 ripetizioni, cambia lato e fai 2 serie per lato."], ["Lasciar cedere la zona lombare mentre sollevi la gamba.", "Aprire le anche ruotando per alzare di più la gamba."], "Immagina un bicchiere d'acqua appoggiato sulla zona lombare che non deve rovesciarsi."),
    "pt": ExerciseGuide(["Comece de quatro apoios, com as mãos sob os ombros e os joelhos sob o quadril.", "Estique um braço para a frente e a perna oposta reta para trás.", "Segure por dois segundos com o quadril nivelado e depois volte.", "Faça 8 repetições, troque de lado e faça 2 séries de cada lado."], ["Deixar a lombar ceder quando a perna sobe.", "Abrir o quadril girando para subir mais a perna."], "Imagine um copo de água apoiado na lombar que não pode derramar."),
    "hi": ExerciseGuide(["चारों हाथ-पैरों पर आ जाओ, हाथ कंधों के नीचे और घुटने कूल्हों के नीचे हों।", "एक बाँह आगे और उल्टा पैर सीधा पीछे फैलाओ।", "कूल्हों को बराबर रखकर दो सेकंड रुको, फिर वापस आओ।", "8 रेप्स करो, तरफ़ बदलो और हर तरफ़ 2 सेट करो।"], ["पैर उठाते समय पीठ के निचले हिस्से को झुकने देना।", "पैर और ऊँचा उठाने के लिए कूल्हे को घुमाकर खोल देना।"], "सोचो कि पीठ के निचले हिस्से पर पानी का गिलास रखा है जो छलकना नहीं चाहिए।"),
    "nl": ExerciseGuide(["Begin op handen en knieën, met je handen onder je schouders en je knieën onder je heupen.", "Strek één arm naar voren en het tegenovergestelde been recht naar achteren.", "Houd twee seconden vast met je heupen recht en keer dan terug.", "Doe 8 herhalingen, wissel van kant en doe 2 sets per kant."], ["Je onderrug laten doorzakken als je been omhoog gaat.", "Je heupen open draaien om je been hoger te krijgen."], "Stel je voor dat er een glas water op je onderrug staat dat niet mag overlopen."),
    "pl": ExerciseGuide(["Zacznij w podporze klęcznym, dłonie pod barkami, kolana pod biodrami.", "Wyciągnij jedną rękę do przodu i przeciwną nogę prosto do tyłu.", "Przytrzymaj dwie sekundy, trzymając biodra prosto, potem wróć.", "Zrób 8 powtórzeń, zmień stronę i wykonaj 2 serie na każdą stronę."], ["Zapadanie się dolnych pleców przy unoszeniu nogi.", "Otwieranie bioder w bok, by unieść nogę wyżej."], "Wyobraź sobie szklankę wody na dolnych plecach, z której nie wolno nic rozlać."),
    "sv": ExerciseGuide(["Börja på alla fyra med händerna under axlarna och knäna under höfterna.", "Sträck ena armen framåt och motsatt ben rakt bakåt.", "Håll i två sekunder med höfterna i våg och återgå sedan.", "Gör 8 upprepningar, byt sida och gör 2 set på varje sida."], ["Att låta ländryggen hänga ner när benet lyfts.", "Att vrida upp höfterna för att få benet högre."], "Tänk dig ett glas vatten på ländryggen som inte får spillas."),
  },
  "dead_bug": {
    "en": ExerciseGuide(["Lie on your back with your arms straight up and your knees bent above your hips.", "Press your lower back gently into the floor.", "Lower one arm overhead and the opposite leg toward the floor, then return.", "Do 8 reps on each side and rest, 2 sets in total."], ["Letting the lower back arch off the floor.", "Rushing through the reps."], "Lower your arm and leg only as far as your back can stay flat on the floor."),
    "tr": ExerciseGuide(["Sırtüstü uzan, kollarını dümdüz yukarı uzat, dizlerini kalçanın üstünde bük.", "Belini hafifçe yere bastır.", "Bir kolunu başının üstüne, çapraz bacağını yere doğru indir, sonra geri getir.", "Her tarafta 8 tekrar yap ve dinlen, toplam 2 set."], ["Belin yerden kalkıp çukurlaşması.", "Tekrarları aceleyle yapmak."], "Kolunu ve bacağını yalnızca belin yerde düz kalabildiği kadar indir."),
    "de": ExerciseGuide(["Leg dich auf den Rücken, die Arme senkrecht nach oben und die Knie über der Hüfte gebeugt.", "Drück den unteren Rücken sanft in den Boden.", "Senk einen Arm nach hinten über den Kopf und das gegenüberliegende Bein Richtung Boden, dann komm zurück.", "Mach 8 Wiederholungen pro Seite und ruh dich aus, insgesamt 2 Sätze."], ["Den unteren Rücken vom Boden abheben und ins Hohlkreuz gehen.", "Durch die Wiederholungen hetzen."], "Senk Arm und Bein nur so weit ab, wie dein Rücken flach am Boden bleibt."),
    "fr": ExerciseGuide(["Allonge-toi sur le dos, les bras tendus vers le plafond et les genoux fléchis au-dessus des hanches.", "Plaque doucement le bas du dos contre le sol.", "Descends un bras derrière la tête et la jambe opposée vers le sol, puis reviens.", "Fais 8 répétitions de chaque côté et repose-toi, 2 séries au total."], ["Laisser le bas du dos se cambrer et se décoller du sol.", "Bâcler les répétitions."], "Descends le bras et la jambe seulement jusqu'où ton dos reste bien à plat au sol."),
    "es": ExerciseGuide(["Túmbate boca arriba con los brazos estirados hacia arriba y las rodillas flexionadas sobre las caderas.", "Presiona la zona lumbar con suavidad contra el suelo.", "Baja un brazo por encima de la cabeza y la pierna contraria hacia el suelo, y vuelve.", "Haz 8 repeticiones de cada lado y descansa, 2 series en total."], ["Dejar que la zona lumbar se arquee y se despegue del suelo.", "Hacer las repeticiones con prisa."], "Baja el brazo y la pierna solo hasta donde la espalda siga plana contra el suelo."),
    "it": ExerciseGuide(["Sdraiati sulla schiena con le braccia tese verso l'alto e le ginocchia piegate sopra le anche.", "Premi dolcemente la zona lombare contro il pavimento.", "Abbassa un braccio sopra la testa e la gamba opposta verso il pavimento, poi torna.", "Fai 8 ripetizioni per lato e riposa, 2 serie in totale."], ["Lasciare che la zona lombare si inarchi staccandosi da terra.", "Fare le ripetizioni di fretta."], "Abbassa braccio e gamba solo fin dove la schiena resta piatta sul pavimento."),
    "pt": ExerciseGuide(["Deite de costas com os braços esticados para cima e os joelhos dobrados sobre o quadril.", "Pressione a lombar com suavidade contra o chão.", "Abaixe um braço acima da cabeça e a perna oposta em direção ao chão, e depois volte.", "Faça 8 repetições de cada lado e descanse, 2 séries no total."], ["Deixar a lombar arquear e descolar do chão.", "Fazer as repetições com pressa."], "Abaixe o braço e a perna só até onde as costas continuarem coladas no chão."),
    "hi": ExerciseGuide(["पीठ के बल लेट जाओ, बाँहें सीधी ऊपर हों और घुटने कूल्हों के ऊपर मुड़े हों।", "पीठ के निचले हिस्से को हल्के से ज़मीन में दबाओ।", "एक बाँह सिर के ऊपर और उल्टा पैर ज़मीन की ओर नीचे लाओ, फिर वापस आओ।", "हर तरफ़ 8 रेप्स करो और आराम करो, कुल 2 सेट।"], ["पीठ के निचले हिस्से को मुड़कर ज़मीन से उठने देना।", "रेप्स को जल्दबाज़ी में करना।"], "बाँह और पैर को सिर्फ़ उतना नीचे लाओ जितने में पीठ ज़मीन पर सपाट रहे।"),
    "nl": ExerciseGuide(["Lig op je rug met je armen recht omhoog en je knieën gebogen boven je heupen.", "Druk je onderrug zachtjes in de vloer.", "Laat één arm boven je hoofd en het tegenovergestelde been naar de vloer zakken en keer dan terug.", "Doe 8 herhalingen per kant en rust, 2 sets in totaal."], ["Je onderrug van de vloer laten komen.", "Te snel door de herhalingen heen jagen."], "Laat je arm en been alleen zo ver zakken als je rug plat op de vloer kan blijven."),
    "pl": ExerciseGuide(["Połóż się na plecach, ramiona proste w górę, kolana ugięte nad biodrami.", "Delikatnie dociśnij dolne plecy do podłogi.", "Opuść jedną rękę za głowę i przeciwną nogę w stronę podłogi, potem wróć.", "Zrób 8 powtórzeń na każdą stronę i odpocznij, łącznie 2 serie."], ["Odrywanie dolnych pleców od podłogi przez wygięcie.", "Pośpiech w powtórzeniach."], "Opuszczaj rękę i nogę tylko tak nisko, by plecy pozostały płasko na podłodze."),
    "sv": ExerciseGuide(["Ligg på rygg med armarna rakt upp och knäna böjda ovanför höfterna.", "Tryck ländryggen försiktigt mot golvet.", "Sänk ena armen över huvudet och motsatt ben mot golvet, och återgå sedan.", "Gör 8 upprepningar på varje sida och vila, 2 set totalt."], ["Att låta ländryggen välvas bort från golvet.", "Att rusa igenom upprepningarna."], "Sänk armen och benet bara så långt att ryggen kan vara platt mot golvet."),
  },
  "side_plank": {
    "en": ExerciseGuide(["Lie on your side with your forearm on the floor, elbow under your shoulder.", "Stack your feet and lift your hips off the floor.", "Keep your body in one straight line from head to heels.", "Hold 15 seconds, switch sides, and do 2 sets on each side."], ["Letting the hips drop toward the floor.", "Rolling the chest forward toward the floor."], "Keep your bottom knee on the floor to make it easier."),
    "tr": ExerciseGuide(["Yan yat, ön kolunu yere koy, dirseğin omzunun altında olsun.", "Ayaklarını üst üste koy ve kalçanı yerden kaldır.", "Başından topuklarına kadar vücudunu tek düz bir çizgide tut.", "15 saniye tut, taraf değiştir ve her tarafta 2 set yap."], ["Kalçanın yere doğru düşmesi.", "Göğsün öne, yere doğru dönmesi."], "Kolaylaştırmak için alttaki dizini yerde tut."),
    "de": ExerciseGuide(["Leg dich auf die Seite, der Unterarm liegt am Boden, der Ellbogen unter der Schulter.", "Stapel die Füße und heb die Hüfte vom Boden.", "Halte den Körper in einer geraden Linie von Kopf bis Ferse.", "Halte 15 Sekunden, wechsle die Seite und mach 2 Sätze pro Seite."], ["Die Hüfte zum Boden absinken lassen.", "Die Brust nach vorn zum Boden kippen."], "Lass das untere Knie auf dem Boden, um es leichter zu machen."),
    "fr": ExerciseGuide(["Allonge-toi sur le côté, l'avant-bras au sol et le coude sous l'épaule.", "Superpose les pieds et décolle les hanches du sol.", "Garde le corps en une seule ligne droite de la tête aux talons.", "Tiens 15 secondes, change de côté et fais 2 séries de chaque côté."], ["Laisser les hanches descendre vers le sol.", "Basculer la poitrine vers l'avant, vers le sol."], "Garde le genou du dessous au sol pour rendre l'exercice plus facile."),
    "es": ExerciseGuide(["Túmbate de lado con el antebrazo en el suelo y el codo bajo el hombro.", "Apila los pies y levanta las caderas del suelo.", "Mantén el cuerpo en una línea recta de la cabeza a los talones.", "Aguanta 15 segundos, cambia de lado y haz 2 series de cada lado."], ["Dejar caer las caderas hacia el suelo.", "Girar el pecho hacia delante, hacia el suelo."], "Deja la rodilla de abajo apoyada en el suelo para hacerlo más fácil."),
    "it": ExerciseGuide(["Sdraiati su un fianco con l'avambraccio a terra e il gomito sotto la spalla.", "Sovrapponi i piedi e solleva i fianchi da terra.", "Tieni il corpo in un'unica linea retta dalla testa ai talloni.", "Tieni 15 secondi, cambia lato e fai 2 serie per lato."], ["Lasciar scendere i fianchi verso il pavimento.", "Ruotare il petto in avanti verso il pavimento."], "Tieni il ginocchio di sotto a terra per renderlo più facile."),
    "pt": ExerciseGuide(["Deite de lado com o antebraço no chão e o cotovelo sob o ombro.", "Empilhe os pés e levante o quadril do chão.", "Mantenha o corpo em uma linha reta da cabeça aos calcanhares.", "Segure 15 segundos, troque de lado e faça 2 séries de cada lado."], ["Deixar o quadril cair em direção ao chão.", "Girar o peito para a frente em direção ao chão."], "Mantenha o joelho de baixo no chão para facilitar."),
    "hi": ExerciseGuide(["करवट लेटो, अग्रबाहु ज़मीन पर हो और कोहनी कंधे के नीचे हो।", "पैरों को एक के ऊपर एक रखो और कूल्हे ज़मीन से उठाओ।", "शरीर को सिर से एड़ियों तक एक सीधी रेखा में रखो।", "15 सेकंड रुको, तरफ़ बदलो और हर तरफ़ 2 सेट करो।"], ["कूल्हों को ज़मीन की ओर गिरने देना।", "सीने को आगे ज़मीन की ओर घुमा देना।"], "आसान बनाने के लिए नीचे वाला घुटना ज़मीन पर टिका रखो।"),
    "nl": ExerciseGuide(["Lig op je zij met je onderarm op de vloer en je elleboog onder je schouder.", "Zet je voeten op elkaar en til je heupen van de vloer.", "Houd je lichaam in één rechte lijn van hoofd tot hielen.", "Houd 15 seconden vast, wissel van kant en doe 2 sets per kant."], ["Je heupen naar de vloer laten zakken.", "Je borst naar voren richting de vloer laten rollen."], "Houd je onderste knie op de vloer om het makkelijker te maken."),
    "pl": ExerciseGuide(["Połóż się na boku, przedramię na podłodze, łokieć pod barkiem.", "Ułóż stopy jedna na drugiej i unieś biodra znad podłogi.", "Trzymaj ciało w jednej prostej linii od głowy do pięt.", "Wytrzymaj 15 sekund, zmień stronę i wykonaj 2 serie na każdą stronę."], ["Opadanie bioder w stronę podłogi.", "Przekręcanie klatki piersiowej do przodu w stronę podłogi."], "Zostaw dolne kolano na podłodze, by było łatwiej."),
    "sv": ExerciseGuide(["Ligg på sidan med underarmen i golvet och armbågen under axeln.", "Lägg fötterna ovanpå varandra och lyft höfterna från golvet.", "Håll kroppen i en rak linje från huvud till hälar.", "Håll i 15 sekunder, byt sida och gör 2 set på varje sida."], ["Att låta höfterna sjunka mot golvet.", "Att rulla bröstet framåt mot golvet."], "Ha det nedre knät i golvet för att göra det lättare."),
  },
  "wall_sit": {
    "en": ExerciseGuide(["Stand with your back against a wall and your feet a step in front of you.", "Slide down until your thighs are level with the floor.", "Keep your knees above your ankles and your whole back on the wall.", "Hold 20 seconds and stand up, 3 sets in total."], ["Resting the hands on the thighs.", "Letting the knees drift forward past the toes."], "Sit a little higher if your knees complain, and go lower as you get stronger."),
    "tr": ExerciseGuide(["Sırtını duvara yasla, ayaklarını bir adım öne al.", "Uylukların yere paralel olana kadar aşağı kay.", "Dizlerini bileklerinin üstünde, sırtının tamamını duvarda tut.", "20 saniye tut ve ayağa kalk, toplam 3 set yap."], ["Elleri uylukların üstüne dayamak.", "Dizlerin öne kayıp ayak parmaklarını geçmesi."], "Dizlerin zorlanıyorsa biraz daha yüksekte otur, güçlendikçe alçal."),
    "de": ExerciseGuide(["Stell dich mit dem Rücken an eine Wand, die Füße einen Schritt davor.", "Rutsch nach unten, bis die Oberschenkel waagerecht sind.", "Halte die Knie über den Knöcheln und den ganzen Rücken an der Wand.", "Halte 20 Sekunden und steh auf, insgesamt 3 Sätze."], ["Die Hände auf die Oberschenkel legen.", "Die Knie über die Zehen nach vorn wandern lassen."], "Sitz etwas höher, wenn deine Knie meckern, und geh tiefer, sobald du stärker wirst."),
    "fr": ExerciseGuide(["Place le dos contre un mur, les pieds un pas devant toi.", "Glisse vers le bas jusqu'à ce que tes cuisses soient à l'horizontale.", "Garde les genoux au-dessus des chevilles et tout le dos contre le mur.", "Tiens 20 secondes et relève-toi, 3 séries au total."], ["Poser les mains sur les cuisses.", "Laisser les genoux dépasser les orteils vers l'avant."], "Monte un peu si tes genoux protestent, et descends plus bas quand tu seras plus fort."),
    "es": ExerciseGuide(["Apoya la espalda en una pared con los pies un paso por delante.", "Baja deslizándote hasta que los muslos queden paralelos al suelo.", "Mantén las rodillas sobre los tobillos y toda la espalda en la pared.", "Aguanta 20 segundos y levántate, 3 series en total."], ["Apoyar las manos en los muslos.", "Dejar que las rodillas pasen hacia delante de las puntas de los pies."], "Sube un poco si te molestan las rodillas, y baja más cuando estés más fuerte."),
    "it": ExerciseGuide(["Stai con la schiena contro il muro e i piedi un passo davanti a te.", "Scivola giù finché le cosce sono parallele al pavimento.", "Tieni le ginocchia sopra le caviglie e tutta la schiena sul muro.", "Tieni 20 secondi e rialzati, 3 serie in totale."], ["Appoggiare le mani sulle cosce.", "Lasciare che le ginocchia vadano avanti oltre le punte dei piedi."], "Resta un po' più in alto se le ginocchia protestano e scendi di più man mano che diventi più forte."),
    "pt": ExerciseGuide(["Fique com as costas na parede e os pés um passo à sua frente.", "Deslize para baixo até as coxas ficarem paralelas ao chão.", "Mantenha os joelhos acima dos tornozelos e as costas inteiras na parede.", "Segure 20 segundos e levante, 3 séries no total."], ["Apoiar as mãos nas coxas.", "Deixar os joelhos irem para a frente além dos dedos dos pés."], "Fique um pouco mais alto se os joelhos reclamarem e desça mais conforme ficar mais forte."),
    "hi": ExerciseGuide(["पीठ को दीवार से लगाकर खड़े हो जाओ, पैर अपने से एक कदम आगे हों।", "नीचे सरको जब तक जांघें ज़मीन के बराबर न आ जाएँ।", "घुटने टखनों के ठीक ऊपर रखो और पूरी पीठ दीवार पर रखो।", "20 सेकंड रुको और खड़े हो जाओ, कुल 3 सेट।"], ["हाथों को जांघों पर टिका देना।", "घुटनों को पंजों से आगे निकलने देना।"], "घुटनों में तकलीफ़ हो तो थोड़ा ऊपर बैठो, और ताक़त बढ़ने पर और नीचे जाओ।"),
    "nl": ExerciseGuide(["Sta met je rug tegen een muur en je voeten een stap voor je.", "Glijd omlaag tot je bovenbenen horizontaal zijn.", "Houd je knieën boven je enkels en je hele rug tegen de muur.", "Houd 20 seconden vast en sta op, 3 sets in totaal."], ["Je handen op je bovenbenen laten rusten.", "Je knieën voorbij je tenen laten schuiven."], "Zit iets hoger als je knieën protesteren en ga lager naarmate je sterker wordt."),
    "pl": ExerciseGuide(["Stań plecami do ściany, stopy krok przed sobą.", "Zsuwaj się w dół, aż uda będą równolegle do podłogi.", "Trzymaj kolana nad kostkami, a całe plecy na ścianie.", "Wytrzymaj 20 sekund i wstań, łącznie 3 serie."], ["Opieranie dłoni na udach.", "Wysuwanie kolan przed palce stóp."], "Usiądź trochę wyżej, jeśli kolana protestują, i schodź niżej, gdy zyskasz więcej siły."),
    "sv": ExerciseGuide(["Stå med ryggen mot en vägg och fötterna ett steg framför dig.", "Glid ner tills låren är i höjd med golvet.", "Ha knäna ovanför vristerna och hela ryggen mot väggen.", "Håll i 20 sekunder och res dig, 3 set totalt."], ["Att vila händerna på låren.", "Att låta knäna glida fram förbi tårna."], "Sitt lite högre om knäna protesterar och gå ner lägre när du blir starkare."),
  },
  "lunges": {
    "en": ExerciseGuide(["Stand tall with your feet hip-width apart.", "Take a big step forward and lower until both knees bend to about 90 degrees.", "Push through your front heel to step back to the start.", "Do 8 reps on each leg and rest, 3 sets in total."], ["Letting the front knee cave inward.", "Leaning the chest far forward over the front leg."], "Take a shorter step or hold a chair for balance until the movement feels steady."),
    "tr": ExerciseGuide(["Dik dur, ayaklarını kalça genişliğinde aç.", "Öne büyük bir adım at, iki dizin de yaklaşık 90 derece bükülene kadar alçal.", "Öndeki topuğunla yeri iterek başlangıç pozisyonuna dön.", "Her bacakla 8 tekrar yap ve dinlen, toplam 3 set."], ["Öndeki dizin içe kaçması.", "Göğsü öndeki bacağın üstüne fazla eğmek."], "Hareket oturana kadar daha kısa adım at ya da dengen için bir sandalyeye tutun."),
    "de": ExerciseGuide(["Stell dich aufrecht hin, die Füße hüftbreit.", "Mach einen großen Schritt nach vorn und senk dich, bis beide Knie etwa 90 Grad gebeugt sind.", "Drück dich über die vordere Ferse zurück in den Start.", "Mach 8 Wiederholungen pro Bein und ruh dich aus, insgesamt 3 Sätze."], ["Das vordere Knie nach innen kippen lassen.", "Den Oberkörper weit über das vordere Bein lehnen."], "Mach einen kürzeren Schritt oder halt dich an einem Stuhl fest, bis sich die Bewegung stabil anfühlt."),
    "fr": ExerciseGuide(["Tiens-toi droit, les pieds écartés largeur de hanches.", "Fais un grand pas en avant et descends jusqu'à ce que les deux genoux soient fléchis à environ 90 degrés.", "Pousse dans le talon avant pour revenir à la position de départ.", "Fais 8 répétitions sur chaque jambe et repose-toi, 3 séries au total."], ["Laisser le genou avant rentrer vers l'intérieur.", "Pencher beaucoup la poitrine vers l'avant au-dessus de la jambe avant."], "Fais un pas plus court ou tiens une chaise pour l'équilibre, jusqu'à ce que le mouvement soit stable."),
    "es": ExerciseGuide(["Ponte recto con los pies a la anchura de las caderas.", "Da un paso grande hacia delante y baja hasta que las dos rodillas formen unos 90 grados.", "Empuja con el talón de delante para volver a la posición inicial.", "Haz 8 repeticiones con cada pierna y descansa, 3 series en total."], ["Dejar que la rodilla de delante se meta hacia dentro.", "Inclinar mucho el pecho hacia delante sobre la pierna de delante."], "Da un paso más corto o agárrate a una silla para el equilibrio hasta que el movimiento te salga estable."),
    "it": ExerciseGuide(["Stai dritto con i piedi alla larghezza delle anche.", "Fai un grande passo avanti e scendi finché entrambe le ginocchia sono piegate a circa 90 gradi.", "Spingi sul tallone davanti per tornare alla posizione di partenza.", "Fai 8 ripetizioni per gamba e riposa, 3 serie in totale."], ["Far cadere verso l'interno il ginocchio davanti.", "Piegare molto il busto in avanti sopra la gamba davanti."], "Fai un passo più corto o tieniti a una sedia per l'equilibrio finché il movimento è stabile."),
    "pt": ExerciseGuide(["Fique em pé com os pés na largura do quadril.", "Dê um passo grande à frente e desça até os dois joelhos ficarem dobrados em cerca de 90 graus.", "Empurre o calcanhar da frente para voltar à posição inicial.", "Faça 8 repetições em cada perna e descanse, 3 séries no total."], ["Deixar o joelho da frente cair para dentro.", "Inclinar muito o peito para a frente sobre a perna da frente."], "Dê um passo mais curto ou segure em uma cadeira para o equilíbrio até o movimento ficar firme."),
    "hi": ExerciseGuide(["पैरों को कूल्हों की चौड़ाई में रखकर सीधे खड़े हो जाओ।", "बड़ा कदम आगे रखो और तब तक नीचे जाओ जब तक दोनों घुटने लगभग 90 डिग्री पर न मुड़ जाएँ।", "आगे वाली एड़ी से धक्का देकर शुरुआती जगह पर वापस आओ।", "हर पैर पर 8 रेप्स करो और आराम करो, कुल 3 सेट।"], ["आगे वाले घुटने को अंदर की ओर गिरने देना।", "सीने को आगे वाले पैर के ऊपर बहुत झुका देना।"], "छोटा कदम रखो या संतुलन के लिए कुर्सी पकड़ लो, जब तक हरकत स्थिर न लगे।"),
    "nl": ExerciseGuide(["Sta rechtop met je voeten op heupbreedte.", "Zet een grote stap naar voren en zak tot beide knieën ongeveer 90 graden gebogen zijn.", "Duw af door je voorste hiel en stap terug naar het begin.", "Doe 8 herhalingen per been en rust, 3 sets in totaal."], ["Je voorste knie naar binnen laten zakken.", "Met je borst ver naar voren over je voorste been leunen."], "Zet een kortere stap of houd een stoel vast voor balans totdat de beweging stabiel voelt."),
    "pl": ExerciseGuide(["Stań prosto, stopy na szerokość bioder.", "Zrób duży krok do przodu i opuść się, aż oba kolana będą ugięte pod kątem około 90 stopni.", "Odepchnij się piętą przedniej nogi i wróć do pozycji wyjściowej.", "Zrób 8 powtórzeń na każdą nogę i odpocznij, łącznie 3 serie."], ["Zapadanie się przedniego kolana do środka.", "Mocne pochylanie klatki do przodu nad przednią nogą."], "Zrób krótszy krok albo przytrzymaj się krzesła, aż ruch będzie stabilny."),
    "sv": ExerciseGuide(["Stå rak med fötterna höftbrett isär.", "Ta ett stort steg framåt och sänk dig tills båda knäna är böjda till ungefär 90 grader.", "Tryck ifrån genom den främre hälen och kliv tillbaka till start.", "Gör 8 upprepningar på varje ben och vila, 3 set totalt."], ["Att låta det främre knät falla inåt.", "Att luta bröstet långt framåt över det främre benet."], "Ta ett kortare steg eller håll i en stol för balans tills rörelsen känns stabil."),
  },
  "step_ups": {
    "en": ExerciseGuide(["Stand in front of a step or a sturdy low bench.", "Place one whole foot on the step and push up until you stand tall.", "Lower the other foot back to the floor slowly.", "Do 8 reps on each leg and rest, 3 sets in total."], ["Pushing off hard with the foot on the floor.", "Dropping down fast instead of lowering with control."], "Use a step that cannot slide or tip, and start low before you go higher."),
    "tr": ExerciseGuide(["Bir basamağın ya da sağlam, alçak bir bankın önünde dur.", "Bir ayağının tamamını basamağa koy ve dik durana kadar yüksel.", "Diğer ayağını yavaşça yere geri indir.", "Her bacakla 8 tekrar yap ve dinlen, toplam 3 set."], ["Yerdeki ayakla güçlüce itmek.", "Kontrollü inmek yerine hızla düşmek."], "Kaymayan ve devrilmeyen bir basamak kullan, yükseltmeden önce alçak bir basamakla başla."),
    "de": ExerciseGuide(["Stell dich vor eine Stufe oder eine stabile, niedrige Bank.", "Setz einen Fuß ganz auf die Stufe und drück dich hoch, bis du aufrecht stehst.", "Setz den anderen Fuß langsam wieder auf den Boden.", "Mach 8 Wiederholungen pro Bein und ruh dich aus, insgesamt 3 Sätze."], ["Sich mit dem Fuß am Boden kräftig abstoßen.", "Schnell nach unten fallen, statt kontrolliert abzusenken."], "Nimm eine Stufe, die nicht rutschen oder kippen kann, und fang niedrig an, bevor du höher gehst."),
    "fr": ExerciseGuide(["Place-toi devant une marche ou un banc bas et solide.", "Pose un pied entier sur la marche et pousse jusqu'à être debout, bien droit.", "Redescends l'autre pied au sol lentement.", "Fais 8 répétitions sur chaque jambe et repose-toi, 3 séries au total."], ["Se pousser fort avec le pied resté au sol.", "Se laisser tomber vite au lieu de descendre avec contrôle."], "Prends une marche qui ne peut ni glisser ni basculer, et commence bas avant de monter plus haut."),
    "es": ExerciseGuide(["Ponte frente a un escalón o un banco bajo y resistente.", "Apoya un pie entero en el escalón y empuja hasta quedar de pie, recto.", "Baja el otro pie al suelo despacio.", "Haz 8 repeticiones con cada pierna y descansa, 3 series en total."], ["Impulsarte fuerte con el pie que queda en el suelo.", "Dejarte caer rápido en vez de bajar con control."], "Usa un escalón que no pueda deslizarse ni volcar, y empieza bajo antes de pasar a uno más alto."),
    "it": ExerciseGuide(["Mettiti davanti a un gradino o a una panca bassa e stabile.", "Appoggia tutto un piede sul gradino e spingi finché sei in piedi.", "Riporta l'altro piede a terra lentamente.", "Fai 8 ripetizioni per gamba e riposa, 3 serie in totale."], ["Spingere forte con il piede rimasto a terra.", "Lasciarsi cadere in fretta invece di scendere con controllo."], "Usa un gradino che non scivola né si ribalta e parti basso prima di salire di altezza."),
    "pt": ExerciseGuide(["Fique em frente a um degrau ou a um banco baixo e firme.", "Apoie o pé inteiro no degrau e empurre até ficar em pé.", "Desça o outro pé de volta ao chão devagar.", "Faça 8 repetições em cada perna e descanse, 3 séries no total."], ["Empurrar forte com o pé que ficou no chão.", "Despencar rápido em vez de descer com controle."], "Use um degrau que não deslize nem tombe e comece baixo antes de ir para um mais alto."),
    "hi": ExerciseGuide(["स्टेप या मज़बूत नीची बेंच के सामने खड़े हो जाओ।", "एक पूरा पैर स्टेप पर रखो और ऊपर धकेलकर सीधे खड़े हो जाओ।", "दूसरे पैर को धीरे वापस ज़मीन पर उतारो।", "हर पैर पर 8 रेप्स करो और आराम करो, कुल 3 सेट।"], ["ज़मीन पर बचे पैर से ज़ोर से धक्का देना।", "काबू से उतरने की जगह तेज़ी से नीचे गिर जाना।"], "ऐसा स्टेप लो जो फिसले या पलटे नहीं, और ऊँचे पर जाने से पहले नीचे से शुरू करो।"),
    "nl": ExerciseGuide(["Ga voor een opstapje of een stevige lage bank staan.", "Zet een hele voet op de verhoging en duw jezelf omhoog tot je rechtop staat.", "Zet de andere voet langzaam terug op de vloer.", "Doe 8 herhalingen per been en rust, 3 sets in totaal."], ["Hard afduwen met de voet die op de vloer staat.", "Snel naar beneden vallen in plaats van gecontroleerd zakken."], "Gebruik een opstapje dat niet kan glijden of kantelen en begin laag voordat je hoger gaat."),
    "pl": ExerciseGuide(["Stań przed schodkiem lub stabilną niską ławką.", "Postaw całą jedną stopę na podwyższeniu i wepchnij się w górę, aż staniesz prosto.", "Powoli opuść drugą stopę z powrotem na podłogę.", "Zrób 8 powtórzeń na każdą nogę i odpocznij, łącznie 3 serie."], ["Mocne odpychanie się stopą stojącą na podłodze.", "Szybkie opadanie zamiast kontrolowanego opuszczania."], "Użyj schodka, który się nie ślizga i nie przechyla, i zacznij od niskiego, zanim wejdziesz wyżej."),
    "sv": ExerciseGuide(["Ställ dig framför ett steg eller en stadig låg bänk.", "Sätt hela ena foten på steget och tryck upp tills du står rak.", "Sänk den andra foten långsamt tillbaka till golvet.", "Gör 8 upprepningar på varje ben och vila, 3 set totalt."], ["Att trycka ifrån hårt med foten som står på golvet.", "Att släppa sig ner snabbt i stället för att sänka sig under kontroll."], "Använd ett steg som inte kan glida eller tippa och börja lågt innan du går högre."),
  },
  "push_ups": {
    "en": ExerciseGuide(["Place your hands on the floor slightly wider than your shoulders.", "Step your feet back so your body forms one straight line.", "Bend your elbows to lower your chest to the floor, then push back up.", "Do 5 reps and rest, 3 sets in total."], ["Letting the hips sag toward the floor.", "Flaring the elbows straight out to the sides."], "Drop to your knees or put your hands on a bench to make it easier."),
    "tr": ExerciseGuide(["Ellerini omuzlarından biraz geniş şekilde yere koy.", "Ayaklarını geriye at, vücudun tek düz bir çizgi oluştursun.", "Dirseklerini bükerek göğsünü yere indir, sonra kendini geri it.", "5 tekrar yap ve dinlen, toplam 3 set."], ["Kalçanın yere doğru sarkması.", "Dirsekleri dümdüz yanlara açmak."], "Kolaylaştırmak için dizlerinin üstüne in ya da ellerini bir banka koy."),
    "de": ExerciseGuide(["Setz die Hände etwas weiter als schulterbreit auf den Boden.", "Geh mit den Füßen zurück, sodass dein Körper eine gerade Linie bildet.", "Beug die Ellbogen, senk die Brust zum Boden und drück dich wieder hoch.", "Mach 5 Wiederholungen und ruh dich aus, insgesamt 3 Sätze."], ["Die Hüfte zum Boden durchhängen lassen.", "Die Ellbogen gerade nach außen abspreizen."], "Geh auf die Knie oder stütz die Hände auf eine Bank, um es leichter zu machen."),
    "fr": ExerciseGuide(["Pose les mains au sol, un peu plus larges que les épaules.", "Recule les pieds pour que ton corps forme une seule ligne droite.", "Fléchis les coudes pour descendre la poitrine vers le sol, puis repousse.", "Fais 5 répétitions et repose-toi, 3 séries au total."], ["Laisser les hanches s'affaisser vers le sol.", "Écarter les coudes droit sur les côtés."], "Mets-toi à genoux ou pose les mains sur un banc pour rendre l'exercice plus facile."),
    "es": ExerciseGuide(["Apoya las manos en el suelo, un poco más abiertas que los hombros.", "Lleva los pies hacia atrás para que el cuerpo forme una línea recta.", "Flexiona los codos para bajar el pecho al suelo y empuja para subir.", "Haz 5 repeticiones y descansa, 3 series en total."], ["Dejar que las caderas se hundan hacia el suelo.", "Abrir los codos directamente hacia los lados."], "Apoya las rodillas o pon las manos en un banco para hacerlo más fácil."),
    "it": ExerciseGuide(["Appoggia le mani a terra un po' più larghe delle spalle.", "Porta i piedi indietro in modo che il corpo formi un'unica linea retta.", "Piega i gomiti per abbassare il petto verso il pavimento, poi spingi su.", "Fai 5 ripetizioni e riposa, 3 serie in totale."], ["Lasciar cedere i fianchi verso il pavimento.", "Aprire i gomiti dritti ai lati."], "Appoggia le ginocchia a terra o le mani su una panca per renderlo più facile."),
    "pt": ExerciseGuide(["Apoie as mãos no chão um pouco mais abertas que os ombros.", "Leve os pés para trás para o corpo formar uma linha reta.", "Dobre os cotovelos para abaixar o peito até o chão e depois empurre para subir.", "Faça 5 repetições e descanse, 3 séries no total."], ["Deixar o quadril cair em direção ao chão.", "Abrir os cotovelos retos para os lados."], "Apoie os joelhos no chão ou as mãos em um banco para facilitar."),
    "hi": ExerciseGuide(["हाथों को ज़मीन पर कंधों से थोड़ा चौड़ा रखो।", "पैरों को पीछे ले जाओ ताकि शरीर एक सीधी रेखा बने।", "कोहनियाँ मोड़कर सीने को ज़मीन की ओर लाओ, फिर ऊपर धकेलो।", "5 रेप्स करो और आराम करो, कुल 3 सेट।"], ["कूल्हों को ज़मीन की ओर झुकने देना।", "कोहनियों को सीधे बगल में फैला देना।"], "आसान बनाने के लिए घुटनों पर आ जाओ या हाथ बेंच पर रख लो।"),
    "nl": ExerciseGuide(["Zet je handen iets breder dan je schouders op de vloer.", "Stap met je voeten naar achteren zodat je lichaam één rechte lijn vormt.", "Buig je ellebogen om je borst naar de vloer te laten zakken en duw jezelf weer omhoog.", "Doe 5 herhalingen en rust, 3 sets in totaal."], ["Je heupen naar de vloer laten zakken.", "Je ellebogen recht naar de zijkant laten wijken."], "Ga op je knieën of zet je handen op een bank om het makkelijker te maken."),
    "pl": ExerciseGuide(["Połóż dłonie na podłodze nieco szerzej niż barki.", "Cofnij stopy, aby ciało tworzyło jedną prostą linię.", "Ugnij łokcie, by opuścić klatkę ku podłodze, potem wypchnij się w górę.", "Zrób 5 powtórzeń i odpocznij, łącznie 3 serie."], ["Opadanie bioder w stronę podłogi.", "Rozstawianie łokci prosto na boki."], "Oprzyj się na kolanach albo połóż dłonie na ławce, by było łatwiej."),
    "sv": ExerciseGuide(["Placera händerna i golvet något bredare än axlarna.", "Kliv bakåt med fötterna så att kroppen bildar en rak linje.", "Böj armbågarna för att sänka bröstet mot golvet och tryck sedan upp igen.", "Gör 5 upprepningar och vila, 3 set totalt."], ["Att låta höfterna sjunka mot golvet.", "Att sprida armbågarna rakt ut åt sidorna."], "Gå ner på knä eller ha händerna på en bänk för att göra det lättare."),
  },
  "single_leg_calf_raise": {
    "en": ExerciseGuide(["Stand on the edge of a step on the ball of one foot and hold a wall or rail.", "Lower your heel slowly below the level of the step.", "Rise as high as you can onto your toes and pause for a second.", "Do 8 reps on each leg and rest, 3 sets in total."], ["Bouncing out of the bottom instead of moving slowly.", "Bending the knee to help the calf."], "Start with body weight, and if you add a dumbbell or backpack, pick a weight light enough to finish every rep with good form."),
    "tr": ExerciseGuide(["Basamağın kenarında tek ayağının ön kısmıyla dur, duvara ya da korkuluğa tutun.", "Topuğunu yavaşça basamak seviyesinin altına indir.", "Parmak ucunda çıkabildiğin kadar yüksel ve bir saniye dur.", "Her bacakla 8 tekrar yap ve dinlen, toplam 3 set."], ["Yavaş hareket etmek yerine alttan yaylanarak çıkmak.", "Baldıra yardım için dizi bükmek."], "Kendi vücut ağırlığınla başla, dambıl ya da sırt çantası eklersen her tekrarı düzgün formla bitirebileceğin kadar hafif bir ağırlık seç."),
    "de": ExerciseGuide(["Stell dich mit dem Ballen eines Fußes an die Kante einer Stufe und halt dich an einer Wand oder einem Geländer fest.", "Senk die Ferse langsam unter die Stufenhöhe.", "Komm so hoch du kannst auf die Zehenspitzen und halte eine Sekunde.", "Mach 8 Wiederholungen pro Bein und ruh dich aus, insgesamt 3 Sätze."], ["Unten wippen, statt dich langsam zu bewegen.", "Das Knie beugen, um der Wade zu helfen."], "Starte mit dem Körpergewicht, und wenn du eine Hantel oder einen Rucksack nimmst, wähl ein Gewicht, bei dem du jede Wiederholung sauber schaffst."),
    "fr": ExerciseGuide(["Place l'avant d'un pied au bord d'une marche et tiens-toi à un mur ou à une rampe.", "Descends lentement le talon sous le niveau de la marche.", "Monte aussi haut que possible sur la pointe du pied et marque une pause d'une seconde.", "Fais 8 répétitions sur chaque jambe et repose-toi, 3 séries au total."], ["Rebondir en bas au lieu de bouger lentement.", "Fléchir le genou pour aider le mollet."], "Commence avec le poids du corps, et si tu ajoutes un haltère ou un sac à dos, choisis une charge qui te permet de finir chaque répétition proprement."),
    "es": ExerciseGuide(["Ponte en el borde de un escalón sobre la parte delantera de un pie y agárrate a una pared o barandilla.", "Baja el talón despacio por debajo del nivel del escalón.", "Sube lo más alto que puedas de puntillas y haz una pausa de un segundo.", "Haz 8 repeticiones con cada pierna y descansa, 3 series en total."], ["Rebotar abajo en vez de moverte despacio.", "Flexionar la rodilla para ayudar a la pantorrilla."], "Empieza con el peso del cuerpo, y si añades una mancuerna o una mochila, elige un peso con el que puedas terminar cada repetición con buena técnica."),
    "it": ExerciseGuide(["Stai sul bordo di un gradino sull'avampiede di una gamba e tieniti a un muro o a una ringhiera.", "Abbassa il tallone lentamente sotto il livello del gradino.", "Sali più in alto che puoi sulle punte e resta fermo un secondo.", "Fai 8 ripetizioni per gamba e riposa, 3 serie in totale."], ["Rimbalzare dalla posizione bassa invece di muoverti piano.", "Piegare il ginocchio per aiutare il polpaccio."], "Parti a corpo libero e, se aggiungi un manubrio o uno zaino, scegli un peso abbastanza leggero da finire ogni ripetizione con una buona tecnica."),
    "pt": ExerciseGuide(["Fique na borda de um degrau na ponta de um pé e segure em uma parede ou corrimão.", "Abaixe o calcanhar devagar abaixo do nível do degrau.", "Suba o mais alto que puder na ponta do pé e segure um segundo.", "Faça 8 repetições em cada perna e descanse, 3 séries no total."], ["Quicar na parte de baixo em vez de se mover devagar.", "Dobrar o joelho para ajudar a panturrilha."], "Comece com o peso do corpo e, se usar um halter ou uma mochila, escolha um peso leve o bastante para terminar cada repetição com boa técnica."),
    "hi": ExerciseGuide(["स्टेप के किनारे पर एक पैर के पंजे पर खड़े हो जाओ और दीवार या रेलिंग पकड़ लो।", "एड़ी को धीरे स्टेप के स्तर से नीचे ले जाओ।", "जितना हो सके पंजों पर ऊपर उठो और एक सेकंड रुको।", "हर पैर पर 8 रेप्स करो और आराम करो, कुल 3 सेट।"], ["धीरे चलने की जगह नीचे से उछलकर ऊपर आना।", "पिंडली की मदद के लिए घुटना मोड़ना।"], "शरीर के वज़न से शुरू करो, और डंबल या बैगपैक जोड़ो तो इतना हल्का वज़न चुनो कि हर रेप सही फ़ॉर्म में पूरी हो।"),
    "nl": ExerciseGuide(["Sta op de rand van een trede op de bal van één voet en houd een muur of leuning vast.", "Laat je hiel langzaam onder het niveau van de trede zakken.", "Kom zo hoog mogelijk op je tenen en pauzeer een seconde.", "Doe 8 herhalingen per been en rust, 3 sets in totaal."], ["Uit de onderste stand veren in plaats van langzaam te bewegen.", "Je knie buigen om je kuit te helpen."], "Begin met je lichaamsgewicht en kies, als je een dumbbell of rugzak toevoegt, een gewicht dat licht genoeg is om elke herhaling netjes af te maken."),
    "pl": ExerciseGuide(["Stań przodostopiem jednej stopy na krawędzi schodka i przytrzymaj się ściany lub poręczy.", "Powoli opuść piętę poniżej poziomu schodka.", "Unieś się jak najwyżej na palce i zatrzymaj się na sekundę.", "Zrób 8 powtórzeń na każdą nogę i odpocznij, łącznie 3 serie."], ["Odbijanie się z dolnej pozycji zamiast powolnego ruchu.", "Uginanie kolana, by pomóc łydce."], "Zacznij z masą własnego ciała, a jeśli dodasz hantlę lub plecak, wybierz ciężar na tyle lekki, by każde powtórzenie zrobić poprawnie."),
    "sv": ExerciseGuide(["Stå på kanten av ett steg med framfoten på ena foten och håll i en vägg eller ett räcke.", "Sänk hälen långsamt under stegets nivå.", "Res dig så högt du kan upp på tå och pausa en sekund.", "Gör 8 upprepningar på varje ben och vila, 3 set totalt."], ["Att studsa upp ur det nedre läget i stället för att röra sig långsamt.", "Att böja knät för att hjälpa vaden."], "Börja med kroppsvikt, och om du lägger till en hantel eller en ryggsäck, välj en vikt som är lätt nog för att klara varje upprepning med bra teknik."),
  },
  "goblet_squat": {
    "en": ExerciseGuide(["Hold one dumbbell or a loaded backpack against your chest with both hands.", "Stand with your feet shoulder-width apart and your toes turned out a little.", "Sit down between your heels with your chest up, then stand back up.", "Do 8 reps and rest, 3 sets in total."], ["Letting the knees cave inward.", "Rounding the back and letting the chest drop."], "Pick a weight light enough to finish every rep with good form."),
    "tr": ExerciseGuide(["Bir dambılı ya da dolu bir sırt çantasını iki elinle göğsüne yasla.", "Ayaklarını omuz genişliğinde aç, parmak uçlarını hafif dışa çevir.", "Göğsün dikken topuklarının arasına doğru çök, sonra ayağa kalk.", "8 tekrar yap ve dinlen, toplam 3 set."], ["Dizlerin içe kaçması.", "Sırtı yuvarlayıp göğsü düşürmek."], "Her tekrarı düzgün formla bitirebileceğin kadar hafif bir ağırlık seç."),
    "de": ExerciseGuide(["Halt eine Hantel oder einen beladenen Rucksack mit beiden Händen vor der Brust.", "Stell dich schulterbreit hin, die Zehen leicht nach außen gedreht.", "Setz dich zwischen die Fersen, die Brust bleibt oben, und steh wieder auf.", "Mach 8 Wiederholungen und ruh dich aus, insgesamt 3 Sätze."], ["Die Knie nach innen kippen lassen.", "Den Rücken rund machen und die Brust sinken lassen."], "Wähl ein Gewicht, bei dem du jede Wiederholung sauber schaffst."),
    "fr": ExerciseGuide(["Tiens un haltère ou un sac à dos chargé contre ta poitrine, à deux mains.", "Place les pieds écartés largeur d'épaules, les pointes un peu ouvertes.", "Descends entre tes talons en gardant la poitrine haute, puis remonte.", "Fais 8 répétitions et repose-toi, 3 séries au total."], ["Laisser les genoux rentrer vers l'intérieur.", "Arrondir le dos et laisser la poitrine tomber."], "Choisis une charge qui te permet de finir chaque répétition proprement."),
    "es": ExerciseGuide(["Sujeta una mancuerna o una mochila con peso contra el pecho con las dos manos.", "Ponte con los pies a la anchura de los hombros y las puntas un poco hacia fuera.", "Siéntate entre los talones con el pecho alto y vuelve a subir.", "Haz 8 repeticiones y descansa, 3 series en total."], ["Dejar que las rodillas se metan hacia dentro.", "Redondear la espalda y dejar caer el pecho."], "Elige un peso con el que puedas terminar cada repetición con buena técnica."),
    "it": ExerciseGuide(["Tieni un manubrio o uno zaino carico contro il petto con entrambe le mani.", "Stai con i piedi alla larghezza delle spalle e le punte un po' aperte.", "Siediti in mezzo ai talloni con il petto alto, poi rialzati.", "Fai 8 ripetizioni e riposa, 3 serie in totale."], ["Far cadere le ginocchia verso l'interno.", "Arrotondare la schiena e far cadere il petto."], "Scegli un peso abbastanza leggero da finire ogni ripetizione con una buona tecnica."),
    "pt": ExerciseGuide(["Segure um halter ou uma mochila com peso junto ao peito, com as duas mãos.", "Fique com os pés na largura dos ombros e os dedos levemente para fora.", "Sente entre os calcanhares com o peito aberto e depois levante.", "Faça 8 repetições e descanse, 3 séries no total."], ["Deixar os joelhos caírem para dentro.", "Arredondar as costas e deixar o peito cair."], "Escolha um peso leve o bastante para terminar cada repetição com boa técnica."),
    "hi": ExerciseGuide(["एक डंबल या भरा हुआ बैगपैक दोनों हाथों से सीने से सटाकर पकड़ो।", "पैरों को कंधों की चौड़ाई में रखो और पंजे थोड़े बाहर की ओर रखो।", "सीना ऊपर रखकर एड़ियों के बीच बैठो, फिर खड़े हो जाओ।", "8 रेप्स करो और आराम करो, कुल 3 सेट।"], ["घुटनों को अंदर की ओर गिरने देना।", "पीठ को गोल करना और सीने को झुका देना।"], "इतना हल्का वज़न चुनो कि हर रेप सही फ़ॉर्म में पूरी हो।"),
    "nl": ExerciseGuide(["Houd één dumbbell of een volle rugzak met beide handen tegen je borst.", "Sta met je voeten op schouderbreedte en je tenen een beetje naar buiten gedraaid.", "Zak tussen je hielen door met je borst omhoog en kom dan weer omhoog.", "Doe 8 herhalingen en rust, 3 sets in totaal."], ["Je knieën naar binnen laten zakken.", "Je rug ronden en je borst laten zakken."], "Kies een gewicht dat licht genoeg is om elke herhaling netjes af te maken."),
    "pl": ExerciseGuide(["Trzymaj jedną hantlę lub załadowany plecak obiema rękami przy klatce.", "Stań w rozkroku na szerokość barków, palce stóp lekko na zewnątrz.", "Usiądź między piętami z uniesioną klatką, potem wstań.", "Zrób 8 powtórzeń i odpocznij, łącznie 3 serie."], ["Zapadanie się kolan do środka.", "Zaokrąglanie pleców i opadanie klatki."], "Wybierz ciężar na tyle lekki, by każde powtórzenie zrobić poprawnie."),
    "sv": ExerciseGuide(["Håll en hantel eller en lastad ryggsäck mot bröstet med båda händerna.", "Stå med fötterna axelbrett isär och tårna lätt utåt.", "Sjunk ner mellan hälarna med bröstet uppe och res dig sedan upp igen.", "Gör 8 upprepningar och vila, 3 set totalt."], ["Att låta knäna falla inåt.", "Att runda ryggen och låta bröstet sjunka."], "Välj en vikt som är lätt nog för att klara varje upprepning med bra teknik."),
  },
  "dumbbell_deadlift": {
    "en": ExerciseGuide(["Stand tall with a dumbbell in each hand in front of your thighs.", "Soften your knees and push your hips back with a flat back.", "Slide the weights down your thighs to just below your knees.", "Squeeze your glutes to stand up, do 8 reps, 3 sets in total."], ["Rounding the back as the weights go down.", "Turning it into a squat by bending the knees a lot."], "Pick a weight light enough to finish every rep with good form."),
    "tr": ExerciseGuide(["Dik dur, iki elinde birer dambıl uyluklarının önünde olsun.", "Dizlerini hafif gevşet, sırtın düzken kalçanı geriye it.", "Ağırlıkları uyluklarından dizlerinin hemen altına kadar kaydır.", "Kalçanı sıkarak doğrul, 8 tekrar yap, toplam 3 set."], ["Ağırlıklar inerken sırtı yuvarlamak.", "Dizleri fazla bükerek hareketi squata çevirmek."], "Her tekrarı düzgün formla bitirebileceğin kadar hafif bir ağırlık seç."),
    "de": ExerciseGuide(["Stell dich aufrecht hin, in jeder Hand eine Hantel vor den Oberschenkeln.", "Beug die Knie leicht und schieb die Hüfte mit geradem Rücken nach hinten.", "Lass die Gewichte an den Oberschenkeln entlang bis knapp unter die Knie gleiten.", "Spann das Gesäß an und richte dich auf, mach 8 Wiederholungen, insgesamt 3 Sätze."], ["Den Rücken rund machen, wenn die Gewichte nach unten gehen.", "Eine Kniebeuge daraus machen, indem die Knie stark gebeugt werden."], "Wähl ein Gewicht, bei dem du jede Wiederholung sauber schaffst."),
    "fr": ExerciseGuide(["Tiens-toi droit avec un haltère dans chaque main devant les cuisses.", "Assouplis les genoux et recule les fesses, dos plat.", "Fais glisser les haltères le long des cuisses jusque juste sous les genoux.", "Serre les fessiers pour te redresser, fais 8 répétitions, 3 séries au total."], ["Arrondir le dos quand les haltères descendent.", "En faire un squat en fléchissant beaucoup les genoux."], "Choisis une charge qui te permet de finir chaque répétition proprement."),
    "es": ExerciseGuide(["Ponte recto con una mancuerna en cada mano delante de los muslos.", "Afloja las rodillas y echa las caderas hacia atrás con la espalda plana.", "Desliza las mancuernas por los muslos hasta justo debajo de las rodillas.", "Aprieta los glúteos para subir, haz 8 repeticiones, 3 series en total."], ["Redondear la espalda al bajar las mancuernas.", "Convertirlo en una sentadilla flexionando mucho las rodillas."], "Elige un peso con el que puedas terminar cada repetición con buena técnica."),
    "it": ExerciseGuide(["Stai dritto con un manubrio per mano davanti alle cosce.", "Sciogli le ginocchia e spingi i fianchi all'indietro con la schiena piatta.", "Fai scivolare i pesi lungo le cosce fin appena sotto le ginocchia.", "Contrai i glutei per rialzarti, fai 8 ripetizioni, 3 serie in totale."], ["Arrotondare la schiena mentre i pesi scendono.", "Trasformarlo in uno squat piegando molto le ginocchia."], "Scegli un peso abbastanza leggero da finire ogni ripetizione con una buona tecnica."),
    "pt": ExerciseGuide(["Fique em pé com um halter em cada mão à frente das coxas.", "Solte os joelhos e leve o quadril para trás com as costas retas.", "Deslize os pesos pelas coxas até um pouco abaixo dos joelhos.", "Contraia os glúteos para levantar, faça 8 repetições, 3 séries no total."], ["Arredondar as costas enquanto os pesos descem.", "Transformar em agachamento dobrando muito os joelhos."], "Escolha um peso leve o bastante para terminar cada repetição com boa técnica."),
    "hi": ExerciseGuide(["सीधे खड़े हो जाओ, हर हाथ में एक डंबल जांघों के आगे हो।", "घुटने ढीले करो और पीठ सपाट रखकर कूल्हों को पीछे धकेलो।", "वज़न को जांघों के साथ घुटनों के ठीक नीचे तक सरकाओ।", "नितंबों को भींचकर खड़े हो जाओ, 8 रेप्स करो, कुल 3 सेट।"], ["वज़न नीचे जाते समय पीठ को गोल करना।", "घुटने बहुत मोड़कर इसे स्क्वाट बना देना।"], "इतना हल्का वज़न चुनो कि हर रेप सही फ़ॉर्म में पूरी हो।"),
    "nl": ExerciseGuide(["Sta rechtop met een dumbbell in elke hand voor je bovenbenen.", "Buig je knieën licht en duw je heupen naar achteren met een platte rug.", "Laat de gewichten langs je bovenbenen zakken tot net onder je knieën.", "Span je billen aan om op te staan, doe 8 herhalingen, 3 sets in totaal."], ["Je rug ronden terwijl de gewichten zakken.", "Er een squat van maken door je knieën veel te buigen."], "Kies een gewicht dat licht genoeg is om elke herhaling netjes af te maken."),
    "pl": ExerciseGuide(["Stań prosto z hantlą w każdej ręce przed udami.", "Lekko ugnij kolana i odsuń biodra w tył, z płaskimi plecami.", "Zsuwaj hantle po udach do miejsca tuż poniżej kolan.", "Napnij pośladki, by wstać, zrób 8 powtórzeń, łącznie 3 serie."], ["Zaokrąglanie pleców podczas opuszczania ciężaru.", "Zamienianie ruchu w przysiad przez mocne uginanie kolan."], "Wybierz ciężar na tyle lekki, by każde powtórzenie zrobić poprawnie."),
    "sv": ExerciseGuide(["Stå rak med en hantel i varje hand framför låren.", "Mjuka upp knäna och skjut höfterna bakåt med rak rygg.", "Låt hantlarna glida nedför låren till strax under knäna.", "Kläm ihop sätet för att resa dig, gör 8 upprepningar, 3 set totalt."], ["Att runda ryggen när vikterna går ner.", "Att göra om det till en knäböj genom att böja knäna mycket."], "Välj en vikt som är lätt nog för att klara varje upprepning med bra teknik."),
  },
  "dumbbell_row": {
    "en": ExerciseGuide(["Place one hand on a bench or chair and step your feet back.", "Hold a dumbbell in the other hand with your back flat and your arm hanging down.", "Pull the weight to your hip with your elbow close, then lower it slowly.", "Do 8 reps on each side and rest, 3 sets in total."], ["Twisting the body to heave the weight up.", "Shrugging the shoulder toward the ear."], "Pick a weight light enough to finish every rep with good form."),
    "tr": ExerciseGuide(["Bir elini bir banka ya da sandalyeye koy, ayaklarını geriye al.", "Diğer elinde dambıl tut, sırtın düz, kolun aşağı sarkık olsun.", "Dirseğin vücuduna yakınken ağırlığı kalçana çek, sonra yavaşça indir.", "Her tarafta 8 tekrar yap ve dinlen, toplam 3 set."], ["Ağırlığı kaldırmak için gövdeyi döndürmek.", "Omzu kulağa doğru kaldırmak."], "Her tekrarı düzgün formla bitirebileceğin kadar hafif bir ağırlık seç."),
    "de": ExerciseGuide(["Stütz eine Hand auf eine Bank oder einen Stuhl und geh mit den Füßen zurück.", "Halte in der anderen Hand eine Hantel, der Rücken ist flach und der Arm hängt nach unten.", "Zieh das Gewicht mit eng geführtem Ellbogen zur Hüfte und senk es langsam ab.", "Mach 8 Wiederholungen pro Seite und ruh dich aus, insgesamt 3 Sätze."], ["Den Körper verdrehen, um das Gewicht hochzuwuchten.", "Die Schulter zum Ohr hochziehen."], "Wähl ein Gewicht, bei dem du jede Wiederholung sauber schaffst."),
    "fr": ExerciseGuide(["Pose une main sur un banc ou une chaise et recule les pieds.", "Tiens un haltère dans l'autre main, le dos plat et le bras pendant vers le sol.", "Tire la charge vers la hanche, le coude près du corps, puis redescends-la lentement.", "Fais 8 répétitions de chaque côté et repose-toi, 3 séries au total."], ["Tordre le corps pour soulever la charge.", "Monter l'épaule vers l'oreille."], "Choisis une charge qui te permet de finir chaque répétition proprement."),
    "es": ExerciseGuide(["Apoya una mano en un banco o una silla y lleva los pies hacia atrás.", "Sujeta una mancuerna con la otra mano, con la espalda plana y el brazo colgando hacia abajo.", "Lleva el peso hacia la cadera con el codo pegado y bájalo despacio.", "Haz 8 repeticiones de cada lado y descansa, 3 series en total."], ["Girar el cuerpo para subir el peso de golpe.", "Subir el hombro hacia la oreja."], "Elige un peso con el que puedas terminar cada repetición con buena técnica."),
    "it": ExerciseGuide(["Appoggia una mano su una panca o su una sedia e porta i piedi indietro.", "Tieni un manubrio nell'altra mano con la schiena piatta e il braccio disteso verso il basso.", "Tira il peso verso l'anca con il gomito vicino al corpo, poi abbassalo lentamente.", "Fai 8 ripetizioni per lato e riposa, 3 serie in totale."], ["Ruotare il corpo per tirare su il peso a forza.", "Alzare la spalla verso l'orecchio."], "Scegli un peso abbastanza leggero da finire ogni ripetizione con una buona tecnica."),
    "pt": ExerciseGuide(["Apoie uma mão em um banco ou cadeira e leve os pés para trás.", "Segure um halter na outra mão, com as costas retas e o braço solto para baixo.", "Puxe o peso até o quadril com o cotovelo junto ao corpo e depois abaixe devagar.", "Faça 8 repetições de cada lado e descanse, 3 séries no total."], ["Girar o corpo para jogar o peso para cima.", "Subir o ombro em direção à orelha."], "Escolha um peso leve o bastante para terminar cada repetição com boa técnica."),
    "hi": ExerciseGuide(["एक हाथ बेंच या कुर्सी पर रखो और पैरों को पीछे ले जाओ।", "दूसरे हाथ में डंबल पकड़ो, पीठ सपाट रखो और बाँह नीचे लटकी रहे।", "कोहनी को पास रखकर वज़न को कूल्हे तक खींचो, फिर धीरे नीचे लाओ।", "हर तरफ़ 8 रेप्स करो और आराम करो, कुल 3 सेट।"], ["वज़न को ज़ोर से ऊपर फेंकने के लिए शरीर को घुमाना।", "कंधे को कान की ओर उचका लेना।"], "इतना हल्का वज़न चुनो कि हर रेप सही फ़ॉर्म में पूरी हो।"),
    "nl": ExerciseGuide(["Leg één hand op een bank of stoel en zet je voeten naar achteren.", "Houd een dumbbell in de andere hand met een platte rug en je arm naar beneden hangend.", "Trek het gewicht met je elleboog dicht bij je lichaam naar je heup en laat het langzaam zakken.", "Doe 8 herhalingen per kant en rust, 3 sets in totaal."], ["Je lichaam draaien om het gewicht omhoog te hijsen.", "Je schouder naar je oor optrekken."], "Kies een gewicht dat licht genoeg is om elke herhaling netjes af te maken."),
    "pl": ExerciseGuide(["Oprzyj jedną rękę na ławce lub krześle i cofnij stopy.", "Trzymaj hantlę w drugiej ręce, z płaskimi plecami i ramieniem zwisającym w dół.", "Przyciągnij ciężar do biodra, łokieć blisko ciała, potem opuść go powoli.", "Zrób 8 powtórzeń na każdą stronę i odpocznij, łącznie 3 serie."], ["Skręcanie ciała, by wyszarpnąć ciężar w górę.", "Unoszenie barku w stronę ucha."], "Wybierz ciężar na tyle lekki, by każde powtórzenie zrobić poprawnie."),
    "sv": ExerciseGuide(["Stötta ena handen på en bänk eller stol och kliv bakåt med fötterna.", "Håll en hantel i den andra handen med rak rygg och armen hängande rakt ner.", "Dra vikten mot höften med armbågen nära kroppen och sänk den sedan långsamt.", "Gör 8 upprepningar på varje sida och vila, 3 set totalt."], ["Att vrida kroppen för att slänga upp vikten.", "Att dra upp axeln mot örat."], "Välj en vikt som är lätt nog för att klara varje upprepning med bra teknik."),
  },
  "farmer_carry": {
    "en": ExerciseGuide(["Stand between two dumbbells or two loaded bags.", "Bend your knees, keep your back flat and pick them up.", "Walk with small steps, shoulders back and eyes forward.", "Walk for 20 seconds, set them down and rest, 3 sets in total."], ["Leaning to one side or letting the shoulders round forward.", "Rounding the back when picking up or putting down the weights."], "Pick a weight light enough to finish every set with good form, and keep both sides equal."),
    "tr": ExerciseGuide(["İki dambılın ya da iki dolu çantanın arasında dur.", "Dizlerini bük, sırtını düz tut ve ağırlıkları yerden al.", "Omuzların geride, gözlerin karşıda, küçük adımlarla yürü.", "20 saniye yürü, ağırlıkları bırak ve dinlen, toplam 3 set."], ["Bir yana yatmak ya da omuzları öne düşürmek.", "Ağırlıkları alırken ya da bırakırken sırtı yuvarlamak."], "Her seti düzgün formla bitirebileceğin kadar hafif bir ağırlık seç, iki taraf eşit olsun."),
    "de": ExerciseGuide(["Stell dich zwischen zwei Hanteln oder zwei beladene Taschen.", "Beug die Knie, halte den Rücken gerade und heb sie auf.", "Geh in kleinen Schritten, die Schultern zurück und den Blick nach vorn.", "Geh 20 Sekunden lang, stell sie ab und ruh dich aus, insgesamt 3 Sätze."], ["Zu einer Seite kippen oder die Schultern nach vorn rollen lassen.", "Beim Aufheben oder Abstellen der Gewichte den Rücken rund machen."], "Wähl ein Gewicht, bei dem du jeden Satz sauber schaffst, und halt beide Seiten gleich schwer."),
    "fr": ExerciseGuide(["Place-toi entre deux haltères ou deux sacs chargés.", "Fléchis les genoux, garde le dos plat et soulève-les.", "Marche à petits pas, les épaules en arrière et le regard devant toi.", "Marche pendant 20 secondes, repose les charges et repose-toi, 3 séries au total."], ["Pencher d'un côté ou laisser les épaules s'arrondir vers l'avant.", "Arrondir le dos en soulevant ou en reposant les charges."], "Choisis une charge qui te permet de finir chaque série proprement, et garde les deux côtés égaux."),
    "es": ExerciseGuide(["Ponte entre dos mancuernas o dos bolsas con peso.", "Flexiona las rodillas, mantén la espalda plana y levántalas.", "Camina con pasos cortos, con los hombros atrás y la mirada al frente.", "Camina durante 20 segundos, deja los pesos y descansa, 3 series en total."], ["Inclinarte hacia un lado o dejar que los hombros se encorven hacia delante.", "Redondear la espalda al levantar o dejar los pesos."], "Elige un peso con el que puedas terminar cada serie con buena técnica, y mantén los dos lados iguales."),
    "it": ExerciseGuide(["Mettiti in mezzo a due manubri o a due borse cariche.", "Piega le ginocchia, tieni la schiena piatta e sollevali.", "Cammina a piccoli passi, con le spalle indietro e lo sguardo in avanti.", "Cammina per 20 secondi, appoggia i pesi e riposa, 3 serie in totale."], ["Pendere da un lato o lasciare che le spalle si curvino in avanti.", "Arrotondare la schiena quando raccogli o appoggi i pesi."], "Scegli un peso abbastanza leggero da finire ogni serie con una buona tecnica e tieni i due lati uguali."),
    "pt": ExerciseGuide(["Fique entre dois halteres ou duas bolsas com peso.", "Dobre os joelhos, mantenha as costas retas e pegue os pesos.", "Ande com passos curtos, ombros para trás e olhos para a frente.", "Ande por 20 segundos, coloque os pesos no chão e descanse, 3 séries no total."], ["Inclinar para um lado ou deixar os ombros caírem para a frente.", "Arredondar as costas ao pegar ou ao largar os pesos."], "Escolha um peso leve o bastante para terminar cada série com boa técnica e mantenha os dois lados iguais."),
    "hi": ExerciseGuide(["दो डंबल या दो भरे बैग के बीच खड़े हो जाओ।", "घुटने मोड़ो, पीठ सपाट रखो और उन्हें उठा लो।", "छोटे कदमों से चलो, कंधे पीछे और नज़र सामने रखो।", "20 सेकंड चलो, वज़न नीचे रखो और आराम करो, कुल 3 सेट।"], ["एक तरफ़ झुक जाना या कंधों को आगे गोल होने देना।", "वज़न उठाते या रखते समय पीठ को गोल करना।"], "इतना हल्का वज़न चुनो कि हर सेट सही फ़ॉर्म में पूरा हो, और दोनों तरफ़ बराबर रखो।"),
    "nl": ExerciseGuide(["Ga tussen twee dumbbells of twee zware tassen staan.", "Buig je knieën, houd je rug plat en til ze op.", "Loop met kleine stappen, schouders naar achteren en blik naar voren.", "Loop 20 seconden, zet ze neer en rust, 3 sets in totaal."], ["Naar één kant leunen of je schouders naar voren laten zakken.", "Je rug ronden bij het oppakken of neerzetten van de gewichten."], "Kies een gewicht dat licht genoeg is om elke set netjes af te maken en houd beide kanten gelijk."),
    "pl": ExerciseGuide(["Stań między dwiema hantlami lub dwiema obciążonymi torbami.", "Ugnij kolana, zachowaj proste plecy i podnieś je.", "Idź małymi krokami, z barkami do tyłu i wzrokiem przed siebie.", "Idź przez 20 sekund, odłóż ciężary i odpocznij, łącznie 3 serie."], ["Przechylanie się na jedną stronę lub zaokrąglanie barków do przodu.", "Zaokrąglanie pleców przy podnoszeniu lub odkładaniu ciężarów."], "Wybierz ciężar na tyle lekki, by każdą serię zrobić poprawnie, i dbaj o równe obciążenie obu stron."),
    "sv": ExerciseGuide(["Ställ dig mellan två hantlar eller två lastade väskor.", "Böj knäna, håll ryggen rak och lyft dem.", "Gå med små steg, axlarna bakåt och blicken framåt.", "Gå i 20 sekunder, ställ ner dem och vila, 3 set totalt."], ["Att luta sig åt ena sidan eller låta axlarna rundas framåt.", "Att runda ryggen när du lyfter eller ställer ner vikterna."], "Välj en vikt som är lätt nog för att klara varje set med bra teknik och håll båda sidorna lika."),
  },
  "band_pull_apart": {
    "en": ExerciseGuide(["Stand tall and hold a band in front of you with straight arms at shoulder height.", "Pull the band apart by squeezing your shoulder blades together.", "Touch the band to your chest, then return slowly.", "Do 12 reps and rest, 2 sets in total."], ["Shrugging the shoulders up toward the ears.", "Letting the band snap back instead of returning slowly."], "Choose a band light enough to finish every rep with good form, and check it for tears first."),
    "tr": ExerciseGuide(["Dik dur, lastiği kolların düz ve omuz hizasında önünde tut.", "Kürek kemiklerini birbirine yaklaştırarak lastiği iki yana aç.", "Lastiği göğsüne değdir, sonra yavaşça geri dön.", "12 tekrar yap ve dinlen, toplam 2 set."], ["Omuzları kulaklara doğru kaldırmak.", "Yavaşça dönmek yerine lastiğin geri fırlamasına izin vermek."], "Her tekrarı düzgün formla bitirebileceğin kadar hafif bir lastik seç, önce yırtık var mı diye bak."),
    "de": ExerciseGuide(["Stell dich aufrecht hin und halt ein Band mit gestreckten Armen auf Schulterhöhe vor dir.", "Zieh das Band auseinander, indem du die Schulterblätter zusammendrückst.", "Führ das Band bis zur Brust und lass es dann langsam zurückkommen.", "Mach 12 Wiederholungen und ruh dich aus, insgesamt 2 Sätze."], ["Die Schultern zu den Ohren hochziehen.", "Das Band zurückschnappen lassen, statt es langsam zurückzuführen."], "Wähl ein Band, bei dem du jede Wiederholung sauber schaffst, und prüf es vorher auf Risse."),
    "fr": ExerciseGuide(["Tiens-toi droit et tiens un élastique devant toi, bras tendus à hauteur d'épaules.", "Écarte l'élastique en serrant les omoplates l'une vers l'autre.", "Amène l'élastique contre la poitrine, puis reviens lentement.", "Fais 12 répétitions et repose-toi, 2 séries au total."], ["Monter les épaules vers les oreilles.", "Laisser l'élastique claquer au retour au lieu de revenir lentement."], "Choisis un élastique qui te permet de finir chaque répétition proprement, et vérifie d'abord qu'il n'est pas déchiré."),
    "es": ExerciseGuide(["Ponte recto y sujeta una banda delante de ti con los brazos estirados a la altura de los hombros.", "Abre la banda juntando los omóplatos.", "Toca el pecho con la banda y vuelve despacio.", "Haz 12 repeticiones y descansa, 2 series en total."], ["Subir los hombros hacia las orejas.", "Dejar que la banda vuelva de golpe en vez de volver despacio."], "Elige una banda con la que puedas terminar cada repetición con buena técnica, y comprueba antes que no tenga roturas."),
    "it": ExerciseGuide(["Stai dritto e tieni un elastico davanti a te con le braccia tese all'altezza delle spalle.", "Apri l'elastico stringendo le scapole l'una verso l'altra.", "Porta l'elastico a toccare il petto, poi torna lentamente.", "Fai 12 ripetizioni e riposa, 2 serie in totale."], ["Alzare le spalle verso le orecchie.", "Lasciare che l'elastico scatti indietro invece di tornare piano."], "Scegli un elastico abbastanza leggero da finire ogni ripetizione con una buona tecnica e controlla prima che non sia strappato."),
    "pt": ExerciseGuide(["Fique em pé e segure um elástico à sua frente com os braços esticados na altura dos ombros.", "Abra o elástico apertando as escápulas uma contra a outra.", "Encoste o elástico no peito e depois volte devagar.", "Faça 12 repetições e descanse, 2 séries no total."], ["Subir os ombros em direção às orelhas.", "Deixar o elástico voltar de uma vez em vez de voltar devagar."], "Escolha um elástico leve o bastante para terminar cada repetição com boa técnica e confira antes se ele não está rasgado."),
    "hi": ExerciseGuide(["सीधे खड़े हो जाओ और बैंड को सामने कंधों की ऊँचाई पर सीधी बाँहों से पकड़ो।", "कंधे के ब्लेड्स को एक-दूसरे की ओर भींचते हुए बैंड को दोनों तरफ़ खींचो।", "बैंड को सीने से छुआओ, फिर धीरे वापस आओ।", "12 रेप्स करो और आराम करो, कुल 2 सेट।"], ["कंधों को कानों की ओर उचका लेना।", "बैंड को धीरे लौटाने की जगह झटके से वापस जाने देना।"], "इतना हल्का बैंड चुनो कि हर रेप सही फ़ॉर्म में पूरी हो, और पहले जाँच लो कि वह कहीं फटा तो नहीं है।"),
    "nl": ExerciseGuide(["Sta rechtop en houd een elastiek met gestrekte armen op schouderhoogte voor je.", "Trek het elastiek uit elkaar door je schouderbladen naar elkaar toe te knijpen.", "Raak met het elastiek je borst aan en keer dan langzaam terug.", "Doe 12 herhalingen en rust, 2 sets in totaal."], ["Je schouders naar je oren optrekken.", "Het elastiek terug laten knallen in plaats van langzaam terug te keren."], "Kies een elastiek dat licht genoeg is om elke herhaling netjes af te maken en controleer eerst of er geen scheurtjes in zitten."),
    "pl": ExerciseGuide(["Stań prosto i trzymaj gumę przed sobą na prostych ramionach, na wysokości barków.", "Rozciągnij gumę, ściągając łopatki ku sobie.", "Dotknij gumą klatki piersiowej, potem wróć powoli.", "Zrób 12 powtórzeń i odpocznij, łącznie 2 serie."], ["Unoszenie barków w stronę uszu.", "Pozwalanie gumie, by wystrzeliła z powrotem, zamiast wracać powoli."], "Wybierz gumę na tyle lekką, by każde powtórzenie zrobić poprawnie, i najpierw sprawdź, czy nie jest pęknięta."),
    "sv": ExerciseGuide(["Stå rak och håll ett gummiband framför dig med raka armar i axelhöjd.", "Dra isär bandet genom att knipa ihop skulderbladen.", "Nudda bröstet med bandet och återgå sedan långsamt.", "Gör 12 upprepningar och vila, 2 set totalt."], ["Att dra upp axlarna mot öronen.", "Att låta bandet smälla tillbaka i stället för att återgå långsamt."], "Välj ett band som är lätt nog för att klara varje upprepning med bra teknik och kontrollera först att det inte har revor."),
  },
  "burpees": {
    "en": ExerciseGuide(["Stand tall, then squat and place your hands on the floor.", "Jump your feet back into a straight plank.", "Jump your feet back in toward your hands.", "Jump straight up, do 5 reps and rest, 3 sets in total."], ["Letting the hips sag in the plank.", "Landing hard with straight legs after the jump."], "Step your feet back and in instead of jumping to make it easier, and slow down if your form slips."),
    "tr": ExerciseGuide(["Dik dur, sonra çök ve ellerini yere koy.", "Ayaklarını geriye sıçratarak dümdüz bir plank pozisyonuna geç.", "Ayaklarını tekrar ellerine doğru sıçrat.", "Dümdüz yukarı zıpla, 5 tekrar yap ve dinlen, toplam 3 set."], ["Plankta kalçanın sarkması.", "Zıplayıştan sonra bacaklar düzken sertçe inmek."], "Kolaylaştırmak için ayaklarını sıçratmak yerine adımla geriye ve öne al, formun bozulursa yavaşla."),
    "de": ExerciseGuide(["Stell dich aufrecht hin, geh dann in die Hocke und setz die Hände auf den Boden.", "Spring mit den Füßen zurück in einen geraden Stütz.", "Spring mit den Füßen wieder zu den Händen.", "Spring senkrecht hoch, mach 5 Wiederholungen und ruh dich aus, insgesamt 3 Sätze."], ["Die Hüfte im Stütz durchhängen lassen.", "Nach dem Sprung mit durchgestreckten Beinen hart landen."], "Geh mit den Füßen zurück und vor, statt zu springen, um es leichter zu machen, und werde langsamer, wenn deine Haltung nachlässt."),
    "fr": ExerciseGuide(["Tiens-toi droit, puis accroupis-toi et pose les mains au sol.", "Saute avec les pieds en arrière pour arriver en planche droite.", "Ramène les pieds en sautant vers tes mains.", "Saute bien droit vers le haut, fais 5 répétitions et repose-toi, 3 séries au total."], ["Laisser les hanches s'affaisser en planche.", "Retomber lourdement, jambes tendues, après le saut."], "Recule et avance les pieds en marchant au lieu de sauter pour faciliter l'exercice, et ralentis si ta posture se dégrade."),
    "es": ExerciseGuide(["Ponte recto, luego baja en sentadilla y apoya las manos en el suelo.", "Salta con los pies hacia atrás hasta quedar en plancha recta.", "Salta con los pies hacia delante, acercándolos a las manos.", "Salta recto hacia arriba, haz 5 repeticiones y descansa, 3 series en total."], ["Dejar que las caderas se hundan en la plancha.", "Caer fuerte con las piernas estiradas después del salto."], "Lleva los pies atrás y adelante caminando en vez de saltar para hacerlo más fácil, y ve más despacio si pierdes la técnica."),
    "it": ExerciseGuide(["Stai dritto, poi accosciati e appoggia le mani a terra.", "Porta i piedi indietro con un salto in un plank dritto.", "Riporta i piedi verso le mani con un salto.", "Salta in verticale, fai 5 ripetizioni e riposa, 3 serie in totale."], ["Lasciar cedere i fianchi nel plank.", "Atterrare forte con le gambe tese dopo il salto."], "Per renderlo più facile porta i piedi indietro e avanti camminando invece di saltare, e rallenta se la tecnica cede."),
    "pt": ExerciseGuide(["Fique em pé, depois agache e apoie as mãos no chão.", "Salte com os pés para trás até ficar em prancha reta.", "Salte com os pés de volta para perto das mãos.", "Salte para cima, faça 5 repetições e descanse, 3 séries no total."], ["Deixar o quadril ceder na prancha.", "Aterrissar forte com as pernas esticadas depois do salto."], "Para facilitar, leve os pés para trás e para a frente andando em vez de saltar, e diminua o ritmo se a técnica falhar."),
